 // full write rebuilds the server's stub view from scratch and\n            // resyncs the patcher baseline. The console.error is the primary\n            // breadcrumb for tracking down the unknown root cause.\n            const dangerous = findDangerousChatOps(patchData.patch)\n            if (dangerous.length > 0) {\n                // The patch was never accepted, so diagnostics and any full\n                // fallback must use the last server-confirmed baseline.\n                rollbackPatchBaseline()\n                // Always log a one-line summary so production environments\n                // see enough to file a bug report. The rich dump below is\n                // gated behind a localStorage flag — chronic loops would\n                // otherwise dump 5 console.errors every 5s save cycle.\n                const sampleOps = dangerous.slice(0, 3).map(d => `${d.op} ${d.path}`).join(', ')\n                console.error(\n                    `[Save] Patcher emitted ${dangerous.length} chat-internal field op(s) — `\n                    + `falling back to full write. sample: ${sampleOps}`\n                    + ` (verbose dump: localStorage.setItem('${CHAT_GUARD_DEBUG_KEY}', '1') then reproduce)`\n                )\n                showChatGuardToastThrottled('client')\n\n                if (isChatGuardDebugEnabled()) {\n                // ── Diagnostic dump for unknown root cause ────────────────\n                // chatToStub is supposed to strip every chat down to 6\n                // metadata fields before the diff. If non-stub fields end\n                // up in patch ops, something slipped past it. Dump enough\n                // shape info to figure out which side of the diff carries\n                // the contraband (baseline vs current) and what flags the\n                // chat object has.\n                const affectedChats: Record<string, any> = {}\n                const seen = new Set<string>()\n                const baselineCharsLen = (patcher as any).lastSyncedDb?.characters?.length ?? -1\n                const currentCharsLen = db.characters?.length ?? -1\n\n                const summarize = (c: any) => {\n                    if (c == null) return null\n                    const keys = Object.keys(c)\n                    // Per-key shape: which fields are strings vs arrays vs objects vs primitives\n                    const keyShapes: Record<string, string> = {}\n                    for (const k of keys) {\n                        const v = c[k]\n                        if (v === null) keyShapes[k] = 'null'\n                        else if (Array.isArray(v)) keyShapes[k] = `Array(${v.length})`\n                        else if (typeof v === 'object') keyShapes[k] = `Object(${Object.keys(v).length})`\n                        else keyShapes[k] = `${typeof v}=${typeof v === 'string' && v.length > 30 ? v.slice(0, 30) + '…' : JSON.stringify(v)}`\n                    }\n                    return {\n                        keys,                                  // full key list, not just length\n                        keyShapes,                             // per-key type/preview\n                        classification: classifyChat(c),\n                        _stub: c._stub,\n                        _placeholder: c._placeholder,\n                        hasMessage: Array.isArray(c.message),\n                        messageLen: Array.isArray(c.message) ? c.message.length : null,\n                        id: c.id,\n                        name: c.name,\n                        // Type fingerprints help identify Svelte $state proxies\n                        // or other wrapper objects that might bypass deep clone.\n                        ctor: c?.constructor?.name,\n                        isFrozen: Object.isFrozen(c),\n                        isProxy: typeof c === 'object' && c !== null && (c as any)?.[Symbol.toStringTag] !== undefined,\n                    }\n                }\n\n                // Re-run chatToStub on the current chat to see what the patcher\n                // would have produced. If this still has non-stub fields, the\n                // bug is INSIDE chatToStub's isChatStub short-circuit (chat\n                // already has `_stub: true` but isn't actually a stub).\n                const stubReplay = (c: any) => {\n                    if (c == null) return null\n                    try {\n                        const result = chatToStub(c)\n                        return summarize(result)\n                    } catch (e) {\n                        return { error: String(e) }\n                    }\n                }\n\n                for (const op of dangerous) {\n                    const m = op.path.match(/^\\/characters\\/(\\d+)\\/chats\\/(\\d+)\\//)\n                    if (!m) continue\n                    const key = `${m[1]}/${m[2]}`\n                    if (seen.has(key)) continue\n                    seen.add(key)\n                    if (seen.size > 5) break\n                    const ci = +m[1], chi = +m[2]\n                    const baselineChar = (patcher as any).lastSyncedDb?.characters?.[ci]\n                    const currentChar = db.characters?.[ci]\n                    const baselineChat = baselineChar?.chats?.[chi]\n                    const currentChat = currentChar?.chats?.[chi]\n                    const opsForThisChat = dangerous.filter(d => d.path.startsWith(`/characters/${ci}/chats/${chi}/`))\n                    // Reference identity: same object? same chats array? same chat slot?\n                    const refIdentity = {\n                        sameCharacter: baselineChar === currentChar,\n                        sameChatsArray: baselineChar?.chats === currentChar?.chats,\n                        sameChatSlot: baselineChat === currentChat,\n                    }\n                    affectedChats[key] = {\n                        characterContext: {\n                            baselineChaId: baselineChar?.chaId,\n                            currentChaId: currentChar?.chaId,\n                            chaIdsMatch: baselineChar?.chaId === currentChar?.chaId,\n                            baselineChatsLen: baselineChar?.chats?.length ?? -1,\n                            currentChatsLen: currentChar?.chats?.length ?? -1,\n                            refIdentity,\n                        },\n                        baselineChat: summarize(baselineChat),\n                        currentChat: summarize(currentChat),\n                        // The crucial diagnostic: if this still leaks message etc,\n                        // chatToStub's isChatStub fast-path was the offender.\n                        currentAfterChatToStub: stubReplay(currentChat),\n                        baselineAfterChatToStub: stubReplay(baselineChat),\n                        opsForThisChat,\n                    }\n                }\n\n                // Distribution of stub/placeholder flags across the affected\n                // characters' chats — useful to spot wholesale corruption\n                // (e.g. a plugin replacing the entire chats array with\n                // _stub-tagged objects).\n                const charsDistribution: Record<string, any> = {}\n                for (const k of Array.from(seen).slice(0, 3)) {\n                    const ci = +k.split('/')[0]\n                    const baselineChats = (patcher as any).lastSyncedDb?.characters?.[ci]?.chats ?? []\n                    const currentChats = db.characters?.[ci]?.chats ?? []\n                    const tally = (chats: any[]) => {\n                        const t = { total: chats.length, stub: 0, placeholder: 0, hybrid: 0, full: 0, neither: 0 }\n                        for (const c of chats) {\n                            if (!c) continue\n                            const isStub = c._stub === true\n                            const isPh = c._placeholder === true\n                            const hasMsg = Array.isArray(c.message)\n                            if (isStub && hasMsg) t.hybrid++\n                            else if (isStub) t.stub++\n                            else if (isPh) t.placeholder++\n                            else if (hasMsg) t.full++\n                            else t.neither++\n                        }\n                        return t\n                    }\n                    charsDistribution[`character[${ci}]`] = {\n                        baseline: tally(baselineChats),\n                        current: tally(currentChats),\n                    }\n                }\n\n                let activeCharID = -1\n                try { selectedCharID.subscribe(v => { activeCharID = v })() } catch {}\n                console.error('[Save:guard-debug] context:', {\n                    baselineCharsLen,\n                    currentCharsLen,\n                    selectedCharID: activeCharID,\n                    totalDangerousOps: dangerous.length,\n                    uniqueAffectedChats: seen.size,\n                })\n                console.error('[Save:guard-debug] all dangerous ops:', dangerous)\n                console.error('[Save:guard-debug] affected chats (baseline / current / stubReplay):', affectedChats)\n                console.error('[Save:guard-debug] chats[] distribution per affected character:', charsDistribution)\n                }\n                // Leave saved=false so the full-write path below kicks in.\n            } else {\n                let patchResult: PatchItemResult\n                try {\n                    patchResult = await forageStorage.patchItem('database/database.bin', patchData)\n                }\n                catch (error) {\n                    rollbackPatchBaseline()\n                    throw error\n                }\n                saved = patchResult.success\n                if (!patchResult.success) {\n                    rollbackPatchBaseline()\n                }\n                if (patchResult.success && patchResult.etag) {\n                    newEtag = patchResult.etag\n                    forageStorage.setDbEtag(patchResult.etag)\n                }\n                if (patchResult.success) {\n                    lastConfirmedServerDb = patcher.baselineSnapshot() as Database\n                }\n                if (patchResult.persistWarning) {\n                    showPersistWarningOnce(patchResult.persistWarning)\n                }\n                // Server's chat-internal-field guard rejected the patch — the\n                // client-side guard above missed this case. Surface to user\n                // and continue to the full-write fallback below.\n                if (patchResult.chatGuardRejected) {\n                    console.error('[Save] Server rejected patch — chat-internal field ops detected server-side')\n                    showChatGuardToastThrottled('server')\n                }\n                else if (patchResult.validationRejected) {\n                    throw new Error(\n                        `Server rejected an invalid database update: ${patchResult.error ?? 'unknown invariant failure'}`\n                    )\n                }\n                else if (patchResult.conflict) {\n                    console.warn('[Save] Patch conflict detected, rebasing tracked changes on the latest server DB...')\n                    await rebaseTrackedLocalChangesOnLatestServerDb(db, toSave)\n                    await sleep(Math.min(500 * (savetrys + 1), 3000))\n                    return 'retry'\n                }\n            }\n        }\n        if (!saved) {\n            if (supportsPatchSync && !options?.forceFullWrite) {\n                console.warn('[Save] Patch conflict, falling through to full write...')\n            }\n            try {\n                const currentEtag = forageStorage.getDbEtag()\n                await forageStorage.setItem('database/database.bin', dbData, currentEtag ?? undefined)\n            } catch (conflictErr) {\n                if (conflictErr instanceof ConflictError) {\n                    console.warn('[Save] Full-write conflict detected, rebasing tracked local changes on latest server DB...')\n                    await rebaseTrackedLocalChangesOnLatestServerDb(db, toSave)\n                    await sleep(Math.min(500 * (savetrys + 1), 3000))\n                    return 'retry'\n                }\n                throw conflictErr\n            }\n\n            // Re-init the confirmed baseline from the exact encoded data that\n            // was accepted. This also keeps conflict recovery safe when patch\n            // sync is disabled but ETag-protected full writes are enabled.\n            const decodedDb = normalizeJSON(await decodeRisuSave(dbData)) as Database\n            lastConfirmedServerDb = decodedDb\n            if (supportsPatchSync) {\n                await patcher.init(decodedDb)\n            }\n        }\n\n        updateKnownChatsAfterSuccessfulSave(db, toSave)\n\n        if (newEtag) {\n            forageStorage.setDbEtag(newEtag)\n        }\n\n\n        return 'saved'\n    }\n\n    async function triggerSave(options?: {\n        forceFullWrite?: boolean\n        skipBroadcast?: boolean\n    }) {\n        if (saveInFlight) {\n            // Mutations queued while a save is in flight belong to the next\n            // transaction. Chain that transaction explicitly; pagehide cannot\n            // otherwise consume the current promise and leave the final dirty\n            // chat stranded in changeTracker.\n            changed = true\n            const currentSave = saveInFlight\n            return currentSave.then(async () => {\n                if (changed || hasTrackedChanges(changeTracker)) {\n                    changed = false\n                    await triggerSave(options)\n                }\n            })\n        }\n\n        const toSave = takeTrackedChanges()\n        if (!hasTrackedChanges(toSave) && !options?.forceFullWrite) {\n            return\n        }\n\n        saveInFlight = (async () => {\n            saving.state = true\n            try {\n                const result = await persistTrackedChanges(toSave, options)\n                if (result === 'saved') {\n                    savetrys = 0\n                    deferredFailureRetries = 0\n                    if (deferredRecoveryTimer) {\n                        clearTimeout(deferredRecoveryTimer)\n                        deferredRecoveryTimer = null\n                    }\n                } else if (result === 'noop' && hasTrackedChanges(toSave)) {\n                    requeueTrackedChanges(toSave)\n                    changed = true\n                }\n                else if (result === 'retry') {\n                    savetrys += 1\n                    if (savetrys > 4) {\n                        // The rebased state is still dirty and remains in the\n                        // tracker, but deterministic 409s must not hammer the\n                        // server forever.\n                        changed = false\n                        alertError(new Error('Saving still conflicts after five rebases. Local edits were kept; reload or resolve the other active session before retrying.'))\n                        savetrys = 0\n                    }\n                    else {\n                        changed = true\n                    }\n                }\n            } catch (error) {\n                requeueTrackedChanges(toSave)\n                if (error instanceof ManualSaveConflictError) {\n                    changed = false\n                    savetrys = 0\n                    alertError(error)\n                    return\n                }\n                savetrys += 1\n                if (savetrys > 4) {\n                    alertError(error)\n                    savetrys = 0\n                    // Keep the dirty tracker and allow a couple of low-rate\n                    // recovery cycles for transient outages without creating\n                    // an unbounded upload loop on a persistent failure.\n                    if (deferredFailureRetries < 2) {\n                        deferredFailureRetries += 1\n                        scheduleDeferredRecovery(30_000)\n                    }\n                    else {\n                        // Persistent server/network outages must not turn a\n                        // dirty in-memory tracker into a permanent silent stop.\n                        // Retry at a low rate to avoid repeated large uploads;\n                        // `online`/visibility events above wake it sooner.\n                        scheduleDeferredRecovery(5 * 60_000)\n                    }\n                }\n                else {\n                    console.error(error)\n                    await sleep(Math.min(500 * savetrys, 3000))\n                    changed = true\n                }\n            } finally {\n                saving.state = false\n                saveInFlight = null\n            }\n        })()\n\n        return saveInFlight\n    }\n\n    requestImmediateSaveImpl = async (options) => {\n        changed = true\n        await tick()\n        await triggerSave({\n            forceFullWrite: options?.forceFullWrite,\n        })\n    }\n\n    requestImportedCharacterSaveImpl = async (chaId) => {\n        const database = getDatabase()\n        const character = database.characters?.find((item) => item?.chaId === chaId)\n        if (!character) {\n            throw new Error('Imported character is no longer present')\n        }\n\n        queueTrackedCharacter(chaId)\n        const expectedChatIds: string[] = []\n        for (const chat of character.chats ?? []) {\n            if (\n                typeof chat?.id !== 'string'\n                || chat.id.trim().length === 0\n                || chat._placeholder\n                || !Array.isArray(chat.message)\n            ) {\n                throw new Error('Imported character contains an invalid chat')\n            }\n            expectedChatIds.push(chat.id)\n            queueTrackedChat(chaId, chat.id)\n        }\n        if (expectedChatIds.length === 0) {\n            throw new Error('Imported character has no chat')\n        }\n\n        changed = true\n        await tick()\n        if (saveInFlight) await saveInFlight\n        await triggerSave()\n\n        const confirmedCharacter = lastConfirmedServerDb?.characters?.find(\n            (item) => item?.chaId === chaId,\n        )\n        const confirmedChatIds = new Set(\n            (confirmedCharacter?.chats ?? [])\n                .map((chat) => chat?.id)\n                .filter((id): id is string => typeof id === 'string' && id.length > 0),\n        )\n        if (\n            !confirmedCharacter\n            || expectedChatIds.some((chatId) => !confirmedChatIds.has(chatId))\n        ) {\n            throw new Error('Server has not confirmed the imported character yet')\n        }\n        await forageStorage.flushDatabase()\n    }\n\n    requestChatSaveImpl = async (chaId, chatId) => {\n        queueTrackedChat(chaId, chatId)\n        changed = true\n        await tick()\n        await triggerSave()\n    }\n\n    let savetrys = 0\n    let deferredFailureRetries = 0\n    let deferredRecoveryTimer: ReturnType<typeof setTimeout> | null = null\n    function scheduleDeferredRecovery(delayMs: number) {\n        if (deferredRecoveryTimer) clearTimeout(deferredRecoveryTimer)\n        deferredRecoveryTimer = setTimeout(() => {\n            deferredRecoveryTimer = null\n            if (hasTrackedChanges(changeTracker)) changed = true\n        }, delayMs)\n    }\n    while (true) {\n        if (!changed) {\n            await sleep(200)\n            continue\n        }\n        changed = false\n        if (requiresFullEncoderReload.state) {\n            encoder = new RisuSaveEncoder()\n            await encoder.init(getDatabase(), {\n                compression: false,\n                skipRemoteSavingOnCharacters: false\n            })\n            requiresFullEncoderReload.state = false\n        }\n        await triggerSave()\n        await sleep(100)\n    }\n}\n\n/**\n * Retrieves the database backups.\n * \n * @returns {Promise<number[]>} - A promise that resolves to an array of backup timestamps.\n */\nexport async function getDbBackups(currentDbSize?: number) {\n    const keys = await forageStorage.keys()\n\n    const backups = keys\n        .filter(key => key.startsWith('database/dbbackup-'))\n        .map(key => parseInt(key.slice(18, -4)))\n        .sort((a, b) => b - a);\n\n    const BACKUP_BUDGET = 500 * 1024 * 1024 // 500MB\n    const maxBackups = currentDbSize\n        ? Math.min(20, Math.max(3, Math.floor(BACKUP_BUDGET / currentDbSize)))\n        : 20\n\n    while (backups.length > maxBackups) {\n        const last = backups.pop()\n        await forageStorage.removeItem(`database/dbbackup-${last}.bin`)\n    }\n    return backups\n}\n\nlet usingSw = false\n\nexport function setUsingSw(value: boolean) {\n    usingSw = value\n}\n\n/**\n * Retrieves fetch data for a given chat ID.\n * \n * @param {string} id - The chat ID to search for in the fetch log.\n * @returns {fetchLog | null} - The fetch log entry if found, otherwise null.\n */\nexport function getFetchData(id: string) {\n    for (const log of fetchLog) {\n        if (log.chatId === id) {\n            return log;\n        }\n    }\n    return null;\n}\n\nconst knownHostes = [\"localhost\", \"127.0.0.1\", \"0.0.0.0\"];\n\n/**\n * Interface representing the arguments for the global fetch function.\n * \n * @interface GlobalFetchArgs\n * @property {boolean} [plainFetchForce] - Whether to force plain fetch.\n * @property {any} [body] - The body of the request.\n * @property {{ [key: string]: string }} [headers] - The headers of the request.\n * @property {boolean} [rawResponse] - Whether to return the raw response.\n * @property {'POST' | 'GET'} [method] - The HTTP method to use.\n * @property {AbortSignal} [abortSignal] - The abort signal to cancel the request.\n * @property {boolean} [useRisuToken] - Whether to use the Risu token.\n * @property {string} [chatId] - The chat ID associated with the request.\n */\ninterface GlobalFetchArgs {\n    plainFetchForce?: boolean;\n    plainFetchDeforce?: boolean;\n    body?: any;\n    headers?: { [key: string]: string };\n    rawResponse?: boolean;\n    method?: 'POST' | 'GET';\n    abortSignal?: AbortSignal;\n    useRisuToken?: boolean;\n    chatId?: string;\n    interceptor?: string;\n    requestTimeoutMs?: number;\n    networkRoute?: 'auto' | 'local_network';\n}\n\n/**\n * Interface representing the result of the global fetch function.\n * \n * @interface GlobalFetchResult\n * @property {boolean} ok - Whether the request was successful.\n * @property {any} data - The data returned from the request.\n * @property {{ [key: string]: string }} headers - The headers returned from the request.\n */\ninterface GlobalFetchResult {\n    ok: boolean;\n    data: any;\n    headers: { [key: string]: string };\n    status: number;\n}\n\n/**\n * Adds a fetch log entry.\n * \n * @param {Object} arg - The arguments for the fetch log entry.\n * @param {any} arg.body - The body of the request.\n * @param {{ [key: string]: string }} [arg.headers] - The headers of the request.\n * @param {any} arg.response - The response from the request.\n * @param {boolean} arg.success - Whether the request was successful.\n * @param {string} arg.url - The URL of the request.\n * @param {string} [arg.resType] - The response type.\n * @param {string} [arg.chatId] - The chat ID associated with the request.\n * @returns {number} - The index of the added fetch log entry.\n */\nexport function addFetchLog(arg: {\n    body: any,\n    headers?: { [key: string]: string },\n    response: any,\n    success: boolean,\n    url: string,\n    resType?: string,\n    chatId?: string,\n    status?: number\n}): number {\n    fetchLog.unshift({\n        body: typeof (arg.body) === 'string' ? arg.body : JSON.stringify(arg.body, null, 2),\n        header: JSON.stringify(arg.headers ?? {}, null, 2),\n        response: typeof (arg.response) === 'string' ? arg.response : JSON.stringify(arg.response, null, 2),\n        responseType: arg.resType ?? 'json',\n        success: arg.success,\n        date: (new Date()).toLocaleTimeString(),\n        url: arg.url,\n        chatId: arg.chatId,\n        status: arg.status\n    });\n    return 0;\n}\n\n/**\n * Performs a global fetch request.\n * \n * @param {string} url - The URL to fetch.\n * @param {GlobalFetchArgs} [arg={}] - The arguments for the fetch request.\n * @returns {Promise<GlobalFetchResult>} - The result of the fetch request.\n */\nexport async function globalFetch(url: string, arg: GlobalFetchArgs = {}): Promise<GlobalFetchResult> {\n    try {\n        const db = getDatabase();\n\n        if (arg.abortSignal?.aborted) { return { ok: false, data: 'aborted', headers: {}, status: 400 }; }\n\n        const urlHost = new URL(url).hostname\n        const useLocalNetworkRoute = arg.networkRoute === 'local_network' && isLocalNetworkUrl(url)\n        const forcePlainFetch = ((knownHostes.includes(urlHost)) || db.usePlainFetch || arg.plainFetchForce) && !arg.plainFetchDeforce && !useLocalNetworkRoute\n\n        if(arg.interceptor){\n            for (const interceptor of bodyIntercepterStore) {\n                try {\n                    arg.body = await interceptor.callback(arg.body, arg.interceptor) || arg.body\n                }\n                catch (e) {\n                    console.error(e)\n                }\n            }\n        }\n\n        const timeoutSignal = buildTimeoutSignal(arg.abortSignal, arg.requestTimeoutMs)\n        const requestArg = timeoutSignal.signal === arg.abortSignal\n            ? arg\n            : { ...arg, abortSignal: timeoutSignal.signal }\n\n        try {\n            if (useLocalNetworkRoute) {\n                return await fetchWithProxy(url, requestArg);\n            }\n\n            if (forcePlainFetch) {\n                return await fetchWithPlainFetch(url, requestArg);\n            }\n            //userScriptFetch is provided by userscript\n            if (window.userScriptFetch && !arg.plainFetchDeforce) {\n                return await fetchWithUSFetch(url, requestArg);\n            }\n            return await fetchWithProxy(url, requestArg);\n        } finally {\n            timeoutSignal.cleanup()\n        }\n\n    } catch (error) {\n        console.error(error);\n        return { ok: false, data: `${error}`, headers: {}, status: 400 };\n    }\n}\n\n/**\n * Adds a fetch log entry in the global fetch log.\n * \n * @param {any} response - The response data.\n * @param {boolean} success - Indicates if the fetch was successful.\n * @param {string} url - The URL of the fetch request.\n * @param {GlobalFetchArgs} arg - The arguments for the fetch request.\n */\nfunction addFetchLogInGlobalFetch(response: any, success: boolean, url: string, arg: GlobalFetchArgs, status?: number) {\n    try {\n        fetchLog.unshift({\n            body: JSON.stringify(arg.body, null, 2),\n            header: JSON.stringify(arg.headers ?? {}, null, 2),\n            response: JSON.stringify(response, null, 2),\n            success: success,\n            date: (new Date()).toLocaleTimeString(),\n            url: url,\n            chatId: arg.chatId,\n            status: status\n        })\n    }\n    catch {\n        fetchLog.unshift({\n            body: JSON.stringify(arg.body, null, 2),\n            header: JSON.stringify(arg.headers ?? {}, null, 2),\n            response: `${response}`,\n            success: success,\n            date: (new Date()).toLocaleTimeString(),\n            url: url,\n            chatId: arg.chatId,\n            status: status\n        })\n    }\n\n    if (fetchLog.length > 20) {\n        fetchLog.pop()\n    }\n}\n\n/**\n * Performs a fetch request using plain fetch.\n * \n * @param {string} url - The URL to fetch.\n * @param {GlobalFetchArgs} arg - The arguments for the fetch request.\n * @returns {Promise<GlobalFetchResult>} - The result of the fetch request.\n */\nasync function fetchWithPlainFetch(url: string, arg: GlobalFetchArgs): Promise<GlobalFetchResult> {\n    try {\n        const headers = { 'Content-Type': 'application/json', ...arg.headers };\n        const response = await fetch(new URL(url), { body: JSON.stringify(arg.body), headers, method: arg.method ?? \"POST\", signal: arg.abortSignal });\n        const data = arg.rawResponse ? new Uint8Array(await response.arrayBuffer()) : await response.json();\n        const ok = response.ok && response.status >= 200 && response.status < 300;\n        addFetchLogInGlobalFetch(data, ok, url, arg, response.status);\n        return { ok, data, headers: Object.fromEntries(response.headers), status: response.status };\n    } catch (error) {\n        return { ok: false, data: `${error}`, headers: {}, status: 400 };\n    }\n}\n\n/**\n * Performs a fetch request using userscript provided fetch.\n * \n * @param {string} url - The URL to fetch.\n * @param {GlobalFetchArgs} arg - The arguments for the fetch request.\n * @returns {Promise<GlobalFetchResult>} - The result of the fetch request.\n */\nasync function fetchWithUSFetch(url: string, arg: GlobalFetchArgs): Promise<GlobalFetchResult> {\n    try {\n        const headers = { 'Content-Type': 'application/json', ...arg.headers };\n        const response = await userScriptFetch(url, { body: JSON.stringify(arg.body), headers, method: arg.method ?? \"POST\", signal: arg.abortSignal });\n        const data = arg.rawResponse ? new Uint8Array(await response.arrayBuffer()) : await response.json();\n        const ok = response.ok && response.status >= 200 && response.status < 300;\n        addFetchLogInGlobalFetch(data, ok, url, arg, response.status);\n        return { ok, data, headers: Object.fromEntries(response.headers), status: response.status };\n    } catch (error) {\n        return { ok: false, data: `${error}`, headers: {}, status: 400 };\n    }\n}\n\n/**\n * Performs a fetch request using a proxy.\n * \n * @param {string} url - The URL to fetch.\n * @param {GlobalFetchArgs} arg - The arguments for the fetch request.\n * @returns {Promise<GlobalFetchResult>} - The result of the fetch request.\n */\nasync function fetchWithProxy(url: string, arg: GlobalFetchArgs): Promise<GlobalFetchResult> {\n    try {\n        const furl = `/proxy2`;\n        arg.headers[\"Content-Type\"] ??= arg.body instanceof URLSearchParams ? \"application/x-www-form-urlencoded\" : \"application/json\";\n        const headers = {\n            \"risu-header\": encodeURIComponent(JSON.stringify(arg.headers)),\n            \"risu-url\": encodeURIComponent(url),\n            \"Content-Type\": arg.body instanceof URLSearchParams ? \"application/x-www-form-urlencoded\" : \"application/json\",\n            ...(arg.useRisuToken && { \"x-risu-tk\": \"use\" }),\n            ...(DBState?.db?.requestLocation && { \"risu-location\": DBState.db.requestLocation }),\n        };\n\n        // Add risu-auth header for Node.js server\n        headers[\"risu-auth\"] = await forageStorage.createAuth();\n\n        const body = arg.body instanceof URLSearchParams ? arg.body.toString() : JSON.stringify(arg.body);\n\n        const response = await fetch(furl, { body, headers, method: arg.method ?? \"POST\", signal: arg.abortSignal });\n        const isSuccess = response.ok && response.status >= 200 && response.status < 300;\n\n        if (arg.rawResponse) {\n            const data = new Uint8Array(await response.arrayBuffer());\n            addFetchLogInGlobalFetch(\"Uint8Array Response\", isSuccess, url, arg, response.status);\n            return { ok: isSuccess, data, headers: Object.fromEntries(response.headers), status: response.status };\n        }\n\n        const text = await response.text();\n        try {\n            const data = JSON.parse(text);\n            addFetchLogInGlobalFetch(data, isSuccess, url, arg, response.status);\n            return { ok: isSuccess, data, headers: Object.fromEntries(response.headers), status: response.status };\n        } catch (error) {\n            const errorMsg = text.startsWith('<!DOCTYPE') ? \"Responded HTML. Is your URL, API key, and password correct?\" : text;\n            addFetchLogInGlobalFetch(text, false, url, arg, response.status);\n            return { ok: false, data: errorMsg, headers: Object.fromEntries(response.headers), status: response.status };\n        }\n    } catch (error) {\n        return { ok: false, data: `${error}`, headers: {}, status: 400 };\n    }\n}\n\n/**\n * Regular expression to match backslashes.\n * \n * @constant {RegExp}\n */\nconst re = /\\\\/g;\n\n/**\n * Gets the basename of a given path.\n * \n * @param {string} data - The path to get the basename from.\n * @returns {string} - The basename of the path.\n */\nexport function getBasename(data: string) {\n    const splited = data.replace(re, '/').split('/');\n    const lasts = splited[splited.length - 1];\n    return lasts;\n}\n\n/**\n * Retrieves uncleanable resources from the database.\n * \n * @param {Database} db - The database to retrieve uncleanable resources from.\n * @param {'basename'|'pure'} [uptype='basename'] - The type of uncleanable resources to retrieve.\n * @returns {string[]} - An array of uncleanable resources.\n */\nexport function getUncleanables(db: Database, uptype: 'basename' | 'pure' = 'basename') {\n    const uncleanable = new Set<string>();\n\n    /**\n     * Adds a resource to the uncleanable list if it is not already included.\n     * \n     * @param {string} data - The resource to add.\n     */\n    function addUncleanable(data: string) {\n        if (!data) {\n            return;\n        }\n        if (data === '') {\n            return;\n        }\n        const bn = uptype === 'basename' ? getBasename(data) : data;\n        uncleanable.add(bn);\n    }\n\n    addUncleanable(db.customBackground);\n    addUncleanable(db.userIcon);\n    // Uploaded notification sounds. Preset-id values (e.g. \"bell\") are not\n    // asset paths, so they add a harmless basename that matches no stored asset.\n    addUncleanable(db.messageSound);\n    addUncleanable(db.translateSound);\n    if (db.customSounds) {\n        for (const s of db.customSounds) {\n            addUncleanable(s.path);\n        }\n    }\n\n    for (const cha of db.characters) {\n        if (cha.image) {\n            addUncleanable(cha.image);\n        }\n        if (cha.emotionImages) {\n            for (const em of cha.emotionImages) {\n                addUncleanable(em[1]);\n            }\n        }\n        if (cha.additionalAssets) {\n            for (const em of cha.additionalAssets) {\n                addUncleanable(em[1]);\n            }\n        }\n        if (cha.vits) {\n            const keys = Object.keys(cha.vits.files);\n            for (const key of keys) {\n                const vit = cha.vits.files[key];\n                addUncleanable(vit);\n            }\n        }\n        if (cha.ccAssets) {\n            for (const asset of cha.ccAssets) {\n                addUncleanable(asset.uri);\n            }\n        }\n    }\n\n    if (db.modules) {\n        for (const module of db.modules) {\n            const assets = module.assets\n            if (assets) {\n                for (const asset of assets) {\n                    addUncleanable(asset[1])\n                }\n            }\n            if(module.icon){\n                addUncleanable(module.icon)\n            }\n        }\n    }\n\n    if (db.personas) {\n        db.personas.map((v) => {\n            addUncleanable(v.icon);\n\n            if(v.embeddedModule){\n                const assets = v.embeddedModule.assets\n                if (assets) {\n                    for (const asset of assets) {\n                        addUncleanable(asset[1])\n                    }\n                }\n                if(v.embeddedModule.icon){\n                    addUncleanable(v.embeddedModule.icon)\n                }\n            }\n        });\n    }\n\n    if (db.characterOrder) {\n        db.characterOrder.forEach((item) => {\n            if (typeof item === 'object' && 'imgFile' in item) {\n                addUncleanable(item.imgFile);\n            }\n        })\n    }\n    return Array.from(uncleanable);\n}\n\n\n/**\n * Replaces database resources with the provided replacer object.\n * \n * @param {Database} db - The database object containing resources to be replaced.\n * @param {{[key: string]: string}} replacer - An object mapping original resource keys to their replacements.\n * @returns {Database} - The updated database object with replaced resources.\n */\nexport function replaceDbResources(db: Database, replacer: { [key: string]: string }): Database {\n    /**\n     * Replaces a given data string with its corresponding value from the replacer object.\n     * \n     * @param {string} data - The data string to be replaced.\n     * @returns {string} - The replaced data string or the original data if no replacement is found.\n     */\n    function replaceData(data: string): string {\n        if (!data) {\n            return data;\n        }\n        return replacer[data] ?? data;\n    }\n\n    db.customBackground = replaceData(db.customBackground);\n    db.userIcon = replaceData(db.userIcon);\n    db.messageSound = replaceData(db.messageSound);\n    db.translateSound = replaceData(db.translateSound);\n    if (db.customSounds) {\n        for (const s of db.customSounds) {\n            s.path = replaceData(s.path);\n        }\n    }\n\n    for (const cha of db.characters) {\n        if (cha.image) {\n            cha.image = replaceData(cha.image);\n        }\n        if (cha.emotionImages) {\n            for (let i = 0; i < cha.emotionImages.length; i++) {\n                cha.emotionImages[i][1] = replaceData(cha.emotionImages[i][1]);\n            }\n        }\n        if (cha.additionalAssets) {\n            for (let i = 0; i < cha.additionalAssets.length; i++) {\n                cha.additionalAssets[i][1] = replaceData(cha.additionalAssets[i][1]);\n            }\n        }\n    }\n    return db;\n}\n\n/**\n * Checks and updates the character order in the database.\n * Ensures that all characters are properly ordered and removes any invalid entries.\n */\nexport function checkCharOrder() {\n    let db = getDatabase()\n    db.characterOrder = db.characterOrder ?? []\n    let ordered = []\n    for (let i = 0; i < db.characterOrder.length; i++) {\n        const folder = db.characterOrder[i]\n        if (typeof (folder) !== 'string' && folder) {\n            for (const f of folder.data) {\n                ordered.push(f)\n            }\n        }\n        if (typeof (folder) === 'string') {\n            ordered.push(folder)\n        }\n    }\n\n    let charIdList: string[] = []\n\n    for (let i = 0; i < db.characters.length; i++) {\n        const char = db.characters[i]\n        const charId = char.chaId\n        if (!char.trashTime) {\n            charIdList.push(charId)\n        }\n        if (!ordered.includes(charId)) {\n            if (charId !== '§temp' && charId !== '§playground' && !char.trashTime) {\n                db.characterOrder.push(charId)\n            }\n        }\n    }\n\n\n    for (let i = 0; i < db.characterOrder.length; i++) {\n        const data = db.characterOrder[i]\n        if (typeof (data) !== 'string') {\n            if (!data) {\n                db.characterOrder.splice(i, 1)\n                i--;\n                continue\n            }\n            if (data.data.length === 0) {\n                db.characterOrder.splice(i, 1)\n                i--;\n                continue\n            }\n            for (let i2 = 0; i2 < data.data.length; i2++) {\n                const data2 = data.data[i2]\n                if (!charIdList.includes(data2)) {\n                    data.data.splice(i2, 1)\n                    i2--;\n                }\n            }\n            db.characterOrder[i] = data\n        }\n        else {\n            if (!charIdList.includes(data)) {\n                db.characterOrder.splice(i, 1)\n                i--;\n            }\n        }\n    }\n\n\n}\n\n/**\n * Retrieves the request log as a formatted string.\n * \n * @returns {string} The formatted request log.\n */\nexport function getRequestLog() {\n    let logString = ''\n    const b = '\\n\\`\\`\\`json\\n'\n    const bend = '\\n\\`\\`\\`\\n'\n\n    for (const log of fetchLog) {\n        logString += `## ${log.date}\\n\\n* Request URL\\n\\n${b}${log.url}${bend}\\n\\n* Request Body\\n\\n${b}${log.body}${bend}\\n\\n* Request Header\\n\\n${b}${log.header}${bend}\\n\\n`\n            + `* Response Body\\n\\n${b}${log.response}${bend}\\n\\n* Response Success\\n\\n${b}${log.success}${bend}\\n\\n`\n    }\n    return logString\n}\n\n/**\n * Retrieves the fetch logs array.\n *\n * @returns {fetchLog[]} The fetch logs array.\n */\nexport function getFetchLogs() {\n    return fetchLog\n}\n\n/**\n * Opens a URL in the appropriate environment.\n * \n * @param {string} url - The URL to open.\n */\nexport function openURL(url: string) {\n    window.open(url, \"_blank\")\n}\n\n/**\n * Converts FormData to a URL-encoded string.\n * \n * @param {FormData} formData - The FormData to convert.\n * @returns {string} The URL-encoded string.\n */\nfunction formDataToString(formData: FormData): string {\n    const params: string[] = [];\n\n    for (const [name, value] of formData.entries()) {\n        params.push(`${encodeURIComponent(name)}=${encodeURIComponent(value.toString())}`);\n    }\n\n    return params.join('&');\n}\n\n/**\n * Class representing a local writer.\n */\nexport class LocalWriter {\n    writer: WritableStreamDefaultWriter\n\n    /**\n     * Initializes the writer.\n     * \n     * @param {string} [name='Binary'] - The name of the file.\n     * @param {string[]} [ext=['bin']] - The file extensions.\n     * @returns {Promise<boolean>} - A promise that resolves to a boolean indicating success.\n     */\n    async init(name = 'Binary', ext = ['bin']): Promise<boolean> {\n        const writableStream = streamSaver.createWriteStream(name + '.' + ext[0])\n        this.writer = writableStream.getWriter()\n        return true\n    }\n\n    /**\n     * Writes backup data to the file.\n     * \n     * @param {string} name - The name of the backup.\n     * @param {Uint8Array} data - The data to write.\n     */\n    async writeBackup(name: string, data: Uint8Array): Promise<void> {\n        const encodedName = new TextEncoder().encode(getBasename(name))\n        const nameLength = new Uint32Array([encodedName.byteLength])\n        await this.writer.write(new Uint8Array(nameLength.buffer))\n        await this.writer.write(encodedName)\n        const dataLength = new Uint32Array([data.byteLength])\n        await this.writer.write(new Uint8Array(dataLength.buffer))\n        await this.writer.write(data)\n    }\n\n    /**\n     * Writes data to the file.\n     * \n     * @param {Uint8Array} data - The data to write.\n     */\n    async write(data: Uint8Array): Promise<void> {\n        await this.writer.write(data)\n    }\n\n    /**\n     * Closes the writer.\n     */\n    async close(): Promise<void> {\n        await this.writer.close()\n    }\n}\n\n/**\n * Class representing a virtual writer.\n */\nexport class VirtualWriter {\n    buf = new AppendableBuffer()\n\n    /**\n     * Writes data to the buffer.\n     * \n     * @param {Uint8Array} data - The data to write.\n     */\n    write(data: Uint8Array): void {\n        this.buf.append(data)\n    }\n\n    /**\n     * Closes the writer. (No operation for VirtualWriter)\n     */\n    close(): void {\n        // do nothing\n    }\n}\n\n/**\n * Index for fetch operations.\n * @type {number}\n */\nlet fetchIndex = 0\n\n/**\n * Stores native fetch data.\n * @type {{ [key: string]: StreamedFetchChunk[] }}\n */\nlet nativeFetchData: { [key: string]: StreamedFetchChunk[] } = {}\n\n/**\n * Interface representing a streamed fetch chunk data.\n * @interface\n */\ninterface StreamedFetchChunkData {\n    type: 'chunk',\n    body: string,\n    id: string\n}\n\n/**\n * Interface representing a streamed fetch header data.\n * @interface\n */\ninterface StreamedFetchHeaderData {\n    type: 'headers',\n    body: { [key: string]: string },\n    id: string,\n    status: number\n}\n\n/**\n * Interface representing a streamed fetch end data.\n * @interface\n */\ninterface StreamedFetchEndData {\n    type: 'end',\n    id: string\n}\n\n/**\n * Type representing a streamed fetch chunk.\n * @typedef {StreamedFetchChunkData | StreamedFetchHeaderData | StreamedFetchEndData} StreamedFetchChunk\n */\ntype StreamedFetchChunk = StreamedFetchChunkData | StreamedFetchHeaderData | StreamedFetchEndData\n\n/**\n * Interface representing a streamed fetch plugin.\n * @interface\n */\ninterface StreamedFetchPlugin {\n    /**\n     * Performs a streamed fetch operation.\n     * @param {Object} options - The options for the fetch operation.\n     * @param {string} options.id - The ID of the fetch operation.\n     * @param {string} options.url - The URL to fetch.\n     * @param {string} options.body - The body of the fetch request.\n     * @param {{ [key: string]: string }} options.headers - The headers of the fetch request.\n     * @returns {Promise<{ error: string, success: boolean }>} - The result of the fetch operation.\n     */\n    streamedFetch(options: { id: string, url: string, body: string, headers: { [key: string]: string } }): Promise<{ \"error\": string, \"success\": boolean }>;\n\n    /**\n     * Adds a listener for the specified event.\n     * @param {string} eventName - The name of the event.\n     * @param {(data: StreamedFetchChunk) => void} listenerFunc - The function to call when the event is triggered.\n     */\n    addListener(eventName: 'streamed_fetch', listenerFunc: (data: StreamedFetchChunk) => void): void;\n}\n\n/**\n * Indicates whether streamed fetch listening is active.\n * @type {boolean}\n */\nlet streamedFetchListening = false\n\n/**\n * The streamed fetch plugin instance.\n * @type {StreamedFetchPlugin | undefined}\n */\nlet capStreamedFetch: StreamedFetchPlugin | undefined\n\n\n/**\n * A class to manage a buffer that can be appended to and deappended from.\n */\nexport class AppendableBuffer {\n    deapended: number = 0\n    #buffer: Uint8Array\n    #byteLength: number = 0\n\n    /**\n     * Creates an instance of AppendableBuffer.\n     */\n    constructor() {\n        this.#buffer = new Uint8Array(128)\n    }\n\n    get buffer(): Uint8Array {\n        return this.#buffer.slice(0, this.#byteLength)\n    }\n\n    /**\n     * Appends data to the buffer.\n     * @param {Uint8Array} data - The data to append.\n     */\n    append(data: Uint8Array) {\n        // New way (faster)\n        const requiredLength = this.#byteLength + data.length\n        if (this.#buffer.byteLength < requiredLength) {\n            let newLength = this.#buffer.byteLength * 2\n            while (newLength < requiredLength) {\n                newLength *= 2\n            }\n            const newBuffer = new Uint8Array(newLength)\n            newBuffer.set(this.#buffer)\n            this.#buffer = newBuffer\n        }\n        this.#buffer.set(data, this.#byteLength)\n        this.#byteLength += data.length\n    }\n\n    /**\n     * Deappends a specified length from the buffer.\n     * @param {number} length - The length to deappend.\n     */\n    deappend(length: number) {\n        this.#buffer = this.#buffer.slice(length)\n        this.deapended += length\n        this.#byteLength -= length\n    }\n\n    /**\n     * Slices the buffer from start to end.\n     * @param {number} start - The start index.\n     * @param {number} end - The end index.\n     * @returns {Uint8Array} - The sliced buffer.\n     */\n    slice(start: number, end: number) {\n        return this.buffer.slice(start - this.deapended, end - this.deapended)\n    }\n\n    /**\n     * Gets the total length of the buffer including deappended length.\n     * @returns {number} - The total length.\n     */\n    length() {\n        return this.#byteLength + this.deapended\n    }\n\n    /**\n     * Clears the buffer.\n     */\n    clear() {\n        this.#buffer = new Uint8Array(128)\n        this.#byteLength = 0\n        this.deapended = 0\n    }\n}\n\n/**\n * Pipes the fetch log to a readable stream.\n * @param {number} fetchLogIndex - The index of the fetch log.\n * @param {ReadableStream<Uint8Array>} readableStream - The readable stream to pipe.\n * @returns {ReadableStream<Uint8Array>} - The new readable stream.\n */\nconst pipeFetchLog = (fetchLogIndex: number, readableStream: ReadableStream<Uint8Array>) => {\n    \n    const splited = readableStream.tee();\n    \n    (async () => {\n        const text = await (new Response(splited[0])).text()\n        fetchLog[fetchLogIndex].response = text\n    })()\n    \n    return splited[1]\n}\n\n/**\n * Fetches data from a given URL using native fetch or through a proxy.\n * @param {string} url - The URL to fetch data from.\n * @param {Object} arg - The arguments for the fetch request.\n * @param {string} arg.body - The body of the request.\n * @param {Object} [arg.headers] - The headers of the request.\n * @param {string} [arg.method=\"POST\"] - The HTTP method of the request.\n * @param {AbortSignal} [arg.signal] - The signal to abort the request.\n * @param {boolean} [arg.useRisuTk] - Whether to use Risu token.\n * @param {string} [arg.chatId] - The chat ID associated with the request.\n * @returns {Promise<Object>} - A promise that resolves to an object containing the response body, headers, and status.\n * @returns {ReadableStream<Uint8Array>} body - The response body as a readable stream.\n * @returns {Headers} headers - The response headers.\n * @returns {number} status - The response status code.\n * @throws {Error} - Throws an error if the request is aborted or if there is an error in the response.\n */\nexport async function fetchNative(url: string, arg: {\n    body?: string | Uint8Array | ArrayBuffer,\n    headers?: { [key: string]: string },\n    method?: \"POST\" | \"GET\" | \"PUT\" | \"DELETE\",\n    signal?: AbortSignal,\n    useRisuTk?: boolean,\n    chatId?: string\n    interceptor?: string\n    requestTimeoutMs?: number\n    networkRoute?: 'auto' | 'local_network'\n}): Promise<Response> {\n    const useInterceptor = !!arg.interceptor\n    if (arg.body === undefined && (arg.method === 'POST' || arg.method === 'PUT')) {\n        throw new Error('Body is required for POST and PUT requests')\n    }\n\n    arg.method = arg.method ?? 'POST'\n\n    const headers = arg.headers ?? {}\n    let realBody: Uint8Array | undefined\n\n    if (arg.method === 'GET' || arg.method === 'DELETE') {\n        realBody = undefined\n    }\n    else if (typeof arg.body === 'string') {\n        let body: string = arg.body\n        if(useInterceptor) {\n            for (const interceptor of bodyIntercepterStore) {\n                try {\n                    body = await interceptor.callback(body, arg.interceptor) || body\n                }\n                catch (e) {\n                    console.error(e)\n                }\n            }\n        }\n        realBody = new TextEncoder().encode(body)\n    }\n    else if (arg.body instanceof Uint8Array) {\n        realBody = arg.body\n    }\n    else if (arg.body instanceof ArrayBuffer) {\n        realBody = new Uint8Array(arg.body)\n    }\n    else {\n        throw new Error('Invalid body type')\n    }\n\n    addFetchLog({\n        body: realBody ? new TextDecoder().decode(realBody) : '',\n        headers: arg.headers,\n        response: 'Streamed Fetch',\n        success: true,\n        url: url,\n        resType: 'stream',\n        chatId: arg.chatId,\n    })\n    const useLocalNetworkRoute = arg.networkRoute === 'local_network' && isLocalNetworkUrl(url)\n    const timeoutSignal = buildTimeoutSignal(arg.signal, arg.requestTimeoutMs)\n    const requestSignal = timeoutSignal.signal\n    const db = getDatabase()\n    let throughProxy = !db.usePlainFetch\n    if (useLocalNetworkRoute) {\n        throughProxy = true\n    }\n\n    try {\n        if (window.userScriptFetch && !throughProxy) {\n            return await window.userScriptFetch(url, {\n                body: realBody as any,\n                headers: headers,\n                method: arg.method,\n                signal: requestSignal\n            })\n        }\n\n        // Local network streaming: try WebSocket proxy job, fallback to /proxy2\n        const useProxyJobWs = useLocalNetworkRoute\n            && arg.interceptor === 'openai_streaming'\n            && arg.method === 'POST'\n        if (useProxyJobWs) {\n            try {\n                return await fetchViaProxyJobWs(url, {\n                    method: arg.method,\n                    headers,\n                    body: realBody,\n                    signal: requestSignal,\n                    requestTimeoutMs: arg.requestTimeoutMs,\n                })\n            } catch (wsErr) {\n                console.warn('[ProxyJobWS] fallback to /proxy2 due to error:', wsErr)\n            }\n        }\n\n        // Local network non-streaming or WS fallback: go through /proxy2 directly\n        if (useLocalNetworkRoute) {\n            return await fetchViaProxy2(url, headers, realBody, {\n                ...arg,\n                signal: requestSignal\n            })\n        }\n\n        // Try direct fetch first (upstream behavior), fall back to proxy on CORS/network error\n        try {\n            return await fetch(url, {\n                body: realBody as any,\n                headers: headers,\n                method: arg.method,\n                signal: requestSignal,\n            })\n        } catch (e) {\n            if (requestSignal?.aborted) throw e\n            return await fetchViaProxy2(url, headers, realBody, {\n                ...arg,\n                signal: requestSignal\n            })\n        }\n    } finally {\n        timeoutSignal.cleanup()\n    }\n}\n\nconst defaultProxyJobHeartbeatSec = 15\n\nasync function fetchViaProxy2(\n    url: string,\n    headers: Record<string, string>,\n    realBody: Uint8Array | undefined,\n    arg: { method?: string, signal?: AbortSignal, useRisuTk?: boolean, requestTimeoutMs?: number }\n): Promise<Response> {\n    const proxyHeaders: Record<string, string> = {\n        \"risu-header\": encodeURIComponent(JSON.stringify(headers)),\n        \"risu-url\": encodeURIComponent(url),\n        \"risu-auth\": await forageStorage.createAuth(),\n        ...(arg.useRisuTk ? { \"x-risu-tk\": \"use\" } : {}),\n        ...(arg.requestTimeoutMs && { \"risu-timeout-ms\": Math.max(1, Math.floor(arg.requestTimeoutMs)).toString() }),\n        ...(DBState?.db?.requestLocation ? { \"risu-location\": DBState.db.requestLocation } : {}),\n    }\n\n    if (realBody) {\n        proxyHeaders[\"Content-Type\"] = headers[\"Content-Type\"] ?? headers[\"content-type\"] ?? \"application/json\"\n    }\n\n    const r = await fetch(`/proxy2`, {\n        body: realBody as any,\n        headers: proxyHeaders,\n        method: arg.method,\n        signal: arg.signal\n    })\n\n    return new Response(r.body, {\n        headers: r.headers,\n        status: r.status\n    })\n}\n\nasync function fetchViaProxyJobWs(url: string, arg: {\n    method: string,\n    headers: Record<string, string>,\n    body?: Uint8Array,\n    signal?: AbortSignal,\n    requestTimeoutMs?: number,\n}): Promise<Response> {\n    const auth = await forageStorage.createAuth()\n    const bodyBase64 = arg.body ? Buffer.from(arg.body).toString('base64') : ''\n\n    const jobRes = await fetch('/proxy-stream-jobs', {\n        method: 'POST',\n        headers: {\n            'Content-Type': 'application/json',\n            'risu-auth': auth,\n        },\n        body: JSON.stringify({\n            url,\n            method: arg.method,\n            headers: arg.headers,\n            bodyBase64,\n            timeoutMs: arg.requestTimeoutMs,\n            heartbeatSec: defaultProxyJobHeartbeatSec,\n        }),\n        signal: arg.signal,\n    })\n\n    if (!jobRes.ok) {\n        throw new Error(`Failed to create proxy stream job: ${jobRes.status} ${await jobRes.text()}`)\n    }\n\n    const { jobId } = await jobRes.json() as { jobId: string }\n    const wsProtocol = location.protocol === 'https:' ? 'wss:' : 'ws:'\n    const wsUrl = `${wsProtocol}//${location.host}/proxy-stream-jobs/${encodeURIComponent(jobId)}/ws?risu-auth=${encodeURIComponent(auth)}`\n\n    return new Promise<Response>((resolve, reject) => {\n        const ws = new WebSocket(wsUrl)\n        let resolved = false\n        let responseStatus = 200\n        let responseHeaders: Record<string, string> = {}\n        let streamController: ReadableStreamDefaultController<Uint8Array> | null = null\n\n        const stream = new ReadableStream<Uint8Array>({\n            start(controller) {\n                streamController = controller\n            },\n            cancel() {\n                ws.close()\n                fetch(`/proxy-stream-jobs/${encodeURIComponent(jobId)}`, {\n                    method: 'DELETE',\n                    headers: { 'risu-auth': auth },\n                }).catch(() => {})\n            }\n        })\n\n        const abortHandler = () => {\n            ws.close()\n            fetch(`/proxy-stream-jobs/${encodeURIComponent(jobId)}`, {\n                method: 'DELETE',\n                headers: { 'risu-auth': auth },\n            }).catch(() => {})\n            if (!resolved) {\n                resolved = true\n                reject(new DOMException('Aborted', 'AbortError'))\n            }\n        }\n\n        if (arg.signal) {\n            if (arg.signal.aborted) {\n                abortHandler()\n                return\n            }\n            arg.signal.addEventListener('abort', abortHandler, { once: true })\n        }\n\n        ws.onmessage = (ev) => {\n            const event = parseProxyJobWsEvent(typeof ev.data === 'string' ? ev.data : '')\n            if (!event) return\n\n            switch (event.type) {\n                case 'job_accepted':\n                case 'ping':\n                    break\n                case 'upstream_headers':\n                    responseStatus = event.status\n                    responseHeaders = event.headers\n                    if (!resolved) {\n                        resolved = true\n                        resolve(new Response(stream, {\n                            status: responseStatus,\n                            headers: responseHeaders,\n                        }))\n                    }\n                    break\n                case 'chunk': {\n                    const bytes = decodeProxyJobWsChunk(event.dataBase64)\n                    streamController?.enqueue(bytes)\n                    break\n                }\n                case 'error': {\n                    const msg = formatProxyStreamErrorMessage(event.status, event.message)\n                    if (!resolved) {\n                        resolved = true\n                        resolve(new Response(msg, {\n                            status: event.status ?? 502,\n                            headers: { 'content-type': 'text/plain' },\n                        }))\n                    }\n                    streamController?.close()\n                    break\n                }\n                case 'done':\n                    streamController?.close()\n                    break\n            }\n        }\n\n        ws.onerror = () => {\n            if (!resolved) {\n                resolved = true\n                reject(new Error('WebSocket connection failed'))\n            }\n        }\n\n        ws.onclose = () => {\n            arg.signal?.removeEventListener('abort', abortHandler)\n            try { streamController?.close() } catch { /* already closed */ }\n            if (!resolved) {\n                resolved = true\n                reject(new Error('WebSocket closed before response'))\n            }\n        }\n    })\n}\n\n/**\n * Converts a ReadableStream of Uint8Array to a text string.\n * \n * @param {ReadableStream<Uint8Array>} stream - The readable stream to convert.\n * @returns {Promise<string>} A promise that resolves to the text content of the stream.\n */\nexport function textifyReadableStream(stream: ReadableStream<Uint8Array>) {\n    return new Response(stream).text()\n}\n\n/**\n * Toggles the fullscreen mode of the document.\n * If the document is currently in fullscreen mode, it exits fullscreen.\n * If the document is not in fullscreen mode, it requests fullscreen with navigation UI hidden.\n */\nexport function toggleFullscreen() {\n    const fullscreenElement = document.fullscreenElement\n    fullscreenElement ? document.exitFullscreen() : document.documentElement.requestFullscreen({\n        navigationUI: \"hide\"\n    })\n}\n\n/**\n * Removes non-Latin characters from a string, replaces multiple spaces with a single space, and trims the string.\n * \n * @param {string} data - The input string to be processed.\n * @returns {string} The processed string with non-Latin characters removed, multiple spaces replaced by a single space, and trimmed.\n */\nexport function trimNonLatin(data: string) {\n    return data.replace(/[^\\x00-\\x7F]/g, \"\")\n        .replace(/ +/g, ' ')\n        .trim()\n}\n\n/**\n * A class that provides a blank writer implementation.\n * \n * This class is used to provide a no-op implementation of a writer, making it compatible with other writer interfaces.\n */\nexport class BlankWriter {\n    constructor() {\n    }\n\n    /**\n     * Initializes the writer.\n     * \n     * This method does nothing and is provided for compatibility with other writer interfaces.\n     */\n    async init() {\n        //do nothing, just to make compatible with other writer\n    }\n\n    /**\n     * Writes data to the writer.\n     * \n     * This method does nothing and is provided for compatibility with other writer interfaces.\n     * \n     * @param {string} key - The key associated with the data.\n     * @param {Uint8Array|string} data - The data to be written.\n     */\n    async write(key: string, data: Uint8Array | string) {\n        //do nothing, just to make compatible with other writer\n    }\n\n    /**\n     * Ends the writing process.\n     * \n     * This method does nothing and is provided for compatibility with other writer interfaces.\n     */\n    async end() {\n        //do nothing, just to make compatible with other writer\n    }\n}\n\nexport async function loadInternalBackup() {\n\n    const keys = await forageStorage.keys()\n    const internalBackups = keys\n        .filter((key) => key.startsWith('database/dbbackup-'))\n        .sort((a, b) => {\n            const aTs = parseInt(a.replace('database/dbbackup-', '').replace('.bin', ''))\n            const bTs = parseInt(b.replace('database/dbbackup-', '').replace('.bin', ''))\n            return bTs - aTs\n        })\n\n    const selectOptions = [\n        'Cancel',\n        ...(internalBackups.map((a) => {\n            return (new Date(parseInt(a.replace('database/dbbackup-', '').replace('dbbackup-', '')) * 100)).toLocaleString()\n        }))\n    ]\n\n    const alertResult = parseInt(\n        await alertSelect(selectOptions)\n    ) - 1\n\n    if (alertResult === -1) {\n        return\n    }\n\n    const selectedBackup = internalBackups[alertResult]\n\n    const data = await forageStorage.getItem(selectedBackup)\n\n    const backupDecoded = await decodeRisuSave(Buffer.from(data) as unknown as Uint8Array)\n    setDatabase(backupDecoded)\n\n    notifySuccess('Loaded backup')\n\n\n\n}\n\n/**\n * A debugging class for performance measurement.\n*/\n\nexport class PerformanceDebugger {\n    kv: { [key: string]: number[] } = {}\n    startTime: number\n    endTime: number\n\n    /**\n     * Starts the timing measurement.\n    */\n    start() {\n        this.startTime = performance.now()\n    }\n\n    /**\n     * Ends the timing measurement and records the time difference.\n     * \n     * @param {string} key - The key to associate with the recorded time.\n    */\n    endAndRecord(key: string) {\n        this.endTime = performance.now()\n        if (!this.kv[key]) {\n            this.kv[key] = []\n        }\n        this.kv[key].push(this.endTime - this.startTime)\n    }\n\n    /**\n     * Ends the timing measurement, records the time difference, and starts a new timing measurement.\n     * \n     * @param {string} key - The key to associate with the recorded time.\n    */\n    endAndRecordAndStart(key: string) {\n        this.endAndRecord(key)\n        this.start()\n    }\n\n    /**\n     * Logs the average time for each key to the console.\n    */\n    log() {\n        let table: { [key: string]: number } = {}\n\n        for (const key in this.kv) {\n            table[key] = this.kv[key].reduce((a, b) => a + b, 0) / this.kv[key].length\n        }\n\n\n        console.table(table)\n    }\n\n    combine(other: PerformanceDebugger) {\n        for (const key in other.kv) {\n            if (!this.kv[key]) {\n                this.kv[key] = []\n            }\n            this.kv[key].push(...other.kv[key])\n        }\n    }\n}\n\nexport function getLanguageCodes() {\n    let languageCodes: {\n        code: string\n        name: string\n    }[] = []\n\n    for (let i = 0x41; i <= 0x5A; i++) {\n        for (let j = 0x41; j <= 0x5A; j++) {\n            languageCodes.push({\n                code: String.fromCharCode(i) + String.fromCharCode(j),\n                name: ''\n            })\n        }\n    }\n\n    languageCodes = languageCodes.map(v => {\n        return {\n            code: v.code.toLocaleLowerCase(),\n            name: new Intl.DisplayNames([\n                DBState.db.language === 'cn' ? 'zh' : DBState.db.language\n            ], {\n                type: 'language',\n                fallback: 'none'\n            }).of(v.code)\n        }\n    }).filter((a) => {\n        return a.name\n    }).sort((a, b) => a.name.localeCompare(b.name))\n\n    return languageCodes\n}\n\nexport function getVersionString(): string {\n    return nodeOnlyVer\n}\n\nexport function toGetter<T extends object>(\n    getterFn: () => T,\n    args?: {\n        //blocks this.children from being accessed\n        restrictChildren:string[]\n    }\n): T {\n\n    const dummyTarget = () => { };\n\n    return new Proxy(dummyTarget, {\n        get(target, prop, receiver) {\n\n            const realInstance = getterFn();\n            \n            if (args?.restrictChildren && args.restrictChildren.includes(prop as string)) {\n                throw new Error(`Access to property '${String(prop)}' is restricted`);\n            }\n\n            if (realInstance === null || realInstance === undefined) {\n                return (realInstance as any)[prop];\n            }\n\n            const value = Reflect.get(realInstance as object, prop);\n\n            if (typeof value === 'function') {\n                return value.bind(realInstance);\n            }\n\n            return value;\n        },\n\n        set(target, prop, value, receiver) {\n\n            if(args?.restrictChildren && args.restrictChildren.includes(prop as string)) {\n                throw new Error(`Access to property '${String(prop)}' is restricted`);\n            }\n            const realInstance = getterFn();\n            return Reflect.set(realInstance as object, prop, value, receiver);\n        },\n\n        has(target, prop) {\n            const realInstance = getterFn();\n            return Reflect.has(realInstance as object, prop);\n        },\n\n        ownKeys(target) {\n            const realInstance = getterFn();\n            return Reflect.ownKeys(realInstance as object);\n        },\n\n        construct(target, argArray, newTarget) {\n            const realInstance = getterFn() as any;\n            return new realInstance(...argArray);\n        },\n\n        deleteProperty(target, prop) {\n            const realInstance = getterFn();\n            return Reflect.deleteProperty(realInstance as object, prop);\n        },\n\n        getPrototypeOf() {\n            const realInstance = getterFn();\n            return Reflect.getPrototypeOf(realInstance as object);\n        }\n    }) as unknown as T;\n}\n\nconst countriesWithAiLaw = new Set<string>([\n\n    // EU\n    // AI Act\n    // https://artificialintelligenceact.eu/\n    \n    \"AT\",\n    \"BE\",\n    \"BG\",\n    \"HR\",\n    \"CY\",\n    \"CZ\",\n    \"DK\",\n    \"EE\",\n    \"FI\",\n    \"FR\",\n    \"DE\",\n    \"EL\",\n    \"GR\",\n    \"HU\",\n    \"IE\",\n    \"IT\",\n    \"LV\",\n    \"LT\",\n    \"LU\",\n    \"MT\",\n    \"NL\",\n    \"PL\",\n    \"PT\",\n    \"RO\",\n    \"SK\",\n    \"SI\",\n    \"ES\",\n    \"SE\",\n\n    //China \n    //Measures for Labeling of AI-Generated Synthetic Content\n    // 关于印发《人工智能生成合成内容标识办法》的通知 \n    // https://www.cac.gov.cn/2025-03/14/c_1743654684782215.htm\n    \"CN\",\n\n    //Although CN Law doesn't apply, just in case\n    \"HK\",\n    \"MO\",\n\n    //TW isn't under mainland china jurisdiction\n    //de facto, de jure in TW law, unlike HK and MO,\n    //So we don't include it for now\n    //\"TW\", \n\n    // Republic of Korea\n    // AI Basic Act\n    // 인공지능 발전과 신뢰 기반 조성 등에 관한 기본법\n    // https://www.law.go.kr/%EB%B2%95%EB%A0%B9/%EC%9D%B8%EA%B3%B5%EC%A7%80%EB%8A%A5%20%EB%B0%9C%EC%A0%84%EA%B3%BC%20%EC%8B%A0%EB%A2%B0%20%EA%B8%B0%EB%B0%98%20%EC%A1%B0%EC%84%B1%20%EB%93%B1%EC%97%90%20%EA%B4%80%ED%95%9C%20%EA%B8%B0%EB%B3%B8%EB%B2%95/(20676,20250121)\n    \"KR\",\n\n    // Vietnam\n    // Digital Tech Law\n    // Luật Công nghệ số\n    \"VN\",\n\n])\n\nexport function aiLawApplies(): boolean {\n\n    //TODO: implement actual logic\n    //lets now assume it always applies\n    //so we don't have legal issues later\n\n    return true\n}\n\nexport function aiWatermarkingLawApplies(): boolean {\n\n    //TODO: implement actual logic\n    //lets now assume it is false for now,\n    //becuase very few countries have it for now\n    return false\n}\n\nexport const chatFoldedState = $state<{\n    data: null| {\n        targetCharacterId: string,\n        targetChatId: string,\n        targetMessageId: string,\n    }\n}>({\n    data: null\n})\n\n//Since its exported, we cannot use $derived here\nexport let chatFoldedStateMessageIndex = $state({\n    index: -1\n})\n\n$effect.root(() => {\n    $effect(() => {\n        if(!chatFoldedState.data){\n            return\n        }\n        const char = DBState.db.characters[selIdState.selId]\n        const chat = char.chats[char.chatPage]\n        if(chatFoldedState.data.targetCharacterId !== char.chaId){\n            chatFoldedState.data = null\n        }\n        if(chatFoldedState.data.targetChatId !== chat.id){\n            chatFoldedState.data = null\n        }\n    })\n\n    $effect(() => {\n        if(chatFoldedState.data === null){\n            chatFoldedStateMessageIndex.index = -1\n            return\n        }\n        const char = DBState.db.characters[selIdState.selId]\n        const chat = char.chats[char.chatPage]\n        const messageIndex = chat.message.findIndex((v) => {\n            return chatFoldedState.data?.targetMessageId === v.chatId\n        })\n        if(messageIndex === -1){\n            console.warn('Target message for folding id' + chatFoldedState.data?.targetMessageId + ' not found')\n            chatFoldedStateMessageIndex.index = -1\n            return\n        }\n        chatFoldedStateMessageIndex.index = messageIndex\n    })\n})\n\nexport function foldChatToMessage(targetMessageIdOrIndex: string | number) {\n    let targetMessageId = ''\n    if (typeof targetMessageIdOrIndex === 'number') {\n        const char = getCurrentCharacter()\n        const chat = char.chats[char.chatPage]\n        const message = chat.message[targetMessageIdOrIndex]\n        targetMessageId = message.chatId\n    }\n    else{\n        targetMessageId = targetMessageIdOrIndex\n    }\n    const char = getCurrentCharacter()\n    const chat = char.chats[char.chatPage]\n    chatFoldedState.data = {\n        targetCharacterId: char.chaId,\n        targetChatId: chat.id,\n        targetMessageId: targetMessageId,\n    }\n}\n\nexport function changeChatTo(IdOrIndex: string | number) {\n    let index = -1\n    if (typeof IdOrIndex === 'number') {\n        index = IdOrIndex\n    }\n\n    if (typeof IdOrIndex === 'string') {\n        const currentCharacter = getCurrentCharacter()\n        index = currentCharacter.chats.findIndex((v) => {\n            return v.id === IdOrIndex\n        })\n    }\n\n    if(index === -1){\n        return\n    }\n\n    chatDeselected.set(false)\n    const char = DBState.db.characters[selIdState.selId]\n    char.chatPage = index\n    const newChat = char.chats[index]\n    if(newChat){\n        if(newChat._placeholder){\n            const capturedIndex = index\n            let cancelled = false\n            loadingOverlayStore.set({ active: true, text: language.loading ?? '', onCancel: () => {\n                cancelled = true\n                chatDeselected.set(true)\n                loadingOverlayStore.set({ active: false, text: '', onCancel: null })\n            }})\n            void ensureChatHydrated(char.chats, capturedIndex, char.chaId).then((hydrated) => {\n                if(cancelled) return\n                if(hydrated && char.chatPage === capturedIndex) loadTogglesFromChat(hydrated)\n            }).catch((e) => {\n                console.error('[changeChatTo] hydration failed:', e)\n            }).finally(() => {\n                if(!cancelled) loadingOverlayStore.set({ active: false, text: '', onCancel: null })\n            })\n        } else {\n            loadTogglesFromChat(newChat)\n        }\n    }\n    ReloadGUIPointer.set(Math.random())\n}\n\nexport function createChatCopyName(originalName: string,type:'Copy'|'Branch'): string {\n    let name = originalName.replaceAll(/\\(((Copy|Branch)( \\d+)?)\\)$/g, '').trim()\n    let copyIndex = 1\n    let newName = `${name} (${type})`\n    const char = getCurrentCharacter()\n    while (char.chats.find((v) => v.name === newName)) {\n        copyIndex++\n        newName = `${name} (${type} ${copyIndex})`\n    }\n    return newName\n}\n","targetVersions":{"pocketrisu":["1.8.1"]}},{"id":"lazy-chat-sync:replace:src:ts:globalApi-svelte-ts:1.9","file":"src/ts/globalApi.svelte.ts","type":"replace","anchor":"import { changeFullscreen, checkNullish, sleep } from \"./util\"\nimport { v4 as uuidv4, v4 } from 'uuid';\nimport { tick } from \"svelte\";\nimport { get } from \"svelte/store\";\nimport streamSaver from 'streamsaver';\nimport { setDatabase, type Database, defaultSdDataFunc, getDatabase, appVer, nodeOnlyVer, getCurrentCharacter, loadTogglesFromChat } from \"./storage/database.svelte\";\nimport { checkRisuUpdate } from \"./update\";\nimport { MobileGUI, botMakerMode, selectedCharID, loadedStore, DBState, LoadingStatusState, selIdState, ReloadGUIPointer, bodyIntercepterStore, loadingOverlayStore, chatDeselected } from \"./stores.svelte\";\nimport { loadPlugins } from \"./plugins/plugins.svelte\";\nimport { alertConfirm, alertError, alertMd, alertNormalWait, alertSelect, alertTOS, waitAlert, notifySuccess, notifyError, notifyInfo } from \"./alert\";\nimport { hasher } from \"./parser/parser.svelte\";\nimport { characterURLImport, hubURL } from \"./characterCards\";\nimport { defaultJailbreak, defaultMainPrompt, oldJailbreak, oldMainPrompt } from \"./storage/defaultPrompts\";\nimport { decodeRisuSave, encodeRisuSaveLegacy, findDangerousChatOps, RisuSaveEncoder, RisuSavePatcher, type toSaveType } from \"./storage/risuSave\";\nimport { isHydrating, saveChatToServer, ensureChatHydrated, chatToStub, classifyChat } from \"./storage/chatStorage\";\nimport { AutoStorage } from \"./storage/autoStorage\";\nimport { ConflictError, type PersistWarning } from \"./storage/nodeStorage\";\nimport { supportsPatchSync } from \"./platform\";\nimport { updateAnimationSpeed } from \"./gui/animation\";\nimport { updateColorScheme, updateTextThemeAndCSS } from \"./gui/colorscheme\";\nimport { language } from \"src/lang\";\nimport { startObserveDom } from \"./observer.svelte\";\nimport { updateGuisize } from \"./gui/guisize\";\nimport { deepTouch } from \"./gui/deepTouch.svelte\";\nimport { updateLorebooks } from \"./characters\";\nimport { initMobileGesture } from \"./hotkey\";\nimport { moduleUpdate } from \"./process/modules\";\nimport { isLocalNetworkUrl } from \"./network/localNetwork\";\nimport { decodeProxyJobWsChunk, formatProxyStreamErrorMessage, parseProxyJobWsEvent } from \"./network/proxyJobWs\";\nimport {\n    createRequestLogScope, recordRequestLog, fetchRequestLogs,\n    type RequestLogCategory, type RequestLogSource, type RequestLogRoute,\n} from \"./requestLog\";\n\nexport const forageStorage = new AutoStorage()\n\nexport async function downloadFile(name: string, dat: Uint8Array | ArrayBuffer | string) {\n    if (typeof (dat) === 'string') {\n        dat = Buffer.from(dat, 'utf-8')\n    }\n    const data = new Uint8Array(dat)\n    const downloadURL = (data: string, fileName: string) => {\n        const a = document.createElement('a')\n        a.href = data\n        a.download = fileName\n        document.body.appendChild(a)\n        a.style.display = 'none'\n        a.click()\n        a.remove()\n    }\n\n    const blob = new Blob([data], { type: 'application/octet-stream' })\n    const url = URL.createObjectURL(blob)\n\n    downloadURL(url, name)\n\n    setTimeout(() => {\n        URL.revokeObjectURL(url)\n    }, 10000)\n}\n\nlet fileCache: {\n    origin: string[], res: (Uint8Array | 'loading' | 'done')[]\n} = {\n    origin: [],\n    res: []\n}\n\nlet pathCache: { [key: string]: string } = {}\nlet checkedPaths: string[] = []\n\nfunction buildTimeoutSignal(signal: AbortSignal | undefined, timeoutMs: number | undefined) {\n    if (!timeoutMs || timeoutMs <= 0) {\n        return {\n            signal,\n            cleanup: () => {}\n        }\n    }\n\n    const controller = new AbortController()\n    const timeoutId = setTimeout(() => controller.abort(), timeoutMs)\n\n    if (signal) {\n        if (signal.aborted) {\n            controller.abort()\n        } else {\n            signal.addEventListener('abort', () => controller.abort(), { once: true })\n        }\n    }\n\n    return {\n        signal: controller.signal,\n        cleanup: () => clearTimeout(timeoutId)\n    }\n}\n\n/**\n * Gets the source URL of a file.\n * \n * @param {string} loc - The location of the file.\n * @returns {Promise<string>} - A promise that resolves to the source URL of the file.\n */\nexport async function getFileSrc(loc: string) {\n    // NodeOnly: return a direct server URL instead of fetching + base64-encoding.\n    // The browser will cache the response using HTTP Cache-Control headers,\n    // so repeated renders (sidebar, chat) cost zero network after first load.\n    if ((globalThis as any).__NODE__) {\n        return `/api/asset/${Buffer.from(loc, 'utf-8').toString('hex')}`\n    }\n    try {\n        if (usingSw) {\n            const encoded = Buffer.from(loc, 'utf-8').toString('hex')\n            let ind = fileCache.origin.indexOf(loc)\n            if (ind === -1) {\n                ind = fileCache.origin.length\n                fileCache.origin.push(loc)\n                fileCache.res.push('loading')\n                try {\n                    const hasCache: boolean = (await (await fetch(\"/sw/check/\" + encoded)).json()).able\n                    if (hasCache) {\n                        fileCache.res[ind] = 'done'\n                        return \"/sw/img/\" + encoded\n                    }\n                    else {\n                        const f: Uint8Array = await forageStorage.getItem(loc) as unknown as Uint8Array\n                        await fetch(\"/sw/register/\" + encoded, {\n                            method: \"POST\",\n                            body: f as any\n                        })\n                        fileCache.res[ind] = 'done'\n                        await sleep(10)\n                    }\n                    return \"/sw/img/\" + encoded\n                } catch (error) {\n\n                }\n            }\n            else {\n                const f = fileCache.res[ind]\n                if (f === 'loading') {\n                    while (fileCache.res[ind] === 'loading') {\n                        await sleep(10)\n                    }\n                }\n                return \"/sw/img/\" + encoded\n            }\n        }\n        else {\n            let ind = fileCache.origin.indexOf(loc)\n            if (ind === -1) {\n                ind = fileCache.origin.length\n                fileCache.origin.push(loc)\n                fileCache.res.push('loading')\n                const f: Uint8Array = await forageStorage.getItem(loc) as unknown as Uint8Array\n                fileCache.res[ind] = f\n                return `data:image/png;base64,${Buffer.from(f).toString('base64')}`\n            }\n            else {\n                const f = fileCache.res[ind]\n                if (f === 'loading') {\n                    while (fileCache.res[ind] === 'loading') {\n                        await sleep(10)\n                    }\n                    return `data:image/png;base64,${Buffer.from(fileCache.res[ind]).toString('base64')}`\n                }\n                return `data:image/png;base64,${Buffer.from(f).toString('base64')}`\n            }\n        }\n    } catch (error) {\n        console.error(error)\n        return ''\n    }\n}\n\n/**\n * Reads an image file and returns its data.\n * \n * @param {string} data - The path to the image file.\n * @returns {Promise<Uint8Array>} - A promise that resolves to the data of the image file.\n */\nexport async function readImage(data: string) {\n    return (await forageStorage.getItem(data) as unknown as Uint8Array)\n}\n\n/**\n * Saves an asset file with the given data, custom ID, and file name.\n * \n * @param {Uint8Array} data - The data of the asset file.\n * @param {string} [customId=''] - The custom ID for the asset file.\n * @param {string} [fileName=''] - The name of the asset file.\n * @returns {Promise<string>} - A promise that resolves to the path of the saved asset file.\n */\nexport async function saveAsset(data: Uint8Array, customId: string = '', fileName: string = '') {\n    let id = ''\n    if (customId !== '') {\n        id = customId\n    }\n    else {\n        try {\n            id = await hasher(data)\n        } catch (error) {\n            id = uuidv4()\n        }\n    }\n    let fileExtension: string = 'png'\n    if (fileName && fileName.split('.').length > 0) {\n        fileExtension = fileName.split('.').pop()\n    }\n    let form = `assets/${id}.${fileExtension}`\n    const replacer = await forageStorage.setItem(form, data)\n    if (replacer) {\n        return replacer\n    }\n    return form\n}\n\n/**\n * Loads an asset file with the given ID.\n * \n * @param {string} id - The ID of the asset file to load.\n * @returns {Promise<Uint8Array>} - A promise that resolves to the data of the loaded asset file.\n */\nexport async function loadAsset(id: string) {\n    return await forageStorage.getItem(id) as unknown as Uint8Array\n}\n\nlet lastSave = ''\nexport let saving = $state({\n    state: false\n})\n\n/**\n * Saves the current state of the database.\n * \n * @returns {Promise<void>} - A promise that resolves when the database has been saved.\n */\nexport let requiresFullEncoderReload = $state({\n    state: false\n})\n\nlet requestImmediateSaveImpl: ((options?: {\n    forceFullWrite?: boolean\n}) => Promise<void> | void) = () => {}\nlet patchSyncBaseline: Database | null = null\n\n// Surfaces server-side persist failures (Stage 1 visibility — see issues.md).\n// The same failure is re-attached on every patch response until cleared, so we\n// dedupe by timestamp to fire one toast per distinct failure event.\nlet lastShownPersistWarningTs = 0\n\nfunction showPersistWarningOnce(warning: PersistWarning) {\n    if (warning.timestamp <= lastShownPersistWarningTs) return\n    lastShownPersistWarningTs = warning.timestamp\n\n    // Stub-flag-loss is the chat-data corruption guard firing at the disk\n    // boundary — this means the persist was REFUSED, not that the save was\n    // safely re-routed. Show the dedicated \"save aborted\" toast so the user\n    // knows their latest changes may not be on disk yet.\n    if (warning.source && warning.source.includes('stub-flag-loss')) {\n        showChatGuardPersistAbortToast()\n        return\n    }\n\n    const sizeStr = warning.attemptedSize != null\n        ? ` (${language.errors.persistFailureAttemptedSize} ${(warning.attemptedSize / 1024 / 1024 / 1024).toFixed(2)}GB)`\n        : ''\n    notifyError(`${language.errors.persistFailureTitle}${sizeStr}`, {\n        description: warning.message,\n        source: 'persist-failure',\n    })\n}\n\n// Throttle the client/server-PATCH chat-guard toast — the underlying root\n// cause may keep firing every 5s save cycle, and we don't want to spam the\n// user. One toast per 5-minute window is enough to surface the situation.\n// Guards 2/3 fall through to a safe full-write so the data IS persisted —\n// the toast is informational, not actionable.\nconst CHAT_GUARD_TOAST_INTERVAL_MS = 5 * 60 * 1000\nlet lastChatGuardToastTs = 0\n\nfunction showChatGuardToastThrottled(source: 'client' | 'server') {\n    const now = Date.now()\n    if (now - lastChatGuardToastTs < CHAT_GUARD_TOAST_INTERVAL_MS) return\n    lastChatGuardToastTs = now\n    notifyError(language.errors.chatGuardTitle, {\n        description: `${language.errors.chatGuardDesc} [${source}]`,\n        source: 'chat-guard',\n    })\n}\n\n// Persist-side guard (guard 1) refuses the disk write outright — there is no\n// fallback path that recovers this cycle's changes automatically. Use a\n// shorter throttle (30s) since this is more severe and actionable: the user\n// should be aware before refreshing that their latest changes might not be\n// persisted. Each separate persist-failure timestamp on the server gates this\n// path via showPersistWarningOnce, so a single corruption won't repeat-toast.\nconst CHAT_GUARD_PERSIST_TOAST_INTERVAL_MS = 30 * 1000\nlet lastChatGuardPersistToastTs = 0\n\n// Verbose chat-guard dump is gated behind a localStorage flag so chronic\n// root-cause environments (e.g. a still-corrupt v1.4.x install) don't flood\n// the console every 5-second save cycle. Toggle with:\n//   localStorage.setItem('risu-chat-guard-debug', '1')\nconst CHAT_GUARD_DEBUG_KEY = 'risu-chat-guard-debug'\nfunction isChatGuardDebugEnabled(): boolean {\n    try {\n        return typeof localStorage !== 'undefined' && localStorage.getItem(CHAT_GUARD_DEBUG_KEY) === '1'\n    } catch {\n        return false\n    }\n}\n\nfunction showChatGuardPersistAbortToast() {\n    const now = Date.now()\n    if (now - lastChatGuardPersistToastTs < CHAT_GUARD_PERSIST_TOAST_INTERVAL_MS) return\n    lastChatGuardPersistToastTs = now\n    notifyError(language.errors.chatGuardPersistTitle, {\n        description: language.errors.chatGuardPersistDesc,\n        source: 'chat-guard-persist',\n    })\n}\n\n// Dev-only preview helpers — bypass throttling so the dev panel always shows\n// the toast immediately. Mirror the production helpers above so any wording\n// or source-tag tweak shows up in the preview without extra synchronization.\nexport function previewChatGuardToast(variant: 'client' | 'server' | 'server-persist') {\n    if (variant === 'server-persist') {\n        notifyError(language.errors.chatGuardPersistTitle, {\n            description: language.errors.chatGuardPersistDesc,\n            source: 'chat-guard-persist',\n        })\n        return\n    }\n    notifyError(language.errors.chatGuardTitle, {\n        description: `${language.errors.chatGuardDesc} [${variant}]`,\n        source: 'chat-guard',\n    })\n}\n\nexport function previewPersistFailureToast() {\n    notifyError(`${language.errors.persistFailureTitle} (${language.errors.persistFailureAttemptedSize} 2.10GB)`, {\n        description: 'preview: simulated kvSet failure (BLOB size > INT_MAX)',\n        source: 'persist-failure',\n    })\n}\n\nexport function requestImmediateSave(options?: {\n    forceFullWrite?: boolean\n}) {\n    return requestImmediateSaveImpl(options)\n}\n\nexport function setPatchSyncBaseline(data: Database | null) {\n    patchSyncBaseline = data ? safeStructuredClone(data) as Database : null\n}\n\nexport async function saveDb() {\n    let changed = false\n    let gotChannel = false\n    const sessionID = v4()\n    let saveInFlight: Promise<void> | null = null\n    const knownChatIdsByCharacter = new Map<string, Set<string>>(\n        (getDatabase()?.characters ?? [])\n            .filter(character => character?.chaId)\n            .map(character => [\n                character.chaId,\n                new Set((character.chats ?? []).map(chat => chat?.id).filter(Boolean)),\n            ])\n    )\n    let channel: BroadcastChannel\n    if (window.BroadcastChannel) {\n        channel = new BroadcastChannel('risu-db')\n    }\n    if (channel) {\n        channel.onmessage = (ev) => {\n            if (ev.data === sessionID) {\n                return\n            }\n            if (!gotChannel) {\n                gotChannel = true\n                alertNormalWait(language.activeTabChange).then(() => {\n                    location.reload()\n                })\n            }\n        }\n    }\n    // Cross-device single-writer lock: mirrors BroadcastChannel behavior\n    // across devices via server-side session check (423 → deactivate).\n    // With reload-on-return below, a write actually reaching 423 means TRUE\n    // simultaneous use of two devices — rare, and the attempted change cannot\n    // be saved — so it stays an explicit blocking modal, never an automatic\n    // reload that would eat the user's action without a word.\n    window.addEventListener('risu-session-deactivated', () => {\n        if (!gotChannel) {\n            gotChannel = true\n            alertNormalWait(language.activeTabChange).then(() => {\n                location.reload()\n            })\n        }\n    })\n\n    // Reload-on-return: while this tab was hidden, another device may have\n    // taken the writer lock and changed data. Check the moment the user comes\n    // BACK — right then nothing is in progress, so a refresh costs nothing —\n    // instead of at the next write, where a 423 would eat the very change\n    // being saved. Only 'stale' reloads (the other device actually wrote);\n    // 'fresh' means our copy is still current and the next user action simply\n    // takes the lock back with no reload at all.\n    let lastLockReturnCheck = 0\n    const checkWriterLockOnReturn = () => {\n        const nowMs = Date.now()\n        if (nowMs - lastLockReturnCheck < 5000) return\n        lastLockReturnCheck = nowMs\n        void (async () => {\n            // Dynamic import: process/index.svelte imports this module, so a\n            // static import here would be circular. Already loaded → instant.\n            const { doingChat } = await import(\"./process/index.svelte\")\n            if (get(doingChat)) return // never yank a running generation\n            const state = await forageStorage.getWriterLockState()\n            if (state !== 'stale') return\n            try { sessionStorage.setItem('risu-session-handoff-reload', '1') } catch { /* toast is best-effort */ }\n            location.reload()\n        })().catch(() => { /* status check failed — do nothing, write path 423 still guards */ })\n    }\n    window.addEventListener('focus', checkWriterLockOnReturn)\n    document.addEventListener('visibilitychange', () => {\n        if (document.visibilityState === 'visible') checkWriterLockOnReturn()\n    })\n\n    // Post-handoff notice from a reload-on-return in the previous page life.\n    // Delayed so the toast container is mounted before it fires.\n    try {\n        if (sessionStorage.getItem('risu-session-handoff-reload')) {\n            sessionStorage.removeItem('risu-session-handoff-reload')\n            setTimeout(() => notifyInfo(language.sessionHandoffReload), 1500)\n        }\n    } catch { /* storage unavailable — skip the notice */ }\n\n    const changeTracker: toSaveType = {\n        character: [],\n        chat: [],\n        root: false,\n        botPreset: false,\n        modules: false,\n        plugins: false,\n        pluginCustomStorage: false\n    }\n\n    let encoder = new RisuSaveEncoder()\n    await encoder.init(getDatabase(), {\n        compression: false\n    })\n\n    let patcher = new RisuSavePatcher()\n    if (supportsPatchSync) {\n        await patcher.init(patchSyncBaseline ?? getDatabase())\n        patchSyncBaseline = null\n    }\n\n    function hasTrackedChanges(toSave: toSaveType) {\n        return !!(\n            toSave.botPreset ||\n            toSave.modules ||\n            toSave.plugins ||\n            toSave.pluginCustomStorage ||\n            toSave.root ||\n            toSave.character.length > 0 ||\n            toSave.chat.length > 0\n        )\n    }\n\n    function takeTrackedChanges() {\n        const toSave = safeStructuredClone(changeTracker)\n        changeTracker.character = changeTracker.character.length === 0 ? [] : [changeTracker.character[0]]\n        changeTracker.chat = changeTracker.chat.length === 0 ? [] : [changeTracker.chat[0]]\n        changeTracker.root = false\n        changeTracker.botPreset = false\n        changeTracker.modules = false\n        changeTracker.plugins = false\n        changeTracker.pluginCustomStorage = false\n        return toSave\n    }\n\n    async function flushServerDbKeepalive() {\n        try {\n            fetch('/api/db/flush', {\n                method: 'POST',\n                keepalive: true,\n                credentials: 'same-origin'\n            }).catch(() => {})\n        } catch {\n            // ignore best-effort flush failures\n        }\n    }\n\n    $effect.root(() => {\n\n        let selIdState = $state(0)\n        let knownCharacterIds = new Set<string>((getDatabase()?.characters ?? []).map((character) => character?.chaId).filter(Boolean))\n        let didInitRootEffect = false\n        let didInitBotPresetEffect = false\n        let didInitModulesEffect = false\n        let didInitPluginsEffect = false\n        let didInitPluginStorageEffect = false\n        let didInitGeneralEffect = false\n        let trackedActiveChatKey = ''\n\n        const debounceTime = 500; // 500 milliseconds\n        let saveTimeout: ReturnType<typeof setTimeout> | null = null;\n\n        selectedCharID.subscribe((v) => {\n            selIdState = v\n        })\n\n        function saveTimeoutExecute() {\n            if (saveTimeout) {\n                clearTimeout(saveTimeout);\n            }\n            saveTimeout = setTimeout(() => {\n                changed = true;\n            }, debounceTime);\n        }\n\n        // Start a best-effort save immediately when the page is hidden/unloaded.\n        function flushImmediate() {\n            if (saveTimeout) {\n                clearTimeout(saveTimeout);\n                saveTimeout = null;\n            }\n            changed = true;\n            void triggerSave({\n                skipBroadcast: true,\n            })\n            void flushServerDbKeepalive()\n        }\n        document.addEventListener('visibilitychange', () => {\n            if (document.visibilityState === 'hidden') flushImmediate();\n        });\n        window.addEventListener('pagehide', flushImmediate);\n\n        $effect(() => {\n            for (const key in DBState.db) {\n                if (\n                    key !== 'characters' && key !== 'botPresets' && key !== 'modules' &&\n                    key !== 'plugins' && key !== 'pluginCustomStorage'\n                ) {\n                    deepTouch(DBState.db[key])\n                }\n            }\n            if (!didInitRootEffect) {\n                didInitRootEffect = true\n                return\n            }\n            changeTracker.root = true\n            saveTimeoutExecute()\n        })\n        $effect(() => {\n            DBState.db.botPresetsId\n            try { deepTouch(DBState.db.botPresets) } catch (e) {\n                console.warn('[Save] deepTouch(botPresets) failed:', e)\n                return\n            }\n            if (!didInitBotPresetEffect) {\n                didInitBotPresetEffect = true\n                return\n            }\n            changeTracker.botPreset = true\n            saveTimeoutExecute()\n        })\n        $effect(() => {\n            try { deepTouch(DBState.db.modules) } catch (e) {\n                console.warn('[Save] deepTouch(modules) failed:', e)\n                return\n            }\n            if (!didInitModulesEffect) {\n                didInitModulesEffect = true\n                return\n            }\n            changeTracker.modules = true\n            saveTimeoutExecute()\n        })\n        $effect(() => {\n            deepTouch(DBState.db.plugins)\n            if (!didInitPluginsEffect) {\n                didInitPluginsEffect = true\n                return\n            }\n            changeTracker.plugins = true\n            saveTimeoutExecute()\n        })\n        $effect(() => {\n            deepTouch(DBState.db.pluginCustomStorage)\n            if (!didInitPluginStorageEffect) {\n                didInitPluginStorageEffect = true\n                return\n            }\n            changeTracker.pluginCustomStorage = true\n            saveTimeoutExecute()\n        })\n        $effect(() => {\n            const currentCharacterIds = (DBState?.db?.characters ?? []).map((character) => character?.chaId).filter(Boolean)\n            deepTouch(currentCharacterIds)\n\n            const currentCharacterIdSet = new Set<string>(currentCharacterIds)\n            for (const previousCharacterId of knownCharacterIds) {\n                if (!currentCharacterIdSet.has(previousCharacterId)) {\n                    changeTracker.character = [previousCharacterId, ...changeTracker.character.filter((v) => v !== previousCharacterId)]\n                }\n            }\n            knownCharacterIds = currentCharacterIdSet\n\n            if (DBState?.db?.characters?.[selIdState]) {\n                for (const key in DBState.db.characters[selIdState]) {\n                    // Exclude chats — chat changes are tracked via chat-specific server save, not database.bin\n                    if (key !== 'chats') {\n                        deepTouch(DBState.db.characters[selIdState][key])\n                    }\n                }\n                // Track stub metadata and chat ordering for database.bin persistence.\n                deepTouch(DBState.db.characters[selIdState].chats.map(c => ({\n                    id: c.id,\n                    name: c.name,\n                    lastDate: c.lastDate,\n                    folderId: c.folderId,\n                })))\n                if (changeTracker.character[0] !== DBState.db.characters[selIdState]?.chaId) {\n                    changeTracker.character.unshift(DBState.db.characters[selIdState]?.chaId)\n                }\n            }\n            if (!didInitGeneralEffect) {\n                didInitGeneralEffect = true\n                changeTracker.character = []\n                changeTracker.chat = []\n                return\n            }\n            saveTimeoutExecute()\n        })\n        $effect(() => {\n            const activeChar = DBState?.db?.characters?.[selIdState]\n            const activeChat = activeChar?.chats?.[activeChar?.chatPage]\n            if (activeChat) {\n                deepTouch(activeChat)\n            }\n\n            const activeChaId = activeChar?.chaId ?? ''\n            const activeChatId = activeChat?.id ?? ''\n            const activeKey = activeChaId && activeChatId ? `${activeChaId}|${activeChatId}` : ''\n\n            if (!activeKey) {\n                trackedActiveChatKey = ''\n                return\n            }\n\n            // Selecting a different chat establishes a new baseline; only later edits are dirty.\n            if (trackedActiveChatKey !== activeKey) {\n                trackedActiveChatKey = activeKey\n                return\n            }\n\n            if (isHydrating(activeChaId, activeChatId)) {\n                return\n            }\n\n            if (\n                changeTracker.chat[0]?.[0] !== activeChaId ||\n                changeTracker.chat[0]?.[1] !== activeChatId\n            ) {\n                changeTracker.chat.unshift([activeChaId, activeChatId])\n            }\n            saveTimeoutExecute()\n        })\n    })\n\n    function requeueTrackedChanges(toSave: toSaveType) {\n        changeTracker.character = [...new Set([...toSave.character, ...changeTracker.character])]\n        const chatSeen = new Set<string>()\n        changeTracker.chat = [...toSave.chat, ...changeTracker.chat].filter((chatPair) => {\n            const key = `${chatPair?.[0] ?? ''}|${chatPair?.[1] ?? ''}`\n            if (chatSeen.has(key)) {\n                return false\n            }\n            chatSeen.add(key)\n            return true\n        })\n        changeTracker.botPreset = changeTracker.botPreset || toSave.botPreset\n        changeTracker.modules = changeTracker.modules || toSave.modules\n        changeTracker.plugins = changeTracker.plugins || toSave.plugins\n        changeTracker.pluginCustomStorage = changeTracker.pluginCustomStorage || toSave.pluginCustomStorage\n        changeTracker.root = changeTracker.root || toSave.root\n    }\n\n    function collectChatsToPersist(db: Database, toSave: toSaveType): [string, string][] {\n        const chatsToPersist: [string, string][] = []\n        const seen = new Set<string>()\n        const pushChat = (chaId: string, chatId: string) => {\n            if (!chaId || !chatId) return\n            const key = `${chaId}|${chatId}`\n            if (seen.has(key)) return\n            seen.add(key)\n            chatsToPersist.push([chaId, chatId])\n        }\n\n        for (const [chaId, chatId] of toSave.chat) {\n            pushChat(chaId, chatId)\n        }\n\n        for (const chaId of toSave.character) {\n            const char = db.characters.find(c => c?.chaId === chaId)\n            if (!char) continue\n            const knownChatIds = knownChatIdsByCharacter.get(chaId) ?? new Set<string>()\n            for (const chat of char.chats ?? []) {\n                if (!chat?.id || chat._placeholder) continue\n                if (!knownChatIds.has(chat.id)) {\n                    pushChat(chaId, chat.id)\n                }\n            }\n        }\n\n        return chatsToPersist\n    }\n\n    function updateKnownChatsAfterSuccessfulSave(db: Database, toSave: toSaveType) {\n        for (const chaId of toSave.character) {\n            const char = db.characters.find(c => c?.chaId === chaId)\n            if (!char) {\n                knownChatIdsByCharacter.delete(chaId)\n                continue\n            }\n            knownChatIdsByCharacter.set(\n                chaId,\n                new Set((char.chats ?? []).map(chat => chat?.id).filter(Boolean))\n            )\n        }\n\n        for (const [chaId, chatId] of toSave.chat) {\n            if (!chaId || !chatId) continue\n            const knownChatIds = knownChatIdsByCharacter.get(chaId) ?? new Set<string>()\n            knownChatIds.add(chatId)\n            knownChatIdsByCharacter.set(chaId, knownChatIds)\n        }\n    }\n\n    async function rebaseTrackedLocalChangesOnLatestServerDb(conflictEtag: string | null, db: Database, toSave: toSaveType) {\n        forageStorage.setDbEtag(conflictEtag ?? null)\n        const latestData = await forageStorage.getItem('database/database.bin') as unknown as Uint8Array\n        if (latestData && latestData.length > 0) {\n            const latestDb = await decodeRisuSave(latestData) as Database\n            const mergedDb = safeStructuredClone(latestDb) as Database\n            const localDb = safeStructuredClone(db) as Database\n\n            for (const key in localDb) {\n                if (\n                    key !== 'characters' && key !== 'botPresets' && key !== 'modules' &&\n                    key !== 'plugins' && key !== 'pluginCustomStorage'\n                ) {\n                    mergedDb[key] = safeStructuredClone(localDb[key])\n                }\n            }\n\n            if (toSave.botPreset) {\n                mergedDb.botPresets = safeStructuredClone(localDb.botPresets)\n                mergedDb.botPresetsId = localDb.botPresetsId\n            }\n            if (toSave.modules) {\n                mergedDb.modules = safeStructuredClone(localDb.modules)\n            }\n\n            const trackedCharIds = new Set<string>(toSave.character.filter(Boolean))\n            for (const trackedChat of toSave.chat) {\n                if (trackedChat?.[0]) {\n                    trackedCharIds.add(trackedChat[0])\n                }\n            }\n            const mergedCharacters = Array.isArray(mergedDb.characters) ? mergedDb.characters : []\n            const localCharacters = Array.isArray(localDb.characters) ? localDb.characters : []\n\n            for (const charId of trackedCharIds) {\n                const localChar = localCharacters.find((char) => char?.chaId === charId)\n                const mergedIndex = mergedCharacters.findIndex((char) => char?.chaId === charId)\n                if (localChar) {\n                    const clonedLocalChar = safeStructuredClone(localChar)\n                    if (mergedIndex >= 0) {\n                        mergedCharacters[mergedIndex] = clonedLocalChar\n                    }\n                    else {\n                        mergedCharacters.push(clonedLocalChar)\n                    }\n                }\n                else if (mergedIndex >= 0) {\n                    mergedCharacters.splice(mergedIndex, 1)\n                }\n            }\n            mergedDb.characters = mergedCharacters\n            const mergedBaseline = safeStructuredClone(mergedDb) as Database\n            setDatabase(mergedDb)\n\n            encoder = new RisuSaveEncoder()\n            await encoder.init(getDatabase(), {\n                compression: false\n            })\n            if (supportsPatchSync) {\n                patcher = new RisuSavePatcher()\n                await patcher.init(mergedBaseline)\n            }\n        }\n        requeueTrackedChanges(toSave)\n        changed = true\n    }\n\n    async function persistTrackedChanges(\n        toSave: toSaveType,\n        options?: {\n            forceFullWrite?: boolean\n            skipBroadcast?: boolean\n        }\n    ): Promise<'saved' | 'retry' | 'noop'> {\n        if (gotChannel) {\n            // Data is saved in another tab.\n            await sleep(1000)\n            return 'noop'\n        }\n        if (channel && !options?.skipBroadcast) {\n            channel.postMessage(sessionID)\n        }\n\n        const db = getDatabase()\n        if (!db.characters) {\n            await sleep(1000)\n            return 'noop'\n        }\n\n        // ── Save changed chat content to server ─────────────────────────\n        const failedChats: [string, string][] = []\n        for (const [chaId, chatId] of collectChatsToPersist(db, toSave)) {\n            const char = db.characters.find(c => c.chaId === chaId)\n            if (!char) continue\n            const chatIndex = char.chats.findIndex(c => c.id === chatId)\n            if (chatIndex === -1) continue\n            const chat = char.chats[chatIndex]\n            // Skip placeholders — they have no real data to save\n            if (!chat || chat._placeholder) continue\n            try {\n                await saveChatToServer(chaId, chatIndex, chatId, chat)\n            } catch (e) {\n                console.error(`[Save] Failed to save chat ${chaId}/${chatId}:`, e)\n                failedChats.push([chaId, chatId])\n            }\n        }\n        if (failedChats.length > 0) {\n            throw new Error(`Failed to save ${failedChats.length} chat${failedChats.length === 1 ? '' : 's'}`)\n        }\n\n        // ── database.bin: exclude chat payload (stubs only via encoder) ──\n        await encoder.set(db, safeStructuredClone(toSave))\n        const encoded = encoder.encode()\n        if (!encoded) {\n            await sleep(1000)\n            return 'noop'\n        }\n        const dbData = new Uint8Array(encoded)\n\n        let saved = false\n        let newEtag: string | undefined\n\n        if (supportsPatchSync && !options?.forceFullWrite) {\n            const patchData = await patcher.set(db, safeStructuredClone(toSave))\n            // Refuse to send patches that would corrupt server-side lazy chats.\n            // chatToStub strips chats to metadata before diffing, so the only\n            // way these ops appear is a baseline desync. Falling through to a\n            // full write rebuilds the server's stub view from scratch and\n            // resyncs the patcher baseline. The console.error is the primary\n            // breadcrumb for tracking down the unknown root cause.\n            const dangerous = findDangerousChatOps(patchData.patch)\n            if (dangerous.length > 0) {\n                // Always log a one-line summary so production environments\n                // see enough to file a bug report. The rich dump below is\n                // gated behind a localStorage flag — chronic loops would\n                // otherwise dump 5 console.errors every 5s save cycle.\n                const sampleOps = dangerous.slice(0, 3).map(d => `${d.op} ${d.path}`).join(', ')\n                console.error(\n                    `[Save] Patcher emitted ${dangerous.length} chat-internal field op(s) — `\n                    + `falling back to full write. sample: ${sampleOps}`\n                    + ` (verbose dump: localStorage.setItem('${CHAT_GUARD_DEBUG_KEY}', '1') then reproduce)`\n                )\n                showChatGuardToastThrottled('client')\n\n                if (isChatGuardDebugEnabled()) {\n                // ── Diagnostic dump for unknown root cause ────────────────\n                // chatToStub is supposed to strip every chat down to 6\n                // metadata fields before the diff. If non-stub fields end\n                // up in patch ops, something slipped past it. Dump enough\n                // shape info to figure out which side of the diff carries\n                // the contraband (baseline vs current) and what flags the\n                // chat object has.\n                const affectedChats: Record<string, any> = {}\n                const seen = new Set<string>()\n                const baselineCharsLen = (patcher as any).lastSyncedDb?.characters?.length ?? -1\n                const currentCharsLen = db.characters?.length ?? -1\n\n                const summarize = (c: any) => {\n                    if (c == null) return null\n                    const keys = Object.keys(c)\n                    // Per-key shape: which fields are strings vs arrays vs objects vs primitives\n                    const keyShapes: Record<string, string> = {}\n                    for (const k of keys) {\n                        const v = c[k]\n                        if (v === null) keyShapes[k] = 'null'\n                        else if (Array.isArray(v)) keyShapes[k] = `Array(${v.length})`\n                        else if (typeof v === 'object') keyShapes[k] = `Object(${Object.keys(v).length})`\n                        else keyShapes[k] = `${typeof v}=${typeof v === 'string' && v.length > 30 ? v.slice(0, 30) + '…' : JSON.stringify(v)}`\n                    }\n                    return {\n                        keys,                                  // full key list, not just length\n                        keyShapes,                             // per-key type/preview\n                        classification: classifyChat(c),\n                        _stub: c._stub,\n                        _placeholder: c._placeholder,\n                        hasMessage: Array.isArray(c.message),\n                        messageLen: Array.isArray(c.message) ? c.message.length : null,\n                        id: c.id,\n                        name: c.name,\n                        // Type fingerprints help identify Svelte $state proxies\n                        // or other wrapper objects that might bypass deep clone.\n                        ctor: c?.constructor?.name,\n                        isFrozen: Object.isFrozen(c),\n                        isProxy: typeof c === 'object' && c !== null && (c as any)?.[Symbol.toStringTag] !== undefined,\n                    }\n                }\n\n                // Re-run chatToStub on the current chat to see what the patcher\n                // would have produced. If this still has non-stub fields, the\n                // bug is INSIDE chatToStub's isChatStub short-circuit (chat\n                // already has `_stub: true` but isn't actually a stub).\n                const stubReplay = (c: any) => {\n                    if (c == null) return null\n                    try {\n                        const result = chatToStub(c)\n                        return summarize(result)\n                    } catch (e) {\n                        return { error: String(e) }\n                    }\n                }\n\n                for (const op of dangerous) {\n                    const m = op.path.match(/^\\/characters\\/(\\d+)\\/chats\\/(\\d+)\\//)\n                    if (!m) continue\n                    const key = `${m[1]}/${m[2]}`\n                    if (seen.has(key)) continue\n                    seen.add(key)\n                    if (seen.size > 5) break\n                    const ci = +m[1], chi = +m[2]\n                    const baselineChar = (patcher as any).lastSyncedDb?.characters?.[ci]\n                    const currentChar = db.characters?.[ci]\n                    const baselineChat = baselineChar?.chats?.[chi]\n                    const currentChat = currentChar?.chats?.[chi]\n                    const opsForThisChat = dangerous.filter(d => d.path.startsWith(`/characters/${ci}/chats/${chi}/`))\n                    // Reference identity: same object? same chats array? same chat slot?\n                    const refIdentity = {\n                        sameCharacter: baselineChar === currentChar,\n                        sameChatsArray: baselineChar?.chats === currentChar?.chats,\n                        sameChatSlot: baselineChat === currentChat,\n                    }\n                    affectedChats[key] = {\n                        characterContext: {\n                            baselineChaId: baselineChar?.chaId,\n                            currentChaId: currentChar?.chaId,\n                            chaIdsMatch: baselineChar?.chaId === currentChar?.chaId,\n                            baselineChatsLen: baselineChar?.chats?.length ?? -1,\n                            currentChatsLen: currentChar?.chats?.length ?? -1,\n                            refIdentity,\n                        },\n                        baselineChat: summarize(baselineChat),\n                        currentChat: summarize(currentChat),\n                        // The crucial diagnostic: if this still leaks message etc,\n                        // chatToStub's isChatStub fast-path was the offender.\n                        currentAfterChatToStub: stubReplay(currentChat),\n                        baselineAfterChatToStub: stubReplay(baselineChat),\n                        opsForThisChat,\n                    }\n                }\n\n                // Distribution of stub/placeholder flags across the affected\n                // characters' chats — useful to spot wholesale corruption\n                // (e.g. a plugin replacing the entire chats array with\n                // _stub-tagged objects).\n                const charsDistribution: Record<string, any> = {}\n                for (const k of Array.from(seen).slice(0, 3)) {\n                    const ci = +k.split('/')[0]\n                    const baselineChats = (patcher as any).lastSyncedDb?.characters?.[ci]?.chats ?? []\n                    const currentChats = db.characters?.[ci]?.chats ?? []\n                    const tally = (chats: any[]) => {\n                        const t = { total: chats.length, stub: 0, placeholder: 0, hybrid: 0, full: 0, neither: 0 }\n                        for (const c of chats) {\n                            if (!c) continue\n                            const isStub = c._stub === true\n                            const isPh = c._placeholder === true\n                            const hasMsg = Array.isArray(c.message)\n                            if (isStub && hasMsg) t.hybrid++\n                            else if (isStub) t.stub++\n                            else if (isPh) t.placeholder++\n                            else if (hasMsg) t.full++\n                            else t.neither++\n                        }\n                        return t\n                    }\n                    charsDistribution[`character[${ci}]`] = {\n                        baseline: tally(baselineChats),\n                        current: tally(currentChats),\n                    }\n                }\n\n                let activeCharID = -1\n                try { selectedCharID.subscribe(v => { activeCharID = v })() } catch {}\n                console.error('[Save:guard-debug] context:', {\n                    baselineCharsLen,\n                    currentCharsLen,\n                    selectedCharID: activeCharID,\n                    totalDangerousOps: dangerous.length,\n                    uniqueAffectedChats: seen.size,\n                })\n                console.error('[Save:guard-debug] all dangerous ops:', dangerous)\n                console.error('[Save:guard-debug] affected chats (baseline / current / stubReplay):', affectedChats)\n                console.error('[Save:guard-debug] chats[] distribution per affected character:', charsDistribution)\n                }\n                // Leave saved=false so the full-write path below kicks in.\n            } else {\n                const patchResult = await forageStorage.patchItem('database/database.bin', patchData)\n                saved = patchResult.success\n                if (patchResult.etag) {\n                    newEtag = patchResult.etag\n                    forageStorage.setDbEtag(patchResult.etag)\n                }\n                if (patchResult.persistWarning) {\n                    showPersistWarningOnce(patchResult.persistWarning)\n                }\n                // Server's chat-internal-field guard rejected the patch — the\n                // client-side guard above missed this case. Surface to user\n                // and continue to the full-write fallback below.\n                if (patchResult.chatGuardRejected) {\n                    console.error('[Save] Server rejected patch — chat-internal field ops detected server-side')\n                    showChatGuardToastThrottled('server')\n                }\n            }\n        }\n        if (!saved) {\n            if (supportsPatchSync && !options?.forceFullWrite) {\n                console.warn('[Save] Patch conflict, falling through to full write...')\n            }\n            try {\n                const currentEtag = forageStorage.getDbEtag()\n                await forageStorage.setItem('database/database.bin', dbData, currentEtag ?? undefined)\n            } catch (conflictErr) {\n                if (conflictErr instanceof ConflictError) {\n                    console.warn('[Save] Full-write conflict detected, rebasing tracked local changes on latest server DB...')\n                    await rebaseTrackedLocalChangesOnLatestServerDb(conflictErr.currentEtag ?? null, db, toSave)\n                    await sleep(Math.min(500 * (savetrys + 1), 3000))\n                    return 'retry'\n                }\n                throw conflictErr\n            }\n\n            // Re-init patcher from the data we just wrote so both sides\n            // share the same baseline (including setDatabase defaults).\n            if (supportsPatchSync) {\n                const decodedDb = await decodeRisuSave(dbData)\n                await patcher.init(decodedDb)\n            }\n        }\n\n        updateKnownChatsAfterSuccessfulSave(db, toSave)\n\n        if (newEtag) {\n            forageStorage.setDbEtag(newEtag)\n        }\n\n\n        return 'saved'\n    }\n\n    async function triggerSave(options?: {\n        forceFullWrite?: boolean\n        skipBroadcast?: boolean\n    }) {\n        if (saveInFlight) {\n            return saveInFlight\n        }\n\n        const toSave = takeTrackedChanges()\n        if (!hasTrackedChanges(toSave) && !options?.forceFullWrite) {\n            return\n        }\n\n        saveInFlight = (async () => {\n            saving.state = true\n            try {\n                const result = await persistTrackedChanges(toSave, options)\n                if (result === 'saved') {\n                    savetrys = 0\n                } else if (result === 'noop' && hasTrackedChanges(toSave)) {\n                    requeueTrackedChanges(toSave)\n                    changed = true\n                }\n            } catch (error) {\n                requeueTrackedChanges(toSave)\n                savetrys += 1\n                if (savetrys > 4) {\n                    alertError(error)\n                    savetrys = 0\n                }\n                else {\n                    console.error(error)\n                    await sleep(Math.min(500 * savetrys, 3000))\n                    changed = true\n                }\n            } finally {\n                saving.state = false\n                saveInFlight = null\n            }\n        })()\n\n        return saveInFlight\n    }\n\n    requestImmediateSaveImpl = async (options) => {\n        changed = true\n        await tick()\n        await triggerSave({\n            forceFullWrite: options?.forceFullWrite,\n        })\n    }\n\n    let savetrys = 0\n    while (true) {\n        if (!changed) {\n            await sleep(200)\n            continue\n        }\n        changed = false\n        if (requiresFullEncoderReload.state) {\n            encoder = new RisuSaveEncoder()\n            await encoder.init(getDatabase(), {\n                compression: false,\n                skipRemoteSavingOnCharacters: false\n            })\n            requiresFullEncoderReload.state = false\n        }\n        await triggerSave()\n        await sleep(100)\n    }\n}\n\n/**\n * Retrieves the database backups.\n * \n * @returns {Promise<number[]>} - A promise that resolves to an array of backup timestamps.\n */\nexport async function getDbBackups(currentDbSize?: number) {\n    const keys = await forageStorage.keys()\n\n    const backups = keys\n        .filter(key => key.startsWith('database/dbbackup-'))\n        .map(key => parseInt(key.slice(18, -4)))\n        .sort((a, b) => b - a);\n\n    const BACKUP_BUDGET = 500 * 1024 * 1024 // 500MB\n    const maxBackups = currentDbSize\n        ? Math.min(20, Math.max(3, Math.floor(BACKUP_BUDGET / currentDbSize)))\n        : 20\n\n    while (backups.length > maxBackups) {\n        const last = backups.pop()\n        await forageStorage.removeItem(`database/dbbackup-${last}.bin`)\n    }\n    return backups\n}\n\nlet usingSw = false\n\nexport function setUsingSw(value: boolean) {\n    usingSw = value\n}\n\n\nconst knownHostes = [\"localhost\", \"127.0.0.1\", \"0.0.0.0\"];\n\n/**\n * Interface representing the arguments for the global fetch function.\n * \n * @interface GlobalFetchArgs\n * @property {boolean} [plainFetchForce] - Whether to force plain fetch.\n * @property {any} [body] - The body of the request.\n * @property {{ [key: string]: string }} [headers] - The headers of the request.\n * @property {boolean} [rawResponse] - Whether to return the raw response.\n * @property {'POST' | 'GET'} [method] - The HTTP method to use.\n * @property {AbortSignal} [abortSignal] - The abort signal to cancel the request.\n * @property {boolean} [useRisuToken] - Whether to use the Risu token.\n * @property {string} [chatId] - The chat ID associated with the request.\n */\ninterface GlobalFetchArgs {\n    plainFetchForce?: boolean;\n    plainFetchDeforce?: boolean;\n    body?: any;\n    headers?: { [key: string]: string };\n    rawResponse?: boolean;\n    method?: 'POST' | 'GET';\n    abortSignal?: AbortSignal;\n    useRisuToken?: boolean;\n    chatId?: string;\n    interceptor?: string;\n    requestTimeoutMs?: number;\n    networkRoute?: 'auto' | 'local_network';\n    /** Request-log classification. Defaults to the neutral 'other'/'other';\n     *  LLM call sites pass 'llm' plus the issuing part of the app so the log's\n     *  default filter and the usage statistics can tell them apart. */\n    logCategory?: RequestLogCategory;\n    logSource?: RequestLogSource;\n    logModel?: string;\n}\n\n/**\n * Interface representing the result of the global fetch function.\n * \n * @interface GlobalFetchResult\n * @property {boolean} ok - Whether the request was successful.\n * @property {any} data - The data returned from the request.\n * @property {{ [key: string]: string }} headers - The headers returned from the request.\n */\ninterface GlobalFetchResult {\n    ok: boolean;\n    data: any;\n    headers: { [key: string]: string };\n    status: number;\n}\n\n/**\n * Performs a global fetch request.\n * \n * @param {string} url - The URL to fetch.\n * @param {GlobalFetchArgs} [arg={}] - The arguments for the fetch request.\n * @returns {Promise<GlobalFetchResult>} - The result of the fetch request.\n */\nexport async function globalFetch(url: string, arg: GlobalFetchArgs = {}): Promise<GlobalFetchResult> {\n    try {\n        const db = getDatabase();\n\n        if (arg.abortSignal?.aborted) { return { ok: false, data: 'aborted', headers: {}, status: 400 }; }\n\n        const urlHost = new URL(url).hostname\n        const useLocalNetworkRoute = arg.networkRoute === 'local_network' && isLocalNetworkUrl(url)\n        const forcePlainFetch = ((knownHostes.includes(urlHost)) || db.usePlainFetch || arg.plainFetchForce) && !arg.plainFetchDeforce && !useLocalNetworkRoute\n\n        if(arg.interceptor){\n            for (const interceptor of bodyIntercepterStore) {\n                try {\n                    arg.body = await interceptor.callback(arg.body, arg.interceptor) || arg.body\n                }\n                catch (e) {\n                    console.error(e)\n                }\n            }\n        }\n\n        const timeoutSignal = buildTimeoutSignal(arg.abortSignal, arg.requestTimeoutMs)\n        const requestArg = timeoutSignal.signal === arg.abortSignal\n            ? arg\n            : { ...arg, abortSignal: timeoutSignal.signal }\n\n        try {\n            if (useLocalNetworkRoute) {\n                return await fetchWithProxy(url, requestArg);\n            }\n\n            if (forcePlainFetch) {\n                return await fetchWithPlainFetch(url, requestArg);\n            }\n            //userScriptFetch is provided by userscript\n            if (window.userScriptFetch && !arg.plainFetchDeforce) {\n                return await fetchWithUSFetch(url, requestArg);\n            }\n            return await fetchWithProxy(url, requestArg);\n        } finally {\n            timeoutSignal.cleanup()\n        }\n\n    } catch (error) {\n        console.error(error);\n        return { ok: false, data: `${error}`, headers: {}, status: 400 };\n    }\n}\n\n/**\n * Records a completed globalFetch request in the server request log.\n *\n * @param {any} response - The response data.\n * @param {boolean} success - Indicates if the fetch was successful.\n * @param {string} url - The URL of the fetch request.\n * @param {GlobalFetchArgs} arg - The arguments for the fetch request.\n * @param {number} started - Epoch ms when the request was issued, for duration.\n */\nfunction addFetchLogInGlobalFetch(response: any, success: boolean, url: string, arg: GlobalFetchArgs, status: number | undefined, started: number) {\n    // Opt-in, same rule as fetchNative: untagged call sites (TTS polling,\n    // asset downloads, plugin traffic) are not worth a persisted row.\n    if (!arg.logCategory) return\n    const stringify = (value: unknown) => {\n        try {\n            return typeof value === 'string' ? value : JSON.stringify(value, null, 2)\n        } catch {\n            return `${value}`\n        }\n    }\n    recordRequestLog({\n        timestamp: started,\n        category: arg.logCategory ?? 'other',\n        source: arg.logSource ?? 'other',\n        chatId: arg.chatId,\n        model: arg.logModel,\n        url,\n        method: arg.method ?? 'POST',\n        status,\n        success,\n        streaming: false,\n        durationMs: Date.now() - started,\n        requestHeaders: stringify(arg.headers ?? {}),\n        requestBody: stringify(arg.body),\n        responseBody: stringify(response),\n    })\n}\n\n/**\n * Performs a fetch request using plain fetch.\n * \n * @param {string} url - The URL to fetch.\n * @param {GlobalFetchArgs} arg - The arguments for the fetch request.\n * @returns {Promise<GlobalFetchResult>} - The result of the fetch request.\n */\nasync function fetchWithPlainFetch(url: string, arg: GlobalFetchArgs): Promise<GlobalFetchResult> {\n    try {\n        const started = Date.now();\n        const headers = { 'Content-Type': 'application/json', ...arg.headers };\n        const response = await fetch(new URL(url), { body: JSON.stringify(arg.body), headers, method: arg.method ?? \"POST\", signal: arg.abortSignal });\n        const data = arg.rawResponse ? new Uint8Array(await response.arrayBuffer()) : await response.json();\n        const ok = response.ok && response.status >= 200 && response.status < 300;\n        addFetchLogInGlobalFetch(data, ok, url, arg, response.status, started);\n        return { ok, data, headers: Object.fromEntries(response.headers), status: response.status };\n    } catch (error) {\n        return { ok: false, data: `${error}`, headers: {}, status: 400 };\n    }\n}\n\n/**\n * Performs a fetch request using userscript provided fetch.\n * \n * @param {string} url - The URL to fetch.\n * @param {GlobalFetchArgs} arg - The arguments for the fetch request.\n * @returns {Promise<GlobalFetchResult>} - The result of the fetch request.\n */\nasync function fetchWithUSFetch(url: string, arg: GlobalFetchArgs): Promise<GlobalFetchResult> {\n    try {\n        const started = Date.now();\n        const headers = { 'Content-Type': 'application/json', ...arg.headers };\n        const response = await userScriptFetch(url, { body: JSON.stringify(arg.body), headers, method: arg.method ?? \"POST\", signal: arg.abortSignal });\n        const data = arg.rawResponse ? new Uint8Array(await response.arrayBuffer()) : await response.json();\n        const ok = response.ok && response.status >= 200 && response.status < 300;\n        addFetchLogInGlobalFetch(data, ok, url, arg, response.status, started);\n        return { ok, data, headers: Object.fromEntries(response.headers), status: response.status };\n    } catch (error) {\n        return { ok: false, data: `${error}`, headers: {}, status: 400 };\n    }\n}\n\n/**\n * Performs a fetch request using a proxy.\n * \n * @param {string} url - The URL to fetch.\n * @param {GlobalFetchArgs} arg - The arguments for the fetch request.\n * @returns {Promise<GlobalFetchResult>} - The result of the fetch request.\n */\nasync function fetchWithProxy(url: string, arg: GlobalFetchArgs): Promise<GlobalFetchResult> {\n    try {\n        const started = Date.now();\n        const furl = `/proxy2`;\n        arg.headers[\"Content-Type\"] ??= arg.body instanceof URLSearchParams ? \"application/x-www-form-urlencoded\" : \"application/json\";\n        const headers = {\n            \"risu-header\": encodeURIComponent(JSON.stringify(arg.headers)),\n            \"risu-url\": encodeURIComponent(url),\n            \"Content-Type\": arg.body instanceof URLSearchParams ? \"application/x-www-form-urlencoded\" : \"application/json\",\n            ...(arg.useRisuToken && { \"x-risu-tk\": \"use\" }),\n            ...(DBState?.db?.requestLocation && { \"risu-location\": DBState.db.requestLocation }),\n        };\n\n        // Add risu-auth header for Node.js server\n        headers[\"risu-auth\"] = await forageStorage.createAuth();\n\n        const body = arg.body instanceof URLSearchParams ? arg.body.toString() : JSON.stringify(arg.body);\n\n        const response = await fetch(furl, { body, headers, method: arg.method ?? \"POST\", signal: arg.abortSignal });\n        const isSuccess = response.ok && response.status >= 200 && response.status < 300;\n\n        if (arg.rawResponse) {\n            const data = new Uint8Array(await response.arrayBuffer());\n            addFetchLogInGlobalFetch(\"Uint8Array Response\", isSuccess, url, arg, response.status, started);\n            return { ok: isSuccess, data, headers: Object.fromEntries(response.headers), status: response.status };\n        }\n\n        const text = await response.text();\n        try {\n            const data = JSON.parse(text);\n            addFetchLogInGlobalFetch(data, isSuccess, url, arg, response.status, started);\n            return { ok: isSuccess, data, headers: Object.fromEntries(response.headers), status: response.status };\n        } catch (error) {\n            const errorMsg = text.startsWith('<!DOCTYPE') ? \"Responded HTML. Is your URL, API key, and password correct?\" : text;\n            addFetchLogInGlobalFetch(text, false, url, arg, response.status, started);\n            return { ok: false, data: errorMsg, headers: Object.fromEntries(response.headers), status: response.status };\n        }\n    } catch (error) {\n        return { ok: false, data: `${error}`, headers: {}, status: 400 };\n    }\n}\n\n/**\n * Regular expression to match backslashes.\n * \n * @constant {RegExp}\n */\nconst re = /\\\\/g;\n\n/**\n * Gets the basename of a given path.\n * \n * @param {string} data - The path to get the basename from.\n * @returns {string} - The basename of the path.\n */\nexport function getBasename(data: string) {\n    const splited = data.replace(re, '/').split('/');\n    const lasts = splited[splited.length - 1];\n    return lasts;\n}\n\n/**\n * Retrieves uncleanable resources from the database.\n * \n * @param {Database} db - The database to retrieve uncleanable resources from.\n * @param {'basename'|'pure'} [uptype='basename'] - The type of uncleanable resources to retrieve.\n * @returns {string[]} - An array of uncleanable resources.\n */\nexport function getUncleanables(db: Database, uptype: 'basename' | 'pure' = 'basename') {\n    const uncleanable = new Set<string>();\n\n    /**\n     * Adds a resource to the uncleanable list if it is not already included.\n     * \n     * @param {string} data - The resource to add.\n     */\n    function addUncleanable(data: string) {\n        if (!data) {\n            return;\n        }\n        if (data === '') {\n            return;\n        }\n        const bn = uptype === 'basename' ? getBasename(data) : data;\n        uncleanable.add(bn);\n    }\n\n    addUncleanable(db.customBackground);\n    addUncleanable(db.userIcon);\n    // Uploaded notification sounds. Preset-id values (e.g. \"bell\") are not\n    // asset paths, so they add a harmless basename that matches no stored asset.\n    addUncleanable(db.messageSound);\n    addUncleanable(db.translateSound);\n    if (db.customSounds) {\n        for (const s of db.customSounds) {\n            addUncleanable(s.path);\n        }\n    }\n\n    for (const cha of db.characters) {\n        if (cha.image) {\n            addUncleanable(cha.image);\n        }\n        if (cha.emotionImages) {\n            for (const em of cha.emotionImages) {\n                addUncleanable(em[1]);\n            }\n        }\n        if (cha.additionalAssets) {\n            for (const em of cha.additionalAssets) {\n                addUncleanable(em[1]);\n            }\n        }\n        if (cha.vits) {\n            const keys = Object.keys(cha.vits.files);\n            for (const key of keys) {\n                const vit = cha.vits.files[key];\n                addUncleanable(vit);\n            }\n        }\n        if (cha.ccAssets) {\n            for (const asset of cha.ccAssets) {\n                addUncleanable(asset.uri);\n            }\n        }\n    }\n\n    if (db.modules) {\n        for (const module of db.modules) {\n            const assets = module.assets\n            if (assets) {\n                for (const asset of assets) {\n                    addUncleanable(asset[1])\n                }\n            }\n            if(module.icon){\n                addUncleanable(module.icon)\n            }\n        }\n    }\n\n    if (db.personas) {\n        db.personas.map((v) => {\n            addUncleanable(v.icon);\n\n            if(v.embeddedModule){\n                const assets = v.embeddedModule.assets\n                if (assets) {\n                    for (const asset of assets) {\n                        addUncleanable(asset[1])\n                    }\n                }\n                if(v.embeddedModule.icon){\n                    addUncleanable(v.embeddedModule.icon)\n                }\n            }\n        });\n    }\n\n    if (db.characterOrder) {\n        db.characterOrder.forEach((item) => {\n            if (typeof item === 'object' && 'imgFile' in item) {\n                addUncleanable(item.imgFile);\n            }\n        })\n    }\n    return Array.from(uncleanable);\n}\n\n\n/**\n * Replaces database resources with the provided replacer object.\n * \n * @param {Database} db - The database object containing resources to be replaced.\n * @param {{[key: string]: string}} replacer - An object mapping original resource keys to their replacements.\n * @returns {Database} - The updated database object with replaced resources.\n */\nexport function replaceDbResources(db: Database, replacer: { [key: string]: string }): Database {\n    /**\n     * Replaces a given data string with its corresponding value from the replacer object.\n     * \n     * @param {string} data - The data string to be replaced.\n     * @returns {string} - The replaced data string or the original data if no replacement is found.\n     */\n    function replaceData(data: string): string {\n        if (!data) {\n            return data;\n        }\n        return replacer[data] ?? data;\n    }\n\n    db.customBackground = replaceData(db.customBackground);\n    db.userIcon = replaceData(db.userIcon);\n    db.messageSound = replaceData(db.messageSound);\n    db.translateSound = replaceData(db.translateSound);\n    if (db.customSounds) {\n        for (const s of db.customSounds) {\n            s.path = replaceData(s.path);\n        }\n    }\n\n    for (const cha of db.characters) {\n        if (cha.image) {\n            cha.image = replaceData(cha.image);\n        }\n        if (cha.emotionImages) {\n            for (let i = 0; i < cha.emotionImages.length; i++) {\n                cha.emotionImages[i][1] = replaceData(cha.emotionImages[i][1]);\n            }\n        }\n        if (cha.additionalAssets) {\n            for (let i = 0; i < cha.additionalAssets.length; i++) {\n                cha.additionalAssets[i][1] = replaceData(cha.additionalAssets[i][1]);\n            }\n        }\n    }\n    return db;\n}\n\n/**\n * Checks and updates the character order in the database.\n * Ensures that all characters are properly ordered and removes any invalid entries.\n */\nexport function checkCharOrder() {\n    let db = getDatabase()\n    db.characterOrder = db.characterOrder ?? []\n    let ordered = []\n    for (let i = 0; i < db.characterOrder.length; i++) {\n        const folder = db.characterOrder[i]\n        if (typeof (folder) !== 'string' && folder) {\n            for (const f of folder.data) {\n                ordered.push(f)\n            }\n        }\n        if (typeof (folder) === 'string') {\n            ordered.push(folder)\n        }\n    }\n\n    let charIdList: string[] = []\n\n    for (let i = 0; i < db.characters.length; i++) {\n        const char = db.characters[i]\n        const charId = char.chaId\n        if (!char.trashTime) {\n            charIdList.push(charId)\n        }\n        if (!ordered.includes(charId)) {\n            if (charId !== '§temp' && charId !== '§playground' && !char.trashTime) {\n                db.characterOrder.push(charId)\n            }\n        }\n    }\n\n\n    for (let i = 0; i < db.characterOrder.length; i++) {\n        const data = db.characterOrder[i]\n        if (typeof (data) !== 'string') {\n            if (!data) {\n                db.characterOrder.splice(i, 1)\n                i--;\n                continue\n            }\n            if (data.data.length === 0) {\n                db.characterOrder.splice(i, 1)\n                i--;\n                continue\n            }\n            for (let i2 = 0; i2 < data.data.length; i2++) {\n                const data2 = data.data[i2]\n                if (!charIdList.includes(data2)) {\n                    data.data.splice(i2, 1)\n                    i2--;\n                }\n            }\n            db.characterOrder[i] = data\n        }\n        else {\n            if (!charIdList.includes(data)) {\n                db.characterOrder.splice(i, 1)\n                i--;\n            }\n        }\n    }\n\n\n}\n\n/**\n * Retrieves the most recent request logs. Kept for the plugin API (v3\n * getFetchLogs), which has always been Promise-returning, so moving the\n * storage server-side is invisible to plugins.\n */\nexport async function getFetchLogs(limit = 20) {\n    return await fetchRequestLogs({ limit, bodies: true })\n}\n\n/**\n * Opens a URL in the appropriate environment.\n * \n * @param {string} url - The URL to open.\n */\nexport function openURL(url: string) {\n    window.open(url, \"_blank\")\n}\n\n/**\n * Converts FormData to a URL-encoded string.\n * \n * @param {FormData} formData - The FormData to convert.\n * @returns {string} The URL-encoded string.\n */\nfunction formDataToString(formData: FormData): string {\n    const params: string[] = [];\n\n    for (const [name, value] of formData.entries()) {\n        params.push(`${encodeURIComponent(name)}=${encodeURIComponent(value.toString())}`);\n    }\n\n    return params.join('&');\n}\n\n/**\n * Class representing a local writer.\n */\nexport class LocalWriter {\n    writer: WritableStreamDefaultWriter\n\n    /**\n     * Initializes the writer.\n     * \n     * @param {string} [name='Binary'] - The name of the file.\n     * @param {string[]} [ext=['bin']] - The file extensions.\n     * @returns {Promise<boolean>} - A promise that resolves to a boolean indicating success.\n     */\n    async init(name = 'Binary', ext = ['bin']): Promise<boolean> {\n        const writableStream = streamSaver.createWriteStream(name + '.' + ext[0])\n        this.writer = writableStream.getWriter()\n        return true\n    }\n\n    /**\n     * Writes backup data to the file.\n     * \n     * @param {string} name - The name of the backup.\n     * @param {Uint8Array} data - The data to write.\n     */\n    async writeBackup(name: string, data: Uint8Array): Promise<void> {\n        const encodedName = new TextEncoder().encode(getBasename(name))\n        const nameLength = new Uint32Array([encodedName.byteLength])\n        await this.writer.write(new Uint8Array(nameLength.buffer))\n        await this.writer.write(encodedName)\n        const dataLength = new Uint32Array([data.byteLength])\n        await this.writer.write(new Uint8Array(dataLength.buffer))\n        await this.writer.write(data)\n    }\n\n    /**\n     * Writes data to the file.\n     * \n     * @param {Uint8Array} data - The data to write.\n     */\n    async write(data: Uint8Array): Promise<void> {\n        await this.writer.write(data)\n    }\n\n    /**\n     * Closes the writer.\n     */\n    async close(): Promise<void> {\n        await this.writer.close()\n    }\n}\n\n/**\n * Class representing a virtual writer.\n */\nexport class VirtualWriter {\n    buf = new AppendableBuffer()\n\n    /**\n     * Writes data to the buffer.\n     * \n     * @param {Uint8Array} data - The data to write.\n     */\n    write(data: Uint8Array): void {\n        this.buf.append(data)\n    }\n\n    /**\n     * Closes the writer. (No operation for VirtualWriter)\n     */\n    close(): void {\n        // do nothing\n    }\n}\n\n/**\n * Index for fetch operations.\n * @type {number}\n */\nlet fetchIndex = 0\n\n/**\n * Stores native fetch data.\n * @type {{ [key: string]: StreamedFetchChunk[] }}\n */\nlet nativeFetchData: { [key: string]: StreamedFetchChunk[] } = {}\n\n/**\n * Interface representing a streamed fetch chunk data.\n * @interface\n */\ninterface StreamedFetchChunkData {\n    type: 'chunk',\n    body: string,\n    id: string\n}\n\n/**\n * Interface representing a streamed fetch header data.\n * @interface\n */\ninterface StreamedFetchHeaderData {\n    type: 'headers',\n    body: { [key: string]: string },\n    id: string,\n    status: number\n}\n\n/**\n * Interface representing a streamed fetch end data.\n * @interface\n */\ninterface StreamedFetchEndData {\n    type: 'end',\n    id: string\n}\n\n/**\n * Type representing a streamed fetch chunk.\n * @typedef {StreamedFetchChunkData | StreamedFetchHeaderData | StreamedFetchEndData} StreamedFetchChunk\n */\ntype StreamedFetchChunk = StreamedFetchChunkData | StreamedFetchHeaderData | StreamedFetchEndData\n\n/**\n * Interface representing a streamed fetch plugin.\n * @interface\n */\ninterface StreamedFetchPlugin {\n    /**\n     * Performs a streamed fetch operation.\n     * @param {Object} options - The options for the fetch operation.\n     * @param {string} options.id - The ID of the fetch operation.\n     * @param {string} options.url - The URL to fetch.\n     * @param {string} options.body - The body of the fetch request.\n     * @param {{ [key: string]: string }} options.headers - The headers of the fetch request.\n     * @returns {Promise<{ error: string, success: boolean }>} - The result of the fetch operation.\n     */\n    streamedFetch(options: { id: string, url: string, body: string, headers: { [key: string]: string } }): Promise<{ \"error\": string, \"success\": boolean }>;\n\n    /**\n     * Adds a listener for the specified event.\n     * @param {string} eventName - The name of the event.\n     * @param {(data: StreamedFetchChunk) => void} listenerFunc - The function to call when the event is triggered.\n     */\n    addListener(eventName: 'streamed_fetch', listenerFunc: (data: StreamedFetchChunk) => void): void;\n}\n\n/**\n * Indicates whether streamed fetch listening is active.\n * @type {boolean}\n */\nlet streamedFetchListening = false\n\n/**\n * The streamed fetch plugin instance.\n * @type {StreamedFetchPlugin | undefined}\n */\nlet capStreamedFetch: StreamedFetchPlugin | undefined\n\n\n/**\n * A class to manage a buffer that can be appended to and deappended from.\n */\nexport class AppendableBuffer {\n    deapended: number = 0\n    #buffer: Uint8Array\n    #byteLength: number = 0\n\n    /**\n     * Creates an instance of AppendableBuffer.\n     */\n    constructor() {\n        this.#buffer = new Uint8Array(128)\n    }\n\n    get buffer(): Uint8Array {\n        return this.#buffer.slice(0, this.#byteLength)\n    }\n\n    /**\n     * Appends data to the buffer.\n     * @param {Uint8Array} data - The data to append.\n     */\n    append(data: Uint8Array) {\n        // New way (faster)\n        const requiredLength = this.#byteLength + data.length\n        if (this.#buffer.byteLength < requiredLength) {\n            let newLength = this.#buffer.byteLength * 2\n            while (newLength < requiredLength) {\n                newLength *= 2\n            }\n            const newBuffer = new Uint8Array(newLength)\n            newBuffer.set(this.#buffer)\n            this.#buffer = newBuffer\n        }\n        this.#buffer.set(data, this.#byteLength)\n        this.#byteLength += data.length\n    }\n\n    /**\n     * Deappends a specified length from the buffer.\n     * @param {number} length - The length to deappend.\n     */\n    deappend(length: number) {\n        this.#buffer = this.#buffer.slice(length)\n        this.deapended += length\n        this.#byteLength -= length\n    }\n\n    /**\n     * Slices the buffer from start to end.\n     * @param {number} start - The start index.\n     * @param {number} end - The end index.\n     * @returns {Uint8Array} - The sliced buffer.\n     */\n    slice(start: number, end: number) {\n        return this.buffer.slice(start - this.deapended, end - this.deapended)\n    }\n\n    /**\n     * Gets the total length of the buffer including deappended length.\n     * @returns {number} - The total length.\n     */\n    length() {\n        return this.#byteLength + this.deapended\n    }\n\n    /**\n     * Clears the buffer.\n     */\n    clear() {\n        this.#buffer = new Uint8Array(128)\n        this.#byteLength = 0\n        this.deapended = 0\n    }\n}\n\n/**\n * Fetches data from a given URL using native fetch or through a proxy.\n * @param {string} url - The URL to fetch data from.\n * @param {Object} arg - The arguments for the fetch request.\n * @param {string} arg.body - The body of the request.\n * @param {Object} [arg.headers] - The headers of the request.\n * @param {string} [arg.method=\"POST\"] - The HTTP method of the request.\n * @param {AbortSignal} [arg.signal] - The signal to abort the request.\n * @param {boolean} [arg.useRisuTk] - Whether to use Risu token.\n * @param {string} [arg.chatId] - The chat ID associated with the request.\n * @returns {Promise<Object>} - A promise that resolves to an object containing the response body, headers, and status.\n * @returns {ReadableStream<Uint8Array>} body - The response body as a readable stream.\n * @returns {Headers} headers - The response headers.\n * @returns {number} status - The response status code.\n * @throws {Error} - Throws an error if the request is aborted or if there is an error in the response.\n */\nexport interface FetchNativeArgs {\n    body?: string | Uint8Array | ArrayBuffer,\n    headers?: { [key: string]: string },\n    method?: \"POST\" | \"GET\" | \"PUT\" | \"DELETE\",\n    signal?: AbortSignal,\n    useRisuTk?: boolean,\n    chatId?: string\n    interceptor?: string\n    requestTimeoutMs?: number\n    networkRoute?: 'auto' | 'local_network'\n    /** Request-log classification; see GlobalFetchArgs for the same fields. */\n    logCategory?: RequestLogCategory\n    logSource?: RequestLogSource\n    logModel?: string\n    /** Reports which transport was actually used. Fires regardless of\n     *  logCategory, so a caller that logs at a higher level (the model-preset\n     *  path) can record the true route instead of guessing. */\n    onLogRoute?: (route: RequestLogRoute) => void\n}\n\nexport async function fetchNative(url: string, arg: FetchNativeArgs): Promise<Response> {\n    // Logging is OPT-IN: only call sites that tag a category are recorded.\n    // Logging everything that passes through here was actively harmful —\n    // ComfyUI polls /history once a second, /view returns a PNG that would be\n    // text-decoded and stored, an MCP SSE connection stays open for the whole\n    // session, and makeProxiedFetch routes the model-preset path through here,\n    // which produced a second, untagged row for every preset request.\n    if (!arg.logCategory) {\n        return fetchNativeRaw(url, arg, { onRoute: arg.onLogRoute })\n    }\n    // Logging wraps the transport rather than living inside it: fetchNativeRaw\n    // returns from several branches (userscript / WS proxy job / proxy2 /\n    // direct), and the response body is a stream that must be tee'd exactly\n    // once. The scope handles both, and assembles the streamed text so the log\n    // records the real response instead of a \"Streamed Fetch\" placeholder.\n    const scope = createRequestLogScope({\n        category: arg.logCategory ?? 'other',\n        source: arg.logSource ?? 'other',\n        chatId: arg.chatId,\n        model: arg.logModel,\n        streaming: true,\n    })\n    const logged = scope.wrap(((_input: RequestInfo | URL, _init?: RequestInit) =>\n        fetchNativeRaw(url, arg, {\n            onRealBody: (body) => scope.setRequestBody(body),\n            onRoute: (route) => { scope.setRoute(route); arg.onLogRoute?.(route) },\n        })\n    ) as typeof fetch)\n    try {\n        return await logged(url, {\n            method: arg.method ?? 'POST',\n            headers: arg.headers,\n            body: arg.body as BodyInit | undefined,\n        })\n    } finally {\n        // Fire-and-forget: close() waits for the tee'd body to finish\n        // assembling, which outlives this return for a streamed response.\n        void scope.close()\n    }\n}\n\nasync function fetchNativeRaw(url: string, arg: FetchNativeArgs, hooks?: {\n    onRealBody?: (body: string) => void,\n    onRoute?: (route: RequestLogRoute) => void,\n}): Promise<Response> {\n    const useInterceptor = !!arg.interceptor\n    if (arg.body === undefined && (arg.method === 'POST' || arg.method === 'PUT')) {\n        throw new Error('Body is required for POST and PUT requests')\n    }\n\n    arg.method = arg.method ?? 'POST'\n\n    const headers = arg.headers ?? {}\n    let realBody: Uint8Array | undefined\n\n    if (arg.method === 'GET' || arg.method === 'DELETE') {\n        realBody = undefined\n    }\n    else if (typeof arg.body === 'string') {\n        let body: string = arg.body\n        if(useInterceptor) {\n            for (const interceptor of bodyIntercepterStore) {\n                try {\n                    body = await interceptor.callback(body, arg.interceptor) || body\n                }\n                catch (e) {\n                    console.error(e)\n                }\n            }\n        }\n        realBody = new TextEncoder().encode(body)\n    }\n    else if (arg.body instanceof Uint8Array) {\n        realBody = arg.body\n    }\n    else if (arg.body instanceof ArrayBuffer) {\n        realBody = new Uint8Array(arg.body)\n    }\n    else {\n        throw new Error('Invalid body type')\n    }\n\n    // The logged body is the one actually sent — after any body interceptor\n    // rewrote it — which is why it is reported from here rather than from the\n    // wrapper's view of arg.body.\n    hooks?.onRealBody?.(realBody ? new TextDecoder().decode(realBody) : '')\n    const useLocalNetworkRoute = arg.networkRoute === 'local_network' && isLocalNetworkUrl(url)\n    const timeoutSignal = buildTimeoutSignal(arg.signal, arg.requestTimeoutMs)\n    const requestSignal = timeoutSignal.signal\n    const db = getDatabase()\n    let throughProxy = !db.usePlainFetch\n    if (useLocalNetworkRoute) {\n        throughProxy = true\n    }\n\n    try {\n        if (window.userScriptFetch && !throughProxy) {\n            hooks?.onRoute?.('direct')\n            return await window.userScriptFetch(url, {\n                body: realBody as any,\n                headers: headers,\n                method: arg.method,\n                signal: requestSignal\n            })\n        }\n\n        // Local network streaming: try WebSocket proxy job, fallback to /proxy2\n        const useProxyJobWs = useLocalNetworkRoute\n            && arg.interceptor === 'openai_streaming'\n            && arg.method === 'POST'\n        if (useProxyJobWs) {\n            try {\n                const res = await fetchViaProxyJobWs(url, {\n                    method: arg.method,\n                    headers,\n                    body: realBody,\n                    signal: requestSignal,\n                    requestTimeoutMs: arg.requestTimeoutMs,\n                })\n                hooks?.onRoute?.('proxy')\n                return res\n            } catch (wsErr) {\n                console.warn('[ProxyJobWS] fallback to /proxy2 due to error:', wsErr)\n            }\n        }\n\n        // Local network non-streaming or WS fallback: go through /proxy2 directly\n        if (useLocalNetworkRoute) {\n            hooks?.onRoute?.('proxy')\n            return await fetchViaProxy2(url, headers, realBody, {\n                ...arg,\n                signal: requestSignal\n            })\n        }\n\n        // Try direct fetch first (upstream behavior), fall back to proxy on CORS/network error\n        try {\n            const res = await fetch(url, {\n                body: realBody as any,\n                headers: headers,\n                method: arg.method,\n                signal: requestSignal,\n            })\n            hooks?.onRoute?.('direct')\n            return res\n        } catch (e) {\n            if (requestSignal?.aborted) throw e\n            // The route is only known once the direct attempt has failed, which\n            // is why it is reported here rather than guessed up front.\n            hooks?.onRoute?.('proxy')\n            return await fetchViaProxy2(url, headers, realBody, {\n                ...arg,\n                signal: requestSignal\n            })\n        }\n    } finally {\n        timeoutSignal.cleanup()\n    }\n}\n\nconst defaultProxyJobHeartbeatSec = 15\n\nasync function fetchViaProxy2(\n    url: string,\n    headers: Record<string, string>,\n    realBody: Uint8Array | undefined,\n    arg: { method?: string, signal?: AbortSignal, useRisuTk?: boolean, requestTimeoutMs?: number }\n): Promise<Response> {\n    const proxyHeaders: Record<string, string> = {\n        \"risu-header\": encodeURIComponent(JSON.stringify(headers)),\n        \"risu-url\": encodeURIComponent(url),\n        \"risu-auth\": await forageStorage.createAuth(),\n        ...(arg.useRisuTk ? { \"x-risu-tk\": \"use\" } : {}),\n        ...(arg.requestTimeoutMs && { \"risu-timeout-ms\": Math.max(1, Math.floor(arg.requestTimeoutMs)).toString() }),\n        ...(DBState?.db?.requestLocation ? { \"risu-location\": DBState.db.requestLocation } : {}),\n    }\n\n    if (realBody) {\n        proxyHeaders[\"Content-Type\"] = headers[\"Content-Type\"] ?? headers[\"content-type\"] ?? \"application/json\"\n    }\n\n    const r = await fetch(`/proxy2`, {\n        body: realBody as any,\n        headers: proxyHeaders,\n        method: arg.method,\n        signal: arg.signal\n    })\n\n    return new Response(r.body, {\n        headers: r.headers,\n        status: r.status\n    })\n}\n\nasync function fetchViaProxyJobWs(url: string, arg: {\n    method: string,\n    headers: Record<string, string>,\n    body?: Uint8Array,\n    signal?: AbortSignal,\n    requestTimeoutMs?: number,\n}): Promise<Response> {\n    const auth = await forageStorage.createAuth()\n    const bodyBase64 = arg.body ? Buffer.from(arg.body).toString('base64') : ''\n\n    const jobRes = await fetch('/proxy-stream-jobs', {\n        method: 'POST',\n        headers: {\n            'Content-Type': 'application/json',\n            'risu-auth': auth,\n        },\n        body: JSON.stringify({\n            url,\n            method: arg.method,\n            headers: arg.headers,\n            bodyBase64,\n            timeoutMs: arg.requestTimeoutMs,\n            heartbeatSec: defaultProxyJobHeartbeatSec,\n        }),\n        signal: arg.signal,\n    })\n\n    if (!jobRes.ok) {\n        throw new Error(`Failed to create proxy stream job: ${jobRes.status} ${await jobRes.text()}`)\n    }\n\n    const { jobId } = await jobRes.json() as { jobId: string }\n    const wsProtocol = location.protocol === 'https:' ? 'wss:' : 'ws:'\n    const wsUrl = `${wsProtocol}//${location.host}/proxy-stream-jobs/${encodeURIComponent(jobId)}/ws?risu-auth=${encodeURIComponent(auth)}`\n\n    return new Promise<Response>((resolve, reject) => {\n        const ws = new WebSocket(wsUrl)\n        let resolved = false\n        let responseStatus = 200\n        let responseHeaders: Record<string, string> = {}\n        let streamController: ReadableStreamDefaultController<Uint8Array> | null = null\n\n        const stream = new ReadableStream<Uint8Array>({\n            start(controller) {\n                streamController = controller\n            },\n            cancel() {\n                ws.close()\n                fetch(`/proxy-stream-jobs/${encodeURIComponent(jobId)}`, {\n                    method: 'DELETE',\n                    headers: { 'risu-auth': auth },\n                }).catch(() => {})\n            }\n        })\n\n        const abortHandler = () => {\n            ws.close()\n            fetch(`/proxy-stream-jobs/${encodeURIComponent(jobId)}`, {\n                method: 'DELETE',\n                headers: { 'risu-auth': auth },\n            }).catch(() => {})\n            if (!resolved) {\n                resolved = true\n                reject(new DOMException('Aborted', 'AbortError'))\n            }\n        }\n\n        if (arg.signal) {\n            if (arg.signal.aborted) {\n                abortHandler()\n                return\n            }\n            arg.signal.addEventListener('abort', abortHandler, { once: true })\n        }\n\n        ws.onmessage = (ev) => {\n            const event = parseProxyJobWsEvent(typeof ev.data === 'string' ? ev.data : '')\n            if (!event) return\n\n            switch (event.type) {\n                case 'job_accepted':\n                case 'ping':\n                    break\n                case 'upstream_headers':\n                    responseStatus = event.status\n                    responseHeaders = event.headers\n                    if (!resolved) {\n                        resolved = true\n                        resolve(new Response(stream, {\n                            status: responseStatus,\n                            headers: responseHeaders,\n                        }))\n                    }\n                    break\n                case 'chunk': {\n                    const bytes = decodeProxyJobWsChunk(event.dataBase64)\n                    streamController?.enqueue(bytes)\n                    break\n                }\n                case 'error': {\n                    const msg = formatProxyStreamErrorMessage(event.status, event.message)\n                    if (!resolved) {\n                        resolved = true\n                        resolve(new Response(msg, {\n                            status: event.status ?? 502,\n                            headers: { 'content-type': 'text/plain' },\n                        }))\n                    }\n                    streamController?.close()\n                    break\n                }\n                case 'done':\n                    streamController?.close()\n                    break\n            }\n        }\n\n        ws.onerror = () => {\n            if (!resolved) {\n                resolved = true\n                reject(new Error('WebSocket connection failed'))\n            }\n        }\n\n        ws.onclose = () => {\n            arg.signal?.removeEventListener('abort', abortHandler)\n            try { streamController?.close() } catch { /* already closed */ }\n            if (!resolved) {\n                resolved = true\n                reject(new Error('WebSocket closed before response'))\n            }\n        }\n    })\n}\n\n/**\n * Converts a ReadableStream of Uint8Array to a text string.\n * \n * @param {ReadableStream<Uint8Array>} stream - The readable stream to convert.\n * @returns {Promise<string>} A promise that resolves to the text content of the stream.\n */\nexport function textifyReadableStream(stream: ReadableStream<Uint8Array>) {\n    return new Response(stream).text()\n}\n\n/**\n * Toggles the fullscreen mode of the document.\n * If the document is currently in fullscreen mode, it exits fullscreen.\n * If the document is not in fullscreen mode, it requests fullscreen with navigation UI hidden.\n */\nexport function toggleFullscreen() {\n    const fullscreenElement = document.fullscreenElement\n    fullscreenElement ? document.exitFullscreen() : document.documentElement.requestFullscreen({\n        navigationUI: \"hide\"\n    })\n}\n\n/**\n * Removes non-Latin characters from a string, replaces multiple spaces with a single space, and trims the string.\n * \n * @param {string} data - The input string to be processed.\n * @returns {string} The processed string with non-Latin characters removed, multiple spaces replaced by a single space, and trimmed.\n */\nexport function trimNonLatin(data: string) {\n    return data.replace(/[^\\x00-\\x7F]/g, \"\")\n        .replace(/ +/g, ' ')\n        .trim()\n}\n\n/**\n * A class that provides a blank writer implementation.\n * \n * This class is used to provide a no-op implementation of a writer, making it compatible with other writer interfaces.\n */\nexport class BlankWriter {\n    constructor() {\n    }\n\n    /**\n     * Initializes the writer.\n     * \n     * This method does nothing and is provided for compatibility with other writer interfaces.\n     */\n    async init() {\n        //do nothing, just to make compatible with other writer\n    }\n\n    /**\n     * Writes data to the writer.\n     * \n     * This method does nothing and is provided for compatibility with other writer interfaces.\n     * \n     * @param {string} key - The key associated with the data.\n     * @param {Uint8Array|string} data - The data to be written.\n     */\n    async write(key: string, data: Uint8Array | string) {\n        //do nothing, just to make compatible with other writer\n    }\n\n    /**\n     * Ends the writing process.\n     * \n     * This method does nothing and is provided for compatibility with other writer interfaces.\n     */\n    async end() {\n        //do nothing, just to make compatible with other writer\n    }\n}\n\nexport async function loadInternalBackup() {\n\n    const keys = await forageStorage.keys()\n    const internalBackups = keys\n        .filter((key) => key.startsWith('database/dbbackup-'))\n        .sort((a, b) => {\n            const aTs = parseInt(a.replace('database/dbbackup-', '').replace('.bin', ''))\n            const bTs = parseInt(b.replace('database/dbbackup-', '').replace('.bin', ''))\n            return bTs - aTs\n        })\n\n    const selectOptions = [\n        'Cancel',\n        ...(internalBackups.map((a) => {\n            return (new Date(parseInt(a.replace('database/dbbackup-', '').replace('dbbackup-', '')) * 100)).toLocaleString()\n        }))\n    ]\n\n    const alertResult = parseInt(\n        await alertSelect(selectOptions)\n    ) - 1\n\n    if (alertResult === -1) {\n        return\n    }\n\n    const selectedBackup = internalBackups[alertResult]\n\n    const data = await forageStorage.getItem(selectedBackup)\n\n    const backupDecoded = await decodeRisuSave(Buffer.from(data) as unknown as Uint8Array)\n    setDatabase(backupDecoded)\n\n    notifySuccess('Loaded backup')\n\n\n\n}\n\n/**\n * A debugging class for performance measurement.\n*/\n\nexport class PerformanceDebugger {\n    kv: { [key: string]: number[] } = {}\n    startTime: number\n    endTime: number\n\n    /**\n     * Starts the timing measurement.\n    */\n    start() {\n        this.startTime = performance.now()\n    }\n\n    /**\n     * Ends the timing measurement and records the time difference.\n     * \n     * @param {string} key - The key to associate with the recorded time.\n    */\n    endAndRecord(key: string) {\n        this.endTime = performance.now()\n        if (!this.kv[key]) {\n            this.kv[key] = []\n        }\n        this.kv[key].push(this.endTime - this.startTime)\n    }\n\n    /**\n     * Ends the timing measurement, records the time difference, and starts a new timing measurement.\n     * \n     * @param {string} key - The key to associate with the recorded time.\n    */\n    endAndRecordAndStart(key: string) {\n        this.endAndRecord(key)\n        this.start()\n    }\n\n    /**\n     * Logs the average time for each key to the console.\n    */\n    log() {\n        let table: { [key: string]: number } = {}\n\n        for (const key in this.kv) {\n            table[key] = this.kv[key].reduce((a, b) => a + b, 0) / this.kv[key].length\n        }\n\n\n        console.table(table)\n    }\n\n    combine(other: PerformanceDebugger) {\n        for (const key in other.kv) {\n            if (!this.kv[key]) {\n                this.kv[key] = []\n            }\n            this.kv[key].push(...other.kv[key])\n        }\n    }\n}\n\nexport function getLanguageCodes() {\n    let languageCodes: {\n        code: string\n        name: string\n    }[] = []\n\n    for (let i = 0x41; i <= 0x5A; i++) {\n        for (let j = 0x41; j <= 0x5A; j++) {\n            languageCodes.push({\n                code: String.fromCharCode(i) + String.fromCharCode(j),\n                name: ''\n            })\n        }\n    }\n\n    languageCodes = languageCodes.map(v => {\n        return {\n            code: v.code.toLocaleLowerCase(),\n            name: new Intl.DisplayNames([\n                DBState.db.language === 'cn' ? 'zh' : DBState.db.language\n            ], {\n                type: 'language',\n                fallback: 'none'\n            }).of(v.code)\n        }\n    }).filter((a) => {\n        return a.name\n    }).sort((a, b) => a.name.localeCompare(b.name))\n\n    return languageCodes\n}\n\nexport function getVersionString(): string {\n    return nodeOnlyVer\n}\n\nexport function toGetter<T extends object>(\n    getterFn: () => T,\n    args?: {\n        //blocks this.children from being accessed\n        restrictChildren:string[]\n    }\n): T {\n\n    const dummyTarget = () => { };\n\n    return new Proxy(dummyTarget, {\n        get(target, prop, receiver) {\n\n            const realInstance = getterFn();\n            \n            if (args?.restrictChildren && args.restrictChildren.includes(prop as string)) {\n                throw new Error(`Access to property '${String(prop)}' is restricted`);\n            }\n\n            if (realInstance === null || realInstance === undefined) {\n                return (realInstance as any)[prop];\n            }\n\n            const value = Reflect.get(realInstance as object, prop);\n\n            if (typeof value === 'function') {\n                return value.bind(realInstance);\n            }\n\n            return value;\n        },\n\n        set(target, prop, value, receiver) {\n\n            if(args?.restrictChildren && args.restrictChildren.includes(prop as string)) {\n                throw new Error(`Access to property '${String(prop)}' is restricted`);\n            }\n            const realInstance = getterFn();\n            return Reflect.set(realInstance as object, prop, value, receiver);\n        },\n\n        has(target, prop) {\n            const realInstance = getterFn();\n            return Reflect.has(realInstance as object, prop);\n        },\n\n        ownKeys(target) {\n            const realInstance = getterFn();\n            return Reflect.ownKeys(realInstance as object);\n        },\n\n        construct(target, argArray, newTarget) {\n            const realInstance = getterFn() as any;\n            return new realInstance(...argArray);\n        },\n\n        deleteProperty(target, prop) {\n            const realInstance = getterFn();\n            return Reflect.deleteProperty(realInstance as object, prop);\n        },\n\n        getPrototypeOf() {\n            const realInstance = getterFn();\n            return Reflect.getPrototypeOf(realInstance as object);\n        }\n    }) as unknown as T;\n}\n\nconst countriesWithAiLaw = new Set<string>([\n\n    // EU\n    // AI Act\n    // https://artificialintelligenceact.eu/\n    \n    \"AT\",\n    \"BE\",\n    \"BG\",\n    \"HR\",\n    \"CY\",\n    \"CZ\",\n    \"DK\",\n    \"EE\",\n    \"FI\",\n    \"FR\",\n    \"DE\",\n    \"EL\",\n    \"GR\",\n    \"HU\",\n    \"IE\",\n    \"IT\",\n    \"LV\",\n    \"LT\",\n    \"LU\",\n    \"MT\",\n    \"NL\",\n    \"PL\",\n    \"PT\",\n    \"RO\",\n    \"SK\",\n    \"SI\",\n    \"ES\",\n    \"SE\",\n\n    //China \n    //Measures for Labeling of AI-Generated Synthetic Content\n    // 关于印发《人工智能生成合成内容标识办法》的通知 \n    // https://www.cac.gov.cn/2025-03/14/c_1743654684782215.htm\n    \"CN\",\n\n    //Although CN Law doesn't apply, just in case\n    \"HK\",\n    \"MO\",\n\n    //TW isn't under mainland china jurisdiction\n    //de facto, de jure in TW law, unlike HK and MO,\n    //So we don't include it for now\n    //\"TW\", \n\n    // Republic of Korea\n    // AI Basic Act\n    // 인공지능 발전과 신뢰 기반 조성 등에 관한 기본법\n    // https://www.law.go.kr/%EB%B2%95%EB%A0%B9/%EC%9D%B8%EA%B3%B5%EC%A7%80%EB%8A%A5%20%EB%B0%9C%EC%A0%84%EA%B3%BC%20%EC%8B%A0%EB%A2%B0%20%EA%B8%B0%EB%B0%98%20%EC%A1%B0%EC%84%B1%20%EB%93%B1%EC%97%90%20%EA%B4%80%ED%95%9C%20%EA%B8%B0%EB%B3%B8%EB%B2%95/(20676,20250121)\n    \"KR\",\n\n    // Vietnam\n    // Digital Tech Law\n    // Luật Công nghệ số\n    \"VN\",\n\n])\n\nexport function aiLawApplies(): boolean {\n\n    //TODO: implement actual logic\n    //lets now assume it always applies\n    //so we don't have legal issues later\n\n    return true\n}\n\nexport function aiWatermarkingLawApplies(): boolean {\n\n    //TODO: implement actual logic\n    //lets now assume it is false for now,\n    //becuase very few countries have it for now\n    return false\n}\n\nexport const chatFoldedState = $state<{\n    data: null| {\n        targetCharacterId: string,\n        targetChatId: string,\n        targetMessageId: string,\n    }\n}>({\n    data: null\n})\n\n//Since its exported, we cannot use $derived here\nexport let chatFoldedStateMessageIndex = $state({\n    index: -1\n})\n\n$effect.root(() => {\n    $effect(() => {\n        if(!chatFoldedState.data){\n            return\n        }\n        const char = DBState.db.characters[selIdState.selId]\n        const chat = char.chats[char.chatPage]\n        if(chatFoldedState.data.targetCharacterId !== char.chaId){\n            chatFoldedState.data = null\n        }\n        if(chatFoldedState.data.targetChatId !== chat.id){\n            chatFoldedState.data = null\n        }\n    })\n\n    $effect(() => {\n        if(chatFoldedState.data === null){\n            chatFoldedStateMessageIndex.index = -1\n            return\n        }\n        const char = DBState.db.characters[selIdState.selId]\n        const chat = char.chats[char.chatPage]\n        const messageIndex = chat.message.findIndex((v) => {\n            return chatFoldedState.data?.targetMessageId === v.chatId\n        })\n        if(messageIndex === -1){\n            console.warn('Target message for folding id' + chatFoldedState.data?.targetMessageId + ' not found')\n            chatFoldedStateMessageIndex.index = -1\n            return\n        }\n        chatFoldedStateMessageIndex.index = messageIndex\n    })\n})\n\nexport function foldChatToMessage(targetMessageIdOrIndex: string | number) {\n    let targetMessageId = ''\n    if (typeof targetMessageIdOrIndex === 'number') {\n        const char = getCurrentCharacter()\n        const chat = char.chats[char.chatPage]\n        const message = chat.message[targetMessageIdOrIndex]\n        targetMessageId = message.chatId\n    }\n    else{\n        targetMessageId = targetMessageIdOrIndex\n    }\n    const char = getCurrentCharacter()\n    const chat = char.chats[char.chatPage]\n    chatFoldedState.data = {\n        targetCharacterId: char.chaId,\n        targetChatId: chat.id,\n        targetMessageId: targetMessageId,\n    }\n}\n\nexport function changeChatTo(IdOrIndex: string | number) {\n    let index = -1\n    if (typeof IdOrIndex === 'number') {\n        index = IdOrIndex\n    }\n\n    if (typeof IdOrIndex === 'string') {\n        const currentCharacter = getCurrentCharacter()\n        index = currentCharacter.chats.findIndex((v) => {\n            return v.id === IdOrIndex\n        })\n    }\n\n    if(index === -1){\n        return\n    }\n\n    chatDeselected.set(false)\n    const char = DBState.db.characters[selIdState.selId]\n    char.chatPage = index\n    const newChat = char.chats[index]\n    if(newChat){\n        if(newChat._placeholder){\n            const capturedIndex = index\n            let cancelled = false\n            loadingOverlayStore.set({ active: true, text: language.loading ?? '', onCancel: () => {\n                cancelled = true\n                chatDeselected.set(true)\n                loadingOverlayStore.set({ active: false, text: '', onCancel: null })\n            }})\n            void ensureChatHydrated(char.chats, capturedIndex, char.chaId).then((hydrated) => {\n                if(cancelled) return\n                if(hydrated && char.chatPage === capturedIndex) loadTogglesFromChat(hydrated)\n            }).catch((e) => {\n                console.error('[changeChatTo] hydration failed:', e)\n            }).finally(() => {\n                if(!cancelled) loadingOverlayStore.set({ active: false, text: '', onCancel: null })\n            })\n        } else {\n            loadTogglesFromChat(newChat)\n        }\n    }\n    ReloadGUIPointer.set(Math.random())\n}\n\nexport function createChatCopyName(originalName: string,type:'Copy'|'Branch'): string {\n    let name = originalName.replaceAll(/\\(((Copy|Branch)( \\d+)?)\\)$/g, '').trim()\n    let copyIndex = 1\n    let newName = `${name} (${type})`\n    const char = getCurrentCharacter()\n    while (char.chats.find((v) => v.name === newName)) {\n        copyIndex++\n        newName = `${name} (${type} ${copyIndex})`\n    }\n    return newName\n}\n","managed":"import { changeFullscreen, checkNullish, sleep } from \"./util\"\nimport { v4 as uuidv4, v4 } from 'uuid';\nimport { tick } from \"svelte\";\nimport { get } from \"svelte/store\";\nimport streamSaver from 'streamsaver';\nimport { setDatabase, type Database, defaultSdDataFunc, getDatabase, appVer, nodeOnlyVer, getCurrentCharacter, loadTogglesFromChat } from \"./storage/database.svelte\";\nimport { checkRisuUpdate } from \"./update\";\nimport { MobileGUI, botMakerMode, selectedCharID, loadedStore, DBState, LoadingStatusState, selIdState, ReloadGUIPointer, bodyIntercepterStore, loadingOverlayStore, chatDeselected } from \"./stores.svelte\";\nimport { loadPlugins } from \"./plugins/plugins.svelte\";\nimport { alertConfirm, alertError, alertMd, alertNormalWait, alertSelect, alertTOS, waitAlert, notifySuccess, notifyError, notifyInfo } from \"./alert\";\nimport { hasher } from \"./parser/parser.svelte\";\nimport { characterURLImport, hubURL } from \"./characterCards\";\nimport { defaultJailbreak, defaultMainPrompt, oldJailbreak, oldMainPrompt } from \"./storage/defaultPrompts\";\nimport { decodeRisuSave, encodeRisuSaveLegacy, findDangerousChatOps, normalizeJSON, RisuSaveEncoder, RisuSavePatcher, type toSaveType } from \"./storage/risuSave\";\nimport { isHydrating, saveChatToServer, ensureChatHydrated, chatToStub, classifyChat, convertStubsToPlaceholders } from \"./storage/chatStorage\";\nimport { classifyChatSaveIntent } from \"./storage/chatSaveIntent\";\nimport { assignMissingChatIdsToNewCharacters } from \"./storage/chatIdentityRepair\";\nimport { AutoStorage } from \"./storage/autoStorage\";\nimport { ConflictError, type PatchItemResult, type PersistWarning } from \"./storage/nodeStorage\";\nimport { supportsPatchSync } from \"./platform\";\nimport { updateAnimationSpeed } from \"./gui/animation\";\nimport { updateColorScheme, updateTextThemeAndCSS } from \"./gui/colorscheme\";\nimport { language } from \"src/lang\";\nimport { startObserveDom } from \"./observer.svelte\";\nimport { updateGuisize } from \"./gui/guisize\";\nimport { deepTouch } from \"./gui/deepTouch.svelte\";\nimport { updateLorebooks } from \"./characters\";\nimport { initMobileGesture } from \"./hotkey\";\nimport { moduleUpdate } from \"./process/modules\";\nimport { isLocalNetworkUrl } from \"./network/localNetwork\";\nimport { decodeProxyJobWsChunk, formatProxyStreamErrorMessage, parseProxyJobWsEvent } from \"./network/proxyJobWs\";\nimport { findTrackedDeletionConflict, jsonValuesEqual, mergeThreeWayValue, mergeTrackedChanges } from \"./storage/conflictRebase\";\nimport {\n    createRequestLogScope, recordRequestLog, fetchRequestLogs,\n    type RequestLogCategory, type RequestLogSource, type RequestLogRoute,\n} from \"./requestLog\";\n\nexport const forageStorage = new AutoStorage()\n\nexport async function downloadFile(name: string, dat: Uint8Array | ArrayBuffer | string) {\n    if (typeof (dat) === 'string') {\n        dat = Buffer.from(dat, 'utf-8')\n    }\n    const data = new Uint8Array(dat)\n    const downloadURL = (data: string, fileName: string) => {\n        const a = document.createElement('a')\n        a.href = data\n        a.download = fileName\n        document.body.appendChild(a)\n        a.style.display = 'none'\n        a.click()\n        a.remove()\n    }\n\n    const blob = new Blob([data], { type: 'application/octet-stream' })\n    const url = URL.createObjectURL(blob)\n\n    downloadURL(url, name)\n\n    setTimeout(() => {\n        URL.revokeObjectURL(url)\n    }, 10000)\n}\n\nlet fileCache: {\n    origin: string[], res: (Uint8Array | 'loading' | 'done')[]\n} = {\n    origin: [],\n    res: []\n}\n\nlet pathCache: { [key: string]: string } = {}\nlet checkedPaths: string[] = []\n\nfunction buildTimeoutSignal(signal: AbortSignal | undefined, timeoutMs: number | undefined) {\n    if (!timeoutMs || timeoutMs <= 0) {\n        return {\n            signal,\n            cleanup: () => {}\n        }\n    }\n\n    const controller = new AbortController()\n    const timeoutId = setTimeout(() => controller.abort(), timeoutMs)\n\n    if (signal) {\n        if (signal.aborted) {\n            controller.abort()\n        } else {\n            signal.addEventListener('abort', () => controller.abort(), { once: true })\n        }\n    }\n\n    return {\n        signal: controller.signal,\n        cleanup: () => clearTimeout(timeoutId)\n    }\n}\n\n/**\n * Gets the source URL of a file.\n * \n * @param {string} loc - The location of the file.\n * @returns {Promise<string>} - A promise that resolves to the source URL of the file.\n */\nexport async function getFileSrc(loc: string) {\n    // NodeOnly: return a direct server URL instead of fetching + base64-encoding.\n    // The browser will cache the response using HTTP Cache-Control headers,\n    // so repeated renders (sidebar, chat) cost zero network after first load.\n    if ((globalThis as any).__NODE__) {\n        return `/api/asset/${Buffer.from(loc, 'utf-8').toString('hex')}`\n    }\n    try {\n        if (usingSw) {\n            const encoded = Buffer.from(loc, 'utf-8').toString('hex')\n            let ind = fileCache.origin.indexOf(loc)\n            if (ind === -1) {\n                ind = fileCache.origin.length\n                fileCache.origin.push(loc)\n                fileCache.res.push('loading')\n                try {\n                    const hasCache: boolean = (await (await fetch(\"/sw/check/\" + encoded)).json()).able\n                    if (hasCache) {\n                        fileCache.res[ind] = 'done'\n                        return \"/sw/img/\" + encoded\n                    }\n                    else {\n                        const f: Uint8Array = await forageStorage.getItem(loc) as unknown as Uint8Array\n                        await fetch(\"/sw/register/\" + encoded, {\n                            method: \"POST\",\n                            body: f as any\n                        })\n                        fileCache.res[ind] = 'done'\n                        await sleep(10)\n                    }\n                    return \"/sw/img/\" + encoded\n                } catch (error) {\n\n                }\n            }\n            else {\n                const f = fileCache.res[ind]\n                if (f === 'loading') {\n                    while (fileCache.res[ind] === 'loading') {\n                        await sleep(10)\n                    }\n                }\n                return \"/sw/img/\" + encoded\n            }\n        }\n        else {\n            let ind = fileCache.origin.indexOf(loc)\n            if (ind === -1) {\n                ind = fileCache.origin.length\n                fileCache.origin.push(loc)\n                fileCache.res.push('loading')\n                const f: Uint8Array = await forageStorage.getItem(loc) as unknown as Uint8Array\n                fileCache.res[ind] = f\n                return `data:image/png;base64,${Buffer.from(f).toString('base64')}`\n            }\n            else {\n                const f = fileCache.res[ind]\n                if (f === 'loading') {\n                    while (fileCache.res[ind] === 'loading') {\n                        await sleep(10)\n                    }\n                    return `data:image/png;base64,${Buffer.from(fileCache.res[ind]).toString('base64')}`\n                }\n                return `data:image/png;base64,${Buffer.from(f).toString('base64')}`\n            }\n        }\n    } catch (error) {\n        console.error(error)\n        return ''\n    }\n}\n\n/**\n * Reads an image file and returns its data.\n * \n * @param {string} data - The path to the image file.\n * @returns {Promise<Uint8Array>} - A promise that resolves to the data of the image file.\n */\nexport async function readImage(data: string) {\n    return (await forageStorage.getItem(data) as unknown as Uint8Array)\n}\n\n/**\n * Saves an asset file with the given data, custom ID, and file name.\n * \n * @param {Uint8Array} data - The data of the asset file.\n * @param {string} [customId=''] - The custom ID for the asset file.\n * @param {string} [fileName=''] - The name of the asset file.\n * @returns {Promise<string>} - A promise that resolves to the path of the saved asset file.\n */\nexport async function saveAsset(data: Uint8Array, customId: string = '', fileName: string = '') {\n    let id = ''\n    if (customId !== '') {\n        id = customId\n    }\n    else {\n        try {\n            id = await hasher(data)\n        } catch (error) {\n            id = uuidv4()\n        }\n    }\n    let fileExtension: string = 'png'\n    if (fileName && fileName.split('.').length > 0) {\n        fileExtension = fileName.split('.').pop()\n    }\n    let form = `assets/${id}.${fileExtension}`\n    const replacer = await forageStorage.setItem(form, data)\n    if (replacer) {\n        return replacer\n    }\n    return form\n}\n\n/**\n * Loads an asset file with the given ID.\n * \n * @param {string} id - The ID of the asset file to load.\n * @returns {Promise<Uint8Array>} - A promise that resolves to the data of the loaded asset file.\n */\nexport async function loadAsset(id: string) {\n    return await forageStorage.getItem(id) as unknown as Uint8Array\n}\n\nlet lastSave = ''\nexport let saving = $state({\n    state: false\n})\n\n/**\n * Saves the current state of the database.\n * \n * @returns {Promise<void>} - A promise that resolves when the database has been saved.\n */\nexport let requiresFullEncoderReload = $state({\n    state: false\n})\n\nlet requestImmediateSaveImpl: ((options?: {\n    forceFullWrite?: boolean\n}) => Promise<void> | void) = () => {}\nlet requestChatSaveImpl: ((chaId: string, chatId: string) => Promise<void> | void) = () => {}\nlet requestImportedCharacterSaveImpl: ((chaId: string) => Promise<void>) = async () => {\n    throw new Error('character import save is not initialized')\n}\nconst pendingExplicitChats = new Map<string, [string, string]>()\nconst pendingExplicitCharacters = new Set<string>()\nlet markChatDirtyImpl = (chaId: string, chatId: string) => {\n    if (chaId && chatId) pendingExplicitChats.set(`${chaId}|${chatId}`, [chaId, chatId])\n}\nlet markCharacterDirtyImpl = (chaId: string) => {\n    if (chaId) pendingExplicitCharacters.add(chaId)\n}\nlet patchSyncBaseline: Database | null = null\n\nclass ManualSaveConflictError extends Error {\n    constructor(message: string) {\n        super(message)\n        this.name = 'ManualSaveConflictError'\n    }\n}\n\n// Surfaces server-side persist failures (Stage 1 visibility — see issues.md).\n// The same failure is re-attached on every patch response until cleared, so we\n// dedupe by timestamp to fire one toast per distinct failure event.\nlet lastShownPersistWarningTs = 0\n\nfunction showPersistWarningOnce(warning: PersistWarning) {\n    if (warning.timestamp <= lastShownPersistWarningTs) return\n    lastShownPersistWarningTs = warning.timestamp\n\n    // Stub-flag-loss is the chat-data corruption guard firing at the disk\n    // boundary — this means the persist was REFUSED, not that the save was\n    // safely re-routed. Show the dedicated \"save aborted\" toast so the user\n    // knows their latest changes may not be on disk yet.\n    if (warning.source && warning.source.includes('stub-flag-loss')) {\n        showChatGuardPersistAbortToast()\n        return\n    }\n\n    const sizeStr = warning.attemptedSize != null\n        ? ` (${language.errors.persistFailureAttemptedSize} ${(warning.attemptedSize / 1024 / 1024 / 1024).toFixed(2)}GB)`\n        : ''\n    notifyError(`${language.errors.persistFailureTitle}${sizeStr}`, {\n        description: warning.message,\n        source: 'persist-failure',\n    })\n}\n\n// Throttle the client/server-PATCH chat-guard toast — the underlying root\n// cause may keep firing every 5s save cycle, and we don't want to spam the\n// user. One toast per 5-minute window is enough to surface the situation.\n// Guards 2/3 fall through to a safe full-write so the data IS persisted —\n// the toast is informational, not actionable.\nconst CHAT_GUARD_TOAST_INTERVAL_MS = 5 * 60 * 1000\nlet lastChatGuardToastTs = 0\n\nfunction showChatGuardToastThrottled(source: 'client' | 'server') {\n    const now = Date.now()\n    if (now - lastChatGuardToastTs < CHAT_GUARD_TOAST_INTERVAL_MS) return\n    lastChatGuardToastTs = now\n    notifyError(language.errors.chatGuardTitle, {\n        description: `${language.errors.chatGuardDesc} [${source}]`,\n        source: 'chat-guard',\n    })\n}\n\n// Persist-side guard (guard 1) refuses the disk write outright — there is no\n// fallback path that recovers this cycle's changes automatically. Use a\n// shorter throttle (30s) since this is more severe and actionable: the user\n// should be aware before refreshing that their latest changes might not be\n// persisted. Each separate persist-failure timestamp on the server gates this\n// path via showPersistWarningOnce, so a single corruption won't repeat-toast.\nconst CHAT_GUARD_PERSIST_TOAST_INTERVAL_MS = 30 * 1000\nlet lastChatGuardPersistToastTs = 0\n\n// Verbose chat-guard dump is gated behind a localStorage flag so chronic\n// root-cause environments (e.g. a still-corrupt v1.4.x install) don't flood\n// the console every 5-second save cycle. Toggle with:\n//   localStorage.setItem('risu-chat-guard-debug', '1')\nconst CHAT_GUARD_DEBUG_KEY = 'risu-chat-guard-debug'\nfunction isChatGuardDebugEnabled(): boolean {\n    try {\n        return typeof localStorage !== 'undefined' && localStorage.getItem(CHAT_GUARD_DEBUG_KEY) === '1'\n    } catch {\n        return false\n    }\n}\n\nfunction showChatGuardPersistAbortToast() {\n    const now = Date.now()\n    if (now - lastChatGuardPersistToastTs < CHAT_GUARD_PERSIST_TOAST_INTERVAL_MS) return\n    lastChatGuardPersistToastTs = now\n    notifyError(language.errors.chatGuardPersistTitle, {\n        description: language.errors.chatGuardPersistDesc,\n        source: 'chat-guard-persist',\n    })\n}\n\n// Dev-only preview helpers — bypass throttling so the dev panel always shows\n// the toast immediately. Mirror the production helpers above so any wording\n// or source-tag tweak shows up in the preview without extra synchronization.\nexport function previewChatGuardToast(variant: 'client' | 'server' | 'server-persist') {\n    if (variant === 'server-persist') {\n        notifyError(language.errors.chatGuardPersistTitle, {\n            description: language.errors.chatGuardPersistDesc,\n            source: 'chat-guard-persist',\n        })\n        return\n    }\n    notifyError(language.errors.chatGuardTitle, {\n        description: `${language.errors.chatGuardDesc} [${variant}]`,\n        source: 'chat-guard',\n    })\n}\n\nexport function previewPersistFailureToast() {\n    notifyError(`${language.errors.persistFailureTitle} (${language.errors.persistFailureAttemptedSize} 2.10GB)`, {\n        description: 'preview: simulated kvSet failure (BLOB size > INT_MAX)',\n        source: 'persist-failure',\n    })\n}\n\nexport function requestImmediateSave(options?: {\n    forceFullWrite?: boolean\n}) {\n    return requestImmediateSaveImpl(options)\n}\n\n/**\n * Enlists every full chat of a newly imported character, waits for the server\n * to confirm the stripped database identity, then flushes the debounced write.\n */\nexport function requestImportedCharacterSave(chaId: string): Promise<void> {\n    return requestImportedCharacterSaveImpl(chaId)\n}\n\n/** Explicit dirty hook for async plugin APIs that mutate an inactive chat. */\nexport function requestChatSave(chaId: string, chatId: string) {\n    return requestChatSaveImpl(chaId, chatId)\n}\n\nexport function markChatDirty(chaId: string, chatId: string): void {\n    markChatDirtyImpl(chaId, chatId)\n}\n\nexport function markCharacterDirty(chaId: string): void {\n    markCharacterDirtyImpl(chaId)\n}\n\nexport function setPatchSyncBaseline(data: Database | null) {\n    patchSyncBaseline = data ? safeStructuredClone(data) as Database : null\n}\n\nexport async function saveDb() {\n    let changed = false\n    let gotChannel = false\n    const sessionID = v4()\n    let saveInFlight: Promise<void> | null = null\n    const knownChatIdsByCharacter = new Map<string, Set<string>>(\n        (getDatabase()?.characters ?? [])\n            .filter(character => character?.chaId)\n            .map(character => [\n                character.chaId,\n                new Set((character.chats ?? []).map(chat => chat?.id).filter(Boolean)),\n            ])\n    )\n    let channel: BroadcastChannel\n    if (window.BroadcastChannel) {\n        channel = new BroadcastChannel('risu-db')\n    }\n    if (channel) {\n        channel.onmessage = (ev) => {\n            if (ev.data === sessionID) {\n                return\n            }\n            if (!gotChannel) {\n                gotChannel = true\n                alertNormalWait(language.activeTabChange).then(() => {\n                    location.reload()\n                })\n            }\n        }\n    }\n    // Cross-device single-writer lock: mirrors BroadcastChannel behavior\n    // across devices via server-side session check (423 → deactivate).\n    // With reload-on-return below, a write actually reaching 423 means TRUE\n    // simultaneous use of two devices — rare, and the attempted change cannot\n    // be saved — so it stays an explicit blocking modal, never an automatic\n    // reload that would eat the user's action without a word.\n    window.addEventListener('risu-session-deactivated', () => {\n        if (!gotChannel) {\n            gotChannel = true\n            alertNormalWait(language.activeTabChange).then(() => {\n                location.reload()\n            })\n        }\n    })\n\n    // Reload-on-return: while this tab was hidden, another device may have\n    // taken the writer lock and changed data. Check the moment the user comes\n    // BACK — right then nothing is in progress, so a refresh costs nothing —\n    // instead of at the next write, where a 423 would eat the very change\n    // being saved. Only 'stale' reloads (the other device actually wrote);\n    // 'fresh' means our copy is still current and the next user action simply\n    // takes the lock back with no reload at all.\n    let lastLockReturnCheck = 0\n    const checkWriterLockOnReturn = () => {\n        const nowMs = Date.now()\n        if (nowMs - lastLockReturnCheck < 5000) return\n        lastLockReturnCheck = nowMs\n        void (async () => {\n            // Dynamic import: process/index.svelte imports this module, so a\n            // static import here would be circular. Already loaded → instant.\n            const { doingChat } = await import(\"./process/index.svelte\")\n            if (get(doingChat)) return // never yank a running generation\n            const state = await forageStorage.getWriterLockState()\n            if (state !== 'stale') return\n            try { sessionStorage.setItem('risu-session-handoff-reload', '1') } catch { /* toast is best-effort */ }\n            location.reload()\n        })().catch(() => { /* status check failed — do nothing, write path 423 still guards */ })\n    }\n    window.addEventListener('focus', checkWriterLockOnReturn)\n    document.addEventListener('visibilitychange', () => {\n        if (document.visibilityState === 'visible') checkWriterLockOnReturn()\n    })\n\n    // Post-handoff notice from a reload-on-return in the previous page life.\n    // Delayed so the toast container is mounted before it fires.\n    try {\n        if (sessionStorage.getItem('risu-session-handoff-reload')) {\n            sessionStorage.removeItem('risu-session-handoff-reload')\n            setTimeout(() => notifyInfo(language.sessionHandoffReload), 1500)\n        }\n    } catch { /* storage unavailable — skip the notice */ }\n\n    const changeTracker: toSaveType = {\n        character: [],\n        chat: [],\n        root: false,\n        botPreset: false,\n        modules: false,\n        plugins: false,\n        pluginCustomStorage: false\n    }\n\n    function queueTrackedChat(chaId: string, chatId: string) {\n        if (!chaId || !chatId) return\n        if (\n            changeTracker.chat[0]?.[0] !== chaId ||\n            changeTracker.chat[0]?.[1] !== chatId\n        ) {\n            changeTracker.chat.unshift([chaId, chatId])\n        }\n    }\n\n    function queueTrackedCharacter(chaId: string) {\n        if (!chaId) return\n        changeTracker.character = [chaId, ...changeTracker.character.filter((id) => id !== chaId)]\n    }\n\n    for (const [chaId, chatId] of pendingExplicitChats.values()) {\n        queueTrackedChat(chaId, chatId)\n    }\n    for (const chaId of pendingExplicitCharacters) {\n        queueTrackedCharacter(chaId)\n    }\n    if (pendingExplicitChats.size > 0 || pendingExplicitCharacters.size > 0) {\n        changed = true\n    }\n    pendingExplicitChats.clear()\n    pendingExplicitCharacters.clear()\n    markChatDirtyImpl = (chaId, chatId) => {\n        queueTrackedChat(chaId, chatId)\n        changed = true\n    }\n    markCharacterDirtyImpl = (chaId) => {\n        queueTrackedCharacter(chaId)\n        changed = true\n    }\n\n    let encoder = new RisuSaveEncoder()\n    await encoder.init(getDatabase(), {\n        compression: false\n    })\n\n    const toServerDatabaseShape = (database: Database): Database => {\n        const cloned = normalizeJSON(safeStructuredClone(database)) as Database\n        cloned.characters = (cloned.characters ?? []).map((character) => ({\n            ...character,\n            chats: (character.chats ?? []).map(chatToStub),\n        })) as any\n        return cloned\n    }\n\n    let lastConfirmedServerDb = patchSyncBaseline\n        ? normalizeJSON(safeStructuredClone(patchSyncBaseline)) as Database\n        : toServerDatabaseShape(getDatabase())\n    let patcher = new RisuSavePatcher()\n    if (supportsPatchSync) {\n        await patcher.init(lastConfirmedServerDb)\n    }\n    patchSyncBaseline = null\n\n    function hasTrackedChanges(toSave: toSaveType) {\n        return !!(\n            toSave.botPreset ||\n            toSave.modules ||\n            toSave.plugins ||\n            toSave.pluginCustomStorage ||\n            toSave.root ||\n            toSave.character.length > 0 ||\n            toSave.chat.length > 0\n        )\n    }\n\n    function takeTrackedChanges() {\n        const toSave = safeStructuredClone(changeTracker)\n        // These entries belong to this save attempt. Mutations that happen\n        // while it is in flight are observed by the effects below and queued\n        // again. Retaining the first entry made unrelated saves repeatedly\n        // upload the same active character/chat.\n        changeTracker.character = []\n        changeTracker.chat = []\n        changeTracker.root = false\n        changeTracker.botPreset = false\n        changeTracker.modules = false\n        changeTracker.plugins = false\n        changeTracker.pluginCustomStorage = false\n        return toSave\n    }\n\n    async function flushServerDbKeepalive() {\n        try {\n            fetch('/api/db/flush', {\n                method: 'POST',\n                keepalive: true,\n                credentials: 'same-origin'\n            }).catch(() => {})\n        } catch {\n            // ignore best-effort flush failures\n        }\n    }\n\n    $effect.root(() => {\n\n        let selIdState = $state(0)\n        let knownCharacterIds = new Set<string>((getDatabase()?.characters ?? []).map((character) => character?.chaId).filter(Boolean))\n        let didInitRootEffect = false\n        let didInitBotPresetEffect = false\n        let didInitModulesEffect = false\n        let didInitPluginsEffect = false\n        let didInitPluginStorageEffect = false\n        let didInitGeneralEffect = false\n        let trackedActiveChatKey = ''\n        const streamingCheckpointAt = new Map<string, number>()\n        const STREAMING_CHECKPOINT_INTERVAL_MS = 10_000\n\n        const debounceTime = 500; // 500 milliseconds\n        let saveTimeout: ReturnType<typeof setTimeout> | null = null;\n\n        selectedCharID.subscribe((v) => {\n            selIdState = v\n        })\n\n        function saveTimeoutExecute() {\n            if (saveTimeout) {\n                clearTimeout(saveTimeout);\n            }\n            saveTimeout = setTimeout(() => {\n                changed = true;\n            }, debounceTime);\n        }\n\n        function queueActiveChatForSave() {\n            const activeChar = DBState?.db?.characters?.[selIdState]\n            const activeChat = activeChar?.chats?.[activeChar?.chatPage]\n            if (!activeChar?.chaId || !activeChat?.id || activeChat._placeholder) return\n            if (isHydrating(activeChar.chaId, activeChat.id)) return\n            queueTrackedChat(activeChar.chaId, activeChat.id)\n        }\n\n        // Start a best-effort save immediately when the page is hidden/unloaded.\n        function flushImmediate() {\n            if (saveTimeout) {\n                clearTimeout(saveTimeout);\n                saveTimeout = null;\n            }\n            // Streaming normally checkpoints every ten seconds. Keep the chat\n            // dirty between checkpoints so pagehide cannot omit the final\n            // partial response merely because the throttle window is active.\n            queueActiveChatForSave()\n            changed = true;\n            void triggerSave({\n                skipBroadcast: true,\n            })\n            void flushServerDbKeepalive()\n        }\n        document.addEventListener('visibilitychange', () => {\n            if (document.visibilityState === 'hidden') {\n                flushImmediate()\n            }\n            else if (hasTrackedChanges(changeTracker)) {\n                // Resume a bounded/paused retry when the browser becomes\n                // active again, even if no new mutation occurred.\n                changed = true\n            }\n        });\n        window.addEventListener('online', () => {\n            if (hasTrackedChanges(changeTracker)) changed = true\n        })\n        window.addEventListener('pagehide', flushImmediate);\n\n        $effect(() => {\n            for (const key in DBState.db) {\n                if (\n                    key !== 'characters' && key !== 'botPresets' && key !== 'modules' &&\n                    key !== 'plugins' && key !== 'pluginCustomStorage'\n                ) {\n                    deepTouch(DBState.db[key])\n                }\n            }\n            if (!didInitRootEffect) {\n                didInitRootEffect = true\n                return\n            }\n            changeTracker.root = true\n            saveTimeoutExecute()\n        })\n        $effect(() => {\n            DBState.db.botPresetsId\n            try { deepTouch(DBState.db.botPresets) } catch (e) {\n                console.warn('[Save] deepTouch(botPresets) failed:', e)\n                return\n            }\n            if (!didInitBotPresetEffect) {\n                didInitBotPresetEffect = true\n                return\n            }\n            changeTracker.botPreset = true\n            saveTimeoutExecute()\n        })\n        $effect(() => {\n            try { deepTouch(DBState.db.modules) } catch (e) {\n                console.warn('[Save] deepTouch(modules) failed:', e)\n                return\n            }\n            if (!didInitModulesEffect) {\n                didInitModulesEffect = true\n                return\n            }\n            changeTracker.modules = true\n            saveTimeoutExecute()\n        })\n        $effect(() => {\n            deepTouch(DBState.db.plugins)\n            if (!didInitPluginsEffect) {\n                didInitPluginsEffect = true\n                return\n            }\n            changeTracker.plugins = true\n            saveTimeoutExecute()\n        })\n        $effect(() => {\n            deepTouch(DBState.db.pluginCustomStorage)\n            if (!didInitPluginStorageEffect) {\n                didInitPluginStorageEffect = true\n                return\n            }\n            changeTracker.pluginCustomStorage = true\n            saveTimeoutExecute()\n        })\n        $effect(() => {\n            const currentCharacterIds = (DBState?.db?.characters ?? []).map((character) => character?.chaId).filter(Boolean)\n            deepTouch(currentCharacterIds)\n\n            const currentCharacterIdSet = new Set<string>(currentCharacterIds)\n            for (const previousCharacterId of knownCharacterIds) {\n                if (!currentCharacterIdSet.has(previousCharacterId)) {\n                    changeTracker.character = [previousCharacterId, ...changeTracker.character.filter((v) => v !== previousCharacterId)]\n                }\n            }\n            knownCharacterIds = currentCharacterIdSet\n\n            if (DBState?.db?.characters?.[selIdState]) {\n                for (const key in DBState.db.characters[selIdState]) {\n                    // Exclude chats — chat changes are tracked via chat-specific server save, not database.bin\n                    if (key !== 'chats') {\n                        deepTouch(DBState.db.characters[selIdState][key])\n                    }\n                }\n                // Track stub metadata and chat ordering for database.bin persistence.\n                deepTouch(DBState.db.characters[selIdState].chats.map(c => ({\n                    id: c.id,\n                    name: c.name,\n                    lastDate: c.lastDate,\n                    folderId: c.folderId,\n                })))\n                if (changeTracker.character[0] !== DBState.db.characters[selIdState]?.chaId) {\n                    changeTracker.character.unshift(DBState.db.characters[selIdState]?.chaId)\n                }\n            }\n            if (!didInitGeneralEffect) {\n                didInitGeneralEffect = true\n                changeTracker.character = []\n                changeTracker.chat = []\n                return\n            }\n            saveTimeoutExecute()\n        })\n        $effect(() => {\n            const activeChar = DBState?.db?.characters?.[selIdState]\n            const activeChat = activeChar?.chats?.[activeChar?.chatPage]\n            if (activeChat) {\n                deepTouch(activeChat)\n            }\n\n            const activeChaId = activeChar?.chaId ?? ''\n            const activeChatId = activeChat?.id ?? ''\n            const activeKey = activeChaId && activeChatId ? `${activeChaId}|${activeChatId}` : ''\n\n            if (!activeKey) {\n                trackedActiveChatKey = ''\n                return\n            }\n\n            // Selecting a different chat establishes a new baseline; only later edits are dirty.\n            if (trackedActiveChatKey !== activeKey) {\n                trackedActiveChatKey = activeKey\n                return\n            }\n\n            if (isHydrating(activeChaId, activeChatId)) {\n                return\n            }\n\n            // Do not upload an ever-growing response for every streamed token.\n            // A periodic checkpoint still preserves partial output if the page\n            // closes mid-generation, and the isStreaming -> false transition\n            // always schedules the final state immediately.\n            if (activeChat.isStreaming === true) {\n                // Record dirtiness immediately, but throttle the actual network\n                // save. A pagehide flush can then persist the latest tokens.\n                queueTrackedChat(activeChaId, activeChatId)\n                const now = Date.now()\n                const lastCheckpoint = streamingCheckpointAt.get(activeKey) ?? 0\n                if (now - lastCheckpoint < STREAMING_CHECKPOINT_INTERVAL_MS) {\n                    return\n                }\n                streamingCheckpointAt.set(activeKey, now)\n            }\n            else {\n                streamingCheckpointAt.delete(activeKey)\n            }\n\n            queueTrackedChat(activeChaId, activeChatId)\n            saveTimeoutExecute()\n        })\n    })\n\n    function requeueTrackedChanges(toSave: toSaveType) {\n        changeTracker.character = [...new Set([...toSave.character, ...changeTracker.character])]\n        const chatSeen = new Set<string>()\n        changeTracker.chat = [...toSave.chat, ...changeTracker.chat].filter((chatPair) => {\n            const key = `${chatPair?.[0] ?? ''}|${chatPair?.[1] ?? ''}`\n            if (chatSeen.has(key)) {\n                return false\n            }\n            chatSeen.add(key)\n            return true\n        })\n        changeTracker.botPreset = changeTracker.botPreset || toSave.botPreset\n        changeTracker.modules = changeTracker.modules || toSave.modules\n        changeTracker.plugins = changeTracker.plugins || toSave.plugins\n        changeTracker.pluginCustomStorage = changeTracker.pluginCustomStorage || toSave.pluginCustomStorage\n        changeTracker.root = changeTracker.root || toSave.root\n    }\n\n    function collectChatsToPersist(db: Database, toSave: toSaveType): [string, string][] {\n        const chatsToPersist: [string, string][] = []\n        const seen = new Set<string>()\n        const pushChat = (chaId: string, chatId: string) => {\n            if (!chaId || !chatId) return\n            const key = `${chaId}|${chatId}`\n            if (seen.has(key)) return\n            seen.add(key)\n            chatsToPersist.push([chaId, chatId])\n        }\n\n        for (const [chaId, chatId] of toSave.chat) {\n            pushChat(chaId, chatId)\n        }\n\n        for (const chaId of toSave.character) {\n            const char = db.characters.find(c => c?.chaId === chaId)\n            if (!char) continue\n            const knownChatIds = knownChatIdsByCharacter.get(chaId) ?? new Set<string>()\n            for (const chat of char.chats ?? []) {\n                if (!chat?.id || chat._placeholder) continue\n                if (!knownChatIds.has(chat.id)) {\n                    pushChat(chaId, chat.id)\n                }\n            }\n        }\n\n        return chatsToPersist\n    }\n\n    function updateKnownChatsAfterSuccessfulSave(db: Database, toSave: toSaveType) {\n        for (const chaId of toSave.character) {\n            const char = db.characters.find(c => c?.chaId === chaId)\n            if (!char) {\n                knownChatIdsByCharacter.delete(chaId)\n                continue\n            }\n            knownChatIdsByCharacter.set(\n                chaId,\n                new Set((char.chats ?? []).map(chat => chat?.id).filter(Boolean))\n            )\n        }\n\n        for (const [chaId, chatId] of toSave.chat) {\n            if (!chaId || !chatId) continue\n            const knownChatIds = knownChatIdsByCharacter.get(chaId) ?? new Set<string>()\n            knownChatIds.add(chatId)\n            knownChatIdsByCharacter.set(chaId, knownChatIds)\n        }\n    }\n\n    async function rebaseTrackedLocalChangesOnLatestServerDb(db: Database, toSave: toSaveType) {\n        // patchItem/full-write conflict handlers roll the patcher back before\n        // entering here, so this is the common ancestor shared by local and\n        // remote state. It must be captured before the network await.\n        const previousServerBaseline = supportsPatchSync\n            ? patcher.baselineSnapshot() as Database\n            : safeStructuredClone(lastConfirmedServerDb) as Database\n        // A conflict ETag describes the server state, not the local baseline.\n        // Force a canonical read instead of making a conditional cache read\n        // with an ETag for bytes we do not own locally.\n        const latestData = await forageStorage.getItemFresh('database/database.bin') as unknown as Uint8Array\n        if (latestData && latestData.length > 0) {\n            const latestDb = normalizeJSON(await decodeRisuSave(latestData)) as Database\n            const latestServerBaseline = safeStructuredClone(latestDb) as Database\n            const localDb = normalizeJSON(safeStructuredClone(db)) as Database\n            const pendingDuringSave = safeStructuredClone(changeTracker)\n            const retryChanges = mergeTrackedChanges(toSave, pendingDuringSave)\n\n            // A remote deletion racing a tracked local edit is not safely\n            // auto-mergeable. Keep the live local object untouched and stop\n            // this retry cycle instead of either reviving the deletion or\n            // silently discarding the edit.\n            const deletionConflict = findTrackedDeletionConflict(\n                previousServerBaseline,\n                localDb,\n                latestDb,\n                retryChanges,\n                chatToStub,\n            )\n            if (deletionConflict) {\n                const subject = deletionConflict.scope === 'character'\n                    ? `Character ${deletionConflict.charId}`\n                    : `Chat ${deletionConflict.chatId}`\n                throw new ManualSaveConflictError(\n                    `${subject} was deleted on another session while it had local edits. ` +\n                    'Local data was kept in this tab; copy or export it before reloading.'\n                )\n            }\n            const mergedDb = mergeThreeWayValue(\n                previousServerBaseline,\n                localDb,\n                latestDb,\n            ) as Database\n\n            // The merge can preserve an edit whose reactive effect had not run\n            // before setDatabase. Ensure the retry covers every coarse block\n            // that now differs from the new server baseline.\n            retryChanges.root = retryChanges.root || Object.keys(mergedDb).some((key) => (\n                key !== 'characters' && key !== 'botPresets' && key !== 'modules' &&\n                !jsonValuesEqual(mergedDb[key], latestDb[key])\n            ))\n            retryChanges.botPreset = retryChanges.botPreset ||\n                !jsonValuesEqual(mergedDb.botPresets, latestDb.botPresets)\n            retryChanges.modules = retryChanges.modules ||\n                !jsonValuesEqual(mergedDb.modules, latestDb.modules)\n            retryChanges.plugins = retryChanges.plugins ||\n                !jsonValuesEqual(mergedDb.plugins, latestDb.plugins)\n            retryChanges.pluginCustomStorage = retryChanges.pluginCustomStorage ||\n                !jsonValuesEqual(mergedDb.pluginCustomStorage, latestDb.pluginCustomStorage)\n\n            const mergedCharacters = Array.isArray(mergedDb.characters) ? mergedDb.characters : []\n            const latestCharacters = Array.isArray(latestDb.characters) ? latestDb.characters : []\n            const latestById = new Map(latestCharacters.map((char) => [char?.chaId, char]))\n            const mergedById = new Map(mergedCharacters.map((char) => [char?.chaId, char]))\n            for (const charId of new Set([...latestById.keys(), ...mergedById.keys()])) {\n                if (!charId) continue\n                const latestChar = latestById.get(charId)\n                const mergedChar = mergedById.get(charId)\n                const latestStubbed = latestChar\n                    ? { ...latestChar, chats: (latestChar.chats ?? []).map(chatToStub) }\n                    : undefined\n                const mergedStubbed = mergedChar\n                    ? { ...mergedChar, chats: (mergedChar.chats ?? []).map(chatToStub) }\n                    : undefined\n                if (!jsonValuesEqual(latestStubbed, mergedStubbed)) {\n                    retryChanges.character.push(charId)\n                }\n            }\n            retryChanges.character = [...new Set(retryChanges.character)]\n\n            // Runtime and plugins must see either real chats or placeholders,\n            // never the raw server-only stub representation.\n            for (const character of mergedDb.characters) {\n                character.chats = convertStubsToPlaceholders(character.chats)\n            }\n            setDatabase(mergedDb)\n\n            encoder = new RisuSaveEncoder()\n            await encoder.init(getDatabase(), {\n                compression: false\n            })\n            if (supportsPatchSync) {\n                patcher = new RisuSavePatcher()\n                // The server still owns latestServerBaseline. Initializing from\n                // merged local state would make the retry hash a state the\n                // server never accepted and cause an endless 409 loop.\n                await patcher.init(latestServerBaseline)\n            }\n            lastConfirmedServerDb = latestServerBaseline\n            requeueTrackedChanges(retryChanges)\n        }\n        else {\n            requeueTrackedChanges(toSave)\n        }\n        changed = true\n    }\n\n    async function persistTrackedChanges(\n        toSave: toSaveType,\n        options?: {\n            forceFullWrite?: boolean\n            skipBroadcast?: boolean\n        }\n    ): Promise<'saved' | 'retry' | 'noop'> {\n        if (gotChannel) {\n            // Data is saved in another tab.\n            await sleep(1000)\n            return 'noop'\n        }\n        if (channel && !options?.skipBroadcast) {\n            channel.postMessage(sessionID)\n        }\n\n        const db = getDatabase()\n        if (!db.characters) {\n            await sleep(1000)\n            return 'noop'\n        }\n\n        // Some legacy/plugin character constructors still omit the initial\n        // chat ID. Repair only server-unknown characters with full payloads:\n        // assigning a new ID to an existing lazy chat could orphan its\n        // server-side content. Include repaired identities in this exact save\n        // attempt because the ordinary tracker snapshot was already taken.\n        const assignedChatIds = assignMissingChatIdsToNewCharacters(\n            db,\n            lastConfirmedServerDb,\n            v4,\n        )\n        for (const { chaId, chatId } of assignedChatIds) {\n            if (!toSave.character.includes(chaId)) {\n                toSave.character.unshift(chaId)\n            }\n            if (!toSave.chat.some(([trackedChaId, trackedChatId]) =>\n                trackedChaId === chaId && trackedChatId === chatId\n            )) {\n                toSave.chat.unshift([chaId, chatId])\n            }\n        }\n        if (assignedChatIds.length > 0) {\n            console.warn(\n                `[Save] Assigned stable IDs to ${assignedChatIds.length} hydrated chat`\n                + `${assignedChatIds.length === 1 ? '' : 's'} on new characters`,\n            )\n        }\n\n        // ── Save changed chat content to server ─────────────────────────\n        const failedChats: [string, string][] = []\n        for (const [chaId, chatId] of collectChatsToPersist(db, toSave)) {\n            const char = db.characters.find(c => c.chaId === chaId)\n            if (!char) continue\n            const chatIndex = char.chats.findIndex(c => c.id === chatId)\n            if (chatIndex === -1) continue\n            const chat = char.chats[chatIndex]\n            // Skip placeholders — they have no real data to save\n            if (!chat || chat._placeholder) continue\n            try {\n                const intent = classifyChatSaveIntent(lastConfirmedServerDb, chaId, chatId)\n                await saveChatToServer(chaId, chatIndex, chatId, chat, intent)\n            } catch (e) {\n                console.error(`[Save] Failed to save chat ${chaId}/${chatId}:`, e)\n                failedChats.push([chaId, chatId])\n            }\n        }\n        if (failedChats.length > 0) {\n            throw new Error(`Failed to save ${failedChats.length} chat${failedChats.length === 1 ? '' : 's'}`)\n        }\n\n        // ── database.bin: exclude chat payload (stubs only via encoder) ──\n        await encoder.set(db, safeStructuredClone(toSave))\n        const encoded = encoder.encode()\n        if (!encoded) {\n            await sleep(1000)\n            return 'noop'\n        }\n        const dbData = new Uint8Array(encoded)\n\n        let saved = false\n        let newEtag: string | undefined\n\n        if (supportsPatchSync && !options?.forceFullWrite) {\n            const preparedPatch = await patcher.set(db, safeStructuredClone(toSave))\n            const { rollback: rollbackPatchBaseline, ...patchData } = preparedPatch\n            // Refuse to send patches that would corrupt server-side lazy chats.\n            // chatToStub strips chats to metadata before diffing, so the only\n            // way these ops appear is a baseline desync. Falling through to a\n            // full write rebuilds the server's stub view from scratch and\n            // resyncs the patcher baseline. The console.error is the primary\n            // breadcrumb for tracking down the unknown root cause.\n            const dangerous = findDangerousChatOps(patchData.patch)\n            if (dangerous.length > 0) {\n                // The patch was never accepted, so diagnostics and any full\n                // fallback must use the last server-confirmed baseline.\n                rollbackPatchBaseline()\n                // Always log a one-line summary so production environments\n                // see enough to file a bug report. The rich dump below is\n                // gated behind a localStorage flag — chronic loops would\n                // otherwise dump 5 console.errors every 5s save cycle.\n                const sampleOps = dangerous.slice(0, 3).map(d => `${d.op} ${d.path}`).join(', ')\n                console.error(\n                    `[Save] Patcher emitted ${dangerous.length} chat-internal field op(s) — `\n                    + `falling back to full write. sample: ${sampleOps}`\n                    + ` (verbose dump: localStorage.setItem('${CHAT_GUARD_DEBUG_KEY}', '1') then reproduce)`\n                )\n                showChatGuardToastThrottled('client')\n\n                if (isChatGuardDebugEnabled()) {\n                // ── Diagnostic dump for unknown root cause ────────────────\n                // chatToStub is supposed to strip every chat down to 6\n                // metadata fields before the diff. If non-stub fields end\n                // up in patch ops, something slipped past it. Dump enough\n                // shape info to figure out which side of the diff carries\n                // the contraband (baseline vs current) and what flags the\n                // chat object has.\n                const affectedChats: Record<string, any> = {}\n                const seen = new Set<string>()\n                const baselineCharsLen = (patcher as any).lastSyncedDb?.characters?.length ?? -1\n                const currentCharsLen = db.characters?.length ?? -1\n\n                const summarize = (c: any) => {\n                    if (c == null) return null\n                    const keys = Object.keys(c)\n                    // Per-key shape: which fields are strings vs arrays vs objects vs primitives\n                    const keyShapes: Record<string, string> = {}\n                    for (const k of keys) {\n                        const v = c[k]\n                        if (v === null) keyShapes[k] = 'null'\n                        else if (Array.isArray(v)) keyShapes[k] = `Array(${v.length})`\n                        else if (typeof v === 'object') keyShapes[k] = `Object(${Object.keys(v).length})`\n                        else keyShapes[k] = `${typeof v}=${typeof v === 'string' && v.length > 30 ? v.slice(0, 30) + '…' : JSON.stringify(v)}`\n                    }\n                    return {\n                        keys,                                  // full key list, not just length\n                        keyShapes,                             // per-key type/preview\n                        classification: classifyChat(c),\n                        _stub: c._stub,\n                        _placeholder: c._placeholder,\n                        hasMessage: Array.isArray(c.message),\n                        messageLen: Array.isArray(c.message) ? c.message.length : null,\n                        id: c.id,\n                        name: c.name,\n                        // Type fingerprints help identify Svelte $state proxies\n                        // or other wrapper objects that might bypass deep clone.\n                        ctor: c?.constructor?.name,\n                        isFrozen: Object.isFrozen(c),\n                        isProxy: typeof c === 'object' && c !== null && (c as any)?.[Symbol.toStringTag] !== undefined,\n                    }\n                }\n\n                // Re-run chatToStub on the current chat to see what the patcher\n                // would have produced. If this still has non-stub fields, the\n                // bug is INSIDE chatToStub's isChatStub short-circuit (chat\n                // already has `_stub: true` but isn't actually a stub).\n                const stubReplay = (c: any) => {\n                    if (c == null) return null\n                    try {\n                        const result = chatToStub(c)\n                        return summarize(result)\n                    } catch (e) {\n                        return { error: String(e) }\n                    }\n                }\n\n                for (const op of dangerous) {\n                    const m = op.path.match(/^\\/characters\\/(\\d+)\\/chats\\/(\\d+)\\//)\n                    if (!m) continue\n                    const key = `${m[1]}/${m[2]}`\n                    if (seen.has(key)) continue\n                    seen.add(key)\n                    if (seen.size > 5) break\n                    const ci = +m[1], chi = +m[2]\n                    const baselineChar = (patcher as any).lastSyncedDb?.characters?.[ci]\n                    const currentChar = db.characters?.[ci]\n                    const baselineChat = baselineChar?.chats?.[chi]\n                    const currentChat = currentChar?.chats?.[chi]\n                    const opsForThisChat = dangerous.filter(d => d.path.startsWith(`/characters/${ci}/chats/${chi}/`))\n                    // Reference identity: same object? same chats array? same chat slot?\n                    const refIdentity = {\n                        sameCharacter: baselineChar === currentChar,\n                        sameChatsArray: baselineChar?.chats === currentChar?.chats,\n                        sameChatSlot: baselineChat === currentChat,\n                    }\n                    affectedChats[key] = {\n                        characterContext: {\n                            baselineChaId: baselineChar?.chaId,\n                            currentChaId: currentChar?.chaId,\n                            chaIdsMatch: baselineChar?.chaId === currentChar?.chaId,\n                            baselineChatsLen: baselineChar?.chats?.length ?? -1,\n                            currentChatsLen: currentChar?.chats?.length ?? -1,\n                            refIdentity,\n                        },\n                        baselineChat: summarize(baselineChat),\n                        currentChat: summarize(currentChat),\n                        // The crucial diagnostic: if this still leaks message etc,\n                        // chatToStub's isChatStub fast-path was the offender.\n                        currentAfterChatToStub: stubReplay(currentChat),\n                        baselineAfterChatToStub: stubReplay(baselineChat),\n                        opsForThisChat,\n                    }\n                }\n\n                // Distribution of stub/placeholder flags across the affected\n                // characters' chats — useful to spot wholesale corruption\n                // (e.g. a plugin replacing the entire chats array with\n                // _stub-tagged objects).\n                const charsDistribution: Record<string, any> = {}\n                for (const k of Array.from(seen).slice(0, 3)) {\n                    const ci = +k.split('/')[0]\n                    const baselineChats = (patcher as any).lastSyncedDb?.characters?.[ci]?.chats ?? []\n                    const currentChats = db.characters?.[ci]?.chats ?? []\n                    const tally = (chats: any[]) => {\n                        const t = { total: chats.length, stub: 0, placeholder: 0, hybrid: 0, full: 0, neither: 0 }\n                        for (const c of chats) {\n                            if (!c) continue\n                            const isStub = c._stub === true\n                            const isPh = c._placeholder === true\n                            const hasMsg = Array.isArray(c.message)\n                            if (isStub && hasMsg) t.hybrid++\n                            else if (isStub) t.stub++\n                            else if (isPh) t.placeholder++\n                            else if (hasMsg) t.full++\n                            else t.neither++\n                        }\n                        return t\n                    }\n                    charsDistribution[`character[${ci}]`] = {\n                        baseline: tally(baselineChats),\n                        current: tally(currentChats),\n                    }\n                }\n\n                let activeCharID = -1\n                try { selectedCharID.subscribe(v => { activeCharID = v })() } catch {}\n                console.error('[Save:guard-debug] context:', {\n                    baselineCharsLen,\n                    currentCharsLen,\n                    selectedCharID: activeCharID,\n                    totalDangerousOps: dangerous.length,\n                    uniqueAffectedChats: seen.size,\n                })\n                console.error('[Save:guard-debug] all dangerous ops:', dangerous)\n                console.error('[Save:guard-debug] affected chats (baseline / current / stubReplay):', affectedChats)\n                console.error('[Save:guard-debug] chats[] distribution per affected character:', charsDistribution)\n                }\n                // Leave saved=false so the full-write path below kicks in.\n            } else {\n                let patchResult: PatchItemResult\n                try {\n                    patchResult = await forageStorage.patchItem('database/database.bin', patchData)\n                }\n                catch (error) {\n                    rollbackPatchBaseline()\n                    throw error\n                }\n                saved = patchResult.success\n                if (!patchResult.success) {\n                    rollbackPatchBaseline()\n                }\n                if (patchResult.success && patchResult.etag) {\n                    newEtag = patchResult.etag\n                    forageStorage.setDbEtag(patchResult.etag)\n                }\n                if (patchResult.success) {\n                    lastConfirmedServerDb = patcher.baselineSnapshot() as Database\n                }\n                if (patchResult.persistWarning) {\n                    showPersistWarningOnce(patchResult.persistWarning)\n                }\n                // Server's chat-internal-field guard rejected the patch — the\n                // client-side guard above missed this case. Surface to user\n                // and continue to the full-write fallback below.\n                if (patchResult.chatGuardRejected) {\n                    console.error('[Save] Server rejected patch — chat-internal field ops detected server-side')\n                    showChatGuardToastThrottled('server')\n                }\n                else if (patchResult.validationRejected) {\n                    throw new Error(\n                        `Server rejected an invalid database update: ${patchResult.error ?? 'unknown invariant failure'}`\n                    )\n                }\n                else if (patchResult.conflict) {\n                    console.warn('[Save] Patch conflict detected, rebasing tracked changes on the latest server DB...')\n                    await rebaseTrackedLocalChangesOnLatestServerDb(db, toSave)\n                    await sleep(Math.min(500 * (savetrys + 1), 3000))\n                    return 'retry'\n                }\n            }\n        }\n        if (!saved) {\n            if (supportsPatchSync && !options?.forceFullWrite) {\n                console.warn('[Save] Patch conflict, falling through to full write...')\n            }\n            try {\n                const currentEtag = forageStorage.getDbEtag()\n                await forageStorage.setItem('database/database.bin', dbData, currentEtag ?? undefined)\n            } catch (conflictErr) {\n                if (conflictErr instanceof ConflictError) {\n                    console.warn('[Save] Full-write conflict detected, rebasing tracked local changes on latest server DB...')\n                    await rebaseTrackedLocalChangesOnLatestServerDb(db, toSave)\n                    await sleep(Math.min(500 * (savetrys + 1), 3000))\n                    return 'retry'\n                }\n                throw conflictErr\n            }\n\n            // Re-init the confirmed baseline from the exact encoded data that\n            // was accepted. This also keeps conflict recovery safe when patch\n            // sync is disabled but ETag-protected full writes are enabled.\n            const decodedDb = normalizeJSON(await decodeRisuSave(dbData)) as Database\n            lastConfirmedServerDb = decodedDb\n            if (supportsPatchSync) {\n                await patcher.init(decodedDb)\n            }\n        }\n\n        updateKnownChatsAfterSuccessfulSave(db, toSave)\n\n        if (newEtag) {\n            forageStorage.setDbEtag(newEtag)\n        }\n\n\n        return 'saved'\n    }\n\n    async function triggerSave(options?: {\n        forceFullWrite?: boolean\n        skipBroadcast?: boolean\n    }) {\n        if (saveInFlight) {\n            // Mutations queued while a save is in flight belong to the next\n            // transaction. Chain that transaction explicitly; pagehide cannot\n            // otherwise consume the current promise and leave the final dirty\n            // chat stranded in changeTracker.\n            changed = true\n            const currentSave = saveInFlight\n            return currentSave.then(async () => {\n                if (changed || hasTrackedChanges(changeTracker)) {\n                    changed = false\n                    await triggerSave(options)\n                }\n            })\n        }\n\n        const toSave = takeTrackedChanges()\n        if (!hasTrackedChanges(toSave) && !options?.forceFullWrite) {\n            return\n        }\n\n        saveInFlight = (async () => {\n            saving.state = true\n            try {\n                const result = await persistTrackedChanges(toSave, options)\n                if (result === 'saved') {\n                    savetrys = 0\n                    deferredFailureRetries = 0\n                    if (deferredRecoveryTimer) {\n                        clearTimeout(deferredRecoveryTimer)\n                        deferredRecoveryTimer = null\n                    }\n                } else if (result === 'noop' && hasTrackedChanges(toSave)) {\n                    requeueTrackedChanges(toSave)\n                    changed = true\n                }\n                else if (result === 'retry') {\n                    savetrys += 1\n                    if (savetrys > 4) {\n                        // The rebased state is still dirty and remains in the\n                        // tracker, but deterministic 409s must not hammer the\n                        // server forever.\n                        changed = false\n                        alertError(new Error('Saving still conflicts after five rebases. Local edits were kept; reload or resolve the other active session before retrying.'))\n                        savetrys = 0\n                    }\n                    else {\n                        changed = true\n                    }\n                }\n            } catch (error) {\n                requeueTrackedChanges(toSave)\n                if (error instanceof ManualSaveConflictError) {\n                    changed = false\n                    savetrys = 0\n                    alertError(error)\n                    return\n                }\n                savetrys += 1\n                if (savetrys > 4) {\n                    alertError(error)\n                    savetrys = 0\n                    // Keep the dirty tracker and allow a couple of low-rate\n                    // recovery cycles for transient outages without creating\n                    // an unbounded upload loop on a persistent failure.\n                    if (deferredFailureRetries < 2) {\n                        deferredFailureRetries += 1\n                        scheduleDeferredRecovery(30_000)\n                    }\n                    else {\n                        // Persistent server/network outages must not turn a\n                        // dirty in-memory tracker into a permanent silent stop.\n                        // Retry at a low rate to avoid repeated large uploads;\n                        // `online`/visibility events above wake it sooner.\n                        scheduleDeferredRecovery(5 * 60_000)\n                    }\n                }\n                else {\n                    console.error(error)\n                    await sleep(Math.min(500 * savetrys, 3000))\n                    changed = true\n                }\n            } finally {\n                saving.state = false\n                saveInFlight = null\n            }\n        })()\n\n        return saveInFlight\n    }\n\n    requestImmediateSaveImpl = async (options) => {\n        changed = true\n        await tick()\n        await triggerSave({\n            forceFullWrite: options?.forceFullWrite,\n        })\n    }\n\n    requestImportedCharacterSaveImpl = async (chaId) => {\n        const database = getDatabase()\n        const character = database.characters?.find((item) => item?.chaId === chaId)\n        if (!character) {\n            throw new Error('Imported character is no longer present')\n        }\n\n        queueTrackedCharacter(chaId)\n        const expectedChatIds: string[] = []\n        for (const chat of character.chats ?? []) {\n            if (\n                typeof chat?.id !== 'string'\n                || chat.id.trim().length === 0\n                || chat._placeholder\n                || !Array.isArray(chat.message)\n            ) {\n                throw new Error('Imported character contains an invalid chat')\n            }\n            expectedChatIds.push(chat.id)\n            queueTrackedChat(chaId, chat.id)\n        }\n        if (expectedChatIds.length === 0) {\n            throw new Error('Imported character has no chat')\n        }\n\n        changed = true\n        await tick()\n        if (saveInFlight) await saveInFlight\n        await triggerSave()\n\n        const confirmedCharacter = lastConfirmedServerDb?.characters?.find(\n            (item) => item?.chaId === chaId,\n        )\n        const confirmedChatIds = new Set(\n            (confirmedCharacter?.chats ?? [])\n                .map((chat) => chat?.id)\n                .filter((id): id is string => typeof id === 'string' && id.length > 0),\n        )\n        if (\n            !confirmedCharacter\n            || expectedChatIds.some((chatId) => !confirmedChatIds.has(chatId))\n        ) {\n            throw new Error('Server has not confirmed the imported character yet')\n        }\n        await forageStorage.flushDatabase()\n    }\n\n    requestChatSaveImpl = async (chaId, chatId) => {\n        queueTrackedChat(chaId, chatId)\n        changed = true\n        await tick()\n        await triggerSave()\n    }\n\n    let savetrys = 0\n    let deferredFailureRetries = 0\n    let deferredRecoveryTimer: ReturnType<typeof setTimeout> | null = null\n    function scheduleDeferredRecovery(delayMs: number) {\n        if (deferredRecoveryTimer) clearTimeout(deferredRecoveryTimer)\n        deferredRecoveryTimer = setTimeout(() => {\n            deferredRecoveryTimer = null\n            if (hasTrackedChanges(changeTracker)) changed = true\n        }, delayMs)\n    }\n    while (true) {\n        if (!changed) {\n            await sleep(200)\n            continue\n        }\n        changed = false\n        if (requiresFullEncoderReload.state) {\n            encoder = new RisuSaveEncoder()\n            await encoder.init(getDatabase(), {\n                compression: false,\n                skipRemoteSavingOnCharacters: false\n            })\n            requiresFullEncoderReload.state = false\n        }\n        await triggerSave()\n        await sleep(100)\n    }\n}\n\n/**\n * Retrieves the database backups.\n * \n * @returns {Promise<number[]>} - A promise that resolves to an array of backup timestamps.\n */\nexport async function getDbBackups(currentDbSize?: number) {\n    const keys = await forageStorage.keys()\n\n    const backups = keys\n        .filter(key => key.startsWith('database/dbbackup-'))\n        .map(key => parseInt(key.slice(18, -4)))\n        .sort((a, b) => b - a);\n\n    const BACKUP_BUDGET = 500 * 1024 * 1024 // 500MB\n    const maxBackups = currentDbSize\n        ? Math.min(20, Math.max(3, Math.floor(BACKUP_BUDGET / currentDbSize)))\n        : 20\n\n    while (backups.length > maxBackups) {\n        const last = backups.pop()\n        await forageStorage.removeItem(`database/dbbackup-${last}.bin`)\n    }\n    return backups\n}\n\nlet usingSw = false\n\nexport function setUsingSw(value: boolean) {\n    usingSw = value\n}\n\n\nconst knownHostes = [\"localhost\", \"127.0.0.1\", \"0.0.0.0\"];\n\n/**\n * Interface representing the arguments for the global fetch function.\n * \n * @interface GlobalFetchArgs\n * @property {boolean} [plainFetchForce] - Whether to force plain fetch.\n * @property {any} [body] - The body of the request.\n * @property {{ [key: string]: string }} [headers] - The headers of the request.\n * @property {boolean} [rawResponse] - Whether to return the raw response.\n * @property {'POST' | 'GET'} [method] - The HTTP method to use.\n * @property {AbortSignal} [abortSignal] - The abort signal to cancel the request.\n * @property {boolean} [useRisuToken] - Whether to use the Risu token.\n * @property {string} [chatId] - The chat ID associated with the request.\n */\ninterface GlobalFetchArgs {\n    plainFetchForce?: boolean;\n    plainFetchDeforce?: boolean;\n    body?: any;\n    headers?: { [key: string]: string };\n    rawResponse?: boolean;\n    method?: 'POST' | 'GET';\n    abortSignal?: AbortSignal;\n    useRisuToken?: boolean;\n    chatId?: string;\n    interceptor?: string;\n    requestTimeoutMs?: number;\n    networkRoute?: 'auto' | 'local_network';\n    /** Request-log classification. Defaults to the neutral 'other'/'other';\n     *  LLM call sites pass 'llm' plus the issuing part of the app so the log's\n     *  default filter and the usage statistics can tell them apart. */\n    logCategory?: RequestLogCategory;\n    logSource?: RequestLogSource;\n    logModel?: string;\n}\n\n/**\n * Interface representing the result of the global fetch function.\n * \n * @interface GlobalFetchResult\n * @property {boolean} ok - Whether the request was successful.\n * @property {any} data - The data returned from the request.\n * @property {{ [key: string]: string }} headers - The headers returned from the request.\n */\ninterface GlobalFetchResult {\n    ok: boolean;\n    data: any;\n    headers: { [key: string]: string };\n    status: number;\n}\n\n/**\n * Performs a global fetch request.\n * \n * @param {string} url - The URL to fetch.\n * @param {GlobalFetchArgs} [arg={}] - The arguments for the fetch request.\n * @returns {Promise<GlobalFetchResult>} - The result of the fetch request.\n */\nexport async function globalFetch(url: string, arg: GlobalFetchArgs = {}): Promise<GlobalFetchResult> {\n    try {\n        const db = getDatabase();\n\n        if (arg.abortSignal?.aborted) { return { ok: false, data: 'aborted', headers: {}, status: 400 }; }\n\n        const urlHost = new URL(url).hostname\n        const useLocalNetworkRoute = arg.networkRoute === 'local_network' && isLocalNetworkUrl(url)\n        const forcePlainFetch = ((knownHostes.includes(urlHost)) || db.usePlainFetch || arg.plainFetchForce) && !arg.plainFetchDeforce && !useLocalNetworkRoute\n\n        if(arg.interceptor){\n            for (const interceptor of bodyIntercepterStore) {\n                try {\n                    arg.body = await interceptor.callback(arg.body, arg.interceptor) || arg.body\n                }\n                catch (e) {\n                    console.error(e)\n                }\n            }\n        }\n\n        const timeoutSignal = buildTimeoutSignal(arg.abortSignal, arg.requestTimeoutMs)\n        const requestArg = timeoutSignal.signal === arg.abortSignal\n            ? arg\n            : { ...arg, abortSignal: timeoutSignal.signal }\n\n        try {\n            if (useLocalNetworkRoute) {\n                return await fetchWithProxy(url, requestArg);\n            }\n\n            if (forcePlainFetch) {\n                return await fetchWithPlainFetch(url, requestArg);\n            }\n            //userScriptFetch is provided by userscript\n            if (window.userScriptFetch && !arg.plainFetchDeforce) {\n                return await fetchWithUSFetch(url, requestArg);\n            }\n            return await fetchWithProxy(url, requestArg);\n        } finally {\n            timeoutSignal.cleanup()\n        }\n\n    } catch (error) {\n        console.error(error);\n        return { ok: false, data: `${error}`, headers: {}, status: 400 };\n    }\n}\n\n/**\n * Records a completed globalFetch request in the server request log.\n *\n * @param {any} response - The response data.\n * @param {boolean} success - Indicates if the fetch was successful.\n * @param {string} url - The URL of the fetch request.\n * @param {GlobalFetchArgs} arg - The arguments for the fetch request.\n * @param {number} started - Epoch ms when the request was issued, for duration.\n */\nfunction addFetchLogInGlobalFetch(response: any, success: boolean, url: string, arg: GlobalFetchArgs, status: number | undefined, started: number) {\n    // Opt-in, same rule as fetchNative: untagged call sites (TTS polling,\n    // asset downloads, plugin traffic) are not worth a persisted row.\n    if (!arg.logCategory) return\n    const stringify = (value: unknown) => {\n        try {\n            return typeof value === 'string' ? value : JSON.stringify(value, null, 2)\n        } catch {\n            return `${value}`\n        }\n    }\n    recordRequestLog({\n        timestamp: started,\n        category: arg.logCategory ?? 'other',\n        source: arg.logSource ?? 'other',\n        chatId: arg.chatId,\n        model: arg.logModel,\n        url,\n        method: arg.method ?? 'POST',\n        status,\n        success,\n        streaming: false,\n        durationMs: Date.now() - started,\n        requestHeaders: stringify(arg.headers ?? {}),\n        requestBody: stringify(arg.body),\n        responseBody: stringify(response),\n    })\n}\n\n/**\n * Performs a fetch request using plain fetch.\n * \n * @param {string} url - The URL to fetch.\n * @param {GlobalFetchArgs} arg - The arguments for the fetch request.\n * @returns {Promise<GlobalFetchResult>} - The result of the fetch request.\n */\nasync function fetchWithPlainFetch(url: string, arg: GlobalFetchArgs): Promise<GlobalFetchResult> {\n    try {\n        const started = Date.now();\n        const headers = { 'Content-Type': 'application/json', ...arg.headers };\n        const response = await fetch(new URL(url), { body: JSON.stringify(arg.body), headers, method: arg.method ?? \"POST\", signal: arg.abortSignal });\n        const data = arg.rawResponse ? new Uint8Array(await response.arrayBuffer()) : await response.json();\n        const ok = response.ok && response.status >= 200 && response.status < 300;\n        addFetchLogInGlobalFetch(data, ok, url, arg, response.status, started);\n        return { ok, data, headers: Object.fromEntries(response.headers), status: response.status };\n    } catch (error) {\n        return { ok: false, data: `${error}`, headers: {}, status: 400 };\n    }\n}\n\n/**\n * Performs a fetch request using userscript provided fetch.\n * \n * @param {string} url - The URL to fetch.\n * @param {GlobalFetchArgs} arg - The arguments for the fetch request.\n * @returns {Promise<GlobalFetchResult>} - The result of the fetch request.\n */\nasync function fetchWithUSFetch(url: string, arg: GlobalFetchArgs): Promise<GlobalFetchResult> {\n    try {\n        const started = Date.now();\n        const headers = { 'Content-Type': 'application/json', ...arg.headers };\n        const response = await userScriptFetch(url, { body: JSON.stringify(arg.body), headers, method: arg.method ?? \"POST\", signal: arg.abortSignal });\n        const data = arg.rawResponse ? new Uint8Array(await response.arrayBuffer()) : await response.json();\n        const ok = response.ok && response.status >= 200 && response.status < 300;\n        addFetchLogInGlobalFetch(data, ok, url, arg, response.status, started);\n        return { ok, data, headers: Object.fromEntries(response.headers), status: response.status };\n    } catch (error) {\n        return { ok: false, data: `${error}`, headers: {}, status: 400 };\n    }\n}\n\n/**\n * Performs a fetch request using a proxy.\n * \n * @param {string} url - The URL to fetch.\n * @param {GlobalFetchArgs} arg - The arguments for the fetch request.\n * @returns {Promise<GlobalFetchResult>} - The result of the fetch request.\n */\nasync function fetchWithProxy(url: string, arg: GlobalFetchArgs): Promise<GlobalFetchResult> {\n    try {\n        const started = Date.now();\n        const furl = `/proxy2`;\n        arg.headers[\"Content-Type\"] ??= arg.body instanceof URLSearchParams ? \"application/x-www-form-urlencoded\" : \"application/json\";\n        const headers = {\n            \"risu-header\": encodeURIComponent(JSON.stringify(arg.headers)),\n            \"risu-url\": encodeURIComponent(url),\n            \"Content-Type\": arg.body instanceof URLSearchParams ? \"application/x-www-form-urlencoded\" : \"application/json\",\n            ...(arg.useRisuToken && { \"x-risu-tk\": \"use\" }),\n            ...(DBState?.db?.requestLocation && { \"risu-location\": DBState.db.requestLocation }),\n        };\n\n        // Add risu-auth header for Node.js server\n        headers[\"risu-auth\"] = await forageStorage.createAuth();\n\n        const body = arg.body instanceof URLSearchParams ? arg.body.toString() : JSON.stringify(arg.body);\n\n        const response = await fetch(furl, { body, headers, method: arg.method ?? \"POST\", signal: arg.abortSignal });\n        const isSuccess = response.ok && response.status >= 200 && response.status < 300;\n\n        if (arg.rawResponse) {\n            const data = new Uint8Array(await response.arrayBuffer());\n            addFetchLogInGlobalFetch(\"Uint8Array Response\", isSuccess, url, arg, response.status, started);\n            return { ok: isSuccess, data, headers: Object.fromEntries(response.headers), status: response.status };\n        }\n\n        const text = await response.text();\n        try {\n            const data = JSON.parse(text);\n            addFetchLogInGlobalFetch(data, isSuccess, url, arg, response.status, started);\n            return { ok: isSuccess, data, headers: Object.fromEntries(response.headers), status: response.status };\n        } catch (error) {\n            const errorMsg = text.startsWith('<!DOCTYPE') ? \"Responded HTML. Is your URL, API key, and password correct?\" : text;\n            addFetchLogInGlobalFetch(text, false, url, arg, response.status, started);\n            return { ok: false, data: errorMsg, headers: Object.fromEntries(response.headers), status: response.status };\n        }\n    } catch (error) {\n        return { ok: false, data: `${error}`, headers: {}, status: 400 };\n    }\n}\n\n/**\n * Regular expression to match backslashes.\n * \n * @constant {RegExp}\n */\nconst re = /\\\\/g;\n\n/**\n * Gets the basename of a given path.\n * \n * @param {string} data - The path to get the basename from.\n * @returns {string} - The basename of the path.\n */\nexport function getBasename(data: string) {\n    const splited = data.replace(re, '/').split('/');\n    const lasts = splited[splited.length - 1];\n    return lasts;\n}\n\n/**\n * Retrieves uncleanable resources from the database.\n * \n * @param {Database} db - The database to retrieve uncleanable resources from.\n * @param {'basename'|'pure'} [uptype='basename'] - The type of uncleanable resources to retrieve.\n * @returns {string[]} - An array of uncleanable resources.\n */\nexport function getUncleanables(db: Database, uptype: 'basename' | 'pure' = 'basename') {\n    const uncleanable = new Set<string>();\n\n    /**\n     * Adds a resource to the uncleanable list if it is not already included.\n     * \n     * @param {string} data - The resource to add.\n     */\n    function addUncleanable(data: string) {\n        if (!data) {\n            return;\n        }\n        if (data === '') {\n            return;\n        }\n        const bn = uptype === 'basename' ? getBasename(data) : data;\n        uncleanable.add(bn);\n    }\n\n    addUncleanable(db.customBackground);\n    addUncleanable(db.userIcon);\n    // Uploaded notification sounds. Preset-id values (e.g. \"bell\") are not\n    // asset paths, so they add a harmless basename that matches no stored asset.\n    addUncleanable(db.messageSound);\n    addUncleanable(db.translateSound);\n    if (db.customSounds) {\n        for (const s of db.customSounds) {\n            addUncleanable(s.path);\n        }\n    }\n\n    for (const cha of db.characters) {\n        if (cha.image) {\n            addUncleanable(cha.image);\n        }\n        if (cha.emotionImages) {\n            for (const em of cha.emotionImages) {\n                addUncleanable(em[1]);\n            }\n        }\n        if (cha.additionalAssets) {\n            for (const em of cha.additionalAssets) {\n                addUncleanable(em[1]);\n            }\n        }\n        if (cha.vits) {\n            const keys = Object.keys(cha.vits.files);\n            for (const key of keys) {\n                const vit = cha.vits.files[key];\n                addUncleanable(vit);\n            }\n        }\n        if (cha.ccAssets) {\n            for (const asset of cha.ccAssets) {\n                addUncleanable(asset.uri);\n            }\n        }\n    }\n\n    if (db.modules) {\n        for (const module of db.modules) {\n            const assets = module.assets\n            if (assets) {\n                for (const asset of assets) {\n                    addUncleanable(asset[1])\n                }\n            }\n            if(module.icon){\n                addUncleanable(module.icon)\n            }\n        }\n    }\n\n    if (db.personas) {\n        db.personas.map((v) => {\n            addUncleanable(v.icon);\n\n            if(v.embeddedModule){\n                const assets = v.embeddedModule.assets\n                if (assets) {\n                    for (const asset of assets) {\n                        addUncleanable(asset[1])\n                    }\n                }\n                if(v.embeddedModule.icon){\n                    addUncleanable(v.embeddedModule.icon)\n                }\n            }\n        });\n    }\n\n    if (db.characterOrder) {\n        db.characterOrder.forEach((item) => {\n            if (typeof item === 'object' && 'imgFile' in item) {\n                addUncleanable(item.imgFile);\n            }\n        })\n    }\n    return Array.from(uncleanable);\n}\n\n\n/**\n * Replaces database resources with the provided replacer object.\n * \n * @param {Database} db - The database object containing resources to be replaced.\n * @param {{[key: string]: string}} replacer - An object mapping original resource keys to their replacements.\n * @returns {Database} - The updated database object with replaced resources.\n */\nexport function replaceDbResources(db: Database, replacer: { [key: string]: string }): Database {\n    /**\n     * Replaces a given data string with its corresponding value from the replacer object.\n     * \n     * @param {string} data - The data string to be replaced.\n     * @returns {string} - The replaced data string or the original data if no replacement is found.\n     */\n    function replaceData(data: string): string {\n        if (!data) {\n            return data;\n        }\n        return replacer[data] ?? data;\n    }\n\n    db.customBackground = replaceData(db.customBackground);\n    db.userIcon = replaceData(db.userIcon);\n    db.messageSound = replaceData(db.messageSound);\n    db.translateSound = replaceData(db.translateSound);\n    if (db.customSounds) {\n        for (const s of db.customSounds) {\n            s.path = replaceData(s.path);\n        }\n    }\n\n    for (const cha of db.characters) {\n        if (cha.image) {\n            cha.image = replaceData(cha.image);\n        }\n        if (cha.emotionImages) {\n            for (let i = 0; i < cha.emotionImages.length; i++) {\n                cha.emotionImages[i][1] = replaceData(cha.emotionImages[i][1]);\n            }\n        }\n        if (cha.additionalAssets) {\n            for (let i = 0; i < cha.additionalAssets.length; i++) {\n                cha.additionalAssets[i][1] = replaceData(cha.additionalAssets[i][1]);\n            }\n        }\n    }\n    return db;\n}\n\n/**\n * Checks and updates the character order in the database.\n * Ensures that all characters are properly ordered and removes any invalid entries.\n */\nexport function checkCharOrder() {\n    let db = getDatabase()\n    db.characterOrder = db.characterOrder ?? []\n    let ordered = []\n    for (let i = 0; i < db.characterOrder.length; i++) {\n        const folder = db.characterOrder[i]\n        if (typeof (folder) !== 'string' && folder) {\n            for (const f of folder.data) {\n                ordered.push(f)\n            }\n        }\n        if (typeof (folder) === 'string') {\n            ordered.push(folder)\n        }\n    }\n\n    let charIdList: string[] = []\n\n    for (let i = 0; i < db.characters.length; i++) {\n        const char = db.characters[i]\n        const charId = char.chaId\n        if (!char.trashTime) {\n            charIdList.push(charId)\n        }\n        if (!ordered.includes(charId)) {\n            if (charId !== '§temp' && charId !== '§playground' && !char.trashTime) {\n                db.characterOrder.push(charId)\n            }\n        }\n    }\n\n\n    for (let i = 0; i < db.characterOrder.length; i++) {\n        const data = db.characterOrder[i]\n        if (typeof (data) !== 'string') {\n            if (!data) {\n                db.characterOrder.splice(i, 1)\n                i--;\n                continue\n            }\n            if (data.data.length === 0) {\n                db.characterOrder.splice(i, 1)\n                i--;\n                continue\n            }\n            for (let i2 = 0; i2 < data.data.length; i2++) {\n                const data2 = data.data[i2]\n                if (!charIdList.includes(data2)) {\n                    data.data.splice(i2, 1)\n                    i2--;\n                }\n            }\n            db.characterOrder[i] = data\n        }\n        else {\n            if (!charIdList.includes(data)) {\n                db.characterOrder.splice(i, 1)\n                i--;\n            }\n        }\n    }\n\n\n}\n\n/**\n * Retrieves the most recent request logs. Kept for the plugin API (v3\n * getFetchLogs), which has always been Promise-returning, so moving the\n * storage server-side is invisible to plugins.\n */\nexport async function getFetchLogs(limit = 20) {\n    return await fetchRequestLogs({ limit, bodies: true })\n}\n\n/**\n * Opens a URL in the appropriate environment.\n * \n * @param {string} url - The URL to open.\n */\nexport function openURL(url: string) {\n    window.open(url, \"_blank\")\n}\n\n/**\n * Converts FormData to a URL-encoded string.\n * \n * @param {FormData} formData - The FormData to convert.\n * @returns {string} The URL-encoded string.\n */\nfunction formDataToString(formData: FormData): string {\n    const params: string[] = [];\n\n    for (const [name, value] of formData.entries()) {\n        params.push(`${encodeURIComponent(name)}=${encodeURIComponent(value.toString())}`);\n    }\n\n    return params.join('&');\n}\n\n/**\n * Class representing a local writer.\n */\nexport class LocalWriter {\n    writer: WritableStreamDefaultWriter\n\n    /**\n     * Initializes the writer.\n     * \n     * @param {string} [name='Binary'] - The name of the file.\n     * @param {string[]} [ext=['bin']] - The file extensions.\n     * @returns {Promise<boolean>} - A promise that resolves to a boolean indicating success.\n     */\n    async init(name = 'Binary', ext = ['bin']): Promise<boolean> {\n        const writableStream = streamSaver.createWriteStream(name + '.' + ext[0])\n        this.writer = writableStream.getWriter()\n        return true\n    }\n\n    /**\n     * Writes backup data to the file.\n     * \n     * @param {string} name - The name of the backup.\n     * @param {Uint8Array} data - The data to write.\n     */\n    async writeBackup(name: string, data: Uint8Array): Promise<void> {\n        const encodedName = new TextEncoder().encode(getBasename(name))\n        const nameLength = new Uint32Array([encodedName.byteLength])\n        await this.writer.write(new Uint8Array(nameLength.buffer))\n        await this.writer.write(encodedName)\n        const dataLength = new Uint32Array([data.byteLength])\n        await this.writer.write(new Uint8Array(dataLength.buffer))\n        await this.writer.write(data)\n    }\n\n    /**\n     * Writes data to the file.\n     * \n     * @param {Uint8Array} data - The data to write.\n     */\n    async write(data: Uint8Array): Promise<void> {\n        await this.writer.write(data)\n    }\n\n    /**\n     * Closes the writer.\n     */\n    async close(): Promise<void> {\n        await this.writer.close()\n    }\n}\n\n/**\n * Class representing a virtual writer.\n */\nexport class VirtualWriter {\n    buf = new AppendableBuffer()\n\n    /**\n     * Writes data to the buffer.\n     * \n     * @param {Uint8Array} data - The data to write.\n     */\n    write(data: Uint8Array): void {\n        this.buf.append(data)\n    }\n\n    /**\n     * Closes the writer. (No operation for VirtualWriter)\n     */\n    close(): void {\n        // do nothing\n    }\n}\n\n/**\n * Index for fetch operations.\n * @type {number}\n */\nlet fetchIndex = 0\n\n/**\n * Stores native fetch data.\n * @type {{ [key: string]: StreamedFetchChunk[] }}\n */\nlet nativeFetchData: { [key: string]: StreamedFetchChunk[] } = {}\n\n/**\n * Interface representing a streamed fetch chunk data.\n * @interface\n */\ninterface StreamedFetchChunkData {\n    type: 'chunk',\n    body: string,\n    id: string\n}\n\n/**\n * Interface representing a streamed fetch header data.\n * @interface\n */\ninterface StreamedFetchHeaderData {\n    type: 'headers',\n    body: { [key: string]: string },\n    id: string,\n    status: number\n}\n\n/**\n * Interface representing a streamed fetch end data.\n * @interface\n */\ninterface StreamedFetchEndData {\n    type: 'end',\n    id: string\n}\n\n/**\n * Type representing a streamed fetch chunk.\n * @typedef {StreamedFetchChunkData | StreamedFetchHeaderData | StreamedFetchEndData} StreamedFetchChunk\n */\ntype StreamedFetchChunk = StreamedFetchChunkData | StreamedFetchHeaderData | StreamedFetchEndData\n\n/**\n * Interface representing a streamed fetch plugin.\n * @interface\n */\ninterface StreamedFetchPlugin {\n    /**\n     * Performs a streamed fetch operation.\n     * @param {Object} options - The options for the fetch operation.\n     * @param {string} options.id - The ID of the fetch operation.\n     * @param {string} options.url - The URL to fetch.\n     * @param {string} options.body - The body of the fetch request.\n     * @param {{ [key: string]: string }} options.headers - The headers of the fetch request.\n     * @returns {Promise<{ error: string, success: boolean }>} - The result of the fetch operation.\n     */\n    streamedFetch(options: { id: string, url: string, body: string, headers: { [key: string]: string } }): Promise<{ \"error\": string, \"success\": boolean }>;\n\n    /**\n     * Adds a listener for the specified event.\n     * @param {string} eventName - The name of the event.\n     * @param {(data: StreamedFetchChunk) => void} listenerFunc - The function to call when the event is triggered.\n     */\n    addListener(eventName: 'streamed_fetch', listenerFunc: (data: StreamedFetchChunk) => void): void;\n}\n\n/**\n * Indicates whether streamed fetch listening is active.\n * @type {boolean}\n */\nlet streamedFetchListening = false\n\n/**\n * The streamed fetch plugin instance.\n * @type {StreamedFetchPlugin | undefined}\n */\nlet capStreamedFetch: StreamedFetchPlugin | undefined\n\n\n/**\n * A class to manage a buffer that can be appended to and deappended from.\n */\nexport class AppendableBuffer {\n    deapended: number = 0\n    #buffer: Uint8Array\n    #byteLength: number = 0\n\n    /**\n     * Creates an instance of AppendableBuffer.\n     */\n    constructor() {\n        this.#buffer = new Uint8Array(128)\n    }\n\n    get buffer(): Uint8Array {\n        return this.#buffer.slice(0, this.#byteLength)\n    }\n\n    /**\n     * Appends data to the buffer.\n     * @param {Uint8Array} data - The data to append.\n     */\n    append(data: Uint8Array) {\n        // New way (faster)\n        const requiredLength = this.#byteLength + data.length\n        if (this.#buffer.byteLength < requiredLength) {\n            let newLength = this.#buffer.byteLength * 2\n            while (newLength < requiredLength) {\n                newLength *= 2\n            }\n            const newBuffer = new Uint8Array(newLength)\n            newBuffer.set(this.#buffer)\n            this.#buffer = newBuffer\n        }\n        this.#buffer.set(data, this.#byteLength)\n        this.#byteLength += data.length\n    }\n\n    /**\n     * Deappends a specified length from the buffer.\n     * @param {number} length - The length to deappend.\n     */\n    deappend(length: number) {\n        this.#buffer = this.#buffer.slice(length)\n        this.deapended += length\n        this.#byteLength -= length\n    }\n\n    /**\n     * Slices the buffer from start to end.\n     * @param {number} start - The start index.\n     * @param {number} end - The end index.\n     * @returns {Uint8Array} - The sliced buffer.\n     */\n    slice(start: number, end: number) {\n        return this.buffer.slice(start - this.deapended, end - this.deapended)\n    }\n\n    /**\n     * Gets the total length of the buffer including deappended length.\n     * @returns {number} - The total length.\n     */\n    length() {\n        return this.#byteLength + this.deapended\n    }\n\n    /**\n     * Clears the buffer.\n     */\n    clear() {\n        this.#buffer = new Uint8Array(128)\n        this.#byteLength = 0\n        this.deapended = 0\n    }\n}\n\n/**\n * Fetches data from a given URL using native fetch or through a proxy.\n * @param {string} url - The URL to fetch data from.\n * @param {Object} arg - The arguments for the fetch request.\n * @param {string} arg.body - The body of the request.\n * @param {Object} [arg.headers] - The headers of the request.\n * @param {string} [arg.method=\"POST\"] - The HTTP method of the request.\n * @param {AbortSignal} [arg.signal] - The signal to abort the request.\n * @param {boolean} [arg.useRisuTk] - Whether to use Risu token.\n * @param {string} [arg.chatId] - The chat ID associated with the request.\n * @returns {Promise<Object>} - A promise that resolves to an object containing the response body, headers, and status.\n * @returns {ReadableStream<Uint8Array>} body - The response body as a readable stream.\n * @returns {Headers} headers - The response headers.\n * @returns {number} status - The response status code.\n * @throws {Error} - Throws an error if the request is aborted or if there is an error in the response.\n */\nexport interface FetchNativeArgs {\n    body?: string | Uint8Array | ArrayBuffer,\n    headers?: { [key: string]: string },\n    method?: \"POST\" | \"GET\" | \"PUT\" | \"DELETE\",\n    signal?: AbortSignal,\n    useRisuTk?: boolean,\n    chatId?: string\n    interceptor?: string\n    requestTimeoutMs?: number\n    networkRoute?: 'auto' | 'local_network'\n    /** Request-log classification; see GlobalFetchArgs for the same fields. */\n    logCategory?: RequestLogCategory\n    logSource?: RequestLogSource\n    logModel?: string\n    /** Reports which transport was actually used. Fires regardless of\n     *  logCategory, so a caller that logs at a higher level (the model-preset\n     *  path) can record the true route instead of guessing. */\n    onLogRoute?: (route: RequestLogRoute) => void\n}\n\nexport async function fetchNative(url: string, arg: FetchNativeArgs): Promise<Response> {\n    // Logging is OPT-IN: only call sites that tag a category are recorded.\n    // Logging everything that passes through here was actively harmful —\n    // ComfyUI polls /history once a second, /view returns a PNG that would be\n    // text-decoded and stored, an MCP SSE connection stays open for the whole\n    // session, and makeProxiedFetch routes the model-preset path through here,\n    // which produced a second, untagged row for every preset request.\n    if (!arg.logCategory) {\n        return fetchNativeRaw(url, arg, { onRoute: arg.onLogRoute })\n    }\n    // Logging wraps the transport rather than living inside it: fetchNativeRaw\n    // returns from several branches (userscript / WS proxy job / proxy2 /\n    // direct), and the response body is a stream that must be tee'd exactly\n    // once. The scope handles both, and assembles the streamed text so the log\n    // records the real response instead of a \"Streamed Fetch\" placeholder.\n    const scope = createRequestLogScope({\n        category: arg.logCategory ?? 'other',\n        source: arg.logSource ?? 'other',\n        chatId: arg.chatId,\n        model: arg.logModel,\n        streaming: true,\n    })\n    const logged = scope.wrap(((_input: RequestInfo | URL, _init?: RequestInit) =>\n        fetchNativeRaw(url, arg, {\n            onRealBody: (body) => scope.setRequestBody(body),\n            onRoute: (route) => { scope.setRoute(route); arg.onLogRoute?.(route) },\n        })\n    ) as typeof fetch)\n    try {\n        return await logged(url, {\n            method: arg.method ?? 'POST',\n            headers: arg.headers,\n            body: arg.body as BodyInit | undefined,\n        })\n    } finally {\n        // Fire-and-forget: close() waits for the tee'd body to finish\n        // assembling, which outlives this return for a streamed response.\n        void scope.close()\n    }\n}\n\nasync function fetchNativeRaw(url: string, arg: FetchNativeArgs, hooks?: {\n    onRealBody?: (body: string) => void,\n    onRoute?: (route: RequestLogRoute) => void,\n}): Promise<Response> {\n    const useInterceptor = !!arg.interceptor\n    if (arg.body === undefined && (arg.method === 'POST' || arg.method === 'PUT')) {\n        throw new Error('Body is required for POST and PUT requests')\n    }\n\n    arg.method = arg.method ?? 'POST'\n\n    const headers = arg.headers ?? {}\n    let realBody: Uint8Array | undefined\n\n    if (arg.method === 'GET' || arg.method === 'DELETE') {\n        realBody = undefined\n    }\n    else if (typeof arg.body === 'string') {\n        let body: string = arg.body\n        if(useInterceptor) {\n            for (const interceptor of bodyIntercepterStore) {\n                try {\n                    body = await interceptor.callback(body, arg.interceptor) || body\n                }\n                catch (e) {\n                    console.error(e)\n                }\n            }\n        }\n        realBody = new TextEncoder().encode(body)\n    }\n    else if (arg.body instanceof Uint8Array) {\n        realBody = arg.body\n    }\n    else if (arg.body instanceof ArrayBuffer) {\n        realBody = new Uint8Array(arg.body)\n    }\n    else {\n        throw new Error('Invalid body type')\n    }\n\n    // The logged body is the one actually sent — after any body interceptor\n    // rewrote it — which is why it is reported from here rather than from the\n    // wrapper's view of arg.body.\n    hooks?.onRealBody?.(realBody ? new TextDecoder().decode(realBody) : '')\n    const useLocalNetworkRoute = arg.networkRoute === 'local_network' && isLocalNetworkUrl(url)\n    const timeoutSignal = buildTimeoutSignal(arg.signal, arg.requestTimeoutMs)\n    const requestSignal = timeoutSignal.signal\n    const db = getDatabase()\n    let throughProxy = !db.usePlainFetch\n    if (useLocalNetworkRoute) {\n        throughProxy = true\n    }\n\n    try {\n        if (window.userScriptFetch && !throughProxy) {\n            hooks?.onRoute?.('direct')\n            return await window.userScriptFetch(url, {\n                body: realBody as any,\n                headers: headers,\n                method: arg.method,\n                signal: requestSignal\n            })\n        }\n\n        // Local network streaming: try WebSocket proxy job, fallback to /proxy2\n        const useProxyJobWs = useLocalNetworkRoute\n            && arg.interceptor === 'openai_streaming'\n            && arg.method === 'POST'\n        if (useProxyJobWs) {\n            try {\n                const res = await fetchViaProxyJobWs(url, {\n                    method: arg.method,\n                    headers,\n                    body: realBody,\n                    signal: requestSignal,\n                    requestTimeoutMs: arg.requestTimeoutMs,\n                })\n                hooks?.onRoute?.('proxy')\n                return res\n            } catch (wsErr) {\n                console.warn('[ProxyJobWS] fallback to /proxy2 due to error:', wsErr)\n            }\n        }\n\n        // Local network non-streaming or WS fallback: go through /proxy2 directly\n        if (useLocalNetworkRoute) {\n            hooks?.onRoute?.('proxy')\n            return await fetchViaProxy2(url, headers, realBody, {\n                ...arg,\n                signal: requestSignal\n            })\n        }\n\n        // Try direct fetch first (upstream behavior), fall back to proxy on CORS/network error\n        try {\n            const res = await fetch(url, {\n                body: realBody as any,\n                headers: headers,\n                method: arg.method,\n                signal: requestSignal,\n            })\n            hooks?.onRoute?.('direct')\n            return res\n        } catch (e) {\n            if (requestSignal?.aborted) throw e\n            // The route is only known once the direct attempt has failed, which\n            // is why it is reported here rather than guessed up front.\n            hooks?.onRoute?.('proxy')\n            return await fetchViaProxy2(url, headers, realBody, {\n                ...arg,\n                signal: requestSignal\n            })\n        }\n    } finally {\n        timeoutSignal.cleanup()\n    }\n}\n\nconst defaultProxyJobHeartbeatSec = 15\n\nasync function fetchViaProxy2(\n    url: string,\n    headers: Record<string, string>,\n    realBody: Uint8Array | undefined,\n    arg: { method?: string, signal?: AbortSignal, useRisuTk?: boolean, requestTimeoutMs?: number }\n): Promise<Response> {\n    const proxyHeaders: Record<string, string> = {\n        \"risu-header\": encodeURIComponent(JSON.stringify(headers)),\n        \"risu-url\": encodeURIComponent(url),\n        \"risu-auth\": await forageStorage.createAuth(),\n        ...(arg.useRisuTk ? { \"x-risu-tk\": \"use\" } : {}),\n        ...(arg.requestTimeoutMs && { \"risu-timeout-ms\": Math.max(1, Math.floor(arg.requestTimeoutMs)).toString() }),\n        ...(DBState?.db?.requestLocation ? { \"risu-location\": DBState.db.requestLocation } : {}),\n    }\n\n    if (realBody) {\n        proxyHeaders[\"Content-Type\"] = headers[\"Content-Type\"] ?? headers[\"content-type\"] ?? \"application/json\"\n    }\n\n    const r = await fetch(`/proxy2`, {\n        body: realBody as any,\n        headers: proxyHeaders,\n        method: arg.method,\n        signal: arg.signal\n    })\n\n    return new Response(r.body, {\n        headers: r.headers,\n        status: r.status\n    })\n}\n\nasync function fetchViaProxyJobWs(url: string, arg: {\n    method: string,\n    headers: Record<string, string>,\n    body?: Uint8Array,\n    signal?: AbortSignal,\n    requestTimeoutMs?: number,\n}): Promise<Response> {\n    const auth = await forageStorage.createAuth()\n    const bodyBase64 = arg.body ? Buffer.from(arg.body).toString('base64') : ''\n\n    const jobRes = await fetch('/proxy-stream-jobs', {\n        method: 'POST',\n        headers: {\n            'Content-Type': 'application/json',\n            'risu-auth': auth,\n        },\n        body: JSON.stringify({\n            url,\n            method: arg.method,\n            headers: arg.headers,\n            bodyBase64,\n            timeoutMs: arg.requestTimeoutMs,\n            heartbeatSec: defaultProxyJobHeartbeatSec,\n        }),\n        signal: arg.signal,\n    })\n\n    if (!jobRes.ok) {\n        throw new Error(`Failed to create proxy stream job: ${jobRes.status} ${await jobRes.text()}`)\n    }\n\n    const { jobId } = await jobRes.json() as { jobId: string }\n    const wsProtocol = location.protocol === 'https:' ? 'wss:' : 'ws:'\n    const wsUrl = `${wsProtocol}//${location.host}/proxy-stream-jobs/${encodeURIComponent(jobId)}/ws?risu-auth=${encodeURIComponent(auth)}`\n\n    return new Promise<Response>((resolve, reject) => {\n        const ws = new WebSocket(wsUrl)\n        let resolved = false\n        let responseStatus = 200\n        let responseHeaders: Record<string, string> = {}\n        let streamController: ReadableStreamDefaultController<Uint8Array> | null = null\n\n        const stream = new ReadableStream<Uint8Array>({\n            start(controller) {\n                streamController = controller\n            },\n            cancel() {\n                ws.close()\n                fetch(`/proxy-stream-jobs/${encodeURIComponent(jobId)}`, {\n                    method: 'DELETE',\n                    headers: { 'risu-auth': auth },\n                }).catch(() => {})\n            }\n        })\n\n        const abortHandler = () => {\n            ws.close()\n            fetch(`/proxy-stream-jobs/${encodeURIComponent(jobId)}`, {\n                method: 'DELETE',\n                headers: { 'risu-auth': auth },\n            }).catch(() => {})\n            if (!resolved) {\n                resolved = true\n                reject(new DOMException('Aborted', 'AbortError'))\n            }\n        }\n\n        if (arg.signal) {\n            if (arg.signal.aborted) {\n                abortHandler()\n                return\n            }\n            arg.signal.addEventListener('abort', abortHandler, { once: true })\n        }\n\n        ws.onmessage = (ev) => {\n            const event = parseProxyJobWsEvent(typeof ev.data === 'string' ? ev.data : '')\n            if (!event) return\n\n            switch (event.type) {\n                case 'job_accepted':\n                case 'ping':\n                    break\n                case 'upstream_headers':\n                    responseStatus = event.status\n                    responseHeaders = event.headers\n                    if (!resolved) {\n                        resolved = true\n                        resolve(new Response(stream, {\n                            status: responseStatus,\n                            headers: responseHeaders,\n                        }))\n                    }\n                    break\n                case 'chunk': {\n                    const bytes = decodeProxyJobWsChunk(event.dataBase64)\n                    streamController?.enqueue(bytes)\n                    break\n                }\n                case 'error': {\n                    const msg = formatProxyStreamErrorMessage(event.status, event.message)\n                    if (!resolved) {\n                        resolved = true\n                        resolve(new Response(msg, {\n                            status: event.status ?? 502,\n                            headers: { 'content-type': 'text/plain' },\n                        }))\n                    }\n                    streamController?.close()\n                    break\n                }\n                case 'done':\n                    streamController?.close()\n                    break\n            }\n        }\n\n        ws.onerror = () => {\n            if (!resolved) {\n                resolved = true\n                reject(new Error('WebSocket connection failed'))\n            }\n        }\n\n        ws.onclose = () => {\n            arg.signal?.removeEventListener('abort', abortHandler)\n            try { streamController?.close() } catch { /* already closed */ }\n            if (!resolved) {\n                resolved = true\n                reject(new Error('WebSocket closed before response'))\n            }\n        }\n    })\n}\n\n/**\n * Converts a ReadableStream of Uint8Array to a text string.\n * \n * @param {ReadableStream<Uint8Array>} stream - The readable stream to convert.\n * @returns {Promise<string>} A promise that resolves to the text content of the stream.\n */\nexport function textifyReadableStream(stream: ReadableStream<Uint8Array>) {\n    return new Response(stream).text()\n}\n\n/**\n * Toggles the fullscreen mode of the document.\n * If the document is currently in fullscreen mode, it exits fullscreen.\n * If the document is not in fullscreen mode, it requests fullscreen with navigation UI hidden.\n */\nexport function toggleFullscreen() {\n    const fullscreenElement = document.fullscreenElement\n    fullscreenElement ? document.exitFullscreen() : document.documentElement.requestFullscreen({\n        navigationUI: \"hide\"\n    })\n}\n\n/**\n * Removes non-Latin characters from a string, replaces multiple spaces with a single space, and trims the string.\n * \n * @param {string} data - The input string to be processed.\n * @returns {string} The processed string with non-Latin characters removed, multiple spaces replaced by a single space, and trimmed.\n */\nexport function trimNonLatin(data: string) {\n    return data.replace(/[^\\x00-\\x7F]/g, \"\")\n        .replace(/ +/g, ' ')\n        .trim()\n}\n\n/**\n * A class that provides a blank writer implementation.\n * \n * This class is used to provide a no-op implementation of a writer, making it compatible with other writer interfaces.\n */\nexport class BlankWriter {\n    constructor() {\n    }\n\n    /**\n     * Initializes the writer.\n     * \n     * This method does nothing and is provided for compatibility with other writer interfaces.\n     */\n    async init() {\n        //do nothing, just to make compatible with other writer\n    }\n\n    /**\n     * Writes data to the writer.\n     * \n     * This method does nothing and is provided for compatibility with other writer interfaces.\n     * \n     * @param {string} key - The key associated with the data.\n     * @param {Uint8Array|string} data - The data to be written.\n     */\n    async write(key: string, data: Uint8Array | string) {\n        //do nothing, just to make compatible with other writer\n    }\n\n    /**\n     * Ends the writing process.\n     * \n     * This method does nothing and is provided for compatibility with other writer interfaces.\n     */\n    async end() {\n        //do nothing, just to make compatible with other writer\n    }\n}\n\nexport async function loadInternalBackup() {\n\n    const keys = await forageStorage.keys()\n    const internalBackups = keys\n        .filter((key) => key.startsWith('database/dbbackup-'))\n        .sort((a, b) => {\n            const aTs = parseInt(a.replace('database/dbbackup-', '').replace('.bin', ''))\n            const bTs = parseInt(b.replace('database/dbbackup-', '').replace('.bin', ''))\n            return bTs - aTs\n        })\n\n    const selectOptions = [\n        'Cancel',\n        ...(internalBackups.map((a) => {\n            return (new Date(parseInt(a.replace('database/dbbackup-', '').replace('dbbackup-', '')) * 100)).toLocaleString()\n        }))\n    ]\n\n    const alertResult = parseInt(\n        await alertSelect(selectOptions)\n    ) - 1\n\n    if (alertResult === -1) {\n        return\n    }\n\n    const selectedBackup = internalBackups[alertResult]\n\n    const data = await forageStorage.getItem(selectedBackup)\n\n    const backupDecoded = await decodeRisuSave(Buffer.from(data) as unknown as Uint8Array)\n    setDatabase(backupDecoded)\n\n    notifySuccess('Loaded backup')\n\n\n\n}\n\n/**\n * A debugging class for performance measurement.\n*/\n\nexport class PerformanceDebugger {\n    kv: { [key: string]: number[] } = {}\n    startTime: number\n    endTime: number\n\n    /**\n     * Starts the timing measurement.\n    */\n    start() {\n        this.startTime = performance.now()\n    }\n\n    /**\n     * Ends the timing measurement and records the time difference.\n     * \n     * @param {string} key - The key to associate with the recorded time.\n    */\n    endAndRecord(key: string) {\n        this.endTime = performance.now()\n        if (!this.kv[key]) {\n            this.kv[key] = []\n        }\n        this.kv[key].push(this.endTime - this.startTime)\n    }\n\n    /**\n     * Ends the timing measurement, records the time difference, and starts a new timing measurement.\n     * \n     * @param {string} key - The key to associate with the recorded time.\n    */\n    endAndRecordAndStart(key: string) {\n        this.endAndRecord(key)\n        this.start()\n    }\n\n    /**\n     * Logs the average time for each key to the console.\n    */\n    log() {\n        let table: { [key: string]: number } = {}\n\n        for (const key in this.kv) {\n            table[key] = this.kv[key].reduce((a, b) => a + b, 0) / this.kv[key].length\n        }\n\n\n        console.table(table)\n    }\n\n    combine(other: PerformanceDebugger) {\n        for (const key in other.kv) {\n            if (!this.kv[key]) {\n                this.kv[key] = []\n            }\n            this.kv[key].push(...other.kv[key])\n        }\n    }\n}\n\nexport function getLanguageCodes() {\n    let languageCodes: {\n        code: string\n        name: string\n    }[] = []\n\n    for (let i = 0x41; i <= 0x5A; i++) {\n        for (let j = 0x41; j <= 0x5A; j++) {\n            languageCodes.push({\n                code: String.fromCharCode(i) + String.fromCharCode(j),\n                name: ''\n            })\n        }\n    }\n\n    languageCodes = languageCodes.map(v => {\n        return {\n            code: v.code.toLocaleLowerCase(),\n            name: new Intl.DisplayNames([\n                DBState.db.language === 'cn' ? 'zh' : DBState.db.language\n            ], {\n                type: 'language',\n                fallback: 'none'\n            }).of(v.code)\n        }\n    }).filter((a) => {\n        return a.name\n    }).sort((a, b) => a.name.localeCompare(b.name))\n\n    return languageCodes\n}\n\nexport function getVersionString(): string {\n    return nodeOnlyVer\n}\n\nexport function toGetter<T extends object>(\n    getterFn: () => T,\n    args?: {\n        //blocks this.children from being accessed\n        restrictChildren:string[]\n    }\n): T {\n\n    const dummyTarget = () => { };\n\n    return new Proxy(dummyTarget, {\n        get(target, prop, receiver) {\n\n            const realInstance = getterFn();\n            \n            if (args?.restrictChildren && args.restrictChildren.includes(prop as string)) {\n                throw new Error(`Access to property '${String(prop)}' is restricted`);\n            }\n\n            if (realInstance === null || realInstance === undefined) {\n                return (realInstance as any)[prop];\n            }\n\n            const value = Reflect.get(realInstance as object, prop);\n\n            if (typeof value === 'function') {\n                return value.bind(realInstance);\n            }\n\n            return value;\n        },\n\n        set(target, prop, value, receiver) {\n\n            if(args?.restrictChildren && args.restrictChildren.includes(prop as string)) {\n                throw new Error(`Access to property '${String(prop)}' is restricted`);\n            }\n            const realInstance = getterFn();\n            return Reflect.set(realInstance as object, prop, value, receiver);\n        },\n\n        has(target, prop) {\n            const realInstance = getterFn();\n            return Reflect.has(realInstance as object, prop);\n        },\n\n        ownKeys(target) {\n            const realInstance = getterFn();\n            return Reflect.ownKeys(realInstance as object);\n        },\n\n        construct(target, argArray, newTarget) {\n            const realInstance = getterFn() as any;\n            return new realInstance(...argArray);\n        },\n\n        deleteProperty(target, prop) {\n            const realInstance = getterFn();\n            return Reflect.deleteProperty(realInstance as object, prop);\n        },\n\n        getPrototypeOf() {\n            const realInstance = getterFn();\n            return Reflect.getPrototypeOf(realInstance as object);\n        }\n    }) as unknown as T;\n}\n\nconst countriesWithAiLaw = new Set<string>([\n\n    // EU\n    // AI Act\n    // https://artificialintelligenceact.eu/\n    \n    \"AT\",\n    \"BE\",\n    \"BG\",\n    \"HR\",\n    \"CY\",\n    \"CZ\",\n    \"DK\",\n    \"EE\",\n    \"FI\",\n    \"FR\",\n    \"DE\",\n    \"EL\",\n    \"GR\",\n    \"HU\",\n    \"IE\",\n    \"IT\",\n    \"LV\",\n    \"LT\",\n    \"LU\",\n    \"MT\",\n    \"NL\",\n    \"PL\",\n    \"PT\",\n    \"RO\",\n    \"SK\",\n    \"SI\",\n    \"ES\",\n    \"SE\",\n\n    //China \n    //Measures for Labeling of AI-Generated Synthetic Content\n    // 关于印发《人工智能生成合成内容标识办法》的通知 \n    // https://www.cac.gov.cn/2025-03/14/c_1743654684782215.htm\n    \"CN\",\n\n    //Although CN Law doesn't apply, just in case\n    \"HK\",\n    \"MO\",\n\n    //TW isn't under mainland china jurisdiction\n    //de facto, de jure in TW law, unlike HK and MO,\n    //So we don't include it for now\n    //\"TW\", \n\n    // Republic of Korea\n    // AI Basic Act\n    // 인공지능 발전과 신뢰 기반 조성 등에 관한 기본법\n    // https://www.law.go.kr/%EB%B2%95%EB%A0%B9/%EC%9D%B8%EA%B3%B5%EC%A7%80%EB%8A%A5%20%EB%B0%9C%EC%A0%84%EA%B3%BC%20%EC%8B%A0%EB%A2%B0%20%EA%B8%B0%EB%B0%98%20%EC%A1%B0%EC%84%B1%20%EB%93%B1%EC%97%90%20%EA%B4%80%ED%95%9C%20%EA%B8%B0%EB%B3%B8%EB%B2%95/(20676,20250121)\n    \"KR\",\n\n    // Vietnam\n    // Digital Tech Law\n    // Luật Công nghệ số\n    \"VN\",\n\n])\n\nexport function aiLawApplies(): boolean {\n\n    //TODO: implement actual logic\n    //lets now assume it always applies\n    //so we don't have legal issues later\n\n    return true\n}\n\nexport function aiWatermarkingLawApplies(): boolean {\n\n    //TODO: implement actual logic\n    //lets now assume it is false for now,\n    //becuase very few countries have it for now\n    return false\n}\n\nexport const chatFoldedState = $state<{\n    data: null| {\n        targetCharacterId: string,\n        targetChatId: string,\n        targetMessageId: string,\n    }\n}>({\n    data: null\n})\n\n//Since its exported, we cannot use $derived here\nexport let chatFoldedStateMessageIndex = $state({\n    index: -1\n})\n\n$effect.root(() => {\n    $effect(() => {\n        if(!chatFoldedState.data){\n            return\n        }\n        const char = DBState.db.characters[selIdState.selId]\n        const chat = char.chats[char.chatPage]\n        if(chatFoldedState.data.targetCharacterId !== char.chaId){\n            chatFoldedState.data = null\n        }\n        if(chatFoldedState.data.targetChatId !== chat.id){\n            chatFoldedState.data = null\n        }\n    })\n\n    $effect(() => {\n        if(chatFoldedState.data === null){\n            chatFoldedStateMessageIndex.index = -1\n            return\n        }\n        const char = DBState.db.characters[selIdState.selId]\n        const chat = char.chats[char.chatPage]\n        const messageIndex = chat.message.findIndex((v) => {\n            return chatFoldedState.data?.targetMessageId === v.chatId\n        })\n        if(messageIndex === -1){\n            console.warn('Target message for folding id' + chatFoldedState.data?.targetMessageId + ' not found')\n            chatFoldedStateMessageIndex.index = -1\n            return\n        }\n        chatFoldedStateMessageIndex.index = messageIndex\n    })\n})\n\nexport function foldChatToMessage(targetMessageIdOrIndex: string | number) {\n    let targetMessageId = ''\n    if (typeof targetMessageIdOrIndex === 'number') {\n        const char = getCurrentCharacter()\n        const chat = char.chats[char.chatPage]\n        const message = chat.message[targetMessageIdOrIndex]\n        targetMessageId = message.chatId\n    }\n    else{\n        targetMessageId = targetMessageIdOrIndex\n    }\n    const char = getCurrentCharacter()\n    const chat = char.chats[char.chatPage]\n    chatFoldedState.data = {\n        targetCharacterId: char.chaId,\n        targetChatId: chat.id,\n        targetMessageId: targetMessageId,\n    }\n}\n\nexport function changeChatTo(IdOrIndex: string | number) {\n    let index = -1\n    if (typeof IdOrIndex === 'number') {\n        index = IdOrIndex\n    }\n\n    if (typeof IdOrIndex === 'string') {\n        const currentCharacter = getCurrentCharacter()\n        index = currentCharacter.chats.findIndex((v) => {\n            return v.id === IdOrIndex\n        })\n    }\n\n    if(index === -1){\n        return\n    }\n\n    chatDeselected.set(false)\n    const char = DBState.db.characters[selIdState.selId]\n    char.chatPage = index\n    const newChat = char.chats[index]\n    if(newChat){\n        if(newChat._placeholder){\n            const capturedIndex = index\n            let cancelled = false\n            loadingOverlayStore.set({ active: true, text: language.loading ?? '', onCancel: () => {\n                cancelled = true\n                chatDeselected.set(true)\n                loadingOverlayStore.set({ active: false, text: '', onCancel: null })\n            }})\n            void ensureChatHydrated(char.chats, capturedIndex, char.chaId).then((hydrated) => {\n                if(cancelled) return\n                if(hydrated && char.chatPage === capturedIndex) loadTogglesFromChat(hydrated)\n            }).catch((e) => {\n                console.error('[changeChatTo] hydration failed:', e)\n            }).finally(() => {\n                if(!cancelled) loadingOverlayStore.set({ active: false, text: '', onCancel: null })\n            })\n        } else {\n            loadTogglesFromChat(newChat)\n        }\n    }\n    ReloadGUIPointer.set(Math.random())\n}\n\nexport function createChatCopyName(originalName: string,type:'Copy'|'Branch'): string {\n    let name = originalName.replaceAll(/\\(((Copy|Branch)( \\d+)?)\\)$/g, '').trim()\n    let copyIndex = 1\n    let newName = `${name} (${type})`\n    const char = getCurrentCharacter()\n    while (char.chats.find((v) => v.name === newName)) {\n        copyIndex++\n        newName = `${name} (${type} ${copyIndex})`\n    }\n    return newName\n}\n","targetVersions":{"pocketrisu":["1.9.0"]}},{"id":"lazy-chat-sync:replace:src:ts:plugins:apiV3:v3-svelte-ts","file":"src/ts/plugins/apiV3/v3.svelte.ts","type":"replace","anchor":"import { allowedDbKeys, customProviderStore, getV2PluginAPIs, handlePluginInstallViaPlugin, pluginV2, type PluginV2ProviderArgument, type PluginV2ProviderOptions, type RisuPlugin } from \"../plugins.svelte\";\nimport { SandboxHost } from \"./factory\";\nimport { getDatabase, normalizeChat } from \"src/ts/storage/database.svelte\";\nimport { SafeLocalPluginStorage, tagWhitelist } from \"../pluginSafeClass\";\nimport { recordOwner, removeOwner, clearOwners } from \"../pluginStorageMeta\";\nimport DOMPurify from 'dompurify';\nimport { additionalChatMenu, additionalFloatingActionButtons, additionalHamburgerMenu, additionalSettingsMenu, bodyIntercepterStore, chatPanelStore, DBState, selectedCharID, type MenuDef } from \"src/ts/stores.svelte\";\nimport { v4 } from \"uuid\";\nimport { sleep } from \"src/ts/util\";\nimport { alertConfirm, alertError, alertNormal } from \"src/ts/alert\";\nimport { language } from \"src/lang\";\nimport { checkCharOrder, forageStorage, getFetchLogs } from \"src/ts/globalApi.svelte\";\nimport { changeColorScheme, updateColorScheme, updateTextThemeAndCSS, type ColorScheme } from \"src/ts/gui/colorscheme\";\nimport { get } from \"svelte/store\";\nimport { registerMCPModule, unregisterMCPModule } from \"src/ts/process/mcp/pluginmcp\";\nimport { getLLMCache, searchLLMCache } from \"src/ts/translator/translator\";\nimport { hasher } from \"src/ts/parser/parser.svelte\";\nimport { LLMFlags, LLMFormat, LLMProvider, LLMTokenizer, type LLMModel } from \"src/ts/model/types\";\nimport { readPersistentJson, removePersistentKey, writePersistentJson } from \"src/ts/storage/persistentKv\";\nimport { sendChat as processSendChat, doingChat } from \"src/ts/process/index.svelte\";\nimport { getModelInfo } from \"src/ts/model/modellist\";\nimport type { ModelModeExtended } from \"src/ts/process/request/shared\";\nimport { requestChatDataMain } from \"src/ts/process/request/request\";\nimport type { OpenAIChat } from \"src/ts/process/index.svelte\";\nimport { getModuleLorebooks } from \"src/ts/process/modules\";\nimport {\n    registerTTSPreprocessor,\n    unregisterTTSPreprocessor,\n    registerTTSPostprocessor,\n    unregisterTTSPostprocessor,\n    type BeforeTTSContext,\n    type BeforeTTSResult,\n    type AfterTTSContext,\n    type AfterTTSResult,\n    type TTSHookFn,\n} from \"src/ts/process/ttsHooks\";\n\n/*\n    V3 API for RisuAI Plugins\n\n    Before adding new APIs here, please check the limitations\n\n    - APIs must be a functions\n        - If you want nested objects, first add as a plain function, `_getPluginStorage` for example\n            And add it too _getAliases function ({'pluginStorage':{'getItem': '_getPluginStorage', ... }})\n            This will make pluginStorage.getItem() work in plugins\n        - If you need constants, use _getPropertiesForInitialization to set them up\n            For example apiVersion and apiVersionCompatibleWith are set this way,\n            Accessable in plugins as risuai.apiVersion\n    - APIs must return, or accept as parameters, only the following types:\n        - Serializable data (string, number, boolean, null, array, object)\n        - Class instances marked with __classType = 'REMOTE_REQUIRED'\n        - Callback functions (only as parameters)\n        - Note that Class or Callbacks inside arrays or objects are not supported\n*/\n\nconst pluginChannel = new Map<string, Function>();\n\nclass SafeElement {\n    #element: HTMLElement;\n    __classType = 'REMOTE_REQUIRED' as const;\n\n    constructor(element: HTMLElement) {\n        if(element.getAttribute('freezed')){\n            throw new Error(\"This element cannot be accessed by SafeELement\")\n        }\n        this.#element = element;\n    }\n\n    public appendChild(child: SafeElement) {\n        this.#element.appendChild(child.#element);\n    }\n\n    public removeChild(child: SafeElement) {\n        this.#element.removeChild(child.#element);\n    }\n\n    public replaceChild(newChild: SafeElement, oldChild: SafeElement) {\n        this.#element.replaceChild(newChild.#element, oldChild.#element);\n    }\n\n    public replaceWith(newElement: SafeElement) {\n        this.#element.replaceWith(newElement.#element);\n    }\n\n    public cloneNode(deep: boolean = false): SafeElement {\n        const cloned = this.#element.cloneNode(deep);\n        return new SafeElement(cloned as HTMLElement);\n    }\n\n    public prepend(child: SafeElement) {\n        this.#element.prepend(child.#element);\n    }\n\n    public remove() {\n        this.#element.remove();\n    }\n\n    public innerText(): string {\n        return this.#element.innerText;\n    }\n\n    public textContent(): string | null {\n        return this.#element.textContent;\n    }\n\n    public setTextContent(value: string) {\n        this.#element.textContent = value;\n    }\n\n    public setInnerText(value: string) {\n        this.#element.innerText = value;\n    }\n\n\n    public setAttribute(name: string, value: string) {\n        if(!name.startsWith('x-')){\n            throw new Error(\"Can only set attributes starting with 'x-' for security reasons. for other attributes, use dedicated methods.\");\n        }\n        this.#element.setAttribute(name, value);\n    }\n    public getAttribute(name: string): string | null {\n        if(!name.startsWith('x-')){\n            throw new Error(\"Can only get attributes starting with 'x-' for security reasons. for other attributes, use dedicated methods.\");\n        }\n        return this.#element.getAttribute(name);\n    }\n    public setStyle(property: string, value: string) {\n        (this.#element.style as any)[property] = value;\n    }\n    public getStyle(property: string): string {\n        return (this.#element.style as any)[property];\n    }\n    public getStyleAttribute(): string {\n        return this.#element.getAttribute('style') || '';\n    }\n    public setStyleAttribute(value: string) {\n        this.#element.setAttribute('style', value);\n    }\n    public addClass(className: string) {\n        // \n        this.#element.classList.add(className);\n    }\n    public removeClass(className: string) {\n        // \n        this.#element.classList.remove(className);\n    }\n    public setClassName(className: string){\n        this.#element.className = className\n    }\n    public getClassName(){\n        return this.#element.className\n    }\n    public hasClass(className: string): boolean {\n        //We don't need to check the className here since we're just checking\n        return this.#element.classList.contains(className);\n    }\n    public focus() {\n        this.#element.focus();\n    }\n    public getChildren(): SafeClassArray<SafeElement> {\n        const children: SafeElement[] = [];\n        this.#element.childNodes.forEach(node => {\n            if(node instanceof HTMLElement) {\n                children.push(new SafeElement(node));\n            }\n        });\n        return new SafeClassArray<SafeElement>(children);\n    }\n    public getParent(): SafeElement | null {\n        if(this.#element.parentElement) {\n            return new SafeElement(this.#element.parentElement);\n        }\n        return null;\n    }\n    public getInnerHTML(): string {\n        return this.#element.innerHTML;\n    }\n    public getOuterHTML(): string {\n        return this.#element.outerHTML;\n    }\n    public clientHeight(): number {\n        return this.#element.clientHeight;\n    }\n    public clientWidth(): number {\n        return this.#element.clientWidth;\n    }\n    public clientTop(): number {\n        return this.#element.clientTop;\n    }\n    public clientLeft(): number {\n        return this.#element.clientLeft;\n    }\n    public nodeName(): string {\n        return this.#element.nodeName;\n    }\n    public nodeType(): number {\n        return this.#element.nodeType;\n    }\n    public querySelectorAll(selector: string): SafeClassArray<SafeElement> {\n        const nodeList = this.#element.querySelectorAll(selector);\n        const elements: SafeElement[] = [];\n        nodeList.forEach(node => {\n            if(node instanceof HTMLElement) {\n                elements.push(new SafeElement(node));\n            }\n        });\n        return new SafeClassArray<SafeElement>(elements);\n    }\n    public querySelector(selector: string): SafeElement | null {\n        const element = this.#element.querySelector(selector);\n        if(element instanceof HTMLElement) {\n            return new SafeElement(element);\n        }\n        return null;\n    }\n    public getElementById(id: string): SafeElement | null {\n        const element = this.querySelector('#' + id);\n        return element;\n    }\n    public getElementsByClassName(className: string): SafeClassArray<SafeElement> {\n        return this.querySelectorAll('.' + className);\n    }\n    public getClientRects(): DOMRectList {\n        return this.#element.getClientRects();\n    }\n    public getBoundingClientRect(): DOMRect {\n        return this.#element.getBoundingClientRect();\n    }\n    public setInnerHTML(value: string) {\n        const san = DOMPurify.sanitize(value);\n        this.#element.innerHTML = san;\n    }\n    public setOuterHTML(value: string) {\n        const san = DOMPurify.sanitize(value);\n        this.#element.outerHTML = san;\n    }\n    public scrollIntoView(options?: boolean | ScrollIntoViewOptions) {\n        this.#element.scrollIntoView(options);\n    }\n    #eventIdMap = new Map<string, Function>()\n\n    public async addEventListener(type:string, listener: (event: any) => void, options?: boolean | AddEventListenerOptions):Promise<string> {\n        const realOptions = typeof options === 'boolean' ? { capture: options } : options || {};\n\n        //allowed with unlimited\n        const allowedDocumentEventListeners = [\n            'click',\n            'dblclick',\n            'contextmenu',\n            'mousedown',\n            'mouseup',\n            'mousemove',\n            'mouseover',\n            'mouseleave',\n            'pointercancel',\n            'pointerdown',\n            'pointerenter',\n            'pointerleave',\n            'pointermove',\n            'pointerout',\n            'pointerover',\n            'pointerup',\n            'scroll',\n            'scrollend'\n        ]\n\n        //allowed, but it has fingerprinting issues,\n        //so it will be delayed random ms.\n        const allowedDelayedEventListeners = [\n            'keydown',\n            'keyup',\n            'keypress'\n        ]\n\n        const id = v4()\n\n        const trimEvent = (event: MouseEvent | KeyboardEvent | Event) => {\n            if(event instanceof MouseEvent){\n                return {\n                    type: event.type,\n                    clientX: event.clientX,\n                    clientY: event.clientY,\n                    button: event.button,\n                    buttons: event.buttons,\n                    altKey: event.altKey,\n                    ctrlKey: event.ctrlKey,\n                    shiftKey: event.shiftKey,\n                    metaKey: event.metaKey,\n                }\n            }\n            else if(event instanceof KeyboardEvent){\n                return {\n                    type: event.type,\n                    key: event.key,\n                    code: event.code,\n                    repeat: event.repeat,\n                    altKey: event.altKey,\n                    ctrlKey: event.ctrlKey,\n                    shiftKey: event.shiftKey,\n                    metaKey: event.metaKey,\n                }\n            }\n            else{\n                return {\n                    type: event.type\n                }\n            }\n\n        }\n\n        if(allowedDocumentEventListeners.includes(type)){\n            const modifiedListener = (event: any) => {\n                listener(trimEvent(event))\n            }\n            this.#eventIdMap.set(id, modifiedListener)\n            document.addEventListener(type, modifiedListener, realOptions)\n            return id;\n        }\n        else if(allowedDelayedEventListeners.includes(type)){\n            const modifiedListener = (event: any) => {\n                let delay = 0;\n                try {\n                    delay = (crypto.getRandomValues(new Uint32Array(1))[0] / 100) % 100; //0-99 ms              \n                } catch (error) {}\n                setTimeout(() => {\n                    listener(trimEvent(event));\n                }, delay);\n            }\n            this.#eventIdMap.set(id, modifiedListener)\n            document.addEventListener(type, modifiedListener, realOptions);\n            return id;\n        }\n        else{\n            throw new Error(`Event listener of type '${type}' is not allowed for security reasons.`);\n        }        \n    }\n\n    public removeEventListener(type:string, id:string, options?: boolean | EventListenerOptions) {\n        const listener = this.#eventIdMap.get(id);\n        if(listener){\n            const realOptions = typeof options === 'boolean' ? { capture: options } : options || {};\n            document.removeEventListener(type, listener as EventListenerOrEventListenerObject, realOptions);\n            this.#eventIdMap.delete(id);\n        }\n    }\n\n    public matches (selector: string): boolean {\n        return this.#element.matches(selector);\n    }\n}\n\nclass SafeDocument extends SafeElement {\n    __classType = 'REMOTE_REQUIRED' as const;\n    constructor(document: Document) {\n        super(document.documentElement);\n    }\n    createElement(tagName: string): SafeElement {\n        if(!tagWhitelist.includes(tagName.toLowerCase())) {\n            console.warn(`Creation of <${tagName}> elements is restricted. Creating a <div> instead.`);\n            tagName = 'div';\n        }\n        if(tagName.toLowerCase() === 'a'){\n            console.warn(`<a> can be created but href attribute cannot be set directly for security reasons. Use .createAnchorElement(href: string) to create safe anchor elements.`);\n        }\n        const element = document.createElement(tagName);\n        return new SafeElement(element);\n    }\n    createAnchorElement(href: string): SafeElement {\n        const anchor = document.createElement('a');\n        try {\n            const url = new URL(href);\n            if(url.protocol !== 'http:' && url.protocol !== 'https:'){\n                throw new Error(\"Invalid protocol\");\n            }\n            anchor.setAttribute('href', url.toString());\n        } catch (error) {\n            console.warn(`Invalid URL provided for anchor element: ${href}. Setting href to '#' instead.`);\n            anchor.setAttribute('href', '#');\n        }\n        return new SafeElement(anchor);\n    }\n}\n\ntype SafeMutationRecordObject = {\n    type: string;\n    target: SafeElement;\n    addedNodes: SafeElement[];\n}\n\nclass SafeClassArray<T> {\n    #items: T[];\n    __classType = 'REMOTE_REQUIRED' as const;\n    constructor(items: T[] = []) {\n        this.#items = items;\n    }\n    at(index: number): T {\n        return this.#items.at(index);\n    }\n    length(): number {\n        return this.#items.length;\n    }\n    push(item: T) {\n        this.#items.push(item);\n    }\n}\n\nclass SafeMutationRecord{\n    __classType = 'REMOTE_REQUIRED' as const;\n    #type: string;\n    #target: SafeElement;\n    #addedNodes: SafeClassArray<SafeElement>;\n    constructor(type: string, target: SafeElement, addedNodes: SafeElement[]) {\n        this.#type = type;\n        this.#target = target;\n        this.#addedNodes = new SafeClassArray<SafeElement>(addedNodes);\n    }\n    getType(): string {\n        return this.#type;\n    }\n    getTarget(): SafeElement {\n        return this.#target;\n    }\n    getAddedNodes(): SafeClassArray<SafeElement> {\n        return this.#addedNodes;\n    }\n}\n\ntype SafeMutationCallback = (mutations: SafeClassArray<SafeMutationRecord>) => void;\n\nclass SafeMutationObserver {\n    #observer: MutationObserver;\n    __classType = 'REMOTE_REQUIRED' as const;\n    constructor(callback: SafeMutationCallback) {\n        this.#observer = new MutationObserver((mutations) => {\n            const safeMutations: SafeMutationRecordObject[] = mutations.map(mutation => {\n\n                const elementMapHelper = (nodeList: NodeList): SafeElement[] => {\n                    const elements: SafeElement[] = [];\n                    nodeList.forEach(node => {\n                        if(node instanceof HTMLElement) {\n                            elements.push(new SafeElement(node));\n                        }\n                    })\n                    return elements;\n                }\n\n                return {\n                    type: mutation.type,\n                    target: new SafeElement(mutation.target as HTMLElement),\n                    addedNodes: elementMapHelper(mutation.addedNodes),\n                    removedNodes: elementMapHelper(mutation.removedNodes)\n                    \n                }\n            })\n\n            const safeClassed = new SafeClassArray<SafeMutationRecord>([]);\n            for(const record of safeMutations){\n                safeClassed.push(new SafeMutationRecord(\n                    record.type,\n                    record.target,\n                    record.addedNodes\n                ));\n            }\n            callback(safeClassed);\n        });\n    }\n\n    observe(element:SafeElement, options: MutationObserverInit) {\n        const identifier = v4();\n        element.setAttribute('x-identifier', identifier);\n        const rawElement = document.querySelector(`[x-identifier=\"${identifier}\"]`) as HTMLElement;\n        if(rawElement){\n            this.#observer.observe(rawElement, options);\n            element.setAttribute('x-identifier', '');\n        }\n    }\n\n}\n\nconst pluginUnloadCallbacks: Map<string, Function[]> = new Map();\n\nconst addPluginUnloadCallback = (pluginName: string, callback: Function) => {\n    if(!pluginUnloadCallbacks.has(pluginName)){\n        pluginUnloadCallbacks.set(pluginName, []);\n    }\n    pluginUnloadCallbacks.get(pluginName)?.push(callback);\n}\n\nconst makeMenuUnloadCallback = (menuId:string, menuStore: MenuDef[]) =>{\n    return () => {\n        const index = menuStore.findIndex(item => item.id === menuId);\n        if(index !== -1){\n            menuStore.splice(index, 1);\n        }\n    }\n}\n\nconst removeChatPanel = (id: string) => {\n    const index = chatPanelStore.findIndex(item => item.id === id);\n    if(index !== -1){\n        chatPanelStore.splice(index, 1);\n    }\n}\n\nconst removePluginChatPanels = (pluginName: string) => {\n    for(let i = chatPanelStore.length - 1; i >= 0; i--){\n        if(chatPanelStore[i].pluginName === pluginName){\n            chatPanelStore.splice(i, 1);\n        }\n    }\n}\n\nconst unloadV3Plugin = async (pluginName: string) => {\n    const callbacks = pluginUnloadCallbacks.get(pluginName);\n    const instance = v3PluginInstances.find(p => p.name === pluginName);\n    if(instance){\n        const index = v3PluginInstances.findIndex(p => p.name === pluginName);\n        if(index !== -1){\n            v3PluginInstances.splice(index, 1);\n        }\n    }\n    if(callbacks){\n        pluginUnloadCallbacks.delete(pluginName); \n        let promises: Promise<void>[] = [];\n        for(const callback of callbacks){\n            const result = callback();\n            if(result instanceof Promise){\n                promises.push(result);\n            }\n        }\n\n        await Promise.any([\n            Promise.all(promises),\n            sleep(1000) //timeout after 1 second\n        ])\n    }\n    try {\n        instance?.host?.terminate();        \n    } catch (error) {\n        console.error(`Error terminating plugin ${pluginName}:`, error);\n    }\n}\n\ntype PluginPermissionDesc = 'fetchLogs'|'db'|'mainDom'|'replacer'|'provider'|'sendChat';\nconst pluginPermissionDescs: PluginPermissionDesc[] = ['fetchLogs', 'db', 'mainDom', 'replacer', 'provider', 'sendChat'];\n\n// Plugin names are free text (the //@name directive), so `${name}_${desc}` keys\n// can collide — both across permissions and with a legacy name-only entry that\n// happens to read like \"name_desc\". JSON-encoding the pair makes every key\n// unambiguous: [\"foo\",\"db\"] can never equal a plain \"foo_db\" or [\"foo_db\",\"x\"].\nconst permissionKeyOf = (pluginName: string, permissionDesc: string) =>\n    JSON.stringify([pluginName, permissionDesc])\n\nconst permissionGivenPlugins: Set<string> = new Set();\nconst permissionDeniedPlugins: Set<string> = new Set();\nconst permissionCache = new Map<string, boolean | number>();\nconst pluginPermissionStateKey = 'cache/plugin-permissions/state.json';\nlet pluginPermissionLoadPromise: Promise<void> | null = null;\n\nasync function ensurePluginPermissionStateLoaded() {\n    if (!pluginPermissionLoadPromise) {\n        pluginPermissionLoadPromise = (async () => {\n            const payload = await readPersistentJson<{\n                given: string[]\n                denied: string[]\n                cache: [string, boolean | number][]\n            }>(pluginPermissionStateKey)\n            if (!payload) {\n                return\n            }\n            permissionGivenPlugins.clear()\n            permissionDeniedPlugins.clear()\n            permissionCache.clear()\n            for (const pluginName of payload.given ?? []) {\n                permissionGivenPlugins.add(pluginName)\n            }\n            for (const pluginName of payload.denied ?? []) {\n                permissionDeniedPlugins.add(pluginName)\n            }\n            for (const [key, value] of payload.cache ?? []) {\n                permissionCache.set(key, value)\n            }\n        })()\n    }\n    await pluginPermissionLoadPromise\n}\n\nexport async function resetAllPluginPermissions() {\n    permissionGivenPlugins.clear()\n    permissionDeniedPlugins.clear()\n    permissionCache.clear()\n    pluginPermissionLoadPromise = Promise.resolve()\n    await removePersistentKey(pluginPermissionStateKey)\n}\n\nexport async function resetPluginPermission(pluginName: string) {\n    await ensurePluginPermissionStateLoaded()\n    // Permission descs are a fixed enum, so we delete the exact key for each\n    // one rather than prefix-matching (which would also wipe another plugin's\n    // keys). `pluginName` alone covers legacy name-only entries from older\n    // versions, which JSON keys never collide with but reset should still clear.\n    const exactKeys = pluginPermissionDescs.map(desc => permissionKeyOf(pluginName, desc))\n    for (const key of [pluginName, ...exactKeys]) {\n        permissionGivenPlugins.delete(key)\n        permissionDeniedPlugins.delete(key)\n    }\n    for (const desc of pluginPermissionDescs) {\n        permissionCache.delete(permissionKeyOf(pluginName, desc) + '_lastGrantTime')\n    }\n    const plugin = DBState.db.plugins?.find(p => p.name === pluginName)\n    if (plugin?.script) {\n        const scriptHashBase = await hasher(new TextEncoder().encode(plugin.script))\n        for (const key of [...permissionCache.keys()]) {\n            if (key.startsWith(scriptHashBase + '_')) {\n                permissionCache.delete(key)\n            }\n        }\n    }\n    await persistPluginPermissionState()\n}\n\nasync function persistPluginPermissionState() {\n    await writePersistentJson(pluginPermissionStateKey, {\n        given: [...permissionGivenPlugins],\n        denied: [...permissionDeniedPlugins],\n        cache: [...permissionCache.entries()]\n    })\n}\n\ntype PluginV3ProviderOptions = PluginV2ProviderOptions & {\n    model?: LLMModel\n}\n\nexport const customV3ProviderMetaStore:LLMModel[] = []\n\n// Serializes permission dialogs. Every plugin shares the single global\n// alertStore, so when several plugins request permission at boot they would\n// otherwise overwrite each other's dialog — only the last one stays clickable\n// and a single click resolves all of them. The chain makes each dialog wait\n// for the previous one to finish, showing them one at a time.\nlet pluginPermissionDialogChain: Promise<unknown> = Promise.resolve()\n\nconst isPermissionResolved = async (\n    pluginName: string,\n    permissionDesc: PluginPermissionDesc,\n    requiresReconfirm: boolean,\n): Promise<{ resolved: boolean; value: boolean; pluginHash: string }> => {\n    const permissionKey = permissionKeyOf(pluginName, permissionDesc);\n    if (!requiresReconfirm && permissionGivenPlugins.has(permissionKey)) {\n        return { resolved: true, value: true, pluginHash: '' }\n    }\n    if (!requiresReconfirm && permissionDeniedPlugins.has(permissionKey)) {\n        return { resolved: true, value: false, pluginHash: '' }\n    }\n\n    const pluginHash = await hasher(\n        new TextEncoder().encode(\n            DBState.db.plugins.find(p => p.name === pluginName)?.script\n        )\n    ) + `_${permissionDesc}`;\n\n    if (!requiresReconfirm && permissionCache.get(pluginHash)) {\n        permissionGivenPlugins.add(permissionKey);\n        return { resolved: true, value: true, pluginHash }\n    }\n\n    return { resolved: false, value: false, pluginHash }\n}\n\nconst getPluginPermission = async (pluginName: string, permissionDesc: PluginPermissionDesc, reconfirm: boolean|'periodically' = false) => {\n    await ensurePluginPermissionStateLoaded()\n\n    // Recomputed (not captured) so a periodic reconfirm reflects the latest\n    // lastGrantTime: when several identical requests queue together, an earlier\n    // one may refresh it, making the reconfirm no longer due for the rest.\n    const computeRequiresReconfirm = () => {\n        if(reconfirm === 'periodically'){\n            const lastGrantTime = permissionCache.get(permissionKeyOf(pluginName, permissionDesc) + '_lastGrantTime') as number | undefined;\n            return !lastGrantTime || Date.now() - lastGrantTime > 3 * 24 * 60 * 60 * 1000; //3 days\n        }\n        return reconfirm === true;\n    }\n\n    // Fast path: if the answer is already known, skip the serialization queue\n    // entirely so cached/granted permissions never block on a pending dialog.\n    const early = await isPermissionResolved(pluginName, permissionDesc, computeRequiresReconfirm())\n    if (early.resolved) {\n        return early.value\n    }\n\n    const showDialog = async (): Promise<boolean> => {\n        // Re-check under the lock: an earlier queued dialog for the same plugin\n        // may have already granted/denied (or refreshed a periodic grant) while\n        // we were waiting our turn — recompute reconfirm so we don't re-prompt.\n        const requiresReconfirm = computeRequiresReconfirm()\n        const recheck = await isPermissionResolved(pluginName, permissionDesc, requiresReconfirm)\n        if (recheck.resolved) {\n            return recheck.value\n        }\n        const pluginHash = recheck.pluginHash\n\n        let alertTitle =\n            permissionDesc === 'fetchLogs' ? language.fetchLogConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'db' ? language.getFullDatabaseConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'mainDom' ? language.mainDomAccessConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'replacer' ? language.replacerPermissionConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'provider' ? language.providerPermissionConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'sendChat' ? language.sendChatConsent.replace(\"{}\", pluginName)\n            : `Error`\n        if(alertTitle === 'Error'){\n            return false;\n        }\n        const permissionKey = permissionKeyOf(pluginName, permissionDesc);\n        const conf = await alertConfirm(alertTitle)\n        if(conf && pluginHash){\n            permissionGivenPlugins.add(permissionKey);\n            permissionDeniedPlugins.delete(permissionKey);\n            permissionCache.set(pluginHash, true);\n            if(reconfirm === 'periodically'){\n                permissionCache.set(permissionKeyOf(pluginName, permissionDesc) + '_lastGrantTime', Date.now());\n            }\n            await persistPluginPermissionState()\n            return true;\n        }\n        permissionDeniedPlugins.add(permissionKey);\n        await persistPluginPermissionState()\n        return false;\n    }\n\n    // Append to the dialog chain so only one permission dialog is shown at a\n    // time. finally restores the chain even if showDialog throws, so a single\n    // failure never deadlocks every later permission request.\n    const run = pluginPermissionDialogChain\n        .catch(() => {})\n        .then(() => showDialog())\n    pluginPermissionDialogChain = run.catch(() => {})\n    return run\n}\n\nconst urlBlacklist = [\n    'risuai.xyz',\n    'risuai.net',\n    'sionyw.com',\n]\n\nconst authorizationHeaders = [\n    'x-api-key',\n    'authorization',\n    'proxy-authorization',\n]\n\nconst makeRisuaiAPIV3 = (iframe:HTMLIFrameElement,plugin:RisuPlugin) => {\n\n    const oldApis = getV2PluginAPIs();\n    return {\n\n        //Old APIs from v2.1\n        risuFetch: (url, options) => {\n            console.error(`[DEPRECATION WARNING] risuFetch is deprecated and will be removed in future versions. Please use nativeFetch instead.`)\n            for(const blocked of urlBlacklist){\n                if(url.toLowerCase().includes(blocked)){\n                    throw new Error(`Requests to ${blocked} are blocked for security reasons.`);\n                }\n            }\n\n            //scan headers\n            const headers = options?.headers || {};\n            for(const headerName in headers){\n                if(authorizationHeaders.includes(headerName.toLowerCase())){\n                    console.warn(`Request contains potentially sensitive header '${headerName}'. handling of such headers may be changed to only work with nativeFetch.`);\n                }\n            }\n            return oldApis.risuFetch(url, options);\n        },\n        nativeFetch: (url, options) => {\n            for(const blocked of urlBlacklist){\n                if(url.toLowerCase().includes(blocked)){\n                    throw new Error(`Requests to ${blocked} are blocked for security reasons.`);\n                }\n            }\n\n            //scan headers\n            const headers = options?.headers || {};\n            for(const headerName in headers){\n                if(authorizationHeaders.includes(headerName.toLowerCase())){\n                    console.warn(`Request contains potentially sensitive header '${headerName}'. handling of such headers may be changed to use server-side approch with write-only api access in the future for better security.`);\n                }\n            }\n            return oldApis.nativeFetch(url, options);\n        },\n        getChar: oldApis.getChar,\n        setChar: oldApis.setChar,\n        addProvider: (name: string, func: (arg: PluginV2ProviderArgument, abortSignal?: AbortSignal) => Promise<{ success: boolean, content: string }>, options?: PluginV3ProviderOptions) => {\n            console.warn(`[WARN] addProvider is a powerful API that can potentially be unsafe if used incorrectly. addProvider's functionality might be limited or changed in future updates to ensure security. please use other APIs if possible.`);\n            let provs = get(customProviderStore)\n            provs.push(name)\n            pluginV2.providers.set(name, async (arg, abortSignal) => {\n               await getPluginPermission(plugin.name, 'provider', 'periodically');\n               //mode is overridden to v3, due to vulnerabilities using mode.\n               //Alternative to mode will be added in future\n               arg.mode = 'v3'\n               return await func(arg, abortSignal);\n            }),\n            pluginV2.providerOptions.set(name, options ?? {})\n            customProviderStore.set(provs)\n\n            const modelData:LLMModel = {\n                id: `pluginmodel:::${name}`,\n                name: options?.model?.name ?? name,\n                shortName: options?.model?.shortName ?? name,\n                fullName: options?.model?.fullName ?? name,\n                internalID: options?.model?.internalID ?? `pluginmodel:::${name}`,\n                provider: LLMProvider.AsIs,\n                format: LLMFormat.Plugin,\n                flags: options?.model?.flags ?? [LLMFlags.hasFullSystemPrompt],\n                parameters: options?.model?.parameters ?? ['temperature', 'top_p', 'frequency_penalty', 'presence_penalty', 'repetition_penalty', 'min_p', 'top_a', 'top_k', 'thinking_tokens'],\n                tokenizer:options?.model?.tokenizer ??  LLMTokenizer.Unknown\n            }\n            customV3ProviderMetaStore.push(modelData);\n        },\n        addTTSPreprocessor: async (\n            func: TTSHookFn<BeforeTTSContext, BeforeTTSResult>,\n        ) => {\n            registerTTSPreprocessor(func);\n            addPluginUnloadCallback(plugin.name, () => unregisterTTSPreprocessor(func));\n        },\n        addTTSPostprocessor: async (\n            func: TTSHookFn<AfterTTSContext, AfterTTSResult>,\n        ) => {\n            registerTTSPostprocessor(func);\n            addPluginUnloadCallback(plugin.name, () => unregisterTTSPostprocessor(func));\n        },\n        addRisuScriptHandler: oldApis.addRisuScriptHandler,\n        removeRisuScriptHandler: oldApis.removeRisuScriptHandler,\n        addRisuReplacer: async (name:string,func:Function) => {\n            //permission check for replacer\n            const conf = await getPluginPermission(plugin.name, 'replacer', 'periodically');\n            if(!conf){\n                return;\n            }\n            oldApis.addRisuReplacer(name, func as any);\n        },\n        removeRisuReplacer: oldApis.removeRisuReplacer,\n        setDatabaseLite: oldApis.setDatabaseLite,\n        setDatabase: oldApis.setDatabase,\n        loadPlugins: oldApis.loadPlugins,\n        readImage: oldApis.readImage,\n        saveAsset: oldApis.saveAsset,\n        //Same functionality, but new implementation\n        getDatabase: async (includeOnly:string[]|'all' = 'all') => {\n            const conf = await getPluginPermission(plugin.name, 'db', 'periodically');\n            if(!conf){\n                return null;\n            }\n            const db = DBState.db\n            let liteDB = {}\n            for(const key of allowedDbKeys){\n                if(includeOnly !== 'all' && !includeOnly.includes(key)){\n                    continue;\n                }\n                (liteDB as any)[key] = $state.snapshot((db as any)[key]);\n            }\n            return liteDB;\n        },\n\n        installPlugin: handlePluginInstallViaPlugin,\n\n        // --- Color Scheme APIs ---\n        changeColorScheme: (name: string) => {\n            changeColorScheme(name)\n        },\n        setColorScheme: (scheme: ColorScheme) => {\n            const requiredKeys = ['bgcolor','darkbg','borderc','selected','draculared','textcolor','textcolor2','darkBorderc','darkbutton','type'] as const\n            for (const key of requiredKeys) {\n                if (typeof (scheme as any)[key] !== 'string') {\n                    throw new Error(`Invalid color scheme: missing or invalid '${key}'`)\n                }\n            }\n            if (scheme.type !== 'light' && scheme.type !== 'dark') {\n                throw new Error('Invalid color scheme type: must be \"light\" or \"dark\"')\n            }\n            const db = DBState.db\n            db.colorSchemeName = 'custom'\n            db.colorScheme = scheme\n            updateColorScheme()\n        },\n        getColorScheme: () => {\n            const db = DBState.db\n            return {\n                name: db.colorSchemeName,\n                scheme: $state.snapshot(db.colorScheme)\n            }\n        },\n\n        // --- Text Theme APIs ---\n        changeTextTheme: (name: string) => {\n            if (!['standard','highcontrast'].includes(name)) {\n                throw new Error(`Invalid text theme: ${name}`)\n            }\n            const db = DBState.db\n            db.textTheme = name\n            updateTextThemeAndCSS()\n        },\n        setCustomTextTheme: (theme: {\n            FontColorStandard: string,\n            FontColorBold: string,\n            FontColorItalic: string,\n            FontColorItalicBold: string,\n            FontColorQuote1: string,\n            FontColorQuote2: string\n        }) => {\n            const requiredKeys = ['FontColorStandard','FontColorBold','FontColorItalic','FontColorItalicBold','FontColorQuote1','FontColorQuote2'] as const\n            for (const key of requiredKeys) {\n                if (typeof (theme as any)[key] !== 'string') {\n                    throw new Error(`Invalid text theme: missing or invalid '${key}'`)\n                }\n            }\n            const db = DBState.db\n            db.textTheme = 'custom'\n            db.customTextTheme = theme\n            updateTextThemeAndCSS()\n        },\n        getTextTheme: () => {\n            const db = DBState.db\n            return {\n                name: db.textTheme,\n                customTheme: $state.snapshot(db.customTextTheme)\n            }\n        },\n\n        //Deprecated APIs from v2.1\n        //Use getArgument / setArgument instead if possible\n        getArg: oldApis.getArg,\n        setArg: oldApis.setArg,\n\n        //New APIs for v3\n        getArgument: async (key:string) => {\n            const db = getDatabase()\n            for (const p of db.plugins) {\n                if (p.name === plugin.name) {\n                    return p.realArg[key];\n                }\n            }\n        },\n        setArgument: async (key:string, value:string) => {\n            const db = getDatabase();\n            for (const p of db.plugins) {\n                if (p.name === plugin.name) {\n                    p.realArg[key] = value;\n                }\n            }\n        },\n        getCharacterFromIndex: (index:number) => {\n            const db = DBState.db\n            const charIds = Object.keys(db.characters);\n            const charId = charIds[index];\n            if(charId){\n                return $state.snapshot(db.characters[charId]);\n            }\n            return null;\n        },\n        setCharacterToIndex: (index:number, char:any) => {\n            const db = DBState.db\n            const charIds = Object.keys(db.characters);\n            const charId = charIds[index];\n            if(charId){\n                DBState.db.characters[charId] = char\n            }\n        },\n        getChatFromIndex: (characterIndex:number, chatIndex:number) => {\n            const db = DBState.db\n            const charIds = Object.keys(db.characters);\n            const charId = charIds[characterIndex];\n            if(charId){\n                const chats = db.characters[charId].chats;\n                if(chats && chats[chatIndex]){\n                    return $state.snapshot(chats[chatIndex]);\n                }\n            }\n            return null;\n        },\n        setChatToIndex: (characterIndex:number, chatIndex:number, chat:any) => {\n            const db = DBState.db\n            const charIds = Object.keys(db.characters);\n            const charId = charIds[characterIndex];\n            if(charId){\n                const chats = db.characters[charId].chats;\n                if(chats && chats[chatIndex]){\n                    DBState.db.characters[charId].chats[chatIndex] = normalizeChat(chat)\n                }\n            }\n        },\n        getCurrentCharacterIndex: () => {\n            return get(selectedCharID)\n        },\n        getCurrentChatIndex: () => {\n            const db = DBState.db\n            const charId = get(selectedCharID)\n            return db.characters[charId].chatPage\n        },\n        getCurrentLorebookEntries: () => {\n            const charId = get(selectedCharID)\n            const char = DBState.db.characters[charId]\n            if(!char){\n                return []\n            }\n            const page = char.chatPage\n            const characterLore = char.globalLore ?? []\n            const chatLore = char.chats?.[page]?.localLore ?? []\n            const moduleLore = getModuleLorebooks()\n            return $state.snapshot(characterLore.concat(chatLore).concat(moduleLore))\n        },\n        //New names for character APIs, to match API naming conventions\n        getCharacter: oldApis.getChar,\n        setCharacter: oldApis.setChar,\n\n        showContainer: (\n            //more types may be added in future\n            type: 'fullscreen' = 'fullscreen'\n        ) => {\n            iframe.style.display = \"block\";\n            \n            switch(type) {\n                case 'fullscreen': {\n                    //move iframe to body if not already there\n                    if(iframe.parentElement !== document.body) {\n                        document.body.appendChild(iframe);\n                    }\n\n                    //Make iframe cover whole screen\n                    iframe.style.position = \"fixed\";\n                    iframe.style.top = \"0\";\n                    iframe.style.left = \"0\";\n                    iframe.style.width = \"100%\";\n                    iframe.style.height = \"100%\";\n                    iframe.style.border = \"none\";\n                    iframe.style.zIndex = \"1000\";\n                    break;\n                }\n                default: {\n                    return\n                }\n            }\n        },\n        hideContainer: () => {\n            iframe.style.display = \"none\";\n        },\n        getRootDocument: async () => {\n            const conf = await getPluginPermission(plugin.name, 'mainDom');\n            if(!conf){\n                return null;\n            }\n            return new SafeDocument(document);\n        },\n        registerSetting: (\n            name:string,\n            callback: any,\n            icon:string = '',\n            iconType:'html'|'img'|'none' = 'none',\n            id?:string\n        ) => {\n            if(iconType !== 'html' && iconType !== 'img' && iconType !== 'none'){\n                throw new Error(\"iconType must be 'html', 'img' or 'none'\");\n            }\n            if(typeof name !== 'string' || name.trim() === ''){\n                throw new Error(\"name must be a non-empty string\");\n            }\n            const menuId = id || v4()\n            const menuDef:MenuDef = {\n                id: menuId,\n                name,\n                icon,\n                iconType,\n                callback\n            }\n            const existingIndex = additionalSettingsMenu.findIndex(item => item.id === menuId)\n            if(existingIndex !== -1){\n                additionalSettingsMenu[existingIndex] = menuDef\n                addPluginUnloadCallback(\n                    plugin.name,\n                    makeMenuUnloadCallback(menuId, additionalSettingsMenu)\n                )\n                return {id: menuId}\n            }\n            additionalSettingsMenu.push(menuDef)\n            addPluginUnloadCallback(\n                plugin.name,\n                makeMenuUnloadCallback(menuId, additionalSettingsMenu)\n            )\n            return {id: menuId};\n        },\n        registerBodyIntercepter: async (callback: (body: any, type: string) => any) => {\n\n            if(await getPluginPermission(plugin.name, 'replacer') === false){\n                return null;\n            }\n            \n            const id = v4();\n            bodyIntercepterStore.push({\n                id,\n                callback\n            })\n            addPluginUnloadCallback(plugin.name, () => {\n                const index = bodyIntercepterStore.findIndex(item => item.id === id);\n                if(index !== -1){\n                    bodyIntercepterStore.splice(index, 1);\n                }\n            })\n            return {id:id};\n        },\n        \n        unregisterBodyIntercepter: (id: string) => {\n            const index = bodyIntercepterStore.findIndex(item => item.id === id);\n            if(index !== -1){\n                bodyIntercepterStore.splice(index, 1);\n            }\n        },\n            \n        registerButton: (\n            arg: {\n                name: string,\n                icon: string,\n                iconType: 'html'|'img'|'none',\n                location?: 'action'|'chat'|'hamburger',\n                id?: string\n            },\n            callback: () => void\n        ) => {\n            let { name, icon, iconType, location, id: providedId } = arg;\n            location = location || 'action';\n            if(iconType !== 'html' && iconType !== 'img' && iconType !== 'none'){\n                throw new Error(\"iconType must be 'html', 'img' or 'none'\");\n            }\n            if(typeof name !== 'string' || name.trim() === ''){\n                throw new Error(\"name must be a non-empty string\");\n            }\n            if(typeof icon !== 'string'){\n                throw new Error(\"icon must be a string\");\n            }\n            const id = providedId || v4()\n            const menuDef:MenuDef = {\n                name,\n                icon,\n                iconType,\n                callback,\n                id\n            }\n\n            const buttonStores = [additionalFloatingActionButtons, additionalHamburgerMenu, additionalChatMenu]\n            for(const store of buttonStores){\n                const existingIndex = store.findIndex(item => item.id === id)\n                if(existingIndex !== -1){\n                    store[existingIndex] = menuDef\n                    addPluginUnloadCallback(\n                        plugin.name,\n                        makeMenuUnloadCallback(id, store)\n                    )\n                    return {id}\n                }\n            }\n\n            switch(location){\n                case 'action':{\n                    additionalFloatingActionButtons.push(menuDef)\n                    addPluginUnloadCallback(\n                        plugin.name,\n                        makeMenuUnloadCallback(menuDef.id, additionalFloatingActionButtons)\n                    )\n                    break\n                }\n                case 'hamburger':{\n                    additionalHamburgerMenu.push(menuDef)\n                    addPluginUnloadCallback(\n                        plugin.name,\n                        makeMenuUnloadCallback(menuDef.id, additionalHamburgerMenu)\n                    )\n                    break\n                }\n                case 'chat':{\n                    additionalChatMenu.push(menuDef)\n                    addPluginUnloadCallback(\n                        plugin.name,\n                        makeMenuUnloadCallback(menuDef.id, additionalChatMenu)\n                    )\n                    break\n                }\n                default:{\n                    throw new Error(\"Invalid location for button\")\n                }\n            }\n            return {id};\n        },\n        setChatPanel: (\n            content: string | null,\n            options: {\n                id?: string,\n                className?: string,\n            } = {}\n        ) => {\n            const id = options.id || `${plugin.name}:default`;\n\n            if(content === null || content === ''){\n                removeChatPanel(id);\n                return {id};\n            }\n\n            if(typeof content !== 'string'){\n                throw new Error(\"content must be a string or null\");\n            }\n\n            const panel = {\n                id,\n                pluginName: plugin.name,\n                html: DOMPurify.sanitize(content),\n                className: typeof options.className === 'string'\n                    ? DOMPurify.sanitize(options.className, {ALLOWED_TAGS: [], ALLOWED_ATTR: []})\n                    : undefined,\n            }\n\n            const existingIndex = chatPanelStore.findIndex(item => item.id === id);\n            if(existingIndex !== -1){\n                chatPanelStore[existingIndex] = panel;\n            }\n            else{\n                chatPanelStore.push(panel);\n            }\n            addPluginUnloadCallback(plugin.name, () => removePluginChatPanels(plugin.name));\n            return {id};\n        },\n        registerMCP: registerMCPModule,\n        unregisterMCP: unregisterMCPModule,\n        unregisterUIPart: (id: string) => {\n            const removeFromMenuStore = (menuStore: MenuDef[]) => {\n                const index = menuStore.findIndex(item => item.id === id);\n                if(index !== -1){\n                    menuStore.splice(index, 1);\n                }\n            }\n\n            removeFromMenuStore(additionalSettingsMenu);\n            removeFromMenuStore(additionalFloatingActionButtons);\n            removeFromMenuStore(additionalHamburgerMenu);\n            removeFromMenuStore(additionalChatMenu);\n            removeChatPanel(id);\n        },\n        log: (message:string) => {\n            console.log(`[RisuAI Plugin: ${plugin.name}] ${message}`);\n        },\n        createMutationObserver(callback: SafeMutationCallback): SafeMutationObserver {\n            return new SafeMutationObserver(callback)\n        },\n        onUnload: (callback: () => void) => {\n            addPluginUnloadCallback(plugin.name, callback);\n        },\n        getFetchLogs: async () => {\n            const unsafeFetchLog = getFetchLogs()\n            const conf = await getPluginPermission(plugin.name, 'fetchLogs');\n            if(!conf){\n                return null;\n            }\n            return unsafeFetchLog.map(log => {\n\n                const url = new URL(log.url);\n                return {\n                    url: url.origin + url.pathname,\n                    body: log.body,\n                    status: log.status,\n                    response: log.response,\n                }\n            })\n        },\n\n        alert: (msg:string) => {\n            return alertNormal(msg)\n        },\n        alertConfirm: (msg:string) => {\n            return alertConfirm(msg)\n        },\n        alertError: (msg:string) => {\n            return alertError(msg)\n        },\n        getRuntimeInfo: () => {\n            return {\n                apiVersion: \"3.0\",\n                platform: 'node',\n                saveMethod:\n                    forageStorage.isAccount ? 'account' :\n                    'local',\n            }\n        },\n        getLocalPluginStorage: () => {\n            return new SafeLocalPluginStorage(plugin.name)\n        },\n        checkCharOrder: checkCharOrder,\n        requestPluginPermission: (permission:string) => {\n            return getPluginPermission(plugin.name, permission as any);\n        },\n        //Internal use APIs\n        _getOldKeys: () => {\n            return Object.keys(oldApis)\n        },\n        _getPropertiesForInitialization: () => {\n            const v = {\n                apiVersion: \"3.0\",\n                apiVersionCompatibleWith: [\"3.0\"],\n            } as any;\n\n            v.list = Object.keys(v);\n            \n            return v;\n        },\n        _getPluginStorage: oldApis.pluginStorage.getItem,\n        // Wrapped (not aliased) so we can record the originating plugin into the\n        // sidecar meta map. The value write is unchanged; reads stay aliased.\n        _setPluginStorage: (key: string, value: any) => {\n            oldApis.pluginStorage.setItem(key, value)\n            recordOwner('save', key, plugin.name)\n        },\n        _removePluginStorage: (key: string) => {\n            oldApis.pluginStorage.removeItem(key)\n            removeOwner('save', key)\n        },\n        _clearPluginStorage: () => {\n            oldApis.pluginStorage.clear()\n            clearOwners('save')\n        },\n        _keyPluginStorage: oldApis.pluginStorage.key,\n        _keysPluginStorage: oldApis.pluginStorage.keys,\n        _lengthPluginStorage: oldApis.pluginStorage.length,\n        _getSafeLocalStorage: oldApis.safeLocalStorage.getItem,\n        _setSafeLocalStorage: (key: string, value: string) => {\n            oldApis.safeLocalStorage.setItem(key, value)\n            recordOwner('local', key, plugin.name)\n        },\n        _removeSafeLocalStorage: (key: string) => {\n            oldApis.safeLocalStorage.removeItem(key)\n            removeOwner('local', key)\n        },\n        _clearSafeLocalStorage: () => {\n            oldApis.safeLocalStorage.clear()\n            clearOwners('local')\n        },\n        _keySafeLocalStorage: oldApis.safeLocalStorage.key,\n        _keysSafeLocalStorage: oldApis.safeLocalStorage.keys,\n        searchTranslationCache: async (partialKey: string) => {\n            return searchLLMCache(partialKey)\n        },\n        getTranslationCache: async (key: string) => {\n            return getLLMCache(key)\n        },\n        _getAliases: () => {\n            return {\n                'pluginStorage':{\n                    'getItem': '_getPluginStorage',\n                    'setItem': '_setPluginStorage',\n                    'removeItem': '_removePluginStorage',\n                    'clear': '_clearPluginStorage',\n                    'key': '_keyPluginStorage',\n                    'keys': '_keysPluginStorage',\n                    'length': '_lengthPluginStorage',\n                },\n                'safeLocalStorage':{\n                    'getItem': '_getSafeLocalStorage',\n                    'setItem': '_setSafeLocalStorage',\n                    'removeItem': '_removeSafeLocalStorage',\n                    'clear': '_clearSafeLocalStorage',\n                    'key': '_keySafeLocalStorage',\n                    'keys': '_keysSafeLocalStorage',\n                }\n            }\n        },\n        runLLMModel: async (options: {\n            mode: ModelModeExtended\n            messages: OpenAIChat[]\n            staticModel?: string\n            allowPlugins?: boolean\n        }) => {\n            return requestChatDataMain({\n                formated: options.messages,\n                bias: {},\n                staticModel: options.staticModel,\n\n                // Calls into plugin-provided models are blocked by default to\n                // guard against accidental IPC loops between provider plugins.\n                // Plugin authors who need to reach the user's plugin-supplied\n                // main or auxiliary model (e.g. a TTS preprocessor that\n                // rewrites text with the configured otherAx model) can opt in\n                // explicitly with `allowPlugins: true`, accepting responsibility\n                // for avoiding provider-to-provider call loops.\n                blockPlugins: !options.allowPlugins,\n            }, options.mode)\n        },\n        sendChat: async (message: string) => {\n            const conf = await getPluginPermission(plugin.name, 'sendChat');\n            if(!conf){\n                return false;\n            }\n\n            if(typeof message !== 'string'){\n                throw new Error(\"Message must be a string\");\n            }\n\n            if(get(doingChat)){\n                throw new Error(\"A chat is already in progress\");\n            }\n\n            if(getModelInfo(DBState.db.aiModel).id.startsWith('pluginmodel:::')){\n                // Executing plugin provider is block because it can be used for loopholes for ipc right now.\n                throw new Error(\"Sending chat with plugin-based model is currently blocked\");\n            }\n\n            const charId = get(selectedCharID);\n            const char = DBState.db.characters[charId];\n            if(!char){\n                throw new Error(\"No character selected\");\n            }\n\n            const chat = char.chats[char.chatPage];\n            if(!chat){\n                throw new Error(\"No active chat found\");\n            }\n\n            if(message){\n                chat.message.push({\n                    role: 'user',\n                    data: message,\n                    time: Date.now(),\n                });\n            }\n\n            try {\n                await processSendChat(-1, {});\n            } finally {\n                // Plugin API path does not pass through the UI unlock logic,\n                // so release doingChat here on both success and failure.\n                doingChat.set(false);\n            }\n\n            return true;\n        },\n        addPluginChannelListener: (channelName: string, callback: Function) => {\n            pluginChannel.set(plugin.name + channelName, callback);\n        },\n        postPluginChannelMessage: (pluginName: string, channelName: string, message: any) => {\n\n            const currentPluginName = plugin.name;\n            const receiverPlugin = DBState.db.plugins.find(p => p.name === pluginName);\n\n            if(!receiverPlugin){\n                console.warn(`[RisuAI Plugin: ${currentPluginName}] Attempted to send message to non-existent plugin '${pluginName}' on channel '${channelName}'.`);\n                return;\n            }\n\n            if(!receiverPlugin.allowedIPC?.includes(currentPluginName)){\n                console.warn(`[RisuAI Plugin: ${currentPluginName}] Attempted to send message to plugin '${pluginName}' but receiver plugin does not allow IPC communication from this plugin. declare //@allowed-ipc ${currentPluginName} in the reciver plugin script to allow IPC communication.`);\n                return;\n            }\n\n            if(!plugin.allowedIPC?.includes(receiverPlugin.name)){\n                console.warn(`[RisuAI Plugin: ${currentPluginName}] Attempted to send message to plugin '${pluginName}' but the sender plugin does not allow IPC communication to this plugin. declare //@allowed-ipc ${receiverPlugin.name} in the sender plugin script to allow IPC communication.`);\n                return;\n            }\n\n\n            const callback = pluginChannel.get(pluginName + channelName);\n            if(callback){\n                callback(message, {\n                    sender: currentPluginName,\n                    channel: channelName\n                });\n            }\n        },\n        saveSecretHeader: async (key: string, value: string|string[]) => {\n            //TODO: Implement server-side secret storage with write-only access for plugins, to enhance security when handling sensitive information like API keys.\n            //This will have rate-limit, to prevent saving it publicly and writing as secret every time before using it.\n            console.warn(`[RisuAI Plugin: ${plugin.name}] saveServerSecret is not implemented yet. This API is intended for securely storing sensitive information like API keys with write-only access for plugins. Please avoid using this API until it is implemented.`);\n        }\n    }\n}\n\ntype V3PluginInstance = {\n    name: string;\n    host: SandboxHost;\n}\n\nconst v3PluginInstances: V3PluginInstance[] = [];\n\nexport async function loadV3Plugins(plugins:RisuPlugin[]){\n    await Promise.all(v3PluginInstances.map(async (instance) => {\n        await unloadV3Plugin(instance.name);\n    }));\n    const loadPromises = plugins.map(plugin => executePluginV3(plugin));\n    await Promise.all(loadPromises);\n}\n\nexport async function executePluginV3(plugin:RisuPlugin){\n\n    const alreadyRunning = v3PluginInstances.find(p => p.name === plugin.name);\n    if(alreadyRunning){\n        console.log(`[RisuAI Plugin: ${plugin.name}] Plugin is already running. Skipping load.`);\n        return;\n    }\n\n    const iframe = document.createElement('iframe');\n    iframe.style.display = \"none\";\n    document.body.appendChild(iframe);\n    const host = new SandboxHost(makeRisuaiAPIV3(iframe, plugin));\n    v3PluginInstances.push({\n        name: plugin.name,\n        host\n    });\n    host.run(iframe, plugin.script);\n    console.log(`[RisuAI Plugin: ${plugin.name}] Loaded API V3 plugin.`);\n}\n\nexport function getV3PluginInstance(name: string) {\n    return v3PluginInstances.find(p => p.name === name);\n}\n\nglobalThis.__debugV3Plugin = (code: string|Function, pluginName: string = '') => {\n    if(code instanceof Function){\n        code = `(${code.toString()})()`;\n    }\n    if(pluginName === ''){\n        return v3PluginInstances[0].host.executeInIframe(code);\n    }\n    const instance = v3PluginInstances.find(p => p.name === pluginName);\n    if(!instance){\n        throw new Error(`Plugin ${pluginName} not found.`);\n    }\n    return instance.host.executeInIframe(code);\n};\n","managed":"import { allowedDbKeys, customProviderStore, getV2PluginAPIs, handlePluginInstallViaPlugin, pluginV2, type PluginV2ProviderArgument, type PluginV2ProviderOptions, type RisuPlugin } from \"../plugins.svelte\";\nimport { SandboxHost } from \"./factory\";\nimport { getDatabase, normalizeChat } from \"src/ts/storage/database.svelte\";\nimport { SafeLocalPluginStorage, tagWhitelist } from \"../pluginSafeClass\";\nimport { recordOwner, removeOwner, clearOwners } from \"../pluginStorageMeta\";\nimport DOMPurify from 'dompurify';\nimport { additionalChatMenu, additionalFloatingActionButtons, additionalHamburgerMenu, additionalSettingsMenu, bodyIntercepterStore, chatPanelStore, DBState, selectedCharID, type MenuDef } from \"src/ts/stores.svelte\";\nimport { v4 } from \"uuid\";\nimport { sleep } from \"src/ts/util\";\nimport { alertConfirm, alertError, alertNormal } from \"src/ts/alert\";\nimport { language } from \"src/lang\";\nimport { checkCharOrder, forageStorage, getFetchLogs, markCharacterDirty, markChatDirty } from \"src/ts/globalApi.svelte\";\nimport { changeColorScheme, updateColorScheme, updateTextThemeAndCSS, type ColorScheme } from \"src/ts/gui/colorscheme\";\nimport { get } from \"svelte/store\";\nimport { registerMCPModule, unregisterMCPModule } from \"src/ts/process/mcp/pluginmcp\";\nimport { getLLMCache, searchLLMCache } from \"src/ts/translator/translator\";\nimport { hasher } from \"src/ts/parser/parser.svelte\";\nimport { LLMFlags, LLMFormat, LLMProvider, LLMTokenizer, type LLMModel } from \"src/ts/model/types\";\nimport { readPersistentJson, removePersistentKey, writePersistentJson } from \"src/ts/storage/persistentKv\";\nimport { ensureChatHydrated, ensureCurrentChatReady } from \"src/ts/storage/chatStorage\";\nimport { assignMissingChatIdsToNewCharacters } from \"src/ts/storage/chatIdentityRepair\";\nimport { sendChat as processSendChat, doingChat } from \"src/ts/process/index.svelte\";\nimport { getModelInfo } from \"src/ts/model/modellist\";\nimport type { ModelModeExtended } from \"src/ts/process/request/shared\";\nimport { requestChatDataMain } from \"src/ts/process/request/request\";\nimport type { OpenAIChat } from \"src/ts/process/index.svelte\";\nimport { getModuleLorebooks } from \"src/ts/process/modules\";\nimport {\n    registerTTSPreprocessor,\n    unregisterTTSPreprocessor,\n    registerTTSPostprocessor,\n    unregisterTTSPostprocessor,\n    type BeforeTTSContext,\n    type BeforeTTSResult,\n    type AfterTTSContext,\n    type AfterTTSResult,\n    type TTSHookFn,\n} from \"src/ts/process/ttsHooks\";\nimport { PluginChatAccess } from \"./pluginChatAccess\";\n\n/*\n    V3 API for RisuAI Plugins\n\n    Before adding new APIs here, please check the limitations\n\n    - APIs must be a functions\n        - If you want nested objects, first add as a plain function, `_getPluginStorage` for example\n            And add it too _getAliases function ({'pluginStorage':{'getItem': '_getPluginStorage', ... }})\n            This will make pluginStorage.getItem() work in plugins\n        - If you need constants, use _getPropertiesForInitialization to set them up\n            For example apiVersion and apiVersionCompatibleWith are set this way,\n            Accessable in plugins as risuai.apiVersion\n    - APIs must return, or accept as parameters, only the following types:\n        - Serializable data (string, number, boolean, null, array, object)\n        - Class instances marked with __classType = 'REMOTE_REQUIRED'\n        - Callback functions (only as parameters)\n        - Note that Class or Callbacks inside arrays or objects are not supported\n*/\n\nconst pluginChannel = new Map<string, Function>();\n\nclass SafeElement {\n    #element: HTMLElement;\n    __classType = 'REMOTE_REQUIRED' as const;\n\n    constructor(element: HTMLElement) {\n        if(element.getAttribute('freezed')){\n            throw new Error(\"This element cannot be accessed by SafeELement\")\n        }\n        this.#element = element;\n    }\n\n    public appendChild(child: SafeElement) {\n        this.#element.appendChild(child.#element);\n    }\n\n    public removeChild(child: SafeElement) {\n        this.#element.removeChild(child.#element);\n    }\n\n    public replaceChild(newChild: SafeElement, oldChild: SafeElement) {\n        this.#element.replaceChild(newChild.#element, oldChild.#element);\n    }\n\n    public replaceWith(newElement: SafeElement) {\n        this.#element.replaceWith(newElement.#element);\n    }\n\n    public cloneNode(deep: boolean = false): SafeElement {\n        const cloned = this.#element.cloneNode(deep);\n        return new SafeElement(cloned as HTMLElement);\n    }\n\n    public prepend(child: SafeElement) {\n        this.#element.prepend(child.#element);\n    }\n\n    public remove() {\n        this.#element.remove();\n    }\n\n    public innerText(): string {\n        return this.#element.innerText;\n    }\n\n    public textContent(): string | null {\n        return this.#element.textContent;\n    }\n\n    public setTextContent(value: string) {\n        this.#element.textContent = value;\n    }\n\n    public setInnerText(value: string) {\n        this.#element.innerText = value;\n    }\n\n\n    public setAttribute(name: string, value: string) {\n        if(!name.startsWith('x-')){\n            throw new Error(\"Can only set attributes starting with 'x-' for security reasons. for other attributes, use dedicated methods.\");\n        }\n        this.#element.setAttribute(name, value);\n    }\n    public getAttribute(name: string): string | null {\n        if(!name.startsWith('x-')){\n            throw new Error(\"Can only get attributes starting with 'x-' for security reasons. for other attributes, use dedicated methods.\");\n        }\n        return this.#element.getAttribute(name);\n    }\n    public setStyle(property: string, value: string) {\n        (this.#element.style as any)[property] = value;\n    }\n    public getStyle(property: string): string {\n        return (this.#element.style as any)[property];\n    }\n    public getStyleAttribute(): string {\n        return this.#element.getAttribute('style') || '';\n    }\n    public setStyleAttribute(value: string) {\n        this.#element.setAttribute('style', value);\n    }\n    public addClass(className: string) {\n        // \n        this.#element.classList.add(className);\n    }\n    public removeClass(className: string) {\n        // \n        this.#element.classList.remove(className);\n    }\n    public setClassName(className: string){\n        this.#element.className = className\n    }\n    public getClassName(){\n        return this.#element.className\n    }\n    public hasClass(className: string): boolean {\n        //We don't need to check the className here since we're just checking\n        return this.#element.classList.contains(className);\n    }\n    public focus() {\n        this.#element.focus();\n    }\n    public getChildren(): SafeClassArray<SafeElement> {\n        const children: SafeElement[] = [];\n        this.#element.childNodes.forEach(node => {\n            if(node instanceof HTMLElement) {\n                children.push(new SafeElement(node));\n            }\n        });\n        return new SafeClassArray<SafeElement>(children);\n    }\n    public getParent(): SafeElement | null {\n        if(this.#element.parentElement) {\n            return new SafeElement(this.#element.parentElement);\n        }\n        return null;\n    }\n    public getInnerHTML(): string {\n        return this.#element.innerHTML;\n    }\n    public getOuterHTML(): string {\n        return this.#element.outerHTML;\n    }\n    public clientHeight(): number {\n        return this.#element.clientHeight;\n    }\n    public clientWidth(): number {\n        return this.#element.clientWidth;\n    }\n    public clientTop(): number {\n        return this.#element.clientTop;\n    }\n    public clientLeft(): number {\n        return this.#element.clientLeft;\n    }\n    public nodeName(): string {\n        return this.#element.nodeName;\n    }\n    public nodeType(): number {\n        return this.#element.nodeType;\n    }\n    public querySelectorAll(selector: string): SafeClassArray<SafeElement> {\n        const nodeList = this.#element.querySelectorAll(selector);\n        const elements: SafeElement[] = [];\n        nodeList.forEach(node => {\n            if(node instanceof HTMLElement) {\n                elements.push(new SafeElement(node));\n            }\n        });\n        return new SafeClassArray<SafeElement>(elements);\n    }\n    public querySelector(selector: string): SafeElement | null {\n        const element = this.#element.querySelector(selector);\n        if(element instanceof HTMLElement) {\n            return new SafeElement(element);\n        }\n        return null;\n    }\n    public getElementById(id: string): SafeElement | null {\n        const element = this.querySelector('#' + id);\n        return element;\n    }\n    public getElementsByClassName(className: string): SafeClassArray<SafeElement> {\n        return this.querySelectorAll('.' + className);\n    }\n    public getClientRects(): DOMRectList {\n        return this.#element.getClientRects();\n    }\n    public getBoundingClientRect(): DOMRect {\n        return this.#element.getBoundingClientRect();\n    }\n    public setInnerHTML(value: string) {\n        const san = DOMPurify.sanitize(value);\n        this.#element.innerHTML = san;\n    }\n    public setOuterHTML(value: string) {\n        const san = DOMPurify.sanitize(value);\n        this.#element.outerHTML = san;\n    }\n    public scrollIntoView(options?: boolean | ScrollIntoViewOptions) {\n        this.#element.scrollIntoView(options);\n    }\n    #eventIdMap = new Map<string, Function>()\n\n    public async addEventListener(type:string, listener: (event: any) => void, options?: boolean | AddEventListenerOptions):Promise<string> {\n        const realOptions = typeof options === 'boolean' ? { capture: options } : options || {};\n\n        //allowed with unlimited\n        const allowedDocumentEventListeners = [\n            'click',\n            'dblclick',\n            'contextmenu',\n            'mousedown',\n            'mouseup',\n            'mousemove',\n            'mouseover',\n            'mouseleave',\n            'pointercancel',\n            'pointerdown',\n            'pointerenter',\n            'pointerleave',\n            'pointermove',\n            'pointerout',\n            'pointerover',\n            'pointerup',\n            'scroll',\n            'scrollend'\n        ]\n\n        //allowed, but it has fingerprinting issues,\n        //so it will be delayed random ms.\n        const allowedDelayedEventListeners = [\n            'keydown',\n            'keyup',\n            'keypress'\n        ]\n\n        const id = v4()\n\n        const trimEvent = (event: MouseEvent | KeyboardEvent | Event) => {\n            if(event instanceof MouseEvent){\n                return {\n                    type: event.type,\n                    clientX: event.clientX,\n                    clientY: event.clientY,\n                    button: event.button,\n                    buttons: event.buttons,\n                    altKey: event.altKey,\n                    ctrlKey: event.ctrlKey,\n                    shiftKey: event.shiftKey,\n                    metaKey: event.metaKey,\n                }\n            }\n            else if(event instanceof KeyboardEvent){\n                return {\n                    type: event.type,\n                    key: event.key,\n                    code: event.code,\n                    repeat: event.repeat,\n                    altKey: event.altKey,\n                    ctrlKey: event.ctrlKey,\n                    shiftKey: event.shiftKey,\n                    metaKey: event.metaKey,\n                }\n            }\n            else{\n                return {\n                    type: event.type\n                }\n            }\n\n        }\n\n        if(allowedDocumentEventListeners.includes(type)){\n            const modifiedListener = (event: any) => {\n                listener(trimEvent(event))\n            }\n            this.#eventIdMap.set(id, modifiedListener)\n            document.addEventListener(type, modifiedListener, realOptions)\n            return id;\n        }\n        else if(allowedDelayedEventListeners.includes(type)){\n            const modifiedListener = (event: any) => {\n                let delay = 0;\n                try {\n                    delay = (crypto.getRandomValues(new Uint32Array(1))[0] / 100) % 100; //0-99 ms              \n                } catch (error) {}\n                setTimeout(() => {\n                    listener(trimEvent(event));\n                }, delay);\n            }\n            this.#eventIdMap.set(id, modifiedListener)\n            document.addEventListener(type, modifiedListener, realOptions);\n            return id;\n        }\n        else{\n            throw new Error(`Event listener of type '${type}' is not allowed for security reasons.`);\n        }        \n    }\n\n    public removeEventListener(type:string, id:string, options?: boolean | EventListenerOptions) {\n        const listener = this.#eventIdMap.get(id);\n        if(listener){\n            const realOptions = typeof options === 'boolean' ? { capture: options } : options || {};\n            document.removeEventListener(type, listener as EventListenerOrEventListenerObject, realOptions);\n            this.#eventIdMap.delete(id);\n        }\n    }\n\n    public matches (selector: string): boolean {\n        return this.#element.matches(selector);\n    }\n}\n\nclass SafeDocument extends SafeElement {\n    __classType = 'REMOTE_REQUIRED' as const;\n    constructor(document: Document) {\n        super(document.documentElement);\n    }\n    createElement(tagName: string): SafeElement {\n        if(!tagWhitelist.includes(tagName.toLowerCase())) {\n            console.warn(`Creation of <${tagName}> elements is restricted. Creating a <div> instead.`);\n            tagName = 'div';\n        }\n        if(tagName.toLowerCase() === 'a'){\n            console.warn(`<a> can be created but href attribute cannot be set directly for security reasons. Use .createAnchorElement(href: string) to create safe anchor elements.`);\n        }\n        const element = document.createElement(tagName);\n        return new SafeElement(element);\n    }\n    createAnchorElement(href: string): SafeElement {\n        const anchor = document.createElement('a');\n        try {\n            const url = new URL(href);\n            if(url.protocol !== 'http:' && url.protocol !== 'https:'){\n                throw new Error(\"Invalid protocol\");\n            }\n            anchor.setAttribute('href', url.toString());\n        } catch (error) {\n            console.warn(`Invalid URL provided for anchor element: ${href}. Setting href to '#' instead.`);\n            anchor.setAttribute('href', '#');\n        }\n        return new SafeElement(anchor);\n    }\n}\n\ntype SafeMutationRecordObject = {\n    type: string;\n    target: SafeElement;\n    addedNodes: SafeElement[];\n}\n\nclass SafeClassArray<T> {\n    #items: T[];\n    __classType = 'REMOTE_REQUIRED' as const;\n    constructor(items: T[] = []) {\n        this.#items = items;\n    }\n    at(index: number): T {\n        return this.#items.at(index);\n    }\n    length(): number {\n        return this.#items.length;\n    }\n    push(item: T) {\n        this.#items.push(item);\n    }\n}\n\nclass SafeMutationRecord{\n    __classType = 'REMOTE_REQUIRED' as const;\n    #type: string;\n    #target: SafeElement;\n    #addedNodes: SafeClassArray<SafeElement>;\n    constructor(type: string, target: SafeElement, addedNodes: SafeElement[]) {\n        this.#type = type;\n        this.#target = target;\n        this.#addedNodes = new SafeClassArray<SafeElement>(addedNodes);\n    }\n    getType(): string {\n        return this.#type;\n    }\n    getTarget(): SafeElement {\n        return this.#target;\n    }\n    getAddedNodes(): SafeClassArray<SafeElement> {\n        return this.#addedNodes;\n    }\n}\n\ntype SafeMutationCallback = (mutations: SafeClassArray<SafeMutationRecord>) => void;\n\nclass SafeMutationObserver {\n    #observer: MutationObserver;\n    __classType = 'REMOTE_REQUIRED' as const;\n    constructor(callback: SafeMutationCallback) {\n        this.#observer = new MutationObserver((mutations) => {\n            const safeMutations: SafeMutationRecordObject[] = mutations.map(mutation => {\n\n                const elementMapHelper = (nodeList: NodeList): SafeElement[] => {\n                    const elements: SafeElement[] = [];\n                    nodeList.forEach(node => {\n                        if(node instanceof HTMLElement) {\n                            elements.push(new SafeElement(node));\n                        }\n                    })\n                    return elements;\n                }\n\n                return {\n                    type: mutation.type,\n                    target: new SafeElement(mutation.target as HTMLElement),\n                    addedNodes: elementMapHelper(mutation.addedNodes),\n                    removedNodes: elementMapHelper(mutation.removedNodes)\n                    \n                }\n            })\n\n            const safeClassed = new SafeClassArray<SafeMutationRecord>([]);\n            for(const record of safeMutations){\n                safeClassed.push(new SafeMutationRecord(\n                    record.type,\n                    record.target,\n                    record.addedNodes\n                ));\n            }\n            callback(safeClassed);\n        });\n    }\n\n    observe(element:SafeElement, options: MutationObserverInit) {\n        const identifier = v4();\n        element.setAttribute('x-identifier', identifier);\n        const rawElement = document.querySelector(`[x-identifier=\"${identifier}\"]`) as HTMLElement;\n        if(rawElement){\n            this.#observer.observe(rawElement, options);\n            element.setAttribute('x-identifier', '');\n        }\n    }\n\n}\n\nconst pluginUnloadCallbacks: Map<string, Function[]> = new Map();\n\nconst addPluginUnloadCallback = (pluginName: string, callback: Function) => {\n    if(!pluginUnloadCallbacks.has(pluginName)){\n        pluginUnloadCallbacks.set(pluginName, []);\n    }\n    pluginUnloadCallbacks.get(pluginName)?.push(callback);\n}\n\nconst makeMenuUnloadCallback = (menuId:string, menuStore: MenuDef[]) =>{\n    return () => {\n        const index = menuStore.findIndex(item => item.id === menuId);\n        if(index !== -1){\n            menuStore.splice(index, 1);\n        }\n    }\n}\n\nconst removeChatPanel = (id: string) => {\n    const index = chatPanelStore.findIndex(item => item.id === id);\n    if(index !== -1){\n        chatPanelStore.splice(index, 1);\n    }\n}\n\nconst removePluginChatPanels = (pluginName: string) => {\n    for(let i = chatPanelStore.length - 1; i >= 0; i--){\n        if(chatPanelStore[i].pluginName === pluginName){\n            chatPanelStore.splice(i, 1);\n        }\n    }\n}\n\nconst unloadV3Plugin = async (pluginName: string) => {\n    const callbacks = pluginUnloadCallbacks.get(pluginName);\n    const instance = v3PluginInstances.find(p => p.name === pluginName);\n    if(instance){\n        const index = v3PluginInstances.findIndex(p => p.name === pluginName);\n        if(index !== -1){\n            v3PluginInstances.splice(index, 1);\n        }\n    }\n    if(callbacks){\n        pluginUnloadCallbacks.delete(pluginName); \n        let promises: Promise<void>[] = [];\n        for(const callback of callbacks){\n            const result = callback();\n            if(result instanceof Promise){\n                promises.push(result);\n            }\n        }\n\n        await Promise.any([\n            Promise.all(promises),\n            sleep(1000) //timeout after 1 second\n        ])\n    }\n    try {\n        instance?.host?.terminate();        \n    } catch (error) {\n        console.error(`Error terminating plugin ${pluginName}:`, error);\n    }\n}\n\ntype PluginPermissionDesc = 'fetchLogs'|'db'|'mainDom'|'replacer'|'provider'|'sendChat';\nconst pluginPermissionDescs: PluginPermissionDesc[] = ['fetchLogs', 'db', 'mainDom', 'replacer', 'provider', 'sendChat'];\n\n// Plugin names are free text (the //@name directive), so `${name}_${desc}` keys\n// can collide — both across permissions and with a legacy name-only entry that\n// happens to read like \"name_desc\". JSON-encoding the pair makes every key\n// unambiguous: [\"foo\",\"db\"] can never equal a plain \"foo_db\" or [\"foo_db\",\"x\"].\nconst permissionKeyOf = (pluginName: string, permissionDesc: string) =>\n    JSON.stringify([pluginName, permissionDesc])\n\nconst permissionGivenPlugins: Set<string> = new Set();\nconst permissionDeniedPlugins: Set<string> = new Set();\nconst permissionCache = new Map<string, boolean | number>();\nconst pluginPermissionStateKey = 'cache/plugin-permissions/state.json';\nlet pluginPermissionLoadPromise: Promise<void> | null = null;\n\nasync function ensurePluginPermissionStateLoaded() {\n    if (!pluginPermissionLoadPromise) {\n        pluginPermissionLoadPromise = (async () => {\n            const payload = await readPersistentJson<{\n                given: string[]\n                denied: string[]\n                cache: [string, boolean | number][]\n            }>(pluginPermissionStateKey)\n            if (!payload) {\n                return\n            }\n            permissionGivenPlugins.clear()\n            permissionDeniedPlugins.clear()\n            permissionCache.clear()\n            for (const pluginName of payload.given ?? []) {\n                permissionGivenPlugins.add(pluginName)\n            }\n            for (const pluginName of payload.denied ?? []) {\n                permissionDeniedPlugins.add(pluginName)\n            }\n            for (const [key, value] of payload.cache ?? []) {\n                permissionCache.set(key, value)\n            }\n        })()\n    }\n    await pluginPermissionLoadPromise\n}\n\nexport async function resetAllPluginPermissions() {\n    permissionGivenPlugins.clear()\n    permissionDeniedPlugins.clear()\n    permissionCache.clear()\n    pluginPermissionLoadPromise = Promise.resolve()\n    await removePersistentKey(pluginPermissionStateKey)\n}\n\nexport async function resetPluginPermission(pluginName: string) {\n    await ensurePluginPermissionStateLoaded()\n    // Permission descs are a fixed enum, so we delete the exact key for each\n    // one rather than prefix-matching (which would also wipe another plugin's\n    // keys). `pluginName` alone covers legacy name-only entries from older\n    // versions, which JSON keys never collide with but reset should still clear.\n    const exactKeys = pluginPermissionDescs.map(desc => permissionKeyOf(pluginName, desc))\n    for (const key of [pluginName, ...exactKeys]) {\n        permissionGivenPlugins.delete(key)\n        permissionDeniedPlugins.delete(key)\n    }\n    for (const desc of pluginPermissionDescs) {\n        permissionCache.delete(permissionKeyOf(pluginName, desc) + '_lastGrantTime')\n    }\n    const plugin = DBState.db.plugins?.find(p => p.name === pluginName)\n    if (plugin?.script) {\n        const scriptHashBase = await hasher(new TextEncoder().encode(plugin.script))\n        for (const key of [...permissionCache.keys()]) {\n            if (key.startsWith(scriptHashBase + '_')) {\n                permissionCache.delete(key)\n            }\n        }\n    }\n    await persistPluginPermissionState()\n}\n\nasync function persistPluginPermissionState() {\n    await writePersistentJson(pluginPermissionStateKey, {\n        given: [...permissionGivenPlugins],\n        denied: [...permissionDeniedPlugins],\n        cache: [...permissionCache.entries()]\n    })\n}\n\ntype PluginV3ProviderOptions = PluginV2ProviderOptions & {\n    model?: LLMModel\n}\n\nexport const customV3ProviderMetaStore:LLMModel[] = []\n\n// Serializes permission dialogs. Every plugin shares the single global\n// alertStore, so when several plugins request permission at boot they would\n// otherwise overwrite each other's dialog — only the last one stays clickable\n// and a single click resolves all of them. The chain makes each dialog wait\n// for the previous one to finish, showing them one at a time.\nlet pluginPermissionDialogChain: Promise<unknown> = Promise.resolve()\n\nconst isPermissionResolved = async (\n    pluginName: string,\n    permissionDesc: PluginPermissionDesc,\n    requiresReconfirm: boolean,\n): Promise<{ resolved: boolean; value: boolean; pluginHash: string }> => {\n    const permissionKey = permissionKeyOf(pluginName, permissionDesc);\n    if (!requiresReconfirm && permissionGivenPlugins.has(permissionKey)) {\n        return { resolved: true, value: true, pluginHash: '' }\n    }\n    if (!requiresReconfirm && permissionDeniedPlugins.has(permissionKey)) {\n        return { resolved: true, value: false, pluginHash: '' }\n    }\n\n    const pluginHash = await hasher(\n        new TextEncoder().encode(\n            DBState.db.plugins.find(p => p.name === pluginName)?.script\n        )\n    ) + `_${permissionDesc}`;\n\n    if (!requiresReconfirm && permissionCache.get(pluginHash)) {\n        permissionGivenPlugins.add(permissionKey);\n        return { resolved: true, value: true, pluginHash }\n    }\n\n    return { resolved: false, value: false, pluginHash }\n}\n\nconst getPluginPermission = async (pluginName: string, permissionDesc: PluginPermissionDesc, reconfirm: boolean|'periodically' = false) => {\n    await ensurePluginPermissionStateLoaded()\n\n    // Recomputed (not captured) so a periodic reconfirm reflects the latest\n    // lastGrantTime: when several identical requests queue together, an earlier\n    // one may refresh it, making the reconfirm no longer due for the rest.\n    const computeRequiresReconfirm = () => {\n        if(reconfirm === 'periodically'){\n            const lastGrantTime = permissionCache.get(permissionKeyOf(pluginName, permissionDesc) + '_lastGrantTime') as number | undefined;\n            return !lastGrantTime || Date.now() - lastGrantTime > 3 * 24 * 60 * 60 * 1000; //3 days\n        }\n        return reconfirm === true;\n    }\n\n    // Fast path: if the answer is already known, skip the serialization queue\n    // entirely so cached/granted permissions never block on a pending dialog.\n    const early = await isPermissionResolved(pluginName, permissionDesc, computeRequiresReconfirm())\n    if (early.resolved) {\n        return early.value\n    }\n\n    const showDialog = async (): Promise<boolean> => {\n        // Re-check under the lock: an earlier queued dialog for the same plugin\n        // may have already granted/denied (or refreshed a periodic grant) while\n        // we were waiting our turn — recompute reconfirm so we don't re-prompt.\n        const requiresReconfirm = computeRequiresReconfirm()\n        const recheck = await isPermissionResolved(pluginName, permissionDesc, requiresReconfirm)\n        if (recheck.resolved) {\n            return recheck.value\n        }\n        const pluginHash = recheck.pluginHash\n\n        let alertTitle =\n            permissionDesc === 'fetchLogs' ? language.fetchLogConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'db' ? language.getFullDatabaseConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'mainDom' ? language.mainDomAccessConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'replacer' ? language.replacerPermissionConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'provider' ? language.providerPermissionConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'sendChat' ? language.sendChatConsent.replace(\"{}\", pluginName)\n            : `Error`\n        if(alertTitle === 'Error'){\n            return false;\n        }\n        const permissionKey = permissionKeyOf(pluginName, permissionDesc);\n        const conf = await alertConfirm(alertTitle)\n        if(conf && pluginHash){\n            permissionGivenPlugins.add(permissionKey);\n            permissionDeniedPlugins.delete(permissionKey);\n            permissionCache.set(pluginHash, true);\n            if(reconfirm === 'periodically'){\n                permissionCache.set(permissionKeyOf(pluginName, permissionDesc) + '_lastGrantTime', Date.now());\n            }\n            await persistPluginPermissionState()\n            return true;\n        }\n        permissionDeniedPlugins.add(permissionKey);\n        await persistPluginPermissionState()\n        return false;\n    }\n\n    // Append to the dialog chain so only one permission dialog is shown at a\n    // time. finally restores the chain even if showDialog throws, so a single\n    // failure never deadlocks every later permission request.\n    const run = pluginPermissionDialogChain\n        .catch(() => {})\n        .then(() => showDialog())\n    pluginPermissionDialogChain = run.catch(() => {})\n    return run\n}\n\nconst urlBlacklist = [\n    'risuai.xyz',\n    'risuai.net',\n    'sionyw.com',\n]\n\nconst authorizationHeaders = [\n    'x-api-key',\n    'authorization',\n    'proxy-authorization',\n]\n\nconst makeRisuaiAPIV3 = (iframe:HTMLIFrameElement,plugin:RisuPlugin) => {\n\n    const oldApis = getV2PluginAPIs();\n    const pluginChatAccess = new PluginChatAccess({\n        getDatabase: () => DBState.db,\n        hydrateChat: (chats, index, chaId) => ensureChatHydrated(chats as any, index, chaId) as any,\n        normalizeChat: (chat) => normalizeChat(chat as any) as any,\n        markChatDirty,\n        markCharacterDirty,\n    })\n\n    const getCurrentCharacterForPlugin = async () => {\n        const characterIndex = get(selectedCharID)\n        const character = await pluginChatAccess.getHydratedCharacterAt(characterIndex)\n        if (get(selectedCharID) !== characterIndex) {\n            throw new Error('The selected character changed while plugin data was loading')\n        }\n        return character ? $state.snapshot(character) : undefined\n    }\n\n    const setCurrentCharacterForPlugin = async (character: any) => {\n        const characterIndex = get(selectedCharID)\n        await pluginChatAccess.replaceCharacterAt(\n            characterIndex,\n            character,\n            () => get(selectedCharID) === characterIndex,\n        )\n    }\n\n    const preparePluginDatabaseWrite = async (newDb: any) => {\n        if (!newDb || typeof newDb !== 'object'\n            || !Object.prototype.hasOwnProperty.call(newDb, 'characters')) {\n            return null\n        }\n\n        const database = await pluginChatAccess.getHydratedDatabase()\n        if (database !== DBState.db) {\n            throw new Error('The plugin database target changed while chats were loading')\n        }\n\n        const previousCharacters = [...(database.characters ?? [])]\n        // Work on detached character/chat shells so assigning an omitted ID\n        // cannot mutate a plugin-owned payload if later validation fails.\n        const candidateCharacters = Array.isArray(newDb.characters)\n            ? newDb.characters.map((character: any) => {\n                if (!character || typeof character !== 'object' || Array.isArray(character)) {\n                    return character\n                }\n                return {\n                    ...character,\n                    chats: Array.isArray(character.chats)\n                        ? character.chats.map((chat: any) => (\n                            chat && typeof chat === 'object' && !Array.isArray(chat)\n                                ? { ...chat }\n                                : chat\n                        ))\n                        : character.chats,\n                }\n            })\n            : newDb.characters\n        assignMissingChatIdsToNewCharacters(\n            { characters: candidateCharacters },\n            { characters: previousCharacters },\n            v4,\n        )\n        const nextCharacters = pluginChatAccess.validateCharacterCollection(candidateCharacters)\n        return {\n            payload: { ...newDb, characters: nextCharacters },\n            previousCharacters,\n            nextCharacters,\n        }\n    }\n\n    const setPluginDatabaseLite = async (newDb: any) => {\n        const prepared = await preparePluginDatabaseWrite(newDb)\n        oldApis.setDatabaseLite(prepared?.payload ?? newDb)\n        if (prepared) {\n            pluginChatAccess.markCharacterCollectionDirty(\n                prepared.previousCharacters,\n                prepared.nextCharacters,\n            )\n        }\n    }\n\n    const setPluginDatabase = async (newDb: any) => {\n        const prepared = await preparePluginDatabaseWrite(newDb)\n        await oldApis.setDatabase(prepared?.payload ?? newDb)\n        if (prepared) {\n            pluginChatAccess.markCharacterCollectionDirty(\n                prepared.previousCharacters,\n                prepared.nextCharacters,\n            )\n        }\n    }\n\n    return {\n\n        //Old APIs from v2.1\n        risuFetch: (url, options) => {\n            console.error(`[DEPRECATION WARNING] risuFetch is deprecated and will be removed in future versions. Please use nativeFetch instead.`)\n            for(const blocked of urlBlacklist){\n                if(url.toLowerCase().includes(blocked)){\n                    throw new Error(`Requests to ${blocked} are blocked for security reasons.`);\n                }\n            }\n\n            //scan headers\n            const headers = options?.headers || {};\n            for(const headerName in headers){\n                if(authorizationHeaders.includes(headerName.toLowerCase())){\n                    console.warn(`Request contains potentially sensitive header '${headerName}'. handling of such headers may be changed to only work with nativeFetch.`);\n                }\n            }\n            return oldApis.risuFetch(url, options);\n        },\n        nativeFetch: (url, options) => {\n            for(const blocked of urlBlacklist){\n                if(url.toLowerCase().includes(blocked)){\n                    throw new Error(`Requests to ${blocked} are blocked for security reasons.`);\n                }\n            }\n\n            //scan headers\n            const headers = options?.headers || {};\n            for(const headerName in headers){\n                if(authorizationHeaders.includes(headerName.toLowerCase())){\n                    console.warn(`Request contains potentially sensitive header '${headerName}'. handling of such headers may be changed to use server-side approch with write-only api access in the future for better security.`);\n                }\n            }\n            return oldApis.nativeFetch(url, options);\n        },\n        getChar: getCurrentCharacterForPlugin,\n        setChar: setCurrentCharacterForPlugin,\n        addProvider: (name: string, func: (arg: PluginV2ProviderArgument, abortSignal?: AbortSignal) => Promise<{ success: boolean, content: string }>, options?: PluginV3ProviderOptions) => {\n            console.warn(`[WARN] addProvider is a powerful API that can potentially be unsafe if used incorrectly. addProvider's functionality might be limited or changed in future updates to ensure security. please use other APIs if possible.`);\n            let provs = get(customProviderStore)\n            provs.push(name)\n            pluginV2.providers.set(name, async (arg, abortSignal) => {\n               await getPluginPermission(plugin.name, 'provider', 'periodically');\n               //mode is overridden to v3, due to vulnerabilities using mode.\n               //Alternative to mode will be added in future\n               arg.mode = 'v3'\n               return await func(arg, abortSignal);\n            }),\n            pluginV2.providerOptions.set(name, options ?? {})\n            customProviderStore.set(provs)\n\n            const modelData:LLMModel = {\n                id: `pluginmodel:::${name}`,\n                name: options?.model?.name ?? name,\n                shortName: options?.model?.shortName ?? name,\n                fullName: options?.model?.fullName ?? name,\n                internalID: options?.model?.internalID ?? `pluginmodel:::${name}`,\n                provider: LLMProvider.AsIs,\n                format: LLMFormat.Plugin,\n                flags: options?.model?.flags ?? [LLMFlags.hasFullSystemPrompt],\n                parameters: options?.model?.parameters ?? ['temperature', 'top_p', 'frequency_penalty', 'presence_penalty', 'repetition_penalty', 'min_p', 'top_a', 'top_k', 'thinking_tokens'],\n                tokenizer:options?.model?.tokenizer ??  LLMTokenizer.Unknown\n            }\n            customV3ProviderMetaStore.push(modelData);\n        },\n        addTTSPreprocessor: async (\n            func: TTSHookFn<BeforeTTSContext, BeforeTTSResult>,\n        ) => {\n            registerTTSPreprocessor(func);\n            addPluginUnloadCallback(plugin.name, () => unregisterTTSPreprocessor(func));\n        },\n        addTTSPostprocessor: async (\n            func: TTSHookFn<AfterTTSContext, AfterTTSResult>,\n        ) => {\n            registerTTSPostprocessor(func);\n            addPluginUnloadCallback(plugin.name, () => unregisterTTSPostprocessor(func));\n        },\n        addRisuScriptHandler: oldApis.addRisuScriptHandler,\n        removeRisuScriptHandler: oldApis.removeRisuScriptHandler,\n        addRisuReplacer: async (name:string,func:Function) => {\n            //permission check for replacer\n            const conf = await getPluginPermission(plugin.name, 'replacer', 'periodically');\n            if(!conf){\n                return;\n            }\n            oldApis.addRisuReplacer(name, func as any);\n        },\n        removeRisuReplacer: oldApis.removeRisuReplacer,\n        setDatabaseLite: setPluginDatabaseLite,\n        setDatabase: setPluginDatabase,\n        loadPlugins: oldApis.loadPlugins,\n        readImage: oldApis.readImage,\n        saveAsset: oldApis.saveAsset,\n        //Same functionality, but new implementation\n        getDatabase: async (includeOnly:string[]|'all' = 'all') => {\n            const conf = await getPluginPermission(plugin.name, 'db', 'periodically');\n            if(!conf){\n                return null;\n            }\n            const shouldIncludeCharacters = includeOnly === 'all' || includeOnly.includes('characters')\n            const db = shouldIncludeCharacters\n                ? await pluginChatAccess.getHydratedDatabase()\n                : DBState.db\n            let liteDB = {}\n            for(const key of allowedDbKeys){\n                if(includeOnly !== 'all' && !includeOnly.includes(key)){\n                    continue;\n                }\n                (liteDB as any)[key] = $state.snapshot((db as any)[key]);\n            }\n            return liteDB;\n        },\n        getDatabaseMetadata: async (includeOnly:string[]|'all' = 'all') => {\n            const conf = await getPluginPermission(plugin.name, 'db', 'periodically');\n            if(!conf){\n                return null;\n            }\n            const shouldIncludeCharacters = includeOnly === 'all' || includeOnly.includes('characters')\n            const db = shouldIncludeCharacters\n                ? pluginChatAccess.getDatabaseWithChatMetadata()\n                : DBState.db\n            let liteDB = {}\n            for(const key of allowedDbKeys){\n                if(includeOnly !== 'all' && !includeOnly.includes(key)){\n                    continue;\n                }\n                (liteDB as any)[key] = $state.snapshot((db as any)[key]);\n            }\n            return liteDB;\n        },\n\n        installPlugin: handlePluginInstallViaPlugin,\n\n        // --- Color Scheme APIs ---\n        changeColorScheme: (name: string) => {\n            changeColorScheme(name)\n        },\n        setColorScheme: (scheme: ColorScheme) => {\n            const requiredKeys = ['bgcolor','darkbg','borderc','selected','draculared','textcolor','textcolor2','darkBorderc','darkbutton','type'] as const\n            for (const key of requiredKeys) {\n                if (typeof (scheme as any)[key] !== 'string') {\n                    throw new Error(`Invalid color scheme: missing or invalid '${key}'`)\n                }\n            }\n            if (scheme.type !== 'light' && scheme.type !== 'dark') {\n                throw new Error('Invalid color scheme type: must be \"light\" or \"dark\"')\n            }\n            const db = DBState.db\n            db.colorSchemeName = 'custom'\n            db.colorScheme = scheme\n            updateColorScheme()\n        },\n        getColorScheme: () => {\n            const db = DBState.db\n            return {\n                name: db.colorSchemeName,\n                scheme: $state.snapshot(db.colorScheme)\n            }\n        },\n\n        // --- Text Theme APIs ---\n        changeTextTheme: (name: string) => {\n            if (!['standard','highcontrast'].includes(name)) {\n                throw new Error(`Invalid text theme: ${name}`)\n            }\n            const db = DBState.db\n            db.textTheme = name\n            updateTextThemeAndCSS()\n        },\n        setCustomTextTheme: (theme: {\n            FontColorStandard: string,\n            FontColorBold: string,\n            FontColorItalic: string,\n            FontColorItalicBold: string,\n            FontColorQuote1: string,\n            FontColorQuote2: string\n        }) => {\n            const requiredKeys = ['FontColorStandard','FontColorBold','FontColorItalic','FontColorItalicBold','FontColorQuote1','FontColorQuote2'] as const\n            for (const key of requiredKeys) {\n                if (typeof (theme as any)[key] !== 'string') {\n                    throw new Error(`Invalid text theme: missing or invalid '${key}'`)\n                }\n            }\n            const db = DBState.db\n            db.textTheme = 'custom'\n            db.customTextTheme = theme\n            updateTextThemeAndCSS()\n        },\n        getTextTheme: () => {\n            const db = DBState.db\n            return {\n                name: db.textTheme,\n                customTheme: $state.snapshot(db.customTextTheme)\n            }\n        },\n\n        //Deprecated APIs from v2.1\n        //Use getArgument / setArgument instead if possible\n        getArg: oldApis.getArg,\n        setArg: oldApis.setArg,\n\n        //New APIs for v3\n        getArgument: async (key:string) => {\n            const db = getDatabase()\n            for (const p of db.plugins) {\n                if (p.name === plugin.name) {\n                    return p.realArg[key];\n                }\n            }\n        },\n        setArgument: async (key:string, value:string) => {\n            const db = getDatabase();\n            for (const p of db.plugins) {\n                if (p.name === plugin.name) {\n                    p.realArg[key] = value;\n                }\n            }\n        },\n        getCharacterFromIndex: async (index:number) => {\n            const character = await pluginChatAccess.getHydratedCharacterAt(index)\n            return character ? $state.snapshot(character) : null\n        },\n        setCharacterToIndex: async (index:number, char:any) => {\n            await pluginChatAccess.replaceCharacterAt(index, char)\n        },\n        getChatFromIndex: async (characterIndex:number, chatIndex:number) => {\n            const chat = await pluginChatAccess.getHydratedChatAt(characterIndex, chatIndex)\n            return chat ? $state.snapshot(chat) : null\n        },\n        setChatToIndex: async (characterIndex:number, chatIndex:number, chat:any) => {\n            await pluginChatAccess.replaceChatAt(characterIndex, chatIndex, chat)\n        },\n        getCurrentCharacterIndex: () => {\n            return get(selectedCharID)\n        },\n        getCurrentChatIndex: () => {\n            const db = DBState.db\n            const charId = get(selectedCharID)\n            return db.characters[charId].chatPage\n        },\n        getCurrentLorebookEntries: async () => {\n            const characterIndex = get(selectedCharID)\n            const char = DBState.db.characters[characterIndex]\n            if(!char){\n                return []\n            }\n            const page = char.chatPage\n            const expectedChatId = char.chats?.[page]?.id\n            const chat = await pluginChatAccess.getHydratedChatAt(characterIndex, page)\n            const currentCharacter = DBState.db.characters[characterIndex]\n            if (get(selectedCharID) !== characterIndex\n                || currentCharacter !== char\n                || currentCharacter.chatPage !== page\n                || currentCharacter.chats?.[page]?.id !== expectedChatId) {\n                throw new Error('The current lorebook target changed while plugin data was loading')\n            }\n            const characterLore = char.globalLore ?? []\n            const chatLore = chat?.localLore ?? []\n            const moduleLore = getModuleLorebooks()\n            return $state.snapshot(characterLore.concat(chatLore).concat(moduleLore))\n        },\n        //New names for character APIs, to match API naming conventions\n        getCharacter: getCurrentCharacterForPlugin,\n        setCharacter: setCurrentCharacterForPlugin,\n\n        showContainer: (\n            //more types may be added in future\n            type: 'fullscreen' = 'fullscreen'\n        ) => {\n            iframe.style.display = \"block\";\n            \n            switch(type) {\n                case 'fullscreen': {\n                    //move iframe to body if not already there\n                    if(iframe.parentElement !== document.body) {\n                        document.body.appendChild(iframe);\n                    }\n\n                    //Make iframe cover whole screen\n                    iframe.style.position = \"fixed\";\n                    iframe.style.top = \"0\";\n                    iframe.style.left = \"0\";\n                    iframe.style.width = \"100%\";\n                    iframe.style.height = \"100%\";\n                    iframe.style.border = \"none\";\n                    iframe.style.zIndex = \"1000\";\n                    break;\n                }\n                default: {\n                    return\n                }\n            }\n        },\n        hideContainer: () => {\n            iframe.style.display = \"none\";\n        },\n        getRootDocument: async () => {\n            const conf = await getPluginPermission(plugin.name, 'mainDom');\n            if(!conf){\n                return null;\n            }\n            return new SafeDocument(document);\n        },\n        registerSetting: (\n            name:string,\n            callback: any,\n            icon:string = '',\n            iconType:'html'|'img'|'none' = 'none',\n            id?:string\n        ) => {\n            if(iconType !== 'html' && iconType !== 'img' && iconType !== 'none'){\n                throw new Error(\"iconType must be 'html', 'img' or 'none'\");\n            }\n            if(typeof name !== 'string' || name.trim() === ''){\n                throw new Error(\"name must be a non-empty string\");\n            }\n            const menuId = id || v4()\n            const menuDef:MenuDef = {\n                id: menuId,\n                name,\n                icon,\n                iconType,\n                callback\n            }\n            const existingIndex = additionalSettingsMenu.findIndex(item => item.id === menuId)\n            if(existingIndex !== -1){\n                additionalSettingsMenu[existingIndex] = menuDef\n                addPluginUnloadCallback(\n                    plugin.name,\n                    makeMenuUnloadCallback(menuId, additionalSettingsMenu)\n                )\n                return {id: menuId}\n            }\n            additionalSettingsMenu.push(menuDef)\n            addPluginUnloadCallback(\n                plugin.name,\n                makeMenuUnloadCallback(menuId, additionalSettingsMenu)\n            )\n            return {id: menuId};\n        },\n        registerBodyIntercepter: async (callback: (body: any, type: string) => any) => {\n\n            if(await getPluginPermission(plugin.name, 'replacer') === false){\n                return null;\n            }\n            \n            const id = v4();\n            bodyIntercepterStore.push({\n                id,\n                callback\n            })\n            addPluginUnloadCallback(plugin.name, () => {\n                const index = bodyIntercepterStore.findIndex(item => item.id === id);\n                if(index !== -1){\n                    bodyIntercepterStore.splice(index, 1);\n                }\n            })\n            return {id:id};\n        },\n        \n        unregisterBodyIntercepter: (id: string) => {\n            const index = bodyIntercepterStore.findIndex(item => item.id === id);\n            if(index !== -1){\n                bodyIntercepterStore.splice(index, 1);\n            }\n        },\n            \n        registerButton: (\n            arg: {\n                name: string,\n                icon: string,\n                iconType: 'html'|'img'|'none',\n                location?: 'action'|'chat'|'hamburger',\n                id?: string\n            },\n            callback: () => void\n        ) => {\n            let { name, icon, iconType, location, id: providedId } = arg;\n            location = location || 'action';\n            if(iconType !== 'html' && iconType !== 'img' && iconType !== 'none'){\n                throw new Error(\"iconType must be 'html', 'img' or 'none'\");\n            }\n            if(typeof name !== 'string' || name.trim() === ''){\n                throw new Error(\"name must be a non-empty string\");\n            }\n            if(typeof icon !== 'string'){\n                throw new Error(\"icon must be a string\");\n            }\n            const id = providedId || v4()\n            const menuDef:MenuDef = {\n                name,\n                icon,\n                iconType,\n                callback,\n                id\n            }\n\n            const buttonStores = [additionalFloatingActionButtons, additionalHamburgerMenu, additionalChatMenu]\n            for(const store of buttonStores){\n                const existingIndex = store.findIndex(item => item.id === id)\n                if(existingIndex !== -1){\n                    store[existingIndex] = menuDef\n                    addPluginUnloadCallback(\n                        plugin.name,\n                        makeMenuUnloadCallback(id, store)\n                    )\n                    return {id}\n                }\n            }\n\n            switch(location){\n                case 'action':{\n                    additionalFloatingActionButtons.push(menuDef)\n                    addPluginUnloadCallback(\n                        plugin.name,\n                        makeMenuUnloadCallback(menuDef.id, additionalFloatingActionButtons)\n                    )\n                    break\n                }\n                case 'hamburger':{\n                    additionalHamburgerMenu.push(menuDef)\n                    addPluginUnloadCallback(\n                        plugin.name,\n                        makeMenuUnloadCallback(menuDef.id, additionalHamburgerMenu)\n                    )\n                    break\n                }\n                case 'chat':{\n                    additionalChatMenu.push(menuDef)\n                    addPluginUnloadCallback(\n                        plugin.name,\n                        makeMenuUnloadCallback(menuDef.id, additionalChatMenu)\n                    )\n                    break\n                }\n                default:{\n                    throw new Error(\"Invalid location for button\")\n                }\n            }\n            return {id};\n        },\n        setChatPanel: (\n            content: string | null,\n            options: {\n                id?: string,\n                className?: string,\n            } = {}\n        ) => {\n            const id = options.id || `${plugin.name}:default`;\n\n            if(content === null || content === ''){\n                removeChatPanel(id);\n                return {id};\n            }\n\n            if(typeof content !== 'string'){\n                throw new Error(\"content must be a string or null\");\n            }\n\n            const panel = {\n                id,\n                pluginName: plugin.name,\n                html: DOMPurify.sanitize(content),\n                className: typeof options.className === 'string'\n                    ? DOMPurify.sanitize(options.className, {ALLOWED_TAGS: [], ALLOWED_ATTR: []})\n                    : undefined,\n            }\n\n            const existingIndex = chatPanelStore.findIndex(item => item.id === id);\n            if(existingIndex !== -1){\n                chatPanelStore[existingIndex] = panel;\n            }\n            else{\n                chatPanelStore.push(panel);\n            }\n            addPluginUnloadCallback(plugin.name, () => removePluginChatPanels(plugin.name));\n            return {id};\n        },\n        registerMCP: registerMCPModule,\n        unregisterMCP: unregisterMCPModule,\n        unregisterUIPart: (id: string) => {\n            const removeFromMenuStore = (menuStore: MenuDef[]) => {\n                const index = menuStore.findIndex(item => item.id === id);\n                if(index !== -1){\n                    menuStore.splice(index, 1);\n                }\n            }\n\n            removeFromMenuStore(additionalSettingsMenu);\n            removeFromMenuStore(additionalFloatingActionButtons);\n            removeFromMenuStore(additionalHamburgerMenu);\n            removeFromMenuStore(additionalChatMenu);\n            removeChatPanel(id);\n        },\n        log: (message:string) => {\n            console.log(`[RisuAI Plugin: ${plugin.name}] ${message}`);\n        },\n        createMutationObserver(callback: SafeMutationCallback): SafeMutationObserver {\n            return new SafeMutationObserver(callback)\n        },\n        onUnload: (callback: () => void) => {\n            addPluginUnloadCallback(plugin.name, callback);\n        },\n        getFetchLogs: async () => {\n            const unsafeFetchLog = getFetchLogs()\n            const conf = await getPluginPermission(plugin.name, 'fetchLogs');\n            if(!conf){\n                return null;\n            }\n            return unsafeFetchLog.map(log => {\n\n                const url = new URL(log.url);\n                return {\n                    url: url.origin + url.pathname,\n                    body: log.body,\n                    status: log.status,\n                    response: log.response,\n                }\n            })\n        },\n\n        alert: (msg:string) => {\n            return alertNormal(msg)\n        },\n        alertConfirm: (msg:string) => {\n            return alertConfirm(msg)\n        },\n        alertError: (msg:string) => {\n            return alertError(msg)\n        },\n        getRuntimeInfo: () => {\n            return {\n                apiVersion: \"3.0\",\n                platform: 'node',\n                saveMethod:\n                    forageStorage.isAccount ? 'account' :\n                    'local',\n            }\n        },\n        getLocalPluginStorage: () => {\n            return new SafeLocalPluginStorage(plugin.name)\n        },\n        checkCharOrder: checkCharOrder,\n        requestPluginPermission: (permission:string) => {\n            return getPluginPermission(plugin.name, permission as any);\n        },\n        //Internal use APIs\n        _getOldKeys: () => {\n            return Object.keys(oldApis)\n        },\n        _getPropertiesForInitialization: () => {\n            const v = {\n                apiVersion: \"3.0\",\n                apiVersionCompatibleWith: [\"3.0\"],\n            } as any;\n\n            v.list = Object.keys(v);\n            \n            return v;\n        },\n        _getPluginStorage: oldApis.pluginStorage.getItem,\n        // Wrapped (not aliased) so we can record the originating plugin into the\n        // sidecar meta map. The value write is unchanged; reads stay aliased.\n        _setPluginStorage: (key: string, value: any) => {\n            oldApis.pluginStorage.setItem(key, value)\n            recordOwner('save', key, plugin.name)\n        },\n        _removePluginStorage: (key: string) => {\n            oldApis.pluginStorage.removeItem(key)\n            removeOwner('save', key)\n        },\n        _clearPluginStorage: () => {\n            oldApis.pluginStorage.clear()\n            clearOwners('save')\n        },\n        _keyPluginStorage: oldApis.pluginStorage.key,\n        _keysPluginStorage: oldApis.pluginStorage.keys,\n        _lengthPluginStorage: oldApis.pluginStorage.length,\n        _getSafeLocalStorage: oldApis.safeLocalStorage.getItem,\n        _setSafeLocalStorage: (key: string, value: string) => {\n            oldApis.safeLocalStorage.setItem(key, value)\n            recordOwner('local', key, plugin.name)\n        },\n        _removeSafeLocalStorage: (key: string) => {\n            oldApis.safeLocalStorage.removeItem(key)\n            removeOwner('local', key)\n        },\n        _clearSafeLocalStorage: () => {\n            oldApis.safeLocalStorage.clear()\n            clearOwners('local')\n        },\n        _keySafeLocalStorage: oldApis.safeLocalStorage.key,\n        _keysSafeLocalStorage: oldApis.safeLocalStorage.keys,\n        searchTranslationCache: async (partialKey: string) => {\n            return searchLLMCache(partialKey)\n        },\n        getTranslationCache: async (key: string) => {\n            return getLLMCache(key)\n        },\n        _getAliases: () => {\n            return {\n                'pluginStorage':{\n                    'getItem': '_getPluginStorage',\n                    'setItem': '_setPluginStorage',\n                    'removeItem': '_removePluginStorage',\n                    'clear': '_clearPluginStorage',\n                    'key': '_keyPluginStorage',\n                    'keys': '_keysPluginStorage',\n                    'length': '_lengthPluginStorage',\n                },\n                'safeLocalStorage':{\n                    'getItem': '_getSafeLocalStorage',\n                    'setItem': '_setSafeLocalStorage',\n                    'removeItem': '_removeSafeLocalStorage',\n                    'clear': '_clearSafeLocalStorage',\n                    'key': '_keySafeLocalStorage',\n                    'keys': '_keysSafeLocalStorage',\n                }\n            }\n        },\n        runLLMModel: async (options: {\n            mode: ModelModeExtended\n            messages: OpenAIChat[]\n            staticModel?: string\n            allowPlugins?: boolean\n        }) => {\n            return requestChatDataMain({\n                formated: options.messages,\n                bias: {},\n                staticModel: options.staticModel,\n\n                // Calls into plugin-provided models are blocked by default to\n                // guard against accidental IPC loops between provider plugins.\n                // Plugin authors who need to reach the user's plugin-supplied\n                // main or auxiliary model (e.g. a TTS preprocessor that\n                // rewrites text with the configured otherAx model) can opt in\n                // explicitly with `allowPlugins: true`, accepting responsibility\n                // for avoiding provider-to-provider call loops.\n                blockPlugins: !options.allowPlugins,\n            }, options.mode)\n        },\n        sendChat: async (message: string) => {\n            const conf = await getPluginPermission(plugin.name, 'sendChat');\n            if(!conf){\n                return false;\n            }\n\n            if(typeof message !== 'string'){\n                throw new Error(\"Message must be a string\");\n            }\n\n            if(get(doingChat)){\n                throw new Error(\"A chat is already in progress\");\n            }\n\n            if(getModelInfo(DBState.db.aiModel).id.startsWith('pluginmodel:::')){\n                // Executing plugin provider is block because it can be used for loopholes for ipc right now.\n                throw new Error(\"Sending chat with plugin-based model is currently blocked\");\n            }\n\n            const charId = get(selectedCharID);\n            const char = DBState.db.characters[charId];\n            if(!char){\n                throw new Error(\"No character selected\");\n            }\n\n            // Lazy-loaded chats are placeholders until their payload is fetched.\n            // Appending to the placeholder loses the message because the normal\n            // send path refuses to process an unhydrated chat. Hydrate first and\n            // only mutate the real chat after that succeeds.\n            const chatPage = char.chatPage;\n            const chat = await ensureCurrentChatReady(char.chats, chatPage, char.chaId);\n            if(!chat){\n                throw new Error(\"No active chat found or the chat could not be loaded\");\n            }\n            if(\n                get(selectedCharID) !== charId ||\n                DBState.db.characters[charId] !== char ||\n                char.chatPage !== chatPage ||\n                char.chats[chatPage] !== chat\n            ){\n                throw new Error(\"The active chat changed while it was loading\");\n            }\n            if(get(doingChat)){\n                throw new Error(\"A chat is already in progress\");\n            }\n\n            if(message){\n                chat.message.push({\n                    role: 'user',\n                    data: message,\n                    time: Date.now(),\n                });\n            }\n\n            try {\n                await processSendChat(-1, {});\n            } finally {\n                // Plugin API path does not pass through the UI unlock logic,\n                // so release doingChat here on both success and failure.\n                doingChat.set(false);\n            }\n\n            return true;\n        },\n        addPluginChannelListener: (channelName: string, callback: Function) => {\n            pluginChannel.set(plugin.name + channelName, callback);\n        },\n        postPluginChannelMessage: (pluginName: string, channelName: string, message: any) => {\n\n            const currentPluginName = plugin.name;\n            const receiverPlugin = DBState.db.plugins.find(p => p.name === pluginName);\n\n            if(!receiverPlugin){\n                console.warn(`[RisuAI Plugin: ${currentPluginName}] Attempted to send message to non-existent plugin '${pluginName}' on channel '${channelName}'.`);\n                return;\n            }\n\n            if(!receiverPlugin.allowedIPC?.includes(currentPluginName)){\n                console.warn(`[RisuAI Plugin: ${currentPluginName}] Attempted to send message to plugin '${pluginName}' but receiver plugin does not allow IPC communication from this plugin. declare //@allowed-ipc ${currentPluginName} in the reciver plugin script to allow IPC communication.`);\n                return;\n            }\n\n            if(!plugin.allowedIPC?.includes(receiverPlugin.name)){\n                console.warn(`[RisuAI Plugin: ${currentPluginName}] Attempted to send message to plugin '${pluginName}' but the sender plugin does not allow IPC communication to this plugin. declare //@allowed-ipc ${receiverPlugin.name} in the sender plugin script to allow IPC communication.`);\n                return;\n            }\n\n\n            const callback = pluginChannel.get(pluginName + channelName);\n            if(callback){\n                callback(message, {\n                    sender: currentPluginName,\n                    channel: channelName\n                });\n            }\n        },\n        saveSecretHeader: async (key: string, value: string|string[]) => {\n            //TODO: Implement server-side secret storage with write-only access for plugins, to enhance security when handling sensitive information like API keys.\n            //This will have rate-limit, to prevent saving it publicly and writing as secret every time before using it.\n            console.warn(`[RisuAI Plugin: ${plugin.name}] saveServerSecret is not implemented yet. This API is intended for securely storing sensitive information like API keys with write-only access for plugins. Please avoid using this API until it is implemented.`);\n        }\n    }\n}\n\ntype V3PluginInstance = {\n    name: string;\n    host: SandboxHost;\n}\n\nconst v3PluginInstances: V3PluginInstance[] = [];\n\nexport async function loadV3Plugins(plugins:RisuPlugin[]){\n    await Promise.all(v3PluginInstances.map(async (instance) => {\n        await unloadV3Plugin(instance.name);\n    }));\n    const loadPromises = plugins.map(plugin => executePluginV3(plugin));\n    await Promise.all(loadPromises);\n}\n\nexport async function executePluginV3(plugin:RisuPlugin){\n\n    const alreadyRunning = v3PluginInstances.find(p => p.name === plugin.name);\n    if(alreadyRunning){\n        console.log(`[RisuAI Plugin: ${plugin.name}] Plugin is already running. Skipping load.`);\n        return;\n    }\n\n    const iframe = document.createElement('iframe');\n    iframe.style.display = \"none\";\n    document.body.appendChild(iframe);\n    const host = new SandboxHost(makeRisuaiAPIV3(iframe, plugin));\n    v3PluginInstances.push({\n        name: plugin.name,\n        host\n    });\n    host.run(iframe, plugin.script);\n    console.log(`[RisuAI Plugin: ${plugin.name}] Loaded API V3 plugin.`);\n}\n\nexport function getV3PluginInstance(name: string) {\n    return v3PluginInstances.find(p => p.name === name);\n}\n\nglobalThis.__debugV3Plugin = (code: string|Function, pluginName: string = '') => {\n    if(code instanceof Function){\n        code = `(${code.toString()})()`;\n    }\n    if(pluginName === ''){\n        return v3PluginInstances[0].host.executeInIframe(code);\n    }\n    const instance = v3PluginInstances.find(p => p.name === pluginName);\n    if(!instance){\n        throw new Error(`Plugin ${pluginName} not found.`);\n    }\n    return instance.host.executeInIframe(code);\n};\n","targetVersions":{"pocketrisu":["1.8.1"]}},{"id":"lazy-chat-sync:replace:src:ts:plugins:apiV3:v3-svelte-ts:1.9","file":"src/ts/plugins/apiV3/v3.svelte.ts","type":"replace","anchor":"import { allowedDbKeys, customProviderStore, getV2PluginAPIs, handlePluginInstallViaPlugin, pluginV2, type PluginV2ProviderArgument, type PluginV2ProviderOptions, type RisuPlugin } from \"../plugins.svelte\";\nimport { SandboxHost } from \"./factory\";\nimport { getDatabase, normalizeChat } from \"src/ts/storage/database.svelte\";\nimport { SafeLocalPluginStorage, tagWhitelist } from \"../pluginSafeClass\";\nimport { recordOwner, removeOwner, clearOwners } from \"../pluginStorageMeta\";\nimport DOMPurify from 'dompurify';\nimport { additionalChatMenu, additionalFloatingActionButtons, additionalHamburgerMenu, additionalSettingsMenu, bodyIntercepterStore, chatPanelStore, DBState, selectedCharID, type MenuDef } from \"src/ts/stores.svelte\";\nimport { v4 } from \"uuid\";\nimport { sleep } from \"src/ts/util\";\nimport { alertConfirm, alertError, alertNormal } from \"src/ts/alert\";\nimport { language } from \"src/lang\";\nimport { checkCharOrder, forageStorage, getFetchLogs } from \"src/ts/globalApi.svelte\";\nimport { changeColorScheme, updateColorScheme, updateTextThemeAndCSS, type ColorScheme } from \"src/ts/gui/colorscheme\";\nimport { get } from \"svelte/store\";\nimport { registerMCPModule, unregisterMCPModule } from \"src/ts/process/mcp/pluginmcp\";\nimport { getInlayAsset } from \"src/ts/process/files/inlays\";\nimport { getLLMCache, searchLLMCache } from \"src/ts/translator/translator\";\nimport { hasher } from \"src/ts/parser/parser.svelte\";\nimport { LLMFlags, LLMFormat, LLMProvider, LLMTokenizer, type LLMModel } from \"src/ts/model/types\";\nimport { readPersistentJson, removePersistentKey, writePersistentJson } from \"src/ts/storage/persistentKv\";\nimport { endAllGenerations } from \"src/ts/process/generationState\";\nimport { sendChat as processSendChat, doingChat } from \"src/ts/process/index.svelte\";\nimport { getModelInfo } from \"src/ts/model/modellist\";\nimport type { ModelModeExtended } from \"src/ts/process/request/shared\";\nimport { requestChatDataMain } from \"src/ts/process/request/request\";\nimport type { OpenAIChat } from \"src/ts/process/index.svelte\";\nimport { getModuleLorebooks } from \"src/ts/process/modules\";\nimport {\n    registerTTSPreprocessor,\n    unregisterTTSPreprocessor,\n    registerTTSPostprocessor,\n    unregisterTTSPostprocessor,\n    type BeforeTTSContext,\n    type BeforeTTSResult,\n    type AfterTTSContext,\n    type AfterTTSResult,\n    type TTSHookFn,\n} from \"src/ts/process/ttsHooks\";\n\n/*\n    V3 API for RisuAI Plugins\n\n    Before adding new APIs here, please check the limitations\n\n    - APIs must be a functions\n        - If you want nested objects, first add as a plain function, `_getPluginStorage` for example\n            And add it too _getAliases function ({'pluginStorage':{'getItem': '_getPluginStorage', ... }})\n            This will make pluginStorage.getItem() work in plugins\n        - If you need constants, use _getPropertiesForInitialization to set them up\n            For example apiVersion and apiVersionCompatibleWith are set this way,\n            Accessable in plugins as risuai.apiVersion\n    - APIs must return, or accept as parameters, only the following types:\n        - Serializable data (string, number, boolean, null, array, object)\n        - Class instances marked with __classType = 'REMOTE_REQUIRED'\n        - Callback functions (only as parameters)\n        - Note that Class or Callbacks inside arrays or objects are not supported\n*/\n\nconst pluginChannel = new Map<string, Function>();\nconst documentEventListeners: Array<{type: string, listener: EventListenerOrEventListenerObject, options: any}> = [];\n\nclass SafeElement {\n    #element: HTMLElement;\n    __classType = 'REMOTE_REQUIRED' as const;\n\n    constructor(element: HTMLElement) {\n        if(element.getAttribute('freezed')){\n            throw new Error(\"This element cannot be accessed by SafeELement\")\n        }\n        this.#element = element;\n    }\n\n    public appendChild(child: SafeElement) {\n        this.#element.appendChild(child.#element);\n    }\n\n    public removeChild(child: SafeElement) {\n        this.#element.removeChild(child.#element);\n    }\n\n    public replaceChild(newChild: SafeElement, oldChild: SafeElement) {\n        this.#element.replaceChild(newChild.#element, oldChild.#element);\n    }\n\n    public replaceWith(newElement: SafeElement) {\n        this.#element.replaceWith(newElement.#element);\n    }\n\n    public cloneNode(deep: boolean = false): SafeElement {\n        const cloned = this.#element.cloneNode(deep);\n        return new SafeElement(cloned as HTMLElement);\n    }\n\n    public prepend(child: SafeElement) {\n        this.#element.prepend(child.#element);\n    }\n\n    public remove() {\n        this.#element.remove();\n    }\n\n    public innerText(): string {\n        return this.#element.innerText;\n    }\n\n    public textContent(): string | null {\n        return this.#element.textContent;\n    }\n\n    public setTextContent(value: string) {\n        this.#element.textContent = value;\n    }\n\n    public setInnerText(value: string) {\n        this.#element.innerText = value;\n    }\n\n\n    public setAttribute(name: string, value: string) {\n        if(!name.startsWith('x-')){\n            throw new Error(\"Can only set attributes starting with 'x-' for security reasons. for other attributes, use dedicated methods.\");\n        }\n        this.#element.setAttribute(name, value);\n    }\n    public getAttribute(name: string): string | null {\n        if(!name.startsWith('x-')){\n            throw new Error(\"Can only get attributes starting with 'x-' for security reasons. for other attributes, use dedicated methods.\");\n        }\n        return this.#element.getAttribute(name);\n    }\n    public setStyle(property: string, value: string) {\n        (this.#element.style as any)[property] = value;\n    }\n    public getStyle(property: string): string {\n        return (this.#element.style as any)[property];\n    }\n    public getStyleAttribute(): string {\n        return this.#element.getAttribute('style') || '';\n    }\n    public setStyleAttribute(value: string) {\n        this.#element.setAttribute('style', value);\n    }\n    public addClass(className: string) {\n        // \n        this.#element.classList.add(className);\n    }\n    public removeClass(className: string) {\n        // \n        this.#element.classList.remove(className);\n    }\n    public setClassName(className: string){\n        this.#element.className = className\n    }\n    public getClassName(){\n        return this.#element.className\n    }\n    public hasClass(className: string): boolean {\n        //We don't need to check the className here since we're just checking\n        return this.#element.classList.contains(className);\n    }\n    public focus() {\n        this.#element.focus();\n    }\n    public getChildren(): SafeClassArray<SafeElement> {\n        const children: SafeElement[] = [];\n        this.#element.childNodes.forEach(node => {\n            if(node instanceof HTMLElement) {\n                children.push(new SafeElement(node));\n            }\n        });\n        return new SafeClassArray<SafeElement>(children);\n    }\n    public getParent(): SafeElement | null {\n        if(this.#element.parentElement) {\n            return new SafeElement(this.#element.parentElement);\n        }\n        return null;\n    }\n    public getInnerHTML(): string {\n        return this.#element.innerHTML;\n    }\n    public getOuterHTML(): string {\n        return this.#element.outerHTML;\n    }\n    public clientHeight(): number {\n        return this.#element.clientHeight;\n    }\n    public clientWidth(): number {\n        return this.#element.clientWidth;\n    }\n    public clientTop(): number {\n        return this.#element.clientTop;\n    }\n    public clientLeft(): number {\n        return this.#element.clientLeft;\n    }\n    public nodeName(): string {\n        return this.#element.nodeName;\n    }\n    public nodeType(): number {\n        return this.#element.nodeType;\n    }\n    public querySelectorAll(selector: string): SafeClassArray<SafeElement> {\n        const nodeList = this.#element.querySelectorAll(selector);\n        const elements: SafeElement[] = [];\n        nodeList.forEach(node => {\n            if(node instanceof HTMLElement) {\n                elements.push(new SafeElement(node));\n            }\n        });\n        return new SafeClassArray<SafeElement>(elements);\n    }\n    public querySelector(selector: string): SafeElement | null {\n        const element = this.#element.querySelector(selector);\n        if(element instanceof HTMLElement) {\n            return new SafeElement(element);\n        }\n        return null;\n    }\n    public getElementById(id: string): SafeElement | null {\n        const element = this.querySelector('#' + id);\n        return element;\n    }\n    public getElementsByClassName(className: string): SafeClassArray<SafeElement> {\n        return this.querySelectorAll('.' + className);\n    }\n    public getClientRects(): DOMRectList {\n        return this.#element.getClientRects();\n    }\n    public getBoundingClientRect(): DOMRect {\n        return this.#element.getBoundingClientRect();\n    }\n    public setInnerHTML(value: string) {\n        const san = DOMPurify.sanitize(value);\n        this.#element.innerHTML = san;\n    }\n    public setOuterHTML(value: string) {\n        const san = DOMPurify.sanitize(value);\n        this.#element.outerHTML = san;\n    }\n    public scrollIntoView(options?: boolean | ScrollIntoViewOptions) {\n        this.#element.scrollIntoView(options);\n    }\n    #eventIdMap = new Map<string, Function>()\n\n    public async addEventListener(type:string, listener: (event: any) => void, options?: boolean | AddEventListenerOptions):Promise<string> {\n        const realOptions = typeof options === 'boolean' ? { capture: options } : options || {};\n\n        //allowed with unlimited\n        const allowedDocumentEventListeners = [\n            'click',\n            'dblclick',\n            'contextmenu',\n            'mousedown',\n            'mouseup',\n            'mousemove',\n            'mouseover',\n            'mouseleave',\n            'pointercancel',\n            'pointerdown',\n            'pointerenter',\n            'pointerleave',\n            'pointermove',\n            'pointerout',\n            'pointerover',\n            'pointerup',\n            'scroll',\n            'scrollend'\n        ]\n\n        //allowed, but it has fingerprinting issues,\n        //so it will be delayed random ms.\n        const allowedDelayedEventListeners = [\n            'keydown',\n            'keyup',\n            'keypress'\n        ]\n\n        const id = v4()\n\n        const trimEvent = (event: MouseEvent | KeyboardEvent | Event) => {\n            if(event instanceof MouseEvent){\n                return {\n                    type: event.type,\n                    clientX: event.clientX,\n                    clientY: event.clientY,\n                    button: event.button,\n                    buttons: event.buttons,\n                    altKey: event.altKey,\n                    ctrlKey: event.ctrlKey,\n                    shiftKey: event.shiftKey,\n                    metaKey: event.metaKey,\n                }\n            }\n            else if(event instanceof KeyboardEvent){\n                return {\n                    type: event.type,\n                    key: event.key,\n                    code: event.code,\n                    repeat: event.repeat,\n                    altKey: event.altKey,\n                    ctrlKey: event.ctrlKey,\n                    shiftKey: event.shiftKey,\n                    metaKey: event.metaKey,\n                }\n            }\n            else{\n                return {\n                    type: event.type\n                }\n            }\n\n        }\n\n        if(allowedDocumentEventListeners.includes(type)){\n            const modifiedListener = (event: any) => {\n                listener(trimEvent(event))\n            }\n            this.#eventIdMap.set(id, modifiedListener)\n            documentEventListeners.push({type, listener: modifiedListener as EventListenerOrEventListenerObject, options: realOptions})\n            document.addEventListener(type, modifiedListener, realOptions)\n            return id;\n        }\n        else if(allowedDelayedEventListeners.includes(type)){\n            const modifiedListener = (event: any) => {\n                let delay = 0;\n                try {\n                    delay = (crypto.getRandomValues(new Uint32Array(1))[0] / 100) % 100; //0-99 ms              \n                } catch (error) {}\n                setTimeout(() => {\n                    listener(trimEvent(event));\n                }, delay);\n            }\n            this.#eventIdMap.set(id, modifiedListener)\n            documentEventListeners.push({type, listener: modifiedListener as EventListenerOrEventListenerObject, options: realOptions})\n            document.addEventListener(type, modifiedListener, realOptions);\n            return id;\n        }\n        else{\n            throw new Error(`Event listener of type '${type}' is not allowed for security reasons.`);\n        }        \n    }\n\n    public removeEventListener(type:string, id:string, options?: boolean | EventListenerOptions) {\n        const listener = this.#eventIdMap.get(id);\n        if(listener){\n            const realOptions = typeof options === 'boolean' ? { capture: options } : options || {};\n            document.removeEventListener(type, listener as EventListenerOrEventListenerObject, realOptions);\n            const idx = documentEventListeners.findIndex(e => e.listener === listener);\n            if(idx !== -1) documentEventListeners.splice(idx, 1);\n            this.#eventIdMap.delete(id);\n        }\n    }\n\n    public matches (selector: string): boolean {\n        return this.#element.matches(selector);\n    }\n}\n\nclass SafeDocument extends SafeElement {\n    __classType = 'REMOTE_REQUIRED' as const;\n    constructor(document: Document) {\n        super(document.documentElement);\n    }\n    createElement(tagName: string): SafeElement {\n        if(!tagWhitelist.includes(tagName.toLowerCase())) {\n            console.warn(`Creation of <${tagName}> elements is restricted. Creating a <div> instead.`);\n            tagName = 'div';\n        }\n        if(tagName.toLowerCase() === 'a'){\n            console.warn(`<a> can be created but href attribute cannot be set directly for security reasons. Use .createAnchorElement(href: string) to create safe anchor elements.`);\n        }\n        const element = document.createElement(tagName);\n        return new SafeElement(element);\n    }\n    createAnchorElement(href: string): SafeElement {\n        const anchor = document.createElement('a');\n        try {\n            const url = new URL(href);\n            if(url.protocol !== 'http:' && url.protocol !== 'https:'){\n                throw new Error(\"Invalid protocol\");\n            }\n            anchor.setAttribute('href', url.toString());\n        } catch (error) {\n            console.warn(`Invalid URL provided for anchor element: ${href}. Setting href to '#' instead.`);\n            anchor.setAttribute('href', '#');\n        }\n        return new SafeElement(anchor);\n    }\n}\n\ntype SafeMutationRecordObject = {\n    type: string;\n    target: SafeElement;\n    addedNodes: SafeElement[];\n}\n\nclass SafeClassArray<T> {\n    #items: T[];\n    __classType = 'REMOTE_REQUIRED' as const;\n    constructor(items: T[] = []) {\n        this.#items = items;\n    }\n    at(index: number): T {\n        return this.#items.at(index);\n    }\n    length(): number {\n        return this.#items.length;\n    }\n    push(item: T) {\n        this.#items.push(item);\n    }\n}\n\nclass SafeMutationRecord{\n    __classType = 'REMOTE_REQUIRED' as const;\n    #type: string;\n    #target: SafeElement;\n    #addedNodes: SafeClassArray<SafeElement>;\n    constructor(type: string, target: SafeElement, addedNodes: SafeElement[]) {\n        this.#type = type;\n        this.#target = target;\n        this.#addedNodes = new SafeClassArray<SafeElement>(addedNodes);\n    }\n    getType(): string {\n        return this.#type;\n    }\n    getTarget(): SafeElement {\n        return this.#target;\n    }\n    getAddedNodes(): SafeClassArray<SafeElement> {\n        return this.#addedNodes;\n    }\n}\n\ntype SafeMutationCallback = (mutations: SafeClassArray<SafeMutationRecord>) => void;\n\nclass SafeMutationObserver {\n    #observer: MutationObserver;\n    __classType = 'REMOTE_REQUIRED' as const;\n    constructor(callback: SafeMutationCallback) {\n        this.#observer = new MutationObserver((mutations) => {\n            const safeMutations: SafeMutationRecordObject[] = mutations.map(mutation => {\n\n                const elementMapHelper = (nodeList: NodeList): SafeElement[] => {\n                    const elements: SafeElement[] = [];\n                    nodeList.forEach(node => {\n                        if(node instanceof HTMLElement) {\n                            elements.push(new SafeElement(node));\n                        }\n                    })\n                    return elements;\n                }\n\n                return {\n                    type: mutation.type,\n                    target: new SafeElement(mutation.target as HTMLElement),\n                    addedNodes: elementMapHelper(mutation.addedNodes),\n                    removedNodes: elementMapHelper(mutation.removedNodes)\n                    \n                }\n            })\n\n            const safeClassed = new SafeClassArray<SafeMutationRecord>([]);\n            for(const record of safeMutations){\n                safeClassed.push(new SafeMutationRecord(\n                    record.type,\n                    record.target,\n                    record.addedNodes\n                ));\n            }\n            callback(safeClassed);\n        });\n    }\n\n    observe(element:SafeElement, options: MutationObserverInit) {\n        const identifier = v4();\n        element.setAttribute('x-identifier', identifier);\n        const rawElement = document.querySelector(`[x-identifier=\"${identifier}\"]`) as HTMLElement;\n        if(rawElement){\n            this.#observer.observe(rawElement, options);\n            element.setAttribute('x-identifier', '');\n        }\n    }\n\n    disconnect() {\n        this.#observer.disconnect();\n    }\n\n}\n\nconst pluginUnloadCallbacks: Map<string, Function[]> = new Map();\n\nconst addPluginUnloadCallback = (pluginName: string, callback: Function) => {\n    if(!pluginUnloadCallbacks.has(pluginName)){\n        pluginUnloadCallbacks.set(pluginName, []);\n    }\n    pluginUnloadCallbacks.get(pluginName)?.push(callback);\n}\n\nconst makeMenuUnloadCallback = (menuId:string, menuStore: MenuDef[]) =>{\n    return () => {\n        const index = menuStore.findIndex(item => item.id === menuId);\n        if(index !== -1){\n            menuStore.splice(index, 1);\n        }\n    }\n}\n\nconst removeChatPanel = (id: string) => {\n    const index = chatPanelStore.findIndex(item => item.id === id);\n    if(index !== -1){\n        chatPanelStore.splice(index, 1);\n    }\n}\n\nconst removePluginChatPanels = (pluginName: string) => {\n    for(let i = chatPanelStore.length - 1; i >= 0; i--){\n        if(chatPanelStore[i].pluginName === pluginName){\n            chatPanelStore.splice(i, 1);\n        }\n    }\n}\n\nconst unloadV3Plugin = async (pluginName: string) => {\n    const callbacks = pluginUnloadCallbacks.get(pluginName);\n    const instance = v3PluginInstances.find(p => p.name === pluginName);\n    if(instance){\n        const index = v3PluginInstances.findIndex(p => p.name === pluginName);\n        if(index !== -1){\n            v3PluginInstances.splice(index, 1);\n        }\n    }\n    if(callbacks){\n        pluginUnloadCallbacks.delete(pluginName); \n        let promises: Promise<void>[] = [];\n        for(const callback of callbacks){\n            const result = callback();\n            if(result instanceof Promise){\n                promises.push(result);\n            }\n        }\n\n        await Promise.any([\n            Promise.all(promises),\n            sleep(1000) //timeout after 1 second\n        ])\n    }\n    try {\n        instance?.host?.terminate();        \n    } catch (error) {\n        console.error(`Error terminating plugin ${pluginName}:`, error);\n    }\n}\n\ntype PluginPermissionDesc = 'fetchLogs'|'db'|'mainDom'|'replacer'|'provider'|'sendChat';\nconst pluginPermissionDescs: PluginPermissionDesc[] = ['fetchLogs', 'db', 'mainDom', 'replacer', 'provider', 'sendChat'];\n\n// Plugin names are free text (the //@name directive), so `${name}_${desc}` keys\n// can collide — both across permissions and with a legacy name-only entry that\n// happens to read like \"name_desc\". JSON-encoding the pair makes every key\n// unambiguous: [\"foo\",\"db\"] can never equal a plain \"foo_db\" or [\"foo_db\",\"x\"].\nconst permissionKeyOf = (pluginName: string, permissionDesc: string) =>\n    JSON.stringify([pluginName, permissionDesc])\n\nconst permissionGivenPlugins: Set<string> = new Set();\nconst permissionDeniedPlugins: Set<string> = new Set();\nconst permissionCache = new Map<string, boolean | number>();\nconst pluginPermissionStateKey = 'cache/plugin-permissions/state.json';\nlet pluginPermissionLoadPromise: Promise<void> | null = null;\n\nasync function ensurePluginPermissionStateLoaded() {\n    if (!pluginPermissionLoadPromise) {\n        pluginPermissionLoadPromise = (async () => {\n            const payload = await readPersistentJson<{\n                given: string[]\n                denied: string[]\n                cache: [string, boolean | number][]\n            }>(pluginPermissionStateKey)\n            if (!payload) {\n                return\n            }\n            permissionGivenPlugins.clear()\n            permissionDeniedPlugins.clear()\n            permissionCache.clear()\n            for (const pluginName of payload.given ?? []) {\n                permissionGivenPlugins.add(pluginName)\n            }\n            for (const pluginName of payload.denied ?? []) {\n                permissionDeniedPlugins.add(pluginName)\n            }\n            for (const [key, value] of payload.cache ?? []) {\n                permissionCache.set(key, value)\n            }\n        })()\n    }\n    await pluginPermissionLoadPromise\n}\n\nexport async function resetAllPluginPermissions() {\n    permissionGivenPlugins.clear()\n    permissionDeniedPlugins.clear()\n    permissionCache.clear()\n    pluginPermissionLoadPromise = Promise.resolve()\n    await removePersistentKey(pluginPermissionStateKey)\n}\n\nexport async function resetPluginPermission(pluginName: string) {\n    await ensurePluginPermissionStateLoaded()\n    // Permission descs are a fixed enum, so we delete the exact key for each\n    // one rather than prefix-matching (which would also wipe another plugin's\n    // keys). `pluginName` alone covers legacy name-only entries from older\n    // versions, which JSON keys never collide with but reset should still clear.\n    const exactKeys = pluginPermissionDescs.map(desc => permissionKeyOf(pluginName, desc))\n    for (const key of [pluginName, ...exactKeys]) {\n        permissionGivenPlugins.delete(key)\n        permissionDeniedPlugins.delete(key)\n    }\n    for (const desc of pluginPermissionDescs) {\n        permissionCache.delete(permissionKeyOf(pluginName, desc) + '_lastGrantTime')\n    }\n    const plugin = DBState.db.plugins?.find(p => p.name === pluginName)\n    if (plugin?.script) {\n        const scriptHashBase = await hasher(new TextEncoder().encode(plugin.script))\n        for (const key of [...permissionCache.keys()]) {\n            if (key.startsWith(scriptHashBase + '_')) {\n                permissionCache.delete(key)\n            }\n        }\n    }\n    await persistPluginPermissionState()\n}\n\nasync function persistPluginPermissionState() {\n    await writePersistentJson(pluginPermissionStateKey, {\n        given: [...permissionGivenPlugins],\n        denied: [...permissionDeniedPlugins],\n        cache: [...permissionCache.entries()]\n    })\n}\n\ntype PluginV3ProviderOptions = PluginV2ProviderOptions & {\n    model?: LLMModel\n}\n\nexport const customV3ProviderMetaStore:LLMModel[] = []\n\n// Serializes permission dialogs. Every plugin shares the single global\n// alertStore, so when several plugins request permission at boot they would\n// otherwise overwrite each other's dialog — only the last one stays clickable\n// and a single click resolves all of them. The chain makes each dialog wait\n// for the previous one to finish, showing them one at a time.\nlet pluginPermissionDialogChain: Promise<unknown> = Promise.resolve()\n\nconst isPermissionResolved = async (\n    pluginName: string,\n    permissionDesc: PluginPermissionDesc,\n    requiresReconfirm: boolean,\n): Promise<{ resolved: boolean; value: boolean; pluginHash: string }> => {\n    const permissionKey = permissionKeyOf(pluginName, permissionDesc);\n    if (!requiresReconfirm && permissionGivenPlugins.has(permissionKey)) {\n        return { resolved: true, value: true, pluginHash: '' }\n    }\n    if (!requiresReconfirm && permissionDeniedPlugins.has(permissionKey)) {\n        return { resolved: true, value: false, pluginHash: '' }\n    }\n\n    const pluginHash = await hasher(\n        new TextEncoder().encode(\n            DBState.db.plugins.find(p => p.name === pluginName)?.script\n        )\n    ) + `_${permissionDesc}`;\n\n    if (!requiresReconfirm && permissionCache.get(pluginHash)) {\n        permissionGivenPlugins.add(permissionKey);\n        return { resolved: true, value: true, pluginHash }\n    }\n\n    return { resolved: false, value: false, pluginHash }\n}\n\nconst getPluginPermission = async (pluginName: string, permissionDesc: PluginPermissionDesc, reconfirm: boolean|'periodically' = false) => {\n    await ensurePluginPermissionStateLoaded()\n\n    // Recomputed (not captured) so a periodic reconfirm reflects the latest\n    // lastGrantTime: when several identical requests queue together, an earlier\n    // one may refresh it, making the reconfirm no longer due for the rest.\n    const computeRequiresReconfirm = () => {\n        if(reconfirm === 'periodically'){\n            const lastGrantTime = permissionCache.get(permissionKeyOf(pluginName, permissionDesc) + '_lastGrantTime') as number | undefined;\n            return !lastGrantTime || Date.now() - lastGrantTime > 3 * 24 * 60 * 60 * 1000; //3 days\n        }\n        return reconfirm === true;\n    }\n\n    // Fast path: if the answer is already known, skip the serialization queue\n    // entirely so cached/granted permissions never block on a pending dialog.\n    const early = await isPermissionResolved(pluginName, permissionDesc, computeRequiresReconfirm())\n    if (early.resolved) {\n        return early.value\n    }\n\n    const showDialog = async (): Promise<boolean> => {\n        // Re-check under the lock: an earlier queued dialog for the same plugin\n        // may have already granted/denied (or refreshed a periodic grant) while\n        // we were waiting our turn — recompute reconfirm so we don't re-prompt.\n        const requiresReconfirm = computeRequiresReconfirm()\n        const recheck = await isPermissionResolved(pluginName, permissionDesc, requiresReconfirm)\n        if (recheck.resolved) {\n            return recheck.value\n        }\n        const pluginHash = recheck.pluginHash\n\n        let alertTitle =\n            permissionDesc === 'fetchLogs' ? language.fetchLogConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'db' ? language.getFullDatabaseConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'mainDom' ? language.mainDomAccessConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'replacer' ? language.replacerPermissionConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'provider' ? language.providerPermissionConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'sendChat' ? language.sendChatConsent.replace(\"{}\", pluginName)\n            : `Error`\n        if(alertTitle === 'Error'){\n            return false;\n        }\n        const permissionKey = permissionKeyOf(pluginName, permissionDesc);\n        const conf = await alertConfirm(alertTitle)\n        if(conf && pluginHash){\n            permissionGivenPlugins.add(permissionKey);\n            permissionDeniedPlugins.delete(permissionKey);\n            permissionCache.set(pluginHash, true);\n            if(reconfirm === 'periodically'){\n                permissionCache.set(permissionKeyOf(pluginName, permissionDesc) + '_lastGrantTime', Date.now());\n            }\n            await persistPluginPermissionState()\n            return true;\n        }\n        permissionDeniedPlugins.add(permissionKey);\n        await persistPluginPermissionState()\n        return false;\n    }\n\n    // Append to the dialog chain so only one permission dialog is shown at a\n    // time. finally restores the chain even if showDialog throws, so a single\n    // failure never deadlocks every later permission request.\n    const run = pluginPermissionDialogChain\n        .catch(() => {})\n        .then(() => showDialog())\n    pluginPermissionDialogChain = run.catch(() => {})\n    return run\n}\n\nconst urlBlacklist = [\n    'risuai.xyz',\n    'risuai.net',\n    'sionyw.com',\n]\n\nconst authorizationHeaders = [\n    'x-api-key',\n    'authorization',\n    'proxy-authorization',\n]\n\nconst makeRisuaiAPIV3 = (iframe:HTMLIFrameElement,plugin:RisuPlugin) => {\n\n    const oldApis = getV2PluginAPIs();\n    return {\n\n        //Old APIs from v2.1\n        risuFetch: (url, options) => {\n            console.error(`[DEPRECATION WARNING] risuFetch is deprecated and will be removed in future versions. Please use nativeFetch instead.`)\n            for(const blocked of urlBlacklist){\n                if(url.toLowerCase().includes(blocked)){\n                    throw new Error(`Requests to ${blocked} are blocked for security reasons.`);\n                }\n            }\n\n            //scan headers\n            const headers = options?.headers || {};\n            for(const headerName in headers){\n                if(authorizationHeaders.includes(headerName.toLowerCase())){\n                    console.warn(`Request contains potentially sensitive header '${headerName}'. handling of such headers may be changed to only work with nativeFetch.`);\n                }\n            }\n            return oldApis.risuFetch(url, options);\n        },\n        nativeFetch: (url, options) => {\n            for(const blocked of urlBlacklist){\n                if(url.toLowerCase().includes(blocked)){\n                    throw new Error(`Requests to ${blocked} are blocked for security reasons.`);\n                }\n            }\n\n            //scan headers\n            const headers = options?.headers || {};\n            for(const headerName in headers){\n                if(authorizationHeaders.includes(headerName.toLowerCase())){\n                    console.warn(`Request contains potentially sensitive header '${headerName}'. handling of such headers may be changed to use server-side approch with write-only api access in the future for better security.`);\n                }\n            }\n            return oldApis.nativeFetch(url, options);\n        },\n        getChar: oldApis.getChar,\n        setChar: oldApis.setChar,\n        addProvider: (name: string, func: (arg: PluginV2ProviderArgument, abortSignal?: AbortSignal) => Promise<{ success: boolean, content: string | ReadableStream<string> }>, options?: PluginV3ProviderOptions) => {\n            console.warn(`[WARN] addProvider is a powerful API that can potentially be unsafe if used incorrectly. addProvider's functionality might be limited or changed in future updates to ensure security. please use other APIs if possible.`);\n            let provs = get(customProviderStore)\n            provs.push(name)\n            pluginV2.providers.set(name, async (arg, abortSignal) => {\n               await getPluginPermission(plugin.name, 'provider', 'periodically');\n               //mode is overridden to v3, due to vulnerabilities using mode.\n               //Alternative to mode will be added in future\n               arg.mode = 'v3'\n               return await func(arg, abortSignal);\n            }),\n            pluginV2.providerOptions.set(name, options ?? {})\n            customProviderStore.set(provs)\n\n            const modelData:LLMModel = {\n                id: `pluginmodel:::${name}`,\n                name: options?.model?.name ?? name,\n                shortName: options?.model?.shortName ?? name,\n                fullName: options?.model?.fullName ?? name,\n                internalID: options?.model?.internalID ?? `pluginmodel:::${name}`,\n                provider: LLMProvider.AsIs,\n                format: LLMFormat.Plugin,\n                flags: options?.model?.flags ?? [LLMFlags.hasFullSystemPrompt],\n                parameters: options?.model?.parameters ?? ['temperature', 'top_p', 'frequency_penalty', 'presence_penalty', 'repetition_penalty', 'min_p', 'top_a', 'top_k', 'thinking_tokens'],\n                tokenizer:options?.model?.tokenizer ??  LLMTokenizer.Unknown\n            }\n            customV3ProviderMetaStore.push(modelData);\n        },\n        addTTSPreprocessor: async (\n            func: TTSHookFn<BeforeTTSContext, BeforeTTSResult>,\n        ) => {\n            registerTTSPreprocessor(func);\n            addPluginUnloadCallback(plugin.name, () => unregisterTTSPreprocessor(func));\n        },\n        addTTSPostprocessor: async (\n            func: TTSHookFn<AfterTTSContext, AfterTTSResult>,\n        ) => {\n            registerTTSPostprocessor(func);\n            addPluginUnloadCallback(plugin.name, () => unregisterTTSPostprocessor(func));\n        },\n        addRisuScriptHandler: oldApis.addRisuScriptHandler,\n        removeRisuScriptHandler: oldApis.removeRisuScriptHandler,\n        addRisuReplacer: async (name:string,func:Function) => {\n            //permission check for replacer\n            const conf = await getPluginPermission(plugin.name, 'replacer', 'periodically');\n            if(!conf){\n                return;\n            }\n            oldApis.addRisuReplacer(name, func as any);\n        },\n        removeRisuReplacer: oldApis.removeRisuReplacer,\n        setDatabaseLite: oldApis.setDatabaseLite,\n        setDatabase: oldApis.setDatabase,\n        loadPlugins: oldApis.loadPlugins,\n        readImage: oldApis.readImage,\n        readInlay: async (id: string) => {\n            return await getInlayAsset(id);\n        },\n        saveAsset: oldApis.saveAsset,\n        //Same functionality, but new implementation\n        getDatabase: async (includeOnly:string[]|'all' = 'all') => {\n            const conf = await getPluginPermission(plugin.name, 'db', 'periodically');\n            if(!conf){\n                return null;\n            }\n            const db = DBState.db\n            let liteDB = {}\n            for(const key of allowedDbKeys){\n                if(includeOnly !== 'all' && !includeOnly.includes(key)){\n                    continue;\n                }\n                (liteDB as any)[key] = $state.snapshot((db as any)[key]);\n            }\n            return liteDB;\n        },\n\n        installPlugin: handlePluginInstallViaPlugin,\n\n        // --- Color Scheme APIs ---\n        changeColorScheme: (name: string) => {\n            changeColorScheme(name)\n        },\n        setColorScheme: (scheme: ColorScheme) => {\n            const requiredKeys = ['bgcolor','darkbg','borderc','selected','draculared','textcolor','textcolor2','darkBorderc','darkbutton','type'] as const\n            for (const key of requiredKeys) {\n                if (typeof (scheme as any)[key] !== 'string') {\n                    throw new Error(`Invalid color scheme: missing or invalid '${key}'`)\n                }\n            }\n            if (scheme.type !== 'light' && scheme.type !== 'dark') {\n                throw new Error('Invalid color scheme type: must be \"light\" or \"dark\"')\n            }\n            const db = DBState.db\n            db.colorSchemeName = 'custom'\n            db.colorScheme = scheme\n            updateColorScheme()\n        },\n        getColorScheme: () => {\n            const db = DBState.db\n            return {\n                name: db.colorSchemeName,\n                scheme: $state.snapshot(db.colorScheme)\n            }\n        },\n\n        // --- Text Theme APIs ---\n        changeTextTheme: (name: string) => {\n            if (!['standard','highcontrast'].includes(name)) {\n                throw new Error(`Invalid text theme: ${name}`)\n            }\n            const db = DBState.db\n            db.textTheme = name\n            updateTextThemeAndCSS()\n        },\n        setCustomTextTheme: (theme: {\n            FontColorStandard: string,\n            FontColorBold: string,\n            FontColorItalic: string,\n            FontColorItalicBold: string,\n            FontColorQuote1: string,\n            FontColorQuote2: string\n        }) => {\n            const requiredKeys = ['FontColorStandard','FontColorBold','FontColorItalic','FontColorItalicBold','FontColorQuote1','FontColorQuote2'] as const\n            for (const key of requiredKeys) {\n                if (typeof (theme as any)[key] !== 'string') {\n                    throw new Error(`Invalid text theme: missing or invalid '${key}'`)\n                }\n            }\n            const db = DBState.db\n            db.textTheme = 'custom'\n            db.customTextTheme = theme\n            updateTextThemeAndCSS()\n        },\n        getTextTheme: () => {\n            const db = DBState.db\n            return {\n                name: db.textTheme,\n                customTheme: $state.snapshot(db.customTextTheme)\n            }\n        },\n\n        //Deprecated APIs from v2.1\n        //Use getArgument / setArgument instead if possible\n        getArg: oldApis.getArg,\n        setArg: oldApis.setArg,\n\n        //New APIs for v3\n        getArgument: async (key:string) => {\n            const db = getDatabase()\n            for (const p of db.plugins) {\n                if (p.name === plugin.name) {\n                    return p.realArg[key];\n                }\n            }\n        },\n        setArgument: async (key:string, value:string) => {\n            const db = getDatabase();\n            for (const p of db.plugins) {\n                if (p.name === plugin.name) {\n                    p.realArg[key] = value;\n                }\n            }\n        },\n        getCharacterFromIndex: (index:number) => {\n            const db = DBState.db\n            const charIds = Object.keys(db.characters);\n            const charId = charIds[index];\n            if(charId){\n                return $state.snapshot(db.characters[charId]);\n            }\n            return null;\n        },\n        setCharacterToIndex: (index:number, char:any) => {\n            const db = DBState.db\n            const charIds = Object.keys(db.characters);\n            const charId = charIds[index];\n            if(charId){\n                DBState.db.characters[charId] = char\n            }\n        },\n        getChatFromIndex: (characterIndex:number, chatIndex:number) => {\n            const db = DBState.db\n            const charIds = Object.keys(db.characters);\n            const charId = charIds[characterIndex];\n            if(charId){\n                const chats = db.characters[charId].chats;\n                if(chats && chats[chatIndex]){\n                    return $state.snapshot(chats[chatIndex]);\n                }\n            }\n            return null;\n        },\n        setChatToIndex: (characterIndex:number, chatIndex:number, chat:any) => {\n            const db = DBState.db\n            const charIds = Object.keys(db.characters);\n            const charId = charIds[characterIndex];\n            if(charId){\n                const chats = db.characters[charId].chats;\n                if(chats && chats[chatIndex]){\n                    DBState.db.characters[charId].chats[chatIndex] = normalizeChat(chat)\n                }\n            }\n        },\n        getCurrentCharacterIndex: () => {\n            return get(selectedCharID)\n        },\n        getCurrentChatIndex: () => {\n            const db = DBState.db\n            const charId = get(selectedCharID)\n            return db.characters[charId].chatPage\n        },\n        getCurrentLorebookEntries: () => {\n            const charId = get(selectedCharID)\n            const char = DBState.db.characters[charId]\n            if(!char){\n                return []\n            }\n            const page = char.chatPage\n            const characterLore = char.globalLore ?? []\n            const chatLore = char.chats?.[page]?.localLore ?? []\n            const moduleLore = getModuleLorebooks()\n            return $state.snapshot(characterLore.concat(chatLore).concat(moduleLore))\n        },\n        //New names for character APIs, to match API naming conventions\n        getCharacter: oldApis.getChar,\n        setCharacter: oldApis.setChar,\n\n        showContainer: (\n            //more types may be added in future\n            type: 'fullscreen' = 'fullscreen'\n        ) => {\n            iframe.style.display = \"block\";\n            \n            switch(type) {\n                case 'fullscreen': {\n                    //move iframe to body if not already there\n                    if(iframe.parentElement !== document.body) {\n                        document.body.appendChild(iframe);\n                    }\n\n                    //Make iframe cover whole screen\n                    iframe.style.position = \"fixed\";\n                    iframe.style.top = \"0\";\n                    iframe.style.left = \"0\";\n                    iframe.style.width = \"100%\";\n                    iframe.style.height = \"100%\";\n                    iframe.style.border = \"none\";\n                    iframe.style.zIndex = \"1000\";\n                    break;\n                }\n                default: {\n                    return\n                }\n            }\n        },\n        hideContainer: () => {\n            iframe.style.display = \"none\";\n        },\n        getRootDocument: async () => {\n            const conf = await getPluginPermission(plugin.name, 'mainDom');\n            if(!conf){\n                return null;\n            }\n            return new SafeDocument(document);\n        },\n        registerSetting: (\n            name:string,\n            callback: any,\n            icon:string = '',\n            iconType:'html'|'img'|'none' = 'none',\n            id?:string\n        ) => {\n            if(iconType !== 'html' && iconType !== 'img' && iconType !== 'none'){\n                throw new Error(\"iconType must be 'html', 'img' or 'none'\");\n            }\n            if(typeof name !== 'string' || name.trim() === ''){\n                throw new Error(\"name must be a non-empty string\");\n            }\n            const menuId = id || v4()\n            const menuDef:MenuDef = {\n                id: menuId,\n                name,\n                icon,\n                iconType,\n                callback\n            }\n            const existingIndex = additionalSettingsMenu.findIndex(item => item.id === menuId)\n            if(existingIndex !== -1){\n                additionalSettingsMenu[existingIndex] = menuDef\n                addPluginUnloadCallback(\n                    plugin.name,\n                    makeMenuUnloadCallback(menuId, additionalSettingsMenu)\n                )\n                return {id: menuId}\n            }\n            additionalSettingsMenu.push(menuDef)\n            addPluginUnloadCallback(\n                plugin.name,\n                makeMenuUnloadCallback(menuId, additionalSettingsMenu)\n            )\n            return {id: menuId};\n        },\n        registerBodyIntercepter: async (callback: (body: any, type: string) => any) => {\n\n            if(await getPluginPermission(plugin.name, 'replacer') === false){\n                return null;\n            }\n            \n            const id = v4();\n            bodyIntercepterStore.push({\n                id,\n                callback\n            })\n            addPluginUnloadCallback(plugin.name, () => {\n                const index = bodyIntercepterStore.findIndex(item => item.id === id);\n                if(index !== -1){\n                    bodyIntercepterStore.splice(index, 1);\n                }\n            })\n            return {id:id};\n        },\n        \n        unregisterBodyIntercepter: (id: string) => {\n            const index = bodyIntercepterStore.findIndex(item => item.id === id);\n            if(index !== -1){\n                bodyIntercepterStore.splice(index, 1);\n            }\n        },\n            \n        registerButton: (\n            arg: {\n                name: string,\n                icon: string,\n                iconType: 'html'|'img'|'none',\n                location?: 'action'|'chat'|'hamburger',\n                id?: string\n            },\n            callback: () => void\n        ) => {\n            let { name, icon, iconType, location, id: providedId } = arg;\n            location = location || 'action';\n            if(iconType !== 'html' && iconType !== 'img' && iconType !== 'none'){\n                throw new Error(\"iconType must be 'html', 'img' or 'none'\");\n            }\n            if(typeof name !== 'string' || name.trim() === ''){\n                throw new Error(\"name must be a non-empty string\");\n            }\n            if(typeof icon !== 'string'){\n                throw new Error(\"icon must be a string\");\n            }\n            const id = providedId || v4()\n            const menuDef:MenuDef = {\n                name,\n                icon,\n                iconType,\n                callback,\n                id\n            }\n\n            const buttonStores = [additionalFloatingActionButtons, additionalHamburgerMenu, additionalChatMenu]\n            for(const store of buttonStores){\n                const existingIndex = store.findIndex(item => item.id === id)\n                if(existingIndex !== -1){\n                    store[existingIndex] = menuDef\n                    addPluginUnloadCallback(\n                        plugin.name,\n                        makeMenuUnloadCallback(id, store)\n                    )\n                    return {id}\n                }\n            }\n\n            switch(location){\n                case 'action':{\n                    additionalFloatingActionButtons.push(menuDef)\n                    addPluginUnloadCallback(\n                        plugin.name,\n                        makeMenuUnloadCallback(menuDef.id, additionalFloatingActionButtons)\n                    )\n                    break\n                }\n                case 'hamburger':{\n                    additionalHamburgerMenu.push(menuDef)\n                    addPluginUnloadCallback(\n                        plugin.name,\n                        makeMenuUnloadCallback(menuDef.id, additionalHamburgerMenu)\n                    )\n                    break\n                }\n                case 'chat':{\n                    additionalChatMenu.push(menuDef)\n                    addPluginUnloadCallback(\n                        plugin.name,\n                        makeMenuUnloadCallback(menuDef.id, additionalChatMenu)\n                    )\n                    break\n                }\n                default:{\n                    throw new Error(\"Invalid location for button\")\n                }\n            }\n            return {id};\n        },\n        setChatPanel: (\n            content: string | null,\n            options: {\n                id?: string,\n                className?: string,\n            } = {}\n        ) => {\n            const id = options.id || `${plugin.name}:default`;\n\n            if(content === null || content === ''){\n                removeChatPanel(id);\n                return {id};\n            }\n\n            if(typeof content !== 'string'){\n                throw new Error(\"content must be a string or null\");\n            }\n\n            const panel = {\n                id,\n                pluginName: plugin.name,\n                html: DOMPurify.sanitize(content),\n                className: typeof options.className === 'string'\n                    ? DOMPurify.sanitize(options.className, {ALLOWED_TAGS: [], ALLOWED_ATTR: []})\n                    : undefined,\n            }\n\n            const existingIndex = chatPanelStore.findIndex(item => item.id === id);\n            if(existingIndex !== -1){\n                chatPanelStore[existingIndex] = panel;\n            }\n            else{\n                chatPanelStore.push(panel);\n            }\n            addPluginUnloadCallback(plugin.name, () => removePluginChatPanels(plugin.name));\n            return {id};\n        },\n        registerMCP: registerMCPModule,\n        unregisterMCP: unregisterMCPModule,\n        unregisterUIPart: (id: string) => {\n            const removeFromMenuStore = (menuStore: MenuDef[]) => {\n                const index = menuStore.findIndex(item => item.id === id);\n                if(index !== -1){\n                    menuStore.splice(index, 1);\n                }\n            }\n\n            removeFromMenuStore(additionalSettingsMenu);\n            removeFromMenuStore(additionalFloatingActionButtons);\n            removeFromMenuStore(additionalHamburgerMenu);\n            removeFromMenuStore(additionalChatMenu);\n            removeChatPanel(id);\n        },\n        log: (message:string) => {\n            console.log(`[RisuAI Plugin: ${plugin.name}] ${message}`);\n        },\n        createMutationObserver(callback: SafeMutationCallback): SafeMutationObserver {\n            const observer = new SafeMutationObserver(callback)\n            addPluginUnloadCallback(plugin.name, () => {\n                observer.disconnect()\n            })\n            return observer\n        },\n        onUnload: (callback: () => void) => {\n            addPluginUnloadCallback(plugin.name, callback);\n        },\n        getFetchLogs: async () => {\n            const conf = await getPluginPermission(plugin.name, 'fetchLogs');\n            if(!conf){\n                return null;\n            }\n            // Reads the server request log; the shape returned to plugins is\n            // unchanged from when this came from the in-memory fetch log.\n            const unsafeFetchLog = await getFetchLogs()\n            return unsafeFetchLog.map(log => {\n\n                const url = new URL(log.url);\n                return {\n                    url: url.origin + url.pathname,\n                    body: log.requestBody ?? '',\n                    status: log.status,\n                    response: log.responseBody,\n                    timestamp: log.timestamp,\n                }\n            })\n        },\n\n        alert: (msg:string) => {\n            return alertNormal(msg)\n        },\n        alertConfirm: (msg:string) => {\n            return alertConfirm(msg)\n        },\n        alertError: (msg:string) => {\n            return alertError(msg)\n        },\n        getRuntimeInfo: () => {\n            return {\n                apiVersion: \"3.0\",\n                platform: 'node',\n                saveMethod:\n                    forageStorage.isAccount ? 'account' :\n                    'local',\n            }\n        },\n        getLocalPluginStorage: () => {\n            return new SafeLocalPluginStorage(plugin.name)\n        },\n        checkCharOrder: checkCharOrder,\n        requestPluginPermission: (permission:string) => {\n            return getPluginPermission(plugin.name, permission as any);\n        },\n        //Internal use APIs\n        _getOldKeys: () => {\n            return Object.keys(oldApis)\n        },\n        _getPropertiesForInitialization: () => {\n            const v = {\n                apiVersion: \"3.0\",\n                apiVersionCompatibleWith: [\"3.0\"],\n            } as any;\n\n            v.list = Object.keys(v);\n            \n            return v;\n        },\n        _getPluginStorage: oldApis.pluginStorage.getItem,\n        // Wrapped (not aliased) so we can record the originating plugin into the\n        // sidecar meta map. The value write is unchanged; reads stay aliased.\n        _setPluginStorage: (key: string, value: any) => {\n            oldApis.pluginStorage.setItem(key, value)\n            recordOwner('save', key, plugin.name)\n        },\n        _removePluginStorage: (key: string) => {\n            oldApis.pluginStorage.removeItem(key)\n            removeOwner('save', key)\n        },\n        _clearPluginStorage: () => {\n            oldApis.pluginStorage.clear()\n            clearOwners('save')\n        },\n        _keyPluginStorage: oldApis.pluginStorage.key,\n        _keysPluginStorage: oldApis.pluginStorage.keys,\n        _lengthPluginStorage: oldApis.pluginStorage.length,\n        _getSafeLocalStorage: oldApis.safeLocalStorage.getItem,\n        _setSafeLocalStorage: (key: string, value: string) => {\n            oldApis.safeLocalStorage.setItem(key, value)\n            recordOwner('local', key, plugin.name)\n        },\n        _removeSafeLocalStorage: (key: string) => {\n            oldApis.safeLocalStorage.removeItem(key)\n            removeOwner('local', key)\n        },\n        _clearSafeLocalStorage: () => {\n            oldApis.safeLocalStorage.clear()\n            clearOwners('local')\n        },\n        _keySafeLocalStorage: oldApis.safeLocalStorage.key,\n        _keysSafeLocalStorage: oldApis.safeLocalStorage.keys,\n        searchTranslationCache: async (partialKey: string) => {\n            return searchLLMCache(partialKey)\n        },\n        getTranslationCache: async (key: string) => {\n            return getLLMCache(key)\n        },\n        _getAliases: () => {\n            return {\n                'pluginStorage':{\n                    'getItem': '_getPluginStorage',\n                    'setItem': '_setPluginStorage',\n                    'removeItem': '_removePluginStorage',\n                    'clear': '_clearPluginStorage',\n                    'key': '_keyPluginStorage',\n                    'keys': '_keysPluginStorage',\n                    'length': '_lengthPluginStorage',\n                },\n                'safeLocalStorage':{\n                    'getItem': '_getSafeLocalStorage',\n                    'setItem': '_setSafeLocalStorage',\n                    'removeItem': '_removeSafeLocalStorage',\n                    'clear': '_clearSafeLocalStorage',\n                    'key': '_keySafeLocalStorage',\n                    'keys': '_keysSafeLocalStorage',\n                }\n            }\n        },\n        runLLMModel: async (options: {\n            mode: ModelModeExtended\n            messages: OpenAIChat[]\n            staticModel?: string\n            allowPlugins?: boolean\n        }) => {\n            return requestChatDataMain({\n                formated: options.messages,\n                bias: {},\n                staticModel: options.staticModel,\n\n                // Calls into plugin-provided models are blocked by default to\n                // guard against accidental IPC loops between provider plugins.\n                // Plugin authors who need to reach the user's plugin-supplied\n                // main or auxiliary model (e.g. a TTS preprocessor that\n                // rewrites text with the configured otherAx model) can opt in\n                // explicitly with `allowPlugins: true`, accepting responsibility\n                // for avoiding provider-to-provider call loops.\n                blockPlugins: !options.allowPlugins,\n            }, options.mode)\n        },\n        sendChat: async (message: string) => {\n            const conf = await getPluginPermission(plugin.name, 'sendChat');\n            if(!conf){\n                return false;\n            }\n\n            if(typeof message !== 'string'){\n                throw new Error(\"Message must be a string\");\n            }\n\n            if(get(doingChat)){\n                throw new Error(\"A chat is already in progress\");\n            }\n\n            if(getModelInfo(DBState.db.aiModel).id.startsWith('pluginmodel:::')){\n                // Executing plugin provider is block because it can be used for loopholes for ipc right now.\n                throw new Error(\"Sending chat with plugin-based model is currently blocked\");\n            }\n\n            const charId = get(selectedCharID);\n            const char = DBState.db.characters[charId];\n            if(!char){\n                throw new Error(\"No character selected\");\n            }\n\n            const chat = char.chats[char.chatPage];\n            if(!chat){\n                throw new Error(\"No active chat found\");\n            }\n\n            if(message){\n                chat.message.push({\n                    role: 'user',\n                    data: message,\n                    time: Date.now(),\n                });\n            }\n\n            try {\n                await processSendChat(-1, {});\n            } finally {\n                // Plugin API path does not pass through the UI unlock logic,\n                // so release doingChat here on both success and failure.\n                endAllGenerations();\n            }\n\n            return true;\n        },\n        addPluginChannelListener: (channelName: string, callback: Function) => {\n            pluginChannel.set(plugin.name + channelName, callback);\n            addPluginUnloadCallback(plugin.name, () => {\n                pluginChannel.delete(plugin.name + channelName);\n            })\n        },\n        postPluginChannelMessage: (pluginName: string, channelName: string, message: any) => {\n\n            const currentPluginName = plugin.name;\n            const receiverPlugin = DBState.db.plugins.find(p => p.name === pluginName);\n\n            if(!receiverPlugin){\n                console.warn(`[RisuAI Plugin: ${currentPluginName}] Attempted to send message to non-existent plugin '${pluginName}' on channel '${channelName}'.`);\n                return;\n            }\n\n            if(!receiverPlugin.allowedIPC?.includes(currentPluginName)){\n                console.warn(`[RisuAI Plugin: ${currentPluginName}] Attempted to send message to plugin '${pluginName}' but receiver plugin does not allow IPC communication from this plugin. declare //@allowed-ipc ${currentPluginName} in the reciver plugin script to allow IPC communication.`);\n                return;\n            }\n\n            if(!plugin.allowedIPC?.includes(receiverPlugin.name)){\n                console.warn(`[RisuAI Plugin: ${currentPluginName}] Attempted to send message to plugin '${pluginName}' but the sender plugin does not allow IPC communication to this plugin. declare //@allowed-ipc ${receiverPlugin.name} in the sender plugin script to allow IPC communication.`);\n                return;\n            }\n\n\n            const callback = pluginChannel.get(pluginName + channelName);\n            if(callback){\n                callback(message, {\n                    sender: currentPluginName,\n                    channel: channelName\n                });\n            }\n        },\n        saveSecretHeader: async (key: string, value: string|string[]) => {\n            //TODO: Implement server-side secret storage with write-only access for plugins, to enhance security when handling sensitive information like API keys.\n            //This will have rate-limit, to prevent saving it publicly and writing as secret every time before using it.\n            console.warn(`[RisuAI Plugin: ${plugin.name}] saveServerSecret is not implemented yet. This API is intended for securely storing sensitive information like API keys with write-only access for plugins. Please avoid using this API until it is implemented.`);\n        }\n    }\n}\n\ntype V3PluginInstance = {\n    name: string;\n    host: SandboxHost;\n}\n\nconst v3PluginInstances: V3PluginInstance[] = [];\n\nexport async function loadV3Plugins(plugins:RisuPlugin[]){\n    await Promise.all(v3PluginInstances.map(async (instance) => {\n        await unloadV3Plugin(instance.name);\n    }));\n\n    for(const entry of documentEventListeners){\n        document.removeEventListener(entry.type, entry.listener, entry.options);\n    }\n    documentEventListeners.length = 0;\n\n    const loadPromises = plugins.map(plugin => executePluginV3(plugin));\n    await Promise.all(loadPromises);\n}\n\nexport async function executePluginV3(plugin:RisuPlugin){\n\n    const alreadyRunning = v3PluginInstances.find(p => p.name === plugin.name);\n    if(alreadyRunning){\n        console.log(`[RisuAI Plugin: ${plugin.name}] Plugin is already running. Skipping load.`);\n        return;\n    }\n\n    const iframe = document.createElement('iframe');\n    iframe.style.display = \"none\";\n    document.body.appendChild(iframe);\n    const host = new SandboxHost(makeRisuaiAPIV3(iframe, plugin));\n    v3PluginInstances.push({\n        name: plugin.name,\n        host\n    });\n    host.run(iframe, plugin.script);\n    console.log(`[RisuAI Plugin: ${plugin.name}] Loaded API V3 plugin.`);\n}\n\nexport function getV3PluginInstance(name: string) {\n    return v3PluginInstances.find(p => p.name === name);\n}\n\nglobalThis.__debugV3Plugin = (code: string|Function, pluginName: string = '') => {\n    if(code instanceof Function){\n        code = `(${code.toString()})()`;\n    }\n    if(pluginName === ''){\n        return v3PluginInstances[0].host.executeInIframe(code);\n    }\n    const instance = v3PluginInstances.find(p => p.name === pluginName);\n    if(!instance){\n        throw new Error(`Plugin ${pluginName} not found.`);\n    }\n    return instance.host.executeInIframe(code);\n};\n","managed":"import { allowedDbKeys, customProviderStore, getV2PluginAPIs, handlePluginInstallViaPlugin, pluginV2, type PluginV2ProviderArgument, type PluginV2ProviderOptions, type RisuPlugin } from \"../plugins.svelte\";\nimport { SandboxHost } from \"./factory\";\nimport { getDatabase, normalizeChat } from \"src/ts/storage/database.svelte\";\nimport { SafeLocalPluginStorage, tagWhitelist } from \"../pluginSafeClass\";\nimport { recordOwner, removeOwner, clearOwners } from \"../pluginStorageMeta\";\nimport DOMPurify from 'dompurify';\nimport { additionalChatMenu, additionalFloatingActionButtons, additionalHamburgerMenu, additionalSettingsMenu, bodyIntercepterStore, chatPanelStore, DBState, selectedCharID, type MenuDef } from \"src/ts/stores.svelte\";\nimport { v4 } from \"uuid\";\nimport { sleep } from \"src/ts/util\";\nimport { alertConfirm, alertError, alertNormal } from \"src/ts/alert\";\nimport { language } from \"src/lang\";\nimport { checkCharOrder, forageStorage, getFetchLogs, markCharacterDirty, markChatDirty } from \"src/ts/globalApi.svelte\";\nimport { changeColorScheme, updateColorScheme, updateTextThemeAndCSS, type ColorScheme } from \"src/ts/gui/colorscheme\";\nimport { get } from \"svelte/store\";\nimport { registerMCPModule, unregisterMCPModule } from \"src/ts/process/mcp/pluginmcp\";\nimport { getInlayAsset } from \"src/ts/process/files/inlays\";\nimport { getLLMCache, searchLLMCache } from \"src/ts/translator/translator\";\nimport { hasher } from \"src/ts/parser/parser.svelte\";\nimport { LLMFlags, LLMFormat, LLMProvider, LLMTokenizer, type LLMModel } from \"src/ts/model/types\";\nimport { readPersistentJson, removePersistentKey, writePersistentJson } from \"src/ts/storage/persistentKv\";\nimport { ensureChatHydrated, ensureCurrentChatReady } from \"src/ts/storage/chatStorage\";\nimport { assignMissingChatIdsToNewCharacters } from \"src/ts/storage/chatIdentityRepair\";\nimport { endAllGenerations } from \"src/ts/process/generationState\";\nimport { sendChat as processSendChat, doingChat } from \"src/ts/process/index.svelte\";\nimport { getModelInfo } from \"src/ts/model/modellist\";\nimport type { ModelModeExtended } from \"src/ts/process/request/shared\";\nimport { requestChatDataMain } from \"src/ts/process/request/request\";\nimport type { OpenAIChat } from \"src/ts/process/index.svelte\";\nimport { getModuleLorebooks } from \"src/ts/process/modules\";\nimport {\n    registerTTSPreprocessor,\n    unregisterTTSPreprocessor,\n    registerTTSPostprocessor,\n    unregisterTTSPostprocessor,\n    type BeforeTTSContext,\n    type BeforeTTSResult,\n    type AfterTTSContext,\n    type AfterTTSResult,\n    type TTSHookFn,\n} from \"src/ts/process/ttsHooks\";\nimport { PluginChatAccess } from \"./pluginChatAccess\";\n\n/*\n    V3 API for RisuAI Plugins\n\n    Before adding new APIs here, please check the limitations\n\n    - APIs must be a functions\n        - If you want nested objects, first add as a plain function, `_getPluginStorage` for example\n            And add it too _getAliases function ({'pluginStorage':{'getItem': '_getPluginStorage', ... }})\n            This will make pluginStorage.getItem() work in plugins\n        - If you need constants, use _getPropertiesForInitialization to set them up\n            For example apiVersion and apiVersionCompatibleWith are set this way,\n            Accessable in plugins as risuai.apiVersion\n    - APIs must return, or accept as parameters, only the following types:\n        - Serializable data (string, number, boolean, null, array, object)\n        - Class instances marked with __classType = 'REMOTE_REQUIRED'\n        - Callback functions (only as parameters)\n        - Note that Class or Callbacks inside arrays or objects are not supported\n*/\n\nconst pluginChannel = new Map<string, Function>();\nconst documentEventListeners: Array<{type: string, listener: EventListenerOrEventListenerObject, options: any}> = [];\n\nclass SafeElement {\n    #element: HTMLElement;\n    __classType = 'REMOTE_REQUIRED' as const;\n\n    constructor(element: HTMLElement) {\n        if(element.getAttribute('freezed')){\n            throw new Error(\"This element cannot be accessed by SafeELement\")\n        }\n        this.#element = element;\n    }\n\n    public appendChild(child: SafeElement) {\n        this.#element.appendChild(child.#element);\n    }\n\n    public removeChild(child: SafeElement) {\n        this.#element.removeChild(child.#element);\n    }\n\n    public replaceChild(newChild: SafeElement, oldChild: SafeElement) {\n        this.#element.replaceChild(newChild.#element, oldChild.#element);\n    }\n\n    public replaceWith(newElement: SafeElement) {\n        this.#element.replaceWith(newElement.#element);\n    }\n\n    public cloneNode(deep: boolean = false): SafeElement {\n        const cloned = this.#element.cloneNode(deep);\n        return new SafeElement(cloned as HTMLElement);\n    }\n\n    public prepend(child: SafeElement) {\n        this.#element.prepend(child.#element);\n    }\n\n    public remove() {\n        this.#element.remove();\n    }\n\n    public innerText(): string {\n        return this.#element.innerText;\n    }\n\n    public textContent(): string | null {\n        return this.#element.textContent;\n    }\n\n    public setTextContent(value: string) {\n        this.#element.textContent = value;\n    }\n\n    public setInnerText(value: string) {\n        this.#element.innerText = value;\n    }\n\n\n    public setAttribute(name: string, value: string) {\n        if(!name.startsWith('x-')){\n            throw new Error(\"Can only set attributes starting with 'x-' for security reasons. for other attributes, use dedicated methods.\");\n        }\n        this.#element.setAttribute(name, value);\n    }\n    public getAttribute(name: string): string | null {\n        if(!name.startsWith('x-')){\n            throw new Error(\"Can only get attributes starting with 'x-' for security reasons. for other attributes, use dedicated methods.\");\n        }\n        return this.#element.getAttribute(name);\n    }\n    public setStyle(property: string, value: string) {\n        (this.#element.style as any)[property] = value;\n    }\n    public getStyle(property: string): string {\n        return (this.#element.style as any)[property];\n    }\n    public getStyleAttribute(): string {\n        return this.#element.getAttribute('style') || '';\n    }\n    public setStyleAttribute(value: string) {\n        this.#element.setAttribute('style', value);\n    }\n    public addClass(className: string) {\n        // \n        this.#element.classList.add(className);\n    }\n    public removeClass(className: string) {\n        // \n        this.#element.classList.remove(className);\n    }\n    public setClassName(className: string){\n        this.#element.className = className\n    }\n    public getClassName(){\n        return this.#element.className\n    }\n    public hasClass(className: string): boolean {\n        //We don't need to check the className here since we're just checking\n        return this.#element.classList.contains(className);\n    }\n    public focus() {\n        this.#element.focus();\n    }\n    public getChildren(): SafeClassArray<SafeElement> {\n        const children: SafeElement[] = [];\n        this.#element.childNodes.forEach(node => {\n            if(node instanceof HTMLElement) {\n                children.push(new SafeElement(node));\n            }\n        });\n        return new SafeClassArray<SafeElement>(children);\n    }\n    public getParent(): SafeElement | null {\n        if(this.#element.parentElement) {\n            return new SafeElement(this.#element.parentElement);\n        }\n        return null;\n    }\n    public getInnerHTML(): string {\n        return this.#element.innerHTML;\n    }\n    public getOuterHTML(): string {\n        return this.#element.outerHTML;\n    }\n    public clientHeight(): number {\n        return this.#element.clientHeight;\n    }\n    public clientWidth(): number {\n        return this.#element.clientWidth;\n    }\n    public clientTop(): number {\n        return this.#element.clientTop;\n    }\n    public clientLeft(): number {\n        return this.#element.clientLeft;\n    }\n    public nodeName(): string {\n        return this.#element.nodeName;\n    }\n    public nodeType(): number {\n        return this.#element.nodeType;\n    }\n    public querySelectorAll(selector: string): SafeClassArray<SafeElement> {\n        const nodeList = this.#element.querySelectorAll(selector);\n        const elements: SafeElement[] = [];\n        nodeList.forEach(node => {\n            if(node instanceof HTMLElement) {\n                elements.push(new SafeElement(node));\n            }\n        });\n        return new SafeClassArray<SafeElement>(elements);\n    }\n    public querySelector(selector: string): SafeElement | null {\n        const element = this.#element.querySelector(selector);\n        if(element instanceof HTMLElement) {\n            return new SafeElement(element);\n        }\n        return null;\n    }\n    public getElementById(id: string): SafeElement | null {\n        const element = this.querySelector('#' + id);\n        return element;\n    }\n    public getElementsByClassName(className: string): SafeClassArray<SafeElement> {\n        return this.querySelectorAll('.' + className);\n    }\n    public getClientRects(): DOMRectList {\n        return this.#element.getClientRects();\n    }\n    public getBoundingClientRect(): DOMRect {\n        return this.#element.getBoundingClientRect();\n    }\n    public setInnerHTML(value: string) {\n        const san = DOMPurify.sanitize(value);\n        this.#element.innerHTML = san;\n    }\n    public setOuterHTML(value: string) {\n        const san = DOMPurify.sanitize(value);\n        this.#element.outerHTML = san;\n    }\n    public scrollIntoView(options?: boolean | ScrollIntoViewOptions) {\n        this.#element.scrollIntoView(options);\n    }\n    #eventIdMap = new Map<string, Function>()\n\n    public async addEventListener(type:string, listener: (event: any) => void, options?: boolean | AddEventListenerOptions):Promise<string> {\n        const realOptions = typeof options === 'boolean' ? { capture: options } : options || {};\n\n        //allowed with unlimited\n        const allowedDocumentEventListeners = [\n            'click',\n            'dblclick',\n            'contextmenu',\n            'mousedown',\n            'mouseup',\n            'mousemove',\n            'mouseover',\n            'mouseleave',\n            'pointercancel',\n            'pointerdown',\n            'pointerenter',\n            'pointerleave',\n            'pointermove',\n            'pointerout',\n            'pointerover',\n            'pointerup',\n            'scroll',\n            'scrollend'\n        ]\n\n        //allowed, but it has fingerprinting issues,\n        //so it will be delayed random ms.\n        const allowedDelayedEventListeners = [\n            'keydown',\n            'keyup',\n            'keypress'\n        ]\n\n        const id = v4()\n\n        const trimEvent = (event: MouseEvent | KeyboardEvent | Event) => {\n            if(event instanceof MouseEvent){\n                return {\n                    type: event.type,\n                    clientX: event.clientX,\n                    clientY: event.clientY,\n                    button: event.button,\n                    buttons: event.buttons,\n                    altKey: event.altKey,\n                    ctrlKey: event.ctrlKey,\n                    shiftKey: event.shiftKey,\n                    metaKey: event.metaKey,\n                }\n            }\n            else if(event instanceof KeyboardEvent){\n                return {\n                    type: event.type,\n                    key: event.key,\n                    code: event.code,\n                    repeat: event.repeat,\n                    altKey: event.altKey,\n                    ctrlKey: event.ctrlKey,\n                    shiftKey: event.shiftKey,\n                    metaKey: event.metaKey,\n                }\n            }\n            else{\n                return {\n                    type: event.type\n                }\n            }\n\n        }\n\n        if(allowedDocumentEventListeners.includes(type)){\n            const modifiedListener = (event: any) => {\n                listener(trimEvent(event))\n            }\n            this.#eventIdMap.set(id, modifiedListener)\n            documentEventListeners.push({type, listener: modifiedListener as EventListenerOrEventListenerObject, options: realOptions})\n            document.addEventListener(type, modifiedListener, realOptions)\n            return id;\n        }\n        else if(allowedDelayedEventListeners.includes(type)){\n            const modifiedListener = (event: any) => {\n                let delay = 0;\n                try {\n                    delay = (crypto.getRandomValues(new Uint32Array(1))[0] / 100) % 100; //0-99 ms              \n                } catch (error) {}\n                setTimeout(() => {\n                    listener(trimEvent(event));\n                }, delay);\n            }\n            this.#eventIdMap.set(id, modifiedListener)\n            documentEventListeners.push({type, listener: modifiedListener as EventListenerOrEventListenerObject, options: realOptions})\n            document.addEventListener(type, modifiedListener, realOptions);\n            return id;\n        }\n        else{\n            throw new Error(`Event listener of type '${type}' is not allowed for security reasons.`);\n        }        \n    }\n\n    public removeEventListener(type:string, id:string, options?: boolean | EventListenerOptions) {\n        const listener = this.#eventIdMap.get(id);\n        if(listener){\n            const realOptions = typeof options === 'boolean' ? { capture: options } : options || {};\n            document.removeEventListener(type, listener as EventListenerOrEventListenerObject, realOptions);\n            const idx = documentEventListeners.findIndex(e => e.listener === listener);\n            if(idx !== -1) documentEventListeners.splice(idx, 1);\n            this.#eventIdMap.delete(id);\n        }\n    }\n\n    public matches (selector: string): boolean {\n        return this.#element.matches(selector);\n    }\n}\n\nclass SafeDocument extends SafeElement {\n    __classType = 'REMOTE_REQUIRED' as const;\n    constructor(document: Document) {\n        super(document.documentElement);\n    }\n    createElement(tagName: string): SafeElement {\n        if(!tagWhitelist.includes(tagName.toLowerCase())) {\n            console.warn(`Creation of <${tagName}> elements is restricted. Creating a <div> instead.`);\n            tagName = 'div';\n        }\n        if(tagName.toLowerCase() === 'a'){\n            console.warn(`<a> can be created but href attribute cannot be set directly for security reasons. Use .createAnchorElement(href: string) to create safe anchor elements.`);\n        }\n        const element = document.createElement(tagName);\n        return new SafeElement(element);\n    }\n    createAnchorElement(href: string): SafeElement {\n        const anchor = document.createElement('a');\n        try {\n            const url = new URL(href);\n            if(url.protocol !== 'http:' && url.protocol !== 'https:'){\n                throw new Error(\"Invalid protocol\");\n            }\n            anchor.setAttribute('href', url.toString());\n        } catch (error) {\n            console.warn(`Invalid URL provided for anchor element: ${href}. Setting href to '#' instead.`);\n            anchor.setAttribute('href', '#');\n        }\n        return new SafeElement(anchor);\n    }\n}\n\ntype SafeMutationRecordObject = {\n    type: string;\n    target: SafeElement;\n    addedNodes: SafeElement[];\n}\n\nclass SafeClassArray<T> {\n    #items: T[];\n    __classType = 'REMOTE_REQUIRED' as const;\n    constructor(items: T[] = []) {\n        this.#items = items;\n    }\n    at(index: number): T {\n        return this.#items.at(index);\n    }\n    length(): number {\n        return this.#items.length;\n    }\n    push(item: T) {\n        this.#items.push(item);\n    }\n}\n\nclass SafeMutationRecord{\n    __classType = 'REMOTE_REQUIRED' as const;\n    #type: string;\n    #target: SafeElement;\n    #addedNodes: SafeClassArray<SafeElement>;\n    constructor(type: string, target: SafeElement, addedNodes: SafeElement[]) {\n        this.#type = type;\n        this.#target = target;\n        this.#addedNodes = new SafeClassArray<SafeElement>(addedNodes);\n    }\n    getType(): string {\n        return this.#type;\n    }\n    getTarget(): SafeElement {\n        return this.#target;\n    }\n    getAddedNodes(): SafeClassArray<SafeElement> {\n        return this.#addedNodes;\n    }\n}\n\ntype SafeMutationCallback = (mutations: SafeClassArray<SafeMutationRecord>) => void;\n\nclass SafeMutationObserver {\n    #observer: MutationObserver;\n    __classType = 'REMOTE_REQUIRED' as const;\n    constructor(callback: SafeMutationCallback) {\n        this.#observer = new MutationObserver((mutations) => {\n            const safeMutations: SafeMutationRecordObject[] = mutations.map(mutation => {\n\n                const elementMapHelper = (nodeList: NodeList): SafeElement[] => {\n                    const elements: SafeElement[] = [];\n                    nodeList.forEach(node => {\n                        if(node instanceof HTMLElement) {\n                            elements.push(new SafeElement(node));\n                        }\n                    })\n                    return elements;\n                }\n\n                return {\n                    type: mutation.type,\n                    target: new SafeElement(mutation.target as HTMLElement),\n                    addedNodes: elementMapHelper(mutation.addedNodes),\n                    removedNodes: elementMapHelper(mutation.removedNodes)\n                    \n                }\n            })\n\n            const safeClassed = new SafeClassArray<SafeMutationRecord>([]);\n            for(const record of safeMutations){\n                safeClassed.push(new SafeMutationRecord(\n                    record.type,\n                    record.target,\n                    record.addedNodes\n                ));\n            }\n            callback(safeClassed);\n        });\n    }\n\n    observe(element:SafeElement, options: MutationObserverInit) {\n        const identifier = v4();\n        element.setAttribute('x-identifier', identifier);\n        const rawElement = document.querySelector(`[x-identifier=\"${identifier}\"]`) as HTMLElement;\n        if(rawElement){\n            this.#observer.observe(rawElement, options);\n            element.setAttribute('x-identifier', '');\n        }\n    }\n\n    disconnect() {\n        this.#observer.disconnect();\n    }\n\n}\n\nconst pluginUnloadCallbacks: Map<string, Function[]> = new Map();\n\nconst addPluginUnloadCallback = (pluginName: string, callback: Function) => {\n    if(!pluginUnloadCallbacks.has(pluginName)){\n        pluginUnloadCallbacks.set(pluginName, []);\n    }\n    pluginUnloadCallbacks.get(pluginName)?.push(callback);\n}\n\nconst makeMenuUnloadCallback = (menuId:string, menuStore: MenuDef[]) =>{\n    return () => {\n        const index = menuStore.findIndex(item => item.id === menuId);\n        if(index !== -1){\n            menuStore.splice(index, 1);\n        }\n    }\n}\n\nconst removeChatPanel = (id: string) => {\n    const index = chatPanelStore.findIndex(item => item.id === id);\n    if(index !== -1){\n        chatPanelStore.splice(index, 1);\n    }\n}\n\nconst removePluginChatPanels = (pluginName: string) => {\n    for(let i = chatPanelStore.length - 1; i >= 0; i--){\n        if(chatPanelStore[i].pluginName === pluginName){\n            chatPanelStore.splice(i, 1);\n        }\n    }\n}\n\nconst unloadV3Plugin = async (pluginName: string) => {\n    const callbacks = pluginUnloadCallbacks.get(pluginName);\n    const instance = v3PluginInstances.find(p => p.name === pluginName);\n    if(instance){\n        const index = v3PluginInstances.findIndex(p => p.name === pluginName);\n        if(index !== -1){\n            v3PluginInstances.splice(index, 1);\n        }\n    }\n    if(callbacks){\n        pluginUnloadCallbacks.delete(pluginName); \n        let promises: Promise<void>[] = [];\n        for(const callback of callbacks){\n            const result = callback();\n            if(result instanceof Promise){\n                promises.push(result);\n            }\n        }\n\n        await Promise.any([\n            Promise.all(promises),\n            sleep(1000) //timeout after 1 second\n        ])\n    }\n    try {\n        instance?.host?.terminate();        \n    } catch (error) {\n        console.error(`Error terminating plugin ${pluginName}:`, error);\n    }\n}\n\ntype PluginPermissionDesc = 'fetchLogs'|'db'|'mainDom'|'replacer'|'provider'|'sendChat';\nconst pluginPermissionDescs: PluginPermissionDesc[] = ['fetchLogs', 'db', 'mainDom', 'replacer', 'provider', 'sendChat'];\n\n// Plugin names are free text (the //@name directive), so `${name}_${desc}` keys\n// can collide — both across permissions and with a legacy name-only entry that\n// happens to read like \"name_desc\". JSON-encoding the pair makes every key\n// unambiguous: [\"foo\",\"db\"] can never equal a plain \"foo_db\" or [\"foo_db\",\"x\"].\nconst permissionKeyOf = (pluginName: string, permissionDesc: string) =>\n    JSON.stringify([pluginName, permissionDesc])\n\nconst permissionGivenPlugins: Set<string> = new Set();\nconst permissionDeniedPlugins: Set<string> = new Set();\nconst permissionCache = new Map<string, boolean | number>();\nconst pluginPermissionStateKey = 'cache/plugin-permissions/state.json';\nlet pluginPermissionLoadPromise: Promise<void> | null = null;\n\nasync function ensurePluginPermissionStateLoaded() {\n    if (!pluginPermissionLoadPromise) {\n        pluginPermissionLoadPromise = (async () => {\n            const payload = await readPersistentJson<{\n                given: string[]\n                denied: string[]\n                cache: [string, boolean | number][]\n            }>(pluginPermissionStateKey)\n            if (!payload) {\n                return\n            }\n            permissionGivenPlugins.clear()\n            permissionDeniedPlugins.clear()\n            permissionCache.clear()\n            for (const pluginName of payload.given ?? []) {\n                permissionGivenPlugins.add(pluginName)\n            }\n            for (const pluginName of payload.denied ?? []) {\n                permissionDeniedPlugins.add(pluginName)\n            }\n            for (const [key, value] of payload.cache ?? []) {\n                permissionCache.set(key, value)\n            }\n        })()\n    }\n    await pluginPermissionLoadPromise\n}\n\nexport async function resetAllPluginPermissions() {\n    permissionGivenPlugins.clear()\n    permissionDeniedPlugins.clear()\n    permissionCache.clear()\n    pluginPermissionLoadPromise = Promise.resolve()\n    await removePersistentKey(pluginPermissionStateKey)\n}\n\nexport async function resetPluginPermission(pluginName: string) {\n    await ensurePluginPermissionStateLoaded()\n    // Permission descs are a fixed enum, so we delete the exact key for each\n    // one rather than prefix-matching (which would also wipe another plugin's\n    // keys). `pluginName` alone covers legacy name-only entries from older\n    // versions, which JSON keys never collide with but reset should still clear.\n    const exactKeys = pluginPermissionDescs.map(desc => permissionKeyOf(pluginName, desc))\n    for (const key of [pluginName, ...exactKeys]) {\n        permissionGivenPlugins.delete(key)\n        permissionDeniedPlugins.delete(key)\n    }\n    for (const desc of pluginPermissionDescs) {\n        permissionCache.delete(permissionKeyOf(pluginName, desc) + '_lastGrantTime')\n    }\n    const plugin = DBState.db.plugins?.find(p => p.name === pluginName)\n    if (plugin?.script) {\n        const scriptHashBase = await hasher(new TextEncoder().encode(plugin.script))\n        for (const key of [...permissionCache.keys()]) {\n            if (key.startsWith(scriptHashBase + '_')) {\n                permissionCache.delete(key)\n            }\n        }\n    }\n    await persistPluginPermissionState()\n}\n\nasync function persistPluginPermissionState() {\n    await writePersistentJson(pluginPermissionStateKey, {\n        given: [...permissionGivenPlugins],\n        denied: [...permissionDeniedPlugins],\n        cache: [...permissionCache.entries()]\n    })\n}\n\ntype PluginV3ProviderOptions = PluginV2ProviderOptions & {\n    model?: LLMModel\n}\n\nexport const customV3ProviderMetaStore:LLMModel[] = []\n\n// Serializes permission dialogs. Every plugin shares the single global\n// alertStore, so when several plugins request permission at boot they would\n// otherwise overwrite each other's dialog — only the last one stays clickable\n// and a single click resolves all of them. The chain makes each dialog wait\n// for the previous one to finish, showing them one at a time.\nlet pluginPermissionDialogChain: Promise<unknown> = Promise.resolve()\n\nconst isPermissionResolved = async (\n    pluginName: string,\n    permissionDesc: PluginPermissionDesc,\n    requiresReconfirm: boolean,\n): Promise<{ resolved: boolean; value: boolean; pluginHash: string }> => {\n    const permissionKey = permissionKeyOf(pluginName, permissionDesc);\n    if (!requiresReconfirm && permissionGivenPlugins.has(permissionKey)) {\n        return { resolved: true, value: true, pluginHash: '' }\n    }\n    if (!requiresReconfirm && permissionDeniedPlugins.has(permissionKey)) {\n        return { resolved: true, value: false, pluginHash: '' }\n    }\n\n    const pluginHash = await hasher(\n        new TextEncoder().encode(\n            DBState.db.plugins.find(p => p.name === pluginName)?.script\n        )\n    ) + `_${permissionDesc}`;\n\n    if (!requiresReconfirm && permissionCache.get(pluginHash)) {\n        permissionGivenPlugins.add(permissionKey);\n        return { resolved: true, value: true, pluginHash }\n    }\n\n    return { resolved: false, value: false, pluginHash }\n}\n\nconst getPluginPermission = async (pluginName: string, permissionDesc: PluginPermissionDesc, reconfirm: boolean|'periodically' = false) => {\n    await ensurePluginPermissionStateLoaded()\n\n    // Recomputed (not captured) so a periodic reconfirm reflects the latest\n    // lastGrantTime: when several identical requests queue together, an earlier\n    // one may refresh it, making the reconfirm no longer due for the rest.\n    const computeRequiresReconfirm = () => {\n        if(reconfirm === 'periodically'){\n            const lastGrantTime = permissionCache.get(permissionKeyOf(pluginName, permissionDesc) + '_lastGrantTime') as number | undefined;\n            return !lastGrantTime || Date.now() - lastGrantTime > 3 * 24 * 60 * 60 * 1000; //3 days\n        }\n        return reconfirm === true;\n    }\n\n    // Fast path: if the answer is already known, skip the serialization queue\n    // entirely so cached/granted permissions never block on a pending dialog.\n    const early = await isPermissionResolved(pluginName, permissionDesc, computeRequiresReconfirm())\n    if (early.resolved) {\n        return early.value\n    }\n\n    const showDialog = async (): Promise<boolean> => {\n        // Re-check under the lock: an earlier queued dialog for the same plugin\n        // may have already granted/denied (or refreshed a periodic grant) while\n        // we were waiting our turn — recompute reconfirm so we don't re-prompt.\n        const requiresReconfirm = computeRequiresReconfirm()\n        const recheck = await isPermissionResolved(pluginName, permissionDesc, requiresReconfirm)\n        if (recheck.resolved) {\n            return recheck.value\n        }\n        const pluginHash = recheck.pluginHash\n\n        let alertTitle =\n            permissionDesc === 'fetchLogs' ? language.fetchLogConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'db' ? language.getFullDatabaseConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'mainDom' ? language.mainDomAccessConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'replacer' ? language.replacerPermissionConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'provider' ? language.providerPermissionConsent.replace(\"{}\", pluginName)\n            : permissionDesc === 'sendChat' ? language.sendChatConsent.replace(\"{}\", pluginName)\n            : `Error`\n        if(alertTitle === 'Error'){\n            return false;\n        }\n        const permissionKey = permissionKeyOf(pluginName, permissionDesc);\n        const conf = await alertConfirm(alertTitle)\n        if(conf && pluginHash){\n            permissionGivenPlugins.add(permissionKey);\n            permissionDeniedPlugins.delete(permissionKey);\n            permissionCache.set(pluginHash, true);\n            if(reconfirm === 'periodically'){\n                permissionCache.set(permissionKeyOf(pluginName, permissionDesc) + '_lastGrantTime', Date.now());\n            }\n            await persistPluginPermissionState()\n            return true;\n        }\n        permissionDeniedPlugins.add(permissionKey);\n        await persistPluginPermissionState()\n        return false;\n    }\n\n    // Append to the dialog chain so only one permission dialog is shown at a\n    // time. finally restores the chain even if showDialog throws, so a single\n    // failure never deadlocks every later permission request.\n    const run = pluginPermissionDialogChain\n        .catch(() => {})\n        .then(() => showDialog())\n    pluginPermissionDialogChain = run.catch(() => {})\n    return run\n}\n\nconst urlBlacklist = [\n    'risuai.xyz',\n    'risuai.net',\n    'sionyw.com',\n]\n\nconst authorizationHeaders = [\n    'x-api-key',\n    'authorization',\n    'proxy-authorization',\n]\n\nconst makeRisuaiAPIV3 = (iframe:HTMLIFrameElement,plugin:RisuPlugin) => {\n\n    const oldApis = getV2PluginAPIs();\n    const pluginChatAccess = new PluginChatAccess({\n        getDatabase: () => DBState.db,\n        hydrateChat: (chats, index, chaId) => ensureChatHydrated(chats as any, index, chaId) as any,\n        normalizeChat: (chat) => normalizeChat(chat as any) as any,\n        markChatDirty,\n        markCharacterDirty,\n    })\n\n    const getCurrentCharacterForPlugin = async () => {\n        const characterIndex = get(selectedCharID)\n        const character = await pluginChatAccess.getHydratedCharacterAt(characterIndex)\n        if (get(selectedCharID) !== characterIndex) {\n            throw new Error('The selected character changed while plugin data was loading')\n        }\n        return character ? $state.snapshot(character) : undefined\n    }\n\n    const setCurrentCharacterForPlugin = async (character: any) => {\n        const characterIndex = get(selectedCharID)\n        await pluginChatAccess.replaceCharacterAt(\n            characterIndex,\n            character,\n            () => get(selectedCharID) === characterIndex,\n        )\n    }\n\n    const preparePluginDatabaseWrite = async (newDb: any) => {\n        if (!newDb || typeof newDb !== 'object'\n            || !Object.prototype.hasOwnProperty.call(newDb, 'characters')) {\n            return null\n        }\n\n        const database = await pluginChatAccess.getHydratedDatabase()\n        if (database !== DBState.db) {\n            throw new Error('The plugin database target changed while chats were loading')\n        }\n\n        const previousCharacters = [...(database.characters ?? [])]\n        // Work on detached character/chat shells so assigning an omitted ID\n        // cannot mutate a plugin-owned payload if later validation fails.\n        const candidateCharacters = Array.isArray(newDb.characters)\n            ? newDb.characters.map((character: any) => {\n                if (!character || typeof character !== 'object' || Array.isArray(character)) {\n                    return character\n                }\n                return {\n                    ...character,\n                    chats: Array.isArray(character.chats)\n                        ? character.chats.map((chat: any) => (\n                            chat && typeof chat === 'object' && !Array.isArray(chat)\n                                ? { ...chat }\n                                : chat\n                        ))\n                        : character.chats,\n                }\n            })\n            : newDb.characters\n        assignMissingChatIdsToNewCharacters(\n            { characters: candidateCharacters },\n            { characters: previousCharacters },\n            v4,\n        )\n        const nextCharacters = pluginChatAccess.validateCharacterCollection(candidateCharacters)\n        return {\n            payload: { ...newDb, characters: nextCharacters },\n            previousCharacters,\n            nextCharacters,\n        }\n    }\n\n    const setPluginDatabaseLite = async (newDb: any) => {\n        const prepared = await preparePluginDatabaseWrite(newDb)\n        oldApis.setDatabaseLite(prepared?.payload ?? newDb)\n        if (prepared) {\n            pluginChatAccess.markCharacterCollectionDirty(\n                prepared.previousCharacters,\n                prepared.nextCharacters,\n            )\n        }\n    }\n\n    const setPluginDatabase = async (newDb: any) => {\n        const prepared = await preparePluginDatabaseWrite(newDb)\n        await oldApis.setDatabase(prepared?.payload ?? newDb)\n        if (prepared) {\n            pluginChatAccess.markCharacterCollectionDirty(\n                prepared.previousCharacters,\n                prepared.nextCharacters,\n            )\n        }\n    }\n\n    return {\n\n        //Old APIs from v2.1\n        risuFetch: (url, options) => {\n            console.error(`[DEPRECATION WARNING] risuFetch is deprecated and will be removed in future versions. Please use nativeFetch instead.`)\n            for(const blocked of urlBlacklist){\n                if(url.toLowerCase().includes(blocked)){\n                    throw new Error(`Requests to ${blocked} are blocked for security reasons.`);\n                }\n            }\n\n            //scan headers\n            const headers = options?.headers || {};\n            for(const headerName in headers){\n                if(authorizationHeaders.includes(headerName.toLowerCase())){\n                    console.warn(`Request contains potentially sensitive header '${headerName}'. handling of such headers may be changed to only work with nativeFetch.`);\n                }\n            }\n            return oldApis.risuFetch(url, options);\n        },\n        nativeFetch: (url, options) => {\n            for(const blocked of urlBlacklist){\n                if(url.toLowerCase().includes(blocked)){\n                    throw new Error(`Requests to ${blocked} are blocked for security reasons.`);\n                }\n            }\n\n            //scan headers\n            const headers = options?.headers || {};\n            for(const headerName in headers){\n                if(authorizationHeaders.includes(headerName.toLowerCase())){\n                    console.warn(`Request contains potentially sensitive header '${headerName}'. handling of such headers may be changed to use server-side approch with write-only api access in the future for better security.`);\n                }\n            }\n            return oldApis.nativeFetch(url, options);\n        },\n        getChar: getCurrentCharacterForPlugin,\n        setChar: setCurrentCharacterForPlugin,\n        addProvider: (name: string, func: (arg: PluginV2ProviderArgument, abortSignal?: AbortSignal) => Promise<{ success: boolean, content: string | ReadableStream<string> }>, options?: PluginV3ProviderOptions) => {\n            console.warn(`[WARN] addProvider is a powerful API that can potentially be unsafe if used incorrectly. addProvider's functionality might be limited or changed in future updates to ensure security. please use other APIs if possible.`);\n            let provs = get(customProviderStore)\n            provs.push(name)\n            pluginV2.providers.set(name, async (arg, abortSignal) => {\n               await getPluginPermission(plugin.name, 'provider', 'periodically');\n               //mode is overridden to v3, due to vulnerabilities using mode.\n               //Alternative to mode will be added in future\n               arg.mode = 'v3'\n               return await func(arg, abortSignal);\n            }),\n            pluginV2.providerOptions.set(name, options ?? {})\n            customProviderStore.set(provs)\n\n            const modelData:LLMModel = {\n                id: `pluginmodel:::${name}`,\n                name: options?.model?.name ?? name,\n                shortName: options?.model?.shortName ?? name,\n                fullName: options?.model?.fullName ?? name,\n                internalID: options?.model?.internalID ?? `pluginmodel:::${name}`,\n                provider: LLMProvider.AsIs,\n                format: LLMFormat.Plugin,\n                flags: options?.model?.flags ?? [LLMFlags.hasFullSystemPrompt],\n                parameters: options?.model?.parameters ?? ['temperature', 'top_p', 'frequency_penalty', 'presence_penalty', 'repetition_penalty', 'min_p', 'top_a', 'top_k', 'thinking_tokens'],\n                tokenizer:options?.model?.tokenizer ??  LLMTokenizer.Unknown\n            }\n            customV3ProviderMetaStore.push(modelData);\n        },\n        addTTSPreprocessor: async (\n            func: TTSHookFn<BeforeTTSContext, BeforeTTSResult>,\n        ) => {\n            registerTTSPreprocessor(func);\n            addPluginUnloadCallback(plugin.name, () => unregisterTTSPreprocessor(func));\n        },\n        addTTSPostprocessor: async (\n            func: TTSHookFn<AfterTTSContext, AfterTTSResult>,\n        ) => {\n            registerTTSPostprocessor(func);\n            addPluginUnloadCallback(plugin.name, () => unregisterTTSPostprocessor(func));\n        },\n        addRisuScriptHandler: oldApis.addRisuScriptHandler,\n        removeRisuScriptHandler: oldApis.removeRisuScriptHandler,\n        addRisuReplacer: async (name:string,func:Function) => {\n            //permission check for replacer\n            const conf = await getPluginPermission(plugin.name, 'replacer', 'periodically');\n            if(!conf){\n                return;\n            }\n            oldApis.addRisuReplacer(name, func as any);\n        },\n        removeRisuReplacer: oldApis.removeRisuReplacer,\n        setDatabaseLite: setPluginDatabaseLite,\n        setDatabase: setPluginDatabase,\n        loadPlugins: oldApis.loadPlugins,\n        readImage: oldApis.readImage,\n        readInlay: async (id: string) => {\n            return await getInlayAsset(id);\n        },\n        saveAsset: oldApis.saveAsset,\n        //Same functionality, but new implementation\n        getDatabase: async (includeOnly:string[]|'all' = 'all') => {\n            const conf = await getPluginPermission(plugin.name, 'db', 'periodically');\n            if(!conf){\n                return null;\n            }\n            const shouldIncludeCharacters = includeOnly === 'all' || includeOnly.includes('characters')\n            const db = shouldIncludeCharacters\n                ? await pluginChatAccess.getHydratedDatabase()\n                : DBState.db\n            let liteDB = {}\n            for(const key of allowedDbKeys){\n                if(includeOnly !== 'all' && !includeOnly.includes(key)){\n                    continue;\n                }\n                (liteDB as any)[key] = $state.snapshot((db as any)[key]);\n            }\n            return liteDB;\n        },\n        getDatabaseMetadata: async (includeOnly:string[]|'all' = 'all') => {\n            const conf = await getPluginPermission(plugin.name, 'db', 'periodically');\n            if(!conf){\n                return null;\n            }\n            const shouldIncludeCharacters = includeOnly === 'all' || includeOnly.includes('characters')\n            const db = shouldIncludeCharacters\n                ? pluginChatAccess.getDatabaseWithChatMetadata()\n                : DBState.db\n            let liteDB = {}\n            for(const key of allowedDbKeys){\n                if(includeOnly !== 'all' && !includeOnly.includes(key)){\n                    continue;\n                }\n                (liteDB as any)[key] = $state.snapshot((db as any)[key]);\n            }\n            return liteDB;\n        },\n\n        installPlugin: handlePluginInstallViaPlugin,\n\n        // --- Color Scheme APIs ---\n        changeColorScheme: (name: string) => {\n            changeColorScheme(name)\n        },\n        setColorScheme: (scheme: ColorScheme) => {\n            const requiredKeys = ['bgcolor','darkbg','borderc','selected','draculared','textcolor','textcolor2','darkBorderc','darkbutton','type'] as const\n            for (const key of requiredKeys) {\n                if (typeof (scheme as any)[key] !== 'string') {\n                    throw new Error(`Invalid color scheme: missing or invalid '${key}'`)\n                }\n            }\n            if (scheme.type !== 'light' && scheme.type !== 'dark') {\n                throw new Error('Invalid color scheme type: must be \"light\" or \"dark\"')\n            }\n            const db = DBState.db\n            db.colorSchemeName = 'custom'\n            db.colorScheme = scheme\n            updateColorScheme()\n        },\n        getColorScheme: () => {\n            const db = DBState.db\n            return {\n                name: db.colorSchemeName,\n                scheme: $state.snapshot(db.colorScheme)\n            }\n        },\n\n        // --- Text Theme APIs ---\n        changeTextTheme: (name: string) => {\n            if (!['standard','highcontrast'].includes(name)) {\n                throw new Error(`Invalid text theme: ${name}`)\n            }\n            const db = DBState.db\n            db.textTheme = name\n            updateTextThemeAndCSS()\n        },\n        setCustomTextTheme: (theme: {\n            FontColorStandard: string,\n            FontColorBold: string,\n            FontColorItalic: string,\n            FontColorItalicBold: string,\n            FontColorQuote1: string,\n            FontColorQuote2: string\n        }) => {\n            const requiredKeys = ['FontColorStandard','FontColorBold','FontColorItalic','FontColorItalicBold','FontColorQuote1','FontColorQuote2'] as const\n            for (const key of requiredKeys) {\n                if (typeof (theme as any)[key] !== 'string') {\n                    throw new Error(`Invalid text theme: missing or invalid '${key}'`)\n                }\n            }\n            const db = DBState.db\n            db.textTheme = 'custom'\n            db.customTextTheme = theme\n            updateTextThemeAndCSS()\n        },\n        getTextTheme: () => {\n            const db = DBState.db\n            return {\n                name: db.textTheme,\n                customTheme: $state.snapshot(db.customTextTheme)\n            }\n        },\n\n        //Deprecated APIs from v2.1\n        //Use getArgument / setArgument instead if possible\n        getArg: oldApis.getArg,\n        setArg: oldApis.setArg,\n\n        //New APIs for v3\n        getArgument: async (key:string) => {\n            const db = getDatabase()\n            for (const p of db.plugins) {\n                if (p.name === plugin.name) {\n                    return p.realArg[key];\n                }\n            }\n        },\n        setArgument: async (key:string, value:string) => {\n            const db = getDatabase();\n            for (const p of db.plugins) {\n                if (p.name === plugin.name) {\n                    p.realArg[key] = value;\n                }\n            }\n        },\n        getCharacterFromIndex: async (index:number) => {\n            const character = await pluginChatAccess.getHydratedCharacterAt(index)\n            return character ? $state.snapshot(character) : null\n        },\n        setCharacterToIndex: async (index:number, char:any) => {\n            await pluginChatAccess.replaceCharacterAt(index, char)\n        },\n        getChatFromIndex: async (characterIndex:number, chatIndex:number) => {\n            const chat = await pluginChatAccess.getHydratedChatAt(characterIndex, chatIndex)\n            return chat ? $state.snapshot(chat) : null\n        },\n        setChatToIndex: async (characterIndex:number, chatIndex:number, chat:any) => {\n            await pluginChatAccess.replaceChatAt(characterIndex, chatIndex, chat)\n        },\n        getCurrentCharacterIndex: () => {\n            return get(selectedCharID)\n        },\n        getCurrentChatIndex: () => {\n            const db = DBState.db\n            const charId = get(selectedCharID)\n            return db.characters[charId].chatPage\n        },\n        getCurrentLorebookEntries: async () => {\n            const characterIndex = get(selectedCharID)\n            const char = DBState.db.characters[characterIndex]\n            if(!char){\n                return []\n            }\n            const page = char.chatPage\n            const expectedChatId = char.chats?.[page]?.id\n            const chat = await pluginChatAccess.getHydratedChatAt(characterIndex, page)\n            const currentCharacter = DBState.db.characters[characterIndex]\n            if (get(selectedCharID) !== characterIndex\n                || currentCharacter !== char\n                || currentCharacter.chatPage !== page\n                || currentCharacter.chats?.[page]?.id !== expectedChatId) {\n                throw new Error('The current lorebook target changed while plugin data was loading')\n            }\n            const characterLore = char.globalLore ?? []\n            const chatLore = chat?.localLore ?? []\n            const moduleLore = getModuleLorebooks()\n            return $state.snapshot(characterLore.concat(chatLore).concat(moduleLore))\n        },\n        //New names for character APIs, to match API naming conventions\n        getCharacter: getCurrentCharacterForPlugin,\n        setCharacter: setCurrentCharacterForPlugin,\n\n        showContainer: (\n            //more types may be added in future\n            type: 'fullscreen' = 'fullscreen'\n        ) => {\n            iframe.style.display = \"block\";\n            \n            switch(type) {\n                case 'fullscreen': {\n                    //move iframe to body if not already there\n                    if(iframe.parentElement !== document.body) {\n                        document.body.appendChild(iframe);\n                    }\n\n                    //Make iframe cover whole screen\n                    iframe.style.position = \"fixed\";\n                    iframe.style.top = \"0\";\n                    iframe.style.left = \"0\";\n                    iframe.style.width = \"100%\";\n                    iframe.style.height = \"100%\";\n                    iframe.style.border = \"none\";\n                    iframe.style.zIndex = \"1000\";\n                    break;\n                }\n                default: {\n                    return\n                }\n            }\n        },\n        hideContainer: () => {\n            iframe.style.display = \"none\";\n        },\n        getRootDocument: async () => {\n            const conf = await getPluginPermission(plugin.name, 'mainDom');\n            if(!conf){\n                return null;\n            }\n            return new SafeDocument(document);\n        },\n        registerSetting: (\n            name:string,\n            callback: any,\n            icon:string = '',\n            iconType:'html'|'img'|'none' = 'none',\n            id?:string\n        ) => {\n            if(iconType !== 'html' && iconType !== 'img' && iconType !== 'none'){\n                throw new Error(\"iconType must be 'html', 'img' or 'none'\");\n            }\n            if(typeof name !== 'string' || name.trim() === ''){\n                throw new Error(\"name must be a non-empty string\");\n            }\n            const menuId = id || v4()\n            const menuDef:MenuDef = {\n                id: menuId,\n                name,\n                icon,\n                iconType,\n                callback\n            }\n            const existingIndex = additionalSettingsMenu.findIndex(item => item.id === menuId)\n            if(existingIndex !== -1){\n                additionalSettingsMenu[existingIndex] = menuDef\n                addPluginUnloadCallback(\n                    plugin.name,\n                    makeMenuUnloadCallback(menuId, additionalSettingsMenu)\n                )\n                return {id: menuId}\n            }\n            additionalSettingsMenu.push(menuDef)\n            addPluginUnloadCallback(\n                plugin.name,\n                makeMenuUnloadCallback(menuId, additionalSettingsMenu)\n            )\n            return {id: menuId};\n        },\n        registerBodyIntercepter: async (callback: (body: any, type: string) => any) => {\n\n            if(await getPluginPermission(plugin.name, 'replacer') === false){\n                return null;\n            }\n            \n            const id = v4();\n            bodyIntercepterStore.push({\n                id,\n                callback\n            })\n            addPluginUnloadCallback(plugin.name, () => {\n                const index = bodyIntercepterStore.findIndex(item => item.id === id);\n                if(index !== -1){\n                    bodyIntercepterStore.splice(index, 1);\n                }\n            })\n            return {id:id};\n        },\n        \n        unregisterBodyIntercepter: (id: string) => {\n            const index = bodyIntercepterStore.findIndex(item => item.id === id);\n            if(index !== -1){\n                bodyIntercepterStore.splice(index, 1);\n            }\n        },\n            \n        registerButton: (\n            arg: {\n                name: string,\n                icon: string,\n                iconType: 'html'|'img'|'none',\n                location?: 'action'|'chat'|'hamburger',\n                id?: string\n            },\n            callback: () => void\n        ) => {\n            let { name, icon, iconType, location, id: providedId } = arg;\n            location = location || 'action';\n            if(iconType !== 'html' && iconType !== 'img' && iconType !== 'none'){\n                throw new Error(\"iconType must be 'html', 'img' or 'none'\");\n            }\n            if(typeof name !== 'string' || name.trim() === ''){\n                throw new Error(\"name must be a non-empty string\");\n            }\n            if(typeof icon !== 'string'){\n                throw new Error(\"icon must be a string\");\n            }\n            const id = providedId || v4()\n            const menuDef:MenuDef = {\n                name,\n                icon,\n                iconType,\n                callback,\n                id\n            }\n\n            const buttonStores = [additionalFloatingActionButtons, additionalHamburgerMenu, additionalChatMenu]\n            for(const store of buttonStores){\n                const existingIndex = store.findIndex(item => item.id === id)\n                if(existingIndex !== -1){\n                    store[existingIndex] = menuDef\n                    addPluginUnloadCallback(\n                        plugin.name,\n                        makeMenuUnloadCallback(id, store)\n                    )\n                    return {id}\n                }\n            }\n\n            switch(location){\n                case 'action':{\n                    additionalFloatingActionButtons.push(menuDef)\n                    addPluginUnloadCallback(\n                        plugin.name,\n                        makeMenuUnloadCallback(menuDef.id, additionalFloatingActionButtons)\n                    )\n                    break\n                }\n                case 'hamburger':{\n                    additionalHamburgerMenu.push(menuDef)\n                    addPluginUnloadCallback(\n                        plugin.name,\n                        makeMenuUnloadCallback(menuDef.id, additionalHamburgerMenu)\n                    )\n                    break\n                }\n                case 'chat':{\n                    additionalChatMenu.push(menuDef)\n                    addPluginUnloadCallback(\n                        plugin.name,\n                        makeMenuUnloadCallback(menuDef.id, additionalChatMenu)\n                    )\n                    break\n                }\n                default:{\n                    throw new Error(\"Invalid location for button\")\n                }\n            }\n            return {id};\n        },\n        setChatPanel: (\n            content: string | null,\n            options: {\n                id?: string,\n                className?: string,\n            } = {}\n        ) => {\n            const id = options.id || `${plugin.name}:default`;\n\n            if(content === null || content === ''){\n                removeChatPanel(id);\n                return {id};\n            }\n\n            if(typeof content !== 'string'){\n                throw new Error(\"content must be a string or null\");\n            }\n\n            const panel = {\n                id,\n                pluginName: plugin.name,\n                html: DOMPurify.sanitize(content),\n                className: typeof options.className === 'string'\n                    ? DOMPurify.sanitize(options.className, {ALLOWED_TAGS: [], ALLOWED_ATTR: []})\n                    : undefined,\n            }\n\n            const existingIndex = chatPanelStore.findIndex(item => item.id === id);\n            if(existingIndex !== -1){\n                chatPanelStore[existingIndex] = panel;\n            }\n            else{\n                chatPanelStore.push(panel);\n            }\n            addPluginUnloadCallback(plugin.name, () => removePluginChatPanels(plugin.name));\n            return {id};\n        },\n        registerMCP: registerMCPModule,\n        unregisterMCP: unregisterMCPModule,\n        unregisterUIPart: (id: string) => {\n            const removeFromMenuStore = (menuStore: MenuDef[]) => {\n                const index = menuStore.findIndex(item => item.id === id);\n                if(index !== -1){\n                    menuStore.splice(index, 1);\n                }\n            }\n\n            removeFromMenuStore(additionalSettingsMenu);\n            removeFromMenuStore(additionalFloatingActionButtons);\n            removeFromMenuStore(additionalHamburgerMenu);\n            removeFromMenuStore(additionalChatMenu);\n            removeChatPanel(id);\n        },\n        log: (message:string) => {\n            console.log(`[RisuAI Plugin: ${plugin.name}] ${message}`);\n        },\n        createMutationObserver(callback: SafeMutationCallback): SafeMutationObserver {\n            const observer = new SafeMutationObserver(callback)\n            addPluginUnloadCallback(plugin.name, () => {\n                observer.disconnect()\n            })\n            return observer\n        },\n        onUnload: (callback: () => void) => {\n            addPluginUnloadCallback(plugin.name, callback);\n        },\n        getFetchLogs: async () => {\n            const conf = await getPluginPermission(plugin.name, 'fetchLogs');\n            if(!conf){\n                return null;\n            }\n            // Reads the server request log; the shape returned to plugins is\n            // unchanged from when this came from the in-memory fetch log.\n            const unsafeFetchLog = await getFetchLogs()\n            return unsafeFetchLog.map(log => {\n\n                const url = new URL(log.url);\n                return {\n                    url: url.origin + url.pathname,\n                    body: log.requestBody ?? '',\n                    status: log.status,\n                    response: log.responseBody,\n                    timestamp: log.timestamp,\n                }\n            })\n        },\n\n        alert: (msg:string) => {\n            return alertNormal(msg)\n        },\n        alertConfirm: (msg:string) => {\n            return alertConfirm(msg)\n        },\n        alertError: (msg:string) => {\n            return alertError(msg)\n        },\n        getRuntimeInfo: () => {\n            return {\n                apiVersion: \"3.0\",\n                platform: 'node',\n                saveMethod:\n                    forageStorage.isAccount ? 'account' :\n                    'local',\n            }\n        },\n        getLocalPluginStorage: () => {\n            return new SafeLocalPluginStorage(plugin.name)\n        },\n        checkCharOrder: checkCharOrder,\n        requestPluginPermission: (permission:string) => {\n            return getPluginPermission(plugin.name, permission as any);\n        },\n        //Internal use APIs\n        _getOldKeys: () => {\n            return Object.keys(oldApis)\n        },\n        _getPropertiesForInitialization: () => {\n            const v = {\n                apiVersion: \"3.0\",\n                apiVersionCompatibleWith: [\"3.0\"],\n            } as any;\n\n            v.list = Object.keys(v);\n            \n            return v;\n        },\n        _getPluginStorage: oldApis.pluginStorage.getItem,\n        // Wrapped (not aliased) so we can record the originating plugin into the\n        // sidecar meta map. The value write is unchanged; reads stay aliased.\n        _setPluginStorage: (key: string, value: any) => {\n            oldApis.pluginStorage.setItem(key, value)\n            recordOwner('save', key, plugin.name)\n        },\n        _removePluginStorage: (key: string) => {\n            oldApis.pluginStorage.removeItem(key)\n            removeOwner('save', key)\n        },\n        _clearPluginStorage: () => {\n            oldApis.pluginStorage.clear()\n            clearOwners('save')\n        },\n        _keyPluginStorage: oldApis.pluginStorage.key,\n        _keysPluginStorage: oldApis.pluginStorage.keys,\n        _lengthPluginStorage: oldApis.pluginStorage.length,\n        _getSafeLocalStorage: oldApis.safeLocalStorage.getItem,\n        _setSafeLocalStorage: (key: string, value: string) => {\n            oldApis.safeLocalStorage.setItem(key, value)\n            recordOwner('local', key, plugin.name)\n        },\n        _removeSafeLocalStorage: (key: string) => {\n            oldApis.safeLocalStorage.removeItem(key)\n            removeOwner('local', key)\n        },\n        _clearSafeLocalStorage: () => {\n            oldApis.safeLocalStorage.clear()\n            clearOwners('local')\n        },\n        _keySafeLocalStorage: oldApis.safeLocalStorage.key,\n        _keysSafeLocalStorage: oldApis.safeLocalStorage.keys,\n        searchTranslationCache: async (partialKey: string) => {\n            return searchLLMCache(partialKey)\n        },\n        getTranslationCache: async (key: string) => {\n            return getLLMCache(key)\n        },\n        _getAliases: () => {\n            return {\n                'pluginStorage':{\n                    'getItem': '_getPluginStorage',\n                    'setItem': '_setPluginStorage',\n                    'removeItem': '_removePluginStorage',\n                    'clear': '_clearPluginStorage',\n                    'key': '_keyPluginStorage',\n                    'keys': '_keysPluginStorage',\n                    'length': '_lengthPluginStorage',\n                },\n                'safeLocalStorage':{\n                    'getItem': '_getSafeLocalStorage',\n                    'setItem': '_setSafeLocalStorage',\n                    'removeItem': '_removeSafeLocalStorage',\n                    'clear': '_clearSafeLocalStorage',\n                    'key': '_keySafeLocalStorage',\n                    'keys': '_keysSafeLocalStorage',\n                }\n            }\n        },\n        runLLMModel: async (options: {\n            mode: ModelModeExtended\n            messages: OpenAIChat[]\n            staticModel?: string\n            allowPlugins?: boolean\n        }) => {\n            return requestChatDataMain({\n                formated: options.messages,\n                bias: {},\n                staticModel: options.staticModel,\n\n                // Calls into plugin-provided models are blocked by default to\n                // guard against accidental IPC loops between provider plugins.\n                // Plugin authors who need to reach the user's plugin-supplied\n                // main or auxiliary model (e.g. a TTS preprocessor that\n                // rewrites text with the configured otherAx model) can opt in\n                // explicitly with `allowPlugins: true`, accepting responsibility\n                // for avoiding provider-to-provider call loops.\n                blockPlugins: !options.allowPlugins,\n            }, options.mode)\n        },\n        sendChat: async (message: string) => {\n            const conf = await getPluginPermission(plugin.name, 'sendChat');\n            if(!conf){\n                return false;\n            }\n\n            if(typeof message !== 'string'){\n                throw new Error(\"Message must be a string\");\n            }\n\n            if(get(doingChat)){\n                throw new Error(\"A chat is already in progress\");\n            }\n\n            if(getModelInfo(DBState.db.aiModel).id.startsWith('pluginmodel:::')){\n                // Executing plugin provider is block because it can be used for loopholes for ipc right now.\n                throw new Error(\"Sending chat with plugin-based model is currently blocked\");\n            }\n\n            const charId = get(selectedCharID);\n            const char = DBState.db.characters[charId];\n            if(!char){\n                throw new Error(\"No character selected\");\n            }\n\n            // Lazy-loaded chats are placeholders until their payload is fetched.\n            // Appending to the placeholder loses the message because the normal\n            // send path refuses to process an unhydrated chat. Hydrate first and\n            // only mutate the real chat after that succeeds.\n            const chatPage = char.chatPage;\n            const chat = await ensureCurrentChatReady(char.chats, chatPage, char.chaId);\n            if(!chat){\n                throw new Error(\"No active chat found or the chat could not be loaded\");\n            }\n            if(\n                get(selectedCharID) !== charId ||\n                DBState.db.characters[charId] !== char ||\n                char.chatPage !== chatPage ||\n                char.chats[chatPage] !== chat\n            ){\n                throw new Error(\"The active chat changed while it was loading\");\n            }\n            if(get(doingChat)){\n                throw new Error(\"A chat is already in progress\");\n            }\n\n            if(message){\n                chat.message.push({\n                    role: 'user',\n                    data: message,\n                    time: Date.now(),\n                });\n            }\n\n            try {\n                await processSendChat(-1, {});\n            } finally {\n                // Plugin API path does not pass through the UI unlock logic,\n                // so release doingChat here on both success and failure.\n                endAllGenerations();\n            }\n\n            return true;\n        },\n        addPluginChannelListener: (channelName: string, callback: Function) => {\n            pluginChannel.set(plugin.name + channelName, callback);\n            addPluginUnloadCallback(plugin.name, () => {\n                pluginChannel.delete(plugin.name + channelName);\n            })\n        },\n        postPluginChannelMessage: (pluginName: string, channelName: string, message: any) => {\n\n            const currentPluginName = plugin.name;\n            const receiverPlugin = DBState.db.plugins.find(p => p.name === pluginName);\n\n            if(!receiverPlugin){\n                console.warn(`[RisuAI Plugin: ${currentPluginName}] Attempted to send message to non-existent plugin '${pluginName}' on channel '${channelName}'.`);\n                return;\n            }\n\n            if(!receiverPlugin.allowedIPC?.includes(currentPluginName)){\n                console.warn(`[RisuAI Plugin: ${currentPluginName}] Attempted to send message to plugin '${pluginName}' but receiver plugin does not allow IPC communication from this plugin. declare //@allowed-ipc ${currentPluginName} in the reciver plugin script to allow IPC communication.`);\n                return;\n            }\n\n            if(!plugin.allowedIPC?.includes(receiverPlugin.name)){\n                console.warn(`[RisuAI Plugin: ${currentPluginName}] Attempted to send message to plugin '${pluginName}' but the sender plugin does not allow IPC communication to this plugin. declare //@allowed-ipc ${receiverPlugin.name} in the sender plugin script to allow IPC communication.`);\n                return;\n            }\n\n\n            const callback = pluginChannel.get(pluginName + channelName);\n            if(callback){\n                callback(message, {\n                    sender: currentPluginName,\n                    channel: channelName\n                });\n            }\n        },\n        saveSecretHeader: async (key: string, value: string|string[]) => {\n            //TODO: Implement server-side secret storage with write-only access for plugins, to enhance security when handling sensitive information like API keys.\n            //This will have rate-limit, to prevent saving it publicly and writing as secret every time before using it.\n            console.warn(`[RisuAI Plugin: ${plugin.name}] saveServerSecret is not implemented yet. This API is intended for securely storing sensitive information like API keys with write-only access for plugins. Please avoid using this API until it is implemented.`);\n        }\n    }\n}\n\ntype V3PluginInstance = {\n    name: string;\n    host: SandboxHost;\n}\n\nconst v3PluginInstances: V3PluginInstance[] = [];\n\nexport async function loadV3Plugins(plugins:RisuPlugin[]){\n    await Promise.all(v3PluginInstances.map(async (instance) => {\n        await unloadV3Plugin(instance.name);\n    }));\n\n    for(const entry of documentEventListeners){\n        document.removeEventListener(entry.type, entry.listener, entry.options);\n    }\n    documentEventListeners.length = 0;\n\n    const loadPromises = plugins.map(plugin => executePluginV3(plugin));\n    await Promise.all(loadPromises);\n}\n\nexport async function executePluginV3(plugin:RisuPlugin){\n\n    const alreadyRunning = v3PluginInstances.find(p => p.name === plugin.name);\n    if(alreadyRunning){\n        console.log(`[RisuAI Plugin: ${plugin.name}] Plugin is already running. Skipping load.`);\n        return;\n    }\n\n    const iframe = document.createElement('iframe');\n    iframe.style.display = \"none\";\n    document.body.appendChild(iframe);\n    const host = new SandboxHost(makeRisuaiAPIV3(iframe, plugin));\n    v3PluginInstances.push({\n        name: plugin.name,\n        host\n    });\n    host.run(iframe, plugin.script);\n    console.log(`[RisuAI Plugin: ${plugin.name}] Loaded API V3 plugin.`);\n}\n\nexport function getV3PluginInstance(name: string) {\n    return v3PluginInstances.find(p => p.name === name);\n}\n\nglobalThis.__debugV3Plugin = (code: string|Function, pluginName: string = '') => {\n    if(code instanceof Function){\n        code = `(${code.toString()})()`;\n    }\n    if(pluginName === ''){\n        return v3PluginInstances[0].host.executeInIframe(code);\n    }\n    const instance = v3PluginInstances.find(p => p.name === pluginName);\n    if(!instance){\n        throw new Error(`Plugin ${pluginName} not found.`);\n    }\n    return instance.host.executeInIframe(code);\n};\n","targetVersions":{"pocketrisu":["1.9.0"]}},{"id":"lazy-chat-sync:replace:src:ts:storage:autoStorage-ts","file":"src/ts/storage/autoStorage.ts","type":"replace","anchor":"import { NodeStorage, type PatchItemResult } from \"./nodeStorage\"\n\nexport class AutoStorage{\n    isAccount:boolean = false\n\n    realStorage:NodeStorage\n\n    async setItem(key:string, value:Uint8Array, etag?:string):Promise<string|null> {\n        await this.realStorage.setItem(key, value, etag)\n        return null\n    }\n    async getItem(key:string):Promise<Buffer> {\n        return await this.realStorage.getItem(key)\n    }\n    async keys(prefix: string = ''):Promise<string[]>{\n        await this.Init()\n        return await this.realStorage.keys(prefix)\n    }\n    async removeItem(key:string){\n        return await this.realStorage.removeItem(key)\n    }\n\n    async checkAccountSync(){\n        return false\n    }\n\n    async Init(){\n        if(!this.realStorage){\n            console.log(\"using node storage\")\n            this.realStorage = new NodeStorage()\n        }\n    }\n\n    async createAuth(): Promise<string> {\n        if (!this.realStorage) {\n            this.realStorage = new NodeStorage()\n        }\n        return this.realStorage.createAuth()\n    }\n\n    async exportBackup(opts?: { target?: 'upstream' }) {\n        await this.Init()\n        return this.realStorage.exportBackup(opts)\n    }\n\n    async importBackup(file: Blob, onProgress?: (loaded: number, total: number) => void) {\n        await this.Init()\n        return this.realStorage.importBackup(file, onProgress)\n    }\n\n    async patchItem(key: string, patchData: { patch: any[], expectedHash: string }): Promise<PatchItemResult> {\n        return await this.realStorage.patchItem(key, patchData)\n    }\n\n    /** Get the last known ETag for database.bin */\n    getDbEtag(): string | null {\n        return this.realStorage._lastDbEtag\n    }\n\n    /** Update cached ETag for database.bin */\n    setDbEtag(etag: string | null) {\n        this.realStorage.setDbEtag(etag)\n    }\n\n    listItem = this.keys\n\n    // ── Bulk asset operations ──────────────────────────────────────────────────\n    async getItems(keys: string[]) { return this.realStorage.getItems(keys) }\n    async setItems(entries: {key: string, value: Uint8Array}[]) { return this.realStorage.setItems(entries) }\n\n    // ── Server-side backup ─────────────────────────────────────────────────────\n    async saveServerBackup(onProgress?: (current: number, total: number, bytes: number, totalBytes: number) => void) { await this.Init(); return this.realStorage.saveServerBackup(onProgress) }\n    async listServerBackups() { await this.Init(); return this.realStorage.listServerBackups() }\n    async restoreServerBackup(filename: string, onProgr